
/* ---------- PERFIS DE USUÁRIO ----------
   Admin-mestre fixo no código — não pode ser rebaixado nem excluído
   pela tela "Equipe", mesmo que apareça na lista. Todo o resto que se
   cadastra nasce como "usuario" — nenhum select de perfil no cadastro
   público. Não usa a senha já cadastrada no Supabase — só decide o
   PERFIL local (admin/usuario), gravado em soliduns_users. */
const EMAIL_ADMIN_MESTRE = 'dr.thiago.viegas@gmail.com';
const NOME_ADMIN_MESTRE = 'Thiago de Oliveira Costa Viegas';
const USERS_STORAGE_KEY = 'soliduns_users';

/* Segundo administrador (não-mestre): entra pré-cadastrado como 'admin' no
   roster local, igual ao mestre — só que sem os privilégios exclusivos de
   mestre (nunca rebaixa/promove ninguém, isso é só do dr.thiago.viegas).
   Não define senha aqui: a autenticação continua 100% no Supabase; no
   primeiro acesso com esse e-mail, ele já entra com perfil 'admin' porque
   já está nesta lista (calcularPerfil só rebaixa quem NÃO está na lista). */
const EMAIL_ADMIN_THALES = 'thales.viegas@gmail.com';
const NOME_ADMIN_THALES = 'Thales de Oliveira Costa Viegas';

function carregarUsuarios(){
  let lista = [];
  try{ lista = JSON.parse(localStorage.getItem(USERS_STORAGE_KEY)) || []; }catch(e){ lista = []; }
  let mudou = false;
  if(!lista.some(u=>u.email.toLowerCase()===EMAIL_ADMIN_MESTRE)){
    lista.push({nome: NOME_ADMIN_MESTRE, email: EMAIL_ADMIN_MESTRE, perfil:'admin'});
    mudou = true;
  }
  if(!lista.some(u=>u.email.toLowerCase()===EMAIL_ADMIN_THALES)){
    lista.push({nome: NOME_ADMIN_THALES, email: EMAIL_ADMIN_THALES, perfil:'admin'});
    mudou = true;
  }
  if(mudou) salvarUsuarios(lista);
  return lista;
}
function salvarUsuarios(lista){
  try{ localStorage.setItem(USERS_STORAGE_KEY, JSON.stringify(lista)); }catch(e){}
}

function calcularPerfil(email, nome){
  email = (email||'').trim().toLowerCase();
  if(email === EMAIL_ADMIN_MESTRE) return 'admin'; // fixo, sempre — nunca lido da lista
  const lista = carregarUsuarios();
  const existente = lista.find(u=>u.email.toLowerCase()===email);
  if(existente) return existente.perfil;
  // Primeiro login desse e-mail: entra no roster como usuario comum
  lista.push({nome: nome || email, email, perfil:'usuario'});
  salvarUsuarios(lista);
  return 'usuario';
}

