/* Regras de casamento da Conciliação Bancária — 74º/75º prompt.
   Fonte única de verdade para o motor (sugerirCandidatos/casarAutomatico)
   e para a tela "Configurar regras". Espelhado em localStorage
   (soliduns_regras_conciliacao) além do state (Supabase). */
const REGRAS_CONCILIACAO_PADRAO = {
  autoAplicarExata: true,
  autoAplicarAproximada: true,
  janelaAproximadaDias: 5,
  janelaSugestaoDias: 5,
  toleranciaSugestaoPct: 7,
  robotAproximadaExigeValorIdentico: true,
  empateNaoFechaSozinho: true, // travado no v1 — não destravar (75º prompt)
  bonusNomeContraparte: true,
  somenteMesmaConta: true,
  respeitarSinal: true,
  transferenciaNuncaReceita: true
};
const REGRAS_CONCILIACAO_KEY = 'soliduns_regras_conciliacao';
function carregarRegrasConciliacaoLocalStorage(){
  try{
    const bruto = localStorage.getItem(REGRAS_CONCILIACAO_KEY);
    if(!bruto) return null;
    return Object.assign({}, REGRAS_CONCILIACAO_PADRAO, JSON.parse(bruto));
  }catch(e){ return null; }
}
function salvarRegrasConciliacaoLocalStorage(regras){
  try{ localStorage.setItem(REGRAS_CONCILIACAO_KEY, JSON.stringify(regras)); }catch(e){}
}

let state = {
  transacoes: [],
  obrigacoes: [],
  empresas: [],
  clientesFornecedores: [],
  contasFinanceiras: [],
  transferencias: [],
  categoriasFluxo: [],
  extratoBancario: [],
  conciliacoes: [],
  contratosRecorrentes: [],
  orcamentos: [],
  compras: [],
  produtos: [],
  movimentosEstoque: [],
  inventarios: [],
  vendas: [],
  cobrancas: [],
  auditoriaFinanceira: [],
  tokensAPI: [],
  regrasConciliacao: Object.assign({}, REGRAS_CONCILIACAO_PADRAO, carregarRegrasConciliacaoLocalStorage() || {}),
  documentosFiscais: [],
  notasFiscaisServico: [],
  notaFiscalEventos: [],
  configFiscalPorEntidade: {},
  itensFiscais: [],
  codigosFiscais: [],
  usuariosFiscais: [],
  convitesContador: [], mapaContabil: [], mapaBanco: [],
  historicoAlteracoesFiscais: [],
  statusAlertasCompliance: {},
  comentariosAlertasCompliance: {},
  arquivosFiscais: [],
  parametrizacaoFiscal: {ambiente: 'homologacao', certificadoNome: '', certificadoConfigurado: false},
  titular: {nome:'', doc:'', email:'', tel:''},
  ultimoDAS: null
};

/* v39: estado vazio de referência (para abrir cadernos do servidor). */
var GESTAO_ESTADO_PADRAO = JSON.stringify(state);
var _estadoCarregado = false;

const STORAGE_KEY = 'gestao-fiscal-state';

/* ---------- PERSISTÊNCIA — localStorage de verdade do navegador ----------
   Antes disto usava window.storage (API exclusiva do artifact do
   Claude) — fora do claude.ai ela não existe, o try/catch engolia o
   erro calado e NADA persistia: um F5 apagava lançamentos, cadastros
   e até a sessão de login. Agora é localStorage real, que funciona em
   qualquer navegador, hospedado onde for.

   Otimização de performance (prompt 31/08/2026): salvarEstado() não
   grava mais na hora — agrupa gravações próximas num debounce curto
   (150ms), suficiente pra não atrasar o usuário mas evitando
   reescrever o blob inteiro a cada clique isolado. flush() força a
   gravação imediata e roda sempre que a aba fecha ou perde foco, pra
   nunca perder o último lançamento. */
let _estadoSaveTimer = null;

function storageStats(){
  const raw = localStorage.getItem(STORAGE_KEY) || '';
  return {
    bytes: raw.length,
    kb: +(raw.length/1024).toFixed(1),
    transacoes: (state.transacoes||[]).length
  };
}

function toastFinanceiro(texto){
  let stack = document.getElementById('toast-stack-financeiro');
  if(!stack){
    stack = document.createElement('div');
    stack.id = 'toast-stack-financeiro';
    stack.style.cssText = 'position:fixed; bottom:20px; right:20px; z-index:9999; display:flex; flex-direction:column; gap:8px; max-width:340px;';
    document.body.appendChild(stack);
  }
  const el = document.createElement('div');
  el.textContent = texto;
  el.style.cssText = 'background:#1c1c1c; border:1px solid #e0563f; color:#f5e6a8; padding:12px 18px; border-radius:10px; font-size:13px; box-shadow:0 8px 24px rgba(0,0,0,.5); font-family:\'IBM Plex Sans\',sans-serif;';
  stack.appendChild(el);
  setTimeout(()=> el.remove(), 7000);
}

function flushEstado(){
  clearTimeout(_estadoSaveTimer);
  /* v39: com login online o caderno vive no servidor (SQL 38). */
  if(gestaoOnline()){ if(_gEspacoId) gestaoAgendarEnvio(); return; }
  /* v39: nunca gravar por cima dos dados do navegador antes de carregá-los
     (antes, trocar de aba sem abrir a Gestão gravava o estado vazio). */
  if(!_estadoCarregado) return;
  try{
    const raw = JSON.stringify(state);
    localStorage.setItem(STORAGE_KEY, raw);
    console.debug('[SOLIDUNS storage]', {bytes: raw.length, kb: +(raw.length/1024).toFixed(1)});
  }catch(e){
    console.error('Falha ao salvar', e);
    toastFinanceiro('Armazenamento cheio — exporte seus dados (Gestão Financeira → Integrações → Exportação) antes de continuar lançando.');
  }
}
window.addEventListener('beforeunload', flushEstado);
document.addEventListener('visibilitychange', function(){
  if(document.hidden) flushEstado();
});

async function salvarEstado(){
  clearTimeout(_estadoSaveTimer);
  _estadoSaveTimer = setTimeout(flushEstado, 150);
}

async function carregarEstado(){
  _estadoCarregado = true;
  try{
    const raw = localStorage.getItem(STORAGE_KEY);
    if(raw){
      state = Object.assign(state, JSON.parse(raw));
    }
  }catch(e){
    // sem dados ainda — segue com estado padrão
  }
  // Backfill: Object.assign acima substitui regrasConciliacao inteiro se
  // já existir salvo — reaplica os defaults para preencher campos novos
  // (75º prompt) em estados salvos antes deles existirem.
  state.regrasConciliacao = Object.assign({}, REGRAS_CONCILIACAO_PADRAO, state.regrasConciliacao || {});
  seedObrigacoesPadrao();
  seedEmpresasPadrao();
  renderTudo();
}

function seedEmpresasPadrao(){
  if(state.empresas.length > 0) return;
  if(typeof _gTipo !== 'undefined' && _gTipo === 'cliente' && gestaoOnline()){   /* v39: caderno de cliente */
    state.empresas = [
      {id: uid(), nome:'Minha empresa', cnpj:'', anexo:'', responsavel:''},
      {id: uid(), nome:'Pessoal', cnpj:'', anexo:'', responsavel:''},
    ];
    return;
  }
  state.empresas = [
    {id: uid(), nome:'MEDMENTOR', cnpj:'', anexo:'5', responsavel:''},
    {id: uid(), nome:'SOLIDUNS', cnpj:'', anexo:'', responsavel:''},
    {id: uid(), nome:'Pessoal', cnpj:'', anexo:'', responsavel:''},
  ];
}

function seedObrigacoesPadrao(){
  if(state.obrigacoes.length > 0) return;
  const hoje = new Date();
  const y = hoje.getFullYear();
  state.obrigacoes = [
    {id: uid(), titulo:'DAS — vencimento mensal', empresa:'Ambas', prazo: proximoDia(20), obs:'Recolhimento mensal do Simples Nacional'},
    {id: uid(), titulo:'DCTFWeb — vencimento mensal', empresa:'Ambas', prazo: proximoDia(15), obs:'Declaração de débitos tributários'},
    {id: uid(), titulo:'NFS-e Nacional obrigatória', empresa:'Ambas', prazo:`${y}-09-01`, obs:'Passa a ser obrigatória para todo o Simples Nacional'},
    {id: uid(), titulo:'Opção de regime para 2027', empresa:'Ambas', prazo:`${y}-09-30`, obs:'Prazo para decidir regime de recolhimento de IBS/CBS a partir de 2027'},
    {id: uid(), titulo:'DEFIS — Declaração anual do Simples', empresa:'Ambas', prazo:`${y+1}-03-31`, obs:'Declaração de Informações Socioeconômicas e Fiscais'},
  ];
}

function proximoDia(dia){
  const hoje = new Date();
  let ano = hoje.getFullYear(), mes = hoje.getMonth();
  let d = new Date(ano, mes, dia);
  if(d < hoje) d = new Date(ano, mes+1, dia);
  return d.toISOString().slice(0,10);
}

function uid(){ return Math.random().toString(36).slice(2,10); }

/* ---------- VALIDAÇÃO DE XML FISCAL (Prompt 152) ----------
   Implementa as 6 camadas pedidas, 100% client-side (sem chamar a
   SEFAZ — isso é o Prompt 153, separado). Retorna exatamente o
   formato de resposta especificado, para ficar fácil de portar para
   um endpoint real no futuro.

   LIMITAÇÃO HONESTA: a "camada 3 — Schema XSD" aqui é uma checagem
   ESTRUTURAL (presença dos elementos mínimos esperados por tipo),
   não uma validação XSD formal contra o schema oficial da SEFAZ —
   um navegador não tem um validador XSD embutido, e portar o XSD
   oficial completo está fora do escopo de um cliente HTML único.
   Isso fica marcado explicitamente em cada resultado (campo
   `xsd_completo: false`) para nunca ser confundido com validação
   oficial. Pelo mesmo motivo, a "camada 4 — assinatura" verifica
   presença/formato do bloco XMLDSig mas não valida a cadeia de
   certificação (exige CA store confiável, que o browser não expõe
   a JS) — por isso o status correto e honesto é sempre
   "assinatura_nao_verificada" quando a cadeia não pôde ser
   verificada, nunca uma autorização fingida. */

const TIPOS_XML_FISCAL = {
  nfeProc: 'nfe', NFe: 'nfe',
  cteProc: 'cte', CTe: 'cte',
  mdfeProc: 'mdfe', MDFe: 'mdfe',
  nfseProc: 'nfse', Nfse: 'nfse', ConsultarNfseResposta: 'nfse',
};

function detectarTipoDocumentoXML(doc){
  const raiz = doc.documentElement ? doc.documentElement.tagName : null;
  if(raiz && TIPOS_XML_FISCAL[raiz]) return TIPOS_XML_FISCAL[raiz];
  // Alguns XMLs vêm com namespace prefixado — tenta pelo local name
  const raizLocal = doc.documentElement ? doc.documentElement.localName : null;
  if(raizLocal && TIPOS_XML_FISCAL[raizLocal]) return TIPOS_XML_FISCAL[raizLocal];
  return null;
}

function extrairTextoTag(doc, tagName){
  const els = doc.getElementsByTagName(tagName);
  return els.length ? (els[0].textContent || '').trim() : null;
}

function validarXMLFiscal(xmlTexto, tamanhoBytes, nomeArquivo, companyId){
  const issues = [];
  const push = (severity, code, path, message) => issues.push({severity, code, path, message});

  // ---- 1) Arquivo ----
  const extensaoOk = /\.xml$/i.test(nomeArquivo || '');
  if(!extensaoOk){
    push('error', 'EXTENSAO_INVALIDA', '', `Arquivo "${nomeArquivo}" não tem extensão .xml.`);
    return { valid_schema:false, valid_signature:'unknown', type:null, layout_version:null,
      access_key:null, issuer_tax_id:null, amount:0, issues, xsd_completo:false };
  }
  const TAMANHO_MAX_BYTES = 10 * 1024 * 1024; // 10 MB
  if(tamanhoBytes > TAMANHO_MAX_BYTES){
    push('error', 'ARQUIVO_MUITO_GRANDE', '', `Arquivo tem ${(tamanhoBytes/1024/1024).toFixed(1)} MB — máximo aceito é 10 MB.`);
    return { valid_schema:false, valid_signature:'unknown', type:null, layout_version:null,
      access_key:null, issuer_tax_id:null, amount:0, issues, xsd_completo:false };
  }

  // ---- 2) Well-formed ----
  const parser = new DOMParser();
  const doc = parser.parseFromString(xmlTexto, 'application/xml');
  const erroParser = doc.getElementsByTagName('parsererror')[0];
  if(erroParser){
    push('error', 'XML_MAL_FORMADO', '', 'XML não é bem formado: ' + erroParser.textContent.split('\n')[0].trim());
    return { valid_schema:false, valid_signature:'unknown', type:null, layout_version:null,
      access_key:null, issuer_tax_id:null, amount:0, issues, xsd_completo:false };
  }

  // ---- 3) "Schema" — checagem estrutural mínima (não é XSD oficial) ----
  const tipo = detectarTipoDocumentoXML(doc);
  if(!tipo){
    push('error', 'TIPO_NAO_RECONHECIDO', '/', 'Não foi possível identificar o tipo do documento (NF-e/NFC-e/NFS-e/CT-e/MDF-e) pela tag raiz.');
    return { valid_schema:false, valid_signature:'unknown', type:null, layout_version:null,
      access_key:null, issuer_tax_id:null, amount:0, issues, xsd_completo:false };
  }

  const TAG_INF_POR_TIPO = {nfe:'infNFe', cte:'infCte', mdfe:'infMDFe', nfse:null};
  const tagInf = TAG_INF_POR_TIPO[tipo];
  let infEl = null;
  if(tagInf){
    const els = doc.getElementsByTagName(tagInf);
    if(!els.length){
      push('error', 'ELEMENTO_INF_AUSENTE', '/', `XML de ${tipo.toUpperCase()} sem o elemento <${tagInf}> — estrutura mínima ausente.`);
    } else {
      infEl = els[0];
    }
  }

  let schemaOk = !!(tagInf ? infEl : true) && issues.every(i => i.severity !== 'error');

  // ---- 4) Assinatura XMLDSig ----
  const assinaturaEls = doc.getElementsByTagName('Signature');
  let validSignature = 'unknown';
  if(assinaturaEls.length === 0){
    validSignature = false;
    push('warning', 'ASSINATURA_AUSENTE', '/Signature', 'XML não contém bloco de assinatura XMLDSig.');
  } else {
    const temCertificado = doc.getElementsByTagName('X509Certificate').length > 0;
    if(!temCertificado){
      validSignature = false;
      push('warning', 'CERTIFICADO_AUSENTE', '/Signature', 'Bloco de assinatura presente, mas sem certificado X509 embutido.');
    } else {
      // Presença de assinatura + certificado confirmada — mas a cadeia de
      // confiança (ICP-Brasil) não pode ser verificada offline no navegador.
      validSignature = 'unknown';
      push('warning', 'ASSINATURA_NAO_VERIFICADA', '/Signature', 'Assinatura e certificado presentes, mas a cadeia de confiança não foi verificada — validação local não substitui autorização da SEFAZ.');
    }
  }

  // ---- 5) Regras de negócio mínimas ----
  let accessKey = null;
  if(infEl){
    const idAttr = infEl.getAttribute('Id') || '';
    const digitos = idAttr.replace(/\D/g, '');
    if(['nfe','cte','mdfe'].includes(tipo)){
      if(digitos.length === 44){
        accessKey = digitos;
      } else {
        push('error', 'CHAVE_INVALIDA', `/${tagInf}/@Id`, `Chave de acesso deveria ter 44 dígitos, encontrados ${digitos.length}.`);
        schemaOk = false;
      }
    }
  }

  const cnpjEmit = extrairTextoTag(doc, 'CNPJ');
  const issuerTaxId = cnpjEmit ? cnpjEmit.replace(/\D/g,'') : null;
  if(!issuerTaxId){
    push('warning', 'CNPJ_EMITENTE_AUSENTE', '//emit/CNPJ', 'Não foi encontrado CNPJ do emitente no XML.');
  } else if(issuerTaxId.length !== 14){
    push('error', 'CNPJ_INVALIDO', '//emit/CNPJ', `CNPJ do emitente com ${issuerTaxId.length} dígitos — esperado 14.`);
    schemaOk = false;
  }

  const dataEmissaoTexto = extrairTextoTag(doc, 'dhEmi') || extrairTextoTag(doc, 'dEmi');
  if(dataEmissaoTexto){
    const dataParseada = new Date(dataEmissaoTexto);
    if(isNaN(dataParseada.getTime())){
      push('error', 'DATA_EMISSAO_INVALIDA', '//ide/dhEmi', `Data de emissão "${dataEmissaoTexto}" não é parseável.`);
      schemaOk = false;
    }
  } else if(tipo !== 'nfse'){
    push('warning', 'DATA_EMISSAO_AUSENTE', '//ide/dhEmi', 'Não foi encontrada data de emissão no XML.');
  }

  let valorTotal = 0;
  const vNFTexto = extrairTextoTag(doc, 'vNF') || extrairTextoTag(doc, 'vTPrest') || extrairTextoTag(doc, 'vServ');
  if(vNFTexto !== null){
    valorTotal = parseFloat(vNFTexto);
    if(isNaN(valorTotal) || valorTotal < 0){
      push('error', 'VALOR_TOTAL_INVALIDO', '//total', `Valor total "${vNFTexto}" inválido ou negativo.`);
      schemaOk = false;
      valorTotal = 0;
    }
  }

  // ---- 6) Duplicidade ----
  if(accessKey){
    const jaExiste = state.documentosFiscais.some(d => d.access_key === accessKey && d.company_id === companyId);
    if(jaExiste){
      push('warning', 'DUPLICATE', '/', `Chave ${accessKey} já foi importada anteriormente para esta empresa.`);
    }
  }

  const layoutVersion = infEl ? (infEl.getAttribute('versao') || null) : null;

  return {
    valid_schema: schemaOk,
    valid_signature: validSignature,
    type: tipo,
    layout_version: layoutVersion,
    access_key: accessKey,
    issuer_tax_id: issuerTaxId,
    amount: valorTotal,
    issues,
    xsd_completo: false, // nunca confundir com validação XSD oficial real
  };
}



/* ---------- Validação de CPF/CNPJ (window.SolidunsDocs) ----------
   Máscara + dígito verificador real, sem biblioteca externa. Usado nos
   cadastros de Clientes e Fornecedores (3.1/3.2). Algoritmo: CPF 1º DV
   pesos 10..2, 2º DV pesos 11..2, resto=(soma*10)%11, 10 vira 0. CNPJ
   pesos 5-4-3-2-9-8-7-6-5-4-3-2 e 6-5-4-3-2-9-8-7-6-5-4-3-2, DV=0 se
   resto<2 senão 11-resto. Rejeita sequências iguais (000.000.000-00 etc). */
(function(){
  function onlyDigits(v){ return String(v||'').replace(/\D/g,''); }
  function maskCPF(v){
    v = onlyDigits(v).slice(0,11);
    if(v.length>9) return v.replace(/(\d{3})(\d{3})(\d{3})(\d{1,2})/, '$1.$2.$3-$4');
    if(v.length>6) return v.replace(/(\d{3})(\d{3})(\d{1,3})/, '$1.$2.$3');
    if(v.length>3) return v.replace(/(\d{3})(\d{1,3})/, '$1.$2');
    return v;
  }
  function maskCNPJ(v){
    v = onlyDigits(v).slice(0,14);
    if(v.length>12) return v.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{1,2})/, '$1.$2.$3/$4-$5');
    if(v.length>8) return v.replace(/(\d{2})(\d{3})(\d{3})(\d{1,4})/, '$1.$2.$3/$4');
    if(v.length>5) return v.replace(/(\d{2})(\d{3})(\d{1,3})/, '$1.$2.$3');
    if(v.length>2) return v.replace(/(\d{2})(\d{1,3})/, '$1.$2');
    return v;
  }
  function allEqual(d){ return /^(\d)\1+$/.test(d); }
  function isValidCPF(value){
    const d = onlyDigits(value);
    if(d.length!==11 || allEqual(d)) return false;
    let sum=0; for(let i=0;i<9;i++) sum += Number(d[i])*(10-i);
    let r=(sum*10)%11; if(r===10) r=0;
    if(r!==Number(d[9])) return false;
    sum=0; for(let i=0;i<10;i++) sum += Number(d[i])*(11-i);
    r=(sum*10)%11; if(r===10) r=0;
    return r===Number(d[10]);
  }
  function isValidCNPJ(value){
    const d = onlyDigits(value);
    if(d.length!==14 || allEqual(d)) return false;
    const w1=[5,4,3,2,9,8,7,6,5,4,3,2], w2=[6,5,4,3,2,9,8,7,6,5,4,3,2];
    function dv(slice, weights){
      let s=0; for(let i=0;i<weights.length;i++) s += Number(slice[i])*weights[i];
      const r=s%11; return r<2 ? 0 : 11-r;
    }
    if(dv(d,w1)!==Number(d[12])) return false;
    return dv(d,w2)===Number(d[13]);
  }
  window.SolidunsDocs = {onlyDigits, isValidCPF, isValidCNPJ, maskCPF, maskCNPJ};
})();
/* Máscara reativa aplicada a qualquer <input data-doc="cpf|cnpj-auto">:
   detecta CPF (11 dígitos) vs CNPJ (14) pelo tamanho digitado. */
function aplicarMascaraDocumento(input){
  const digitos = SolidunsDocs.onlyDigits(input.value);
  input.value = digitos.length > 11 ? SolidunsDocs.maskCNPJ(input.value) : SolidunsDocs.maskCPF(input.value);
}
function validarCampoDocumento(input){
  const digitos = SolidunsDocs.onlyDigits(input.value);
  if(!digitos){ limparErroCampo(input); return true; }
  const valido = digitos.length === 11 ? SolidunsDocs.isValidCPF(input.value) : digitos.length === 14 ? SolidunsDocs.isValidCNPJ(input.value) : false;
  if(!valido){ mostrarErroCampo(input, digitos.length < 11 ? 'CPF/CNPJ incompleto.' : 'CPF/CNPJ inválido — confira os dígitos verificadores.'); return false; }
  limparErroCampo(input);
  return true;
}

/* ---------- HELPER ÚNICO DE TÍTULO DA ABA (título + metadados) ----------
   Toda view chama isto ao entrar — nenhuma outra parte do código deve
   setar document.title diretamente. Regra única:
     document.title = nome ? `${nome} · Soliduns` : "Soliduns"
   O 2º parâmetro (descrição) é opcional; quando omitido usa a descrição
   padrão do site (só Mercado financeiro define uma própria por enquanto). */
/* TITULO_PADRAO vale apenas para a home, que é a página que o Google
   indexa e exibe nos resultados — por isso ele carrega os três segmentos
   de atuação. Telas internas continuam curtas, no formato "Nome · Soliduns",
   montado em setTituloPagina. */
const TITULO_PADRAO = 'SOLIDUNS — Reestruturação, Ativos e Educação Financeira';
const DESCRICAO_PADRAO = 'Reestruturação de empresas, análise de ativos e cursos preparatórios para certificações ANBIMA. Consultoria e plataforma educacional em Brasília.';

function setTituloPagina(nome, descricao){
  const t = nome ? `${nome} · Soliduns` : TITULO_PADRAO;
  const d = descricao || DESCRICAO_PADRAO;
  document.title = t;
  const metaDesc = document.getElementById('meta-description');
  const metaOgT = document.getElementById('meta-og-title');
  const metaOgD = document.getElementById('meta-og-description');
  if(metaDesc) metaDesc.setAttribute('content', d);
  if(metaOgT) metaOgT.setAttribute('content', t);
  if(metaOgD) metaOgD.setAttribute('content', d);
}

/* O modal Equipe (só admin) abre por cima do dashboard ou do módulo fiscal
   sem trocar de tela — ao fechar, o título precisa voltar ao da tela que
   ficou por baixo (painel do dashboard, ou Gestão financeira/fiscal). */
function restaurarTituloAposFecharEquipe(){
  if(document.getElementById('tela-dashboard').style.display !== 'none'){
    const painelAtivo = document.querySelector('#tela-dashboard .painel.ativo');
    const id = painelAtivo ? painelAtivo.id.replace('painel-','') : 'educacao';
    if(id === 'acoes') setTituloPagina('Mercado financeiro', 'Cotações, screener de ações e simulação de carteira — Mercado financeiro Soliduns.');
    else if(id === 'leilao') setTituloPagina('Leilão de imóveis');
    else if(id === 'leilao-veiculos') setTituloPagina('Leilão de automóveis');
    else if(id === 'avaliacao-imoveis') setTituloPagina('Avaliação de imóveis');
    else if(id === 'mercado-imobiliario') setTituloPagina('Mercado imobiliário');
    else if(id === 'investimentos-escolha') setTituloPagina('Investimentos');
    else setTituloPagina('Educação continuada');
  } else {
    setTituloPagina(window.__moduloFiscalModoAtual === 'fiscal' ? 'Gestão fiscal' : 'Gestão financeira');
  }
}

function formatBRL(v){
  return (v||0).toLocaleString('pt-BR', {style:'currency', currency:'BRL'});
}
function parseDate(s){ return new Date(s+'T00:00:00'); }
function diasAte(dataStr){
  const hoje = new Date(); hoje.setHours(0,0,0,0);
  const alvo = parseDate(dataStr);
  return Math.round((alvo - hoje) / (1000*60*60*24));
}

