function registrarSimulacao(tipo, resumo, valorTotal){
  if(!state.historicoSimulacoes) state.historicoSimulacoes = [];
  state.historicoSimulacoes.unshift({
    id: uid(), tipo, resumo, valorTotal, data: new Date().toISOString()
  });
  state.historicoSimulacoes = state.historicoSimulacoes.slice(0, 20); // guarda as 20 mais recentes
  salvarEstado();
}

let fiscalHistoricoSelecionados = [];
function renderizarHistoricoSimulacoes(){
  const lista = document.getElementById('fiscal-historico-lista');
  if(!lista) return;
  const historico = state.historicoSimulacoes || [];
  if(historico.length === 0){
    lista.innerHTML = '<div class="empty">Nenhuma simulação feita ainda. Calcule em Calculadoras e Simuladores (5.0) para começar o histórico.</div>';
    document.getElementById('fiscal-historico-comparacao').style.display = 'none';
    return;
  }
  lista.innerHTML = historico.map(h=>{
    const dataFmt = new Date(h.data).toLocaleString('pt-BR', {day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'});
    return `<div class="fiscal-hist-item">
      <input type="checkbox" data-hist-id="${h.id}" ${fiscalHistoricoSelecionados.includes(h.id) ? 'checked':''}>
      <span class="hist-tipo">${h.tipo}</span>
      <span class="hist-data">${dataFmt}</span>
      <span>${h.resumo}</span>
      <span class="hist-valor">${formatBRL(h.valorTotal)}</span>
    </div>`;
  }).join('');
  lista.querySelectorAll('[data-hist-id]').forEach(chk=>{
    chk.addEventListener('change', ()=>{
      const id = chk.getAttribute('data-hist-id');
      if(chk.checked){
        if(fiscalHistoricoSelecionados.length >= 2){
          chk.checked = false; // só permite comparar 2 por vez
          return;
        }
        fiscalHistoricoSelecionados.push(id);
      } else {
        fiscalHistoricoSelecionados = fiscalHistoricoSelecionados.filter(x=>x!==id);
      }
      renderizarComparacaoSimulacoes();
    });
  });
}
function renderizarComparacaoSimulacoes(){
  const box = document.getElementById('fiscal-historico-comparacao');
  if(fiscalHistoricoSelecionados.length !== 2){
    box.style.display = 'none';
    return;
  }
  const historico = state.historicoSimulacoes || [];
  const itens = fiscalHistoricoSelecionados.map(id => historico.find(h=>h.id===id)).filter(Boolean);
  if(itens.length !== 2){ box.style.display = 'none'; return; }
  box.style.display = 'block';
  const diferenca = itens[0].valorTotal - itens[1].valorTotal;
  box.innerHTML = `
    <h3 style="color:var(--gold); font-size:14px; margin:0 0 12px;">Comparação</h3>
    <div class="fiscal-comparacao-grid">
      ${itens.map(h=>`<div class="panel"><div class="hist-tipo">${h.tipo}</div><p style="font-size:12px; color:var(--ink-soft); margin:6px 0;">${h.resumo}</p><div style="font-family:'IBM Plex Mono',monospace; font-size:18px; color:var(--gold);">${formatBRL(h.valorTotal)}</div></div>`).join('')}
    </div>
    <p style="margin-top:12px; font-size:13px;">Diferença: <strong>${formatBRL(Math.abs(diferenca))}</strong> ${diferenca>0 ? '(o primeiro é maior)' : diferenca<0 ? '(o segundo é maior)' : '(iguais)'}</p>
  `;
}

function renderizarKpisFiscal(){
  const grid = document.getElementById('fiscal-kpi-grid');
  if(!grid) return;
  grid.innerHTML = FISCAL_KPIS.map(k=>{
    const r = k.calcular();
    return `<button type="button" class="fiscal-kpi-card" data-kpi="${k.id}">
      <span class="kpi-label">${k.label}</span>
      <span class="kpi-valor">${r.valor}</span>
    </button>`;
  }).join('');
  grid.querySelectorAll('.fiscal-kpi-card').forEach(card=>{
    card.addEventListener('click', ()=>{
      grid.querySelectorAll('.fiscal-kpi-card').forEach(c=>c.classList.remove('selecionado'));
      card.classList.add('selecionado');
      const kpi = FISCAL_KPIS.find(k=>k.id===card.getAttribute('data-kpi'));
      const r = kpi.calcular();
      document.getElementById('fiscal-kpi-detalhe-titulo').textContent = kpi.label;
      document.getElementById('fiscal-kpi-detalhe-conteudo').innerHTML = `<p>${r.detalhe}</p>`;
    });
  });
}

function reindexSidebarFinanceira(){
  ['financeiro','fiscal'].forEach(grupo=>{
    const itens = document.querySelectorAll('.spine .nav-item[data-grupo="'+grupo+'"]');
    let raiz = 0, ultimoPaiCodigo = null, subContador = 0;
    itens.forEach(item=>{
      const codeEl = item.querySelector('.nav-code');
      if(!codeEl) return;
      let codigo;
      if(item.getAttribute('data-sub') === 'true' && ultimoPaiCodigo !== null){
        subContador++;
        codigo = `${ultimoPaiCodigo}.${subContador}`;
      } else {
        raiz++;
        subContador = 0;
        ultimoPaiCodigo = raiz;
        codigo = `${raiz}.0`;
      }
      codeEl.textContent = codigo;
      const viewId = item.getAttribute('data-view');
      if(viewId){
        const tagView = document.querySelector('#view-'+viewId+' .page-tag');
        if(tagView) tagView.textContent = codigo;
      }
    });
  });
}
