/* ---------- FLUXO DE CAIXA ---------- */
/* ---------- CONTAS A PAGAR / CONTAS A RECEBER (telas dedicadas) ----------
   Reaproveita state.transacoes (mesma fonte do Fluxo de Caixa) filtrando
   por tipo fixo. addContaTipo/renderContasTipo/popularFavorecidos são
   genéricas — servem pro prefixo 'ap' (pagar) e 'ar' (receber) igual. */
function popularFavorecidosSelect(prefixo){
  const sel = document.getElementById(prefixo + '-favorecido');
  if(!sel) return;
  const valorAtual = sel.value;
  sel.innerHTML = '<option value="">-- Nenhum / avulso --</option>' +
    state.clientesFornecedores.filter(c=>c.ativo!==false).map(c=>`<option value="${c.id}">${c.nome}${c.documento ? ' — '+c.documento : ''}</option>`).join('');
  sel.value = valorAtual;
}

function addContaTipo(tipo, prefixo){
  const desc = document.getElementById(prefixo + '-desc').value.trim();
  const valorInput = document.getElementById(prefixo + '-valor');
  const vencInput = document.getElementById(prefixo + '-venc');
  const descInput = document.getElementById(prefixo + '-desc');
  const msg = document.getElementById(prefixo + '-form-msg');

  const valido = validarCampos([
    {input: descInput, obrigatorio:true, mensagemVazio:'Informe a descrição.'},
    {input: valorInput, obrigatorio:true, tipo:'numero', moeda:true, minimo:0.01, mensagemVazio:'Informe o valor.', mensagemInvalido:'Informe um valor válido.'},
    {input: vencInput, obrigatorio:true, mensagemVazio:'Informe o vencimento.'}
  ]);
  if(!valido){
    msg.textContent = 'Corrija os campos destacados antes de salvar.';
    msg.className = 'auth-msg erro';
    return;
  }
  msg.textContent = '';

  const favorecidoId = document.getElementById(prefixo + '-favorecido').value;
  const favorecido = favorecidoId ? state.clientesFornecedores.find(c=>c.id===favorecidoId) : null;

  state.transacoes.push({
    id: uid(),
    tipo,
    empresa: document.getElementById(prefixo + '-empresa').value,
    descricao: desc,
    valor: parseMoeda(valorInput.value),
    vencimento: vencInput.value,
    categoria: document.getElementById(prefixo + '-cat').value.trim() || '—',
    status: 'pendente',
    favorecidoId: favorecidoId || null,
    favorecidoNome: favorecido ? favorecido.nome : null,
    baixas: []
  });
  descInput.value = '';
  valorInput.value = '';
  vencInput.value = '';
  document.getElementById(prefixo + '-cat').value = '';
  salvarEstado();
  renderTudo();
}

function statusVisualContaTipo(t){
  const calc = statusCalculadoTransacao(t);
  if(calc === 'pago') return 'pago';
  const hoje = new Date(); hoje.setHours(0,0,0,0);
  const venc = parseDate(t.vencimento);
  return venc < hoje ? 'vencido' : 'aberto';
}

function renderContasTipo(tipo, prefixo){
  popularFavorecidosSelect(prefixo);
  popularDatalistCategorias();   /* v103-GF (GF2) */
  recGerarPendentes();           /* v105-GF (GF13) */
  const fEmpresa = document.getElementById(prefixo + '-filtro-empresa').value;
  const fStatus = document.getElementById(prefixo + '-filtro-status').value;
  const tbody = document.getElementById(prefixo + '-tbody');

  let lista = state.transacoes.filter(t=>t.tipo===tipo).sort((a,b)=> a.vencimento.localeCompare(b.vencimento));
  if(fEmpresa) lista = lista.filter(t=>t.empresa===fEmpresa);

  const NOMES_STATUS_VISUAL = {aberto:'Em aberto', vencido:'Vencido', pago: tipo==='receber' ? 'Recebido' : 'Pago', parcial:'Pago parcial'};
  const listaComStatusVisual = lista.map(t=>({t, sv: statusCalculadoTransacao(t)==='parcial' ? 'parcial' : statusVisualContaTipo(t)}));
  const listaFiltrada = fStatus ? listaComStatusVisual.filter(x=> fStatus==='pago' ? x.sv==='pago' || x.sv==='parcial' : x.sv===fStatus) : listaComStatusVisual;

  document.getElementById(prefixo + '-empty').style.display = listaFiltrada.length ? 'none' : 'block';
  tbody.innerHTML = listaFiltrada.map(({t, sv})=>{
    const saldoAberto = t.valor - valorPagoTransacao(t);
    return `<tr>
      <td>${t.descricao}</td>
      <td>${t.favorecidoNome || '—'}</td>
      <td>${t.empresa}</td>
      <td>${t.categoria}</td>
      <td>${parseDate(t.vencimento).toLocaleDateString('pt-BR')}</td>
      <td><span class="tag ${sv==='vencido'?'pagar':sv==='pago'?'pago':sv==='parcial'?'parcial':'pendente'}" style="cursor:pointer" onclick="abrirModalBaixa('${t.id}')" title="Clique para informar ${tipo==='receber'?'recebimento':'pagamento'}">${NOMES_STATUS_VISUAL[sv]}${sv==='parcial' ? ' — resta '+formatBRL(saldoAberto) : ''}</span></td>
      <td class="num">${formatBRL(t.valor)}</td>
      <td>${sv!=='pago' ? `<button class="ghost" style="color:var(--gold);" onclick="abrirModalBaixa('${t.id}')">${tipo==='receber'?'Receber':'Pagar'}</button> ` : ''}<button class="ghost" onclick="removerTransacao('${t.id}')">Excluir</button></td>
    </tr>`;
  }).join('');

  // KPIs — todos calculados a partir da MESMA lista (antes do filtro de status),
  // e cada um representa exatamente o que aparece na tabela ao clicar nele.
  const todasDoTipo = state.transacoes.filter(t=>t.tipo===tipo);
  const previsto = todasDoTipo.reduce((s,t)=>s+t.valor, 0);
  const abertoTotal = todasDoTipo.filter(t=>statusCalculadoTransacao(t)!=='pago').reduce((s,t)=> s + (t.valor - valorPagoTransacao(t)), 0);
  const vencidoTotal = todasDoTipo.filter(t=> statusCalculadoTransacao(t)!=='pago' && statusVisualContaTipo(t)==='vencido').reduce((s,t)=> s + (t.valor - valorPagoTransacao(t)), 0);
  const pagoTotal = todasDoTipo.reduce((s,t)=> s + valorPagoTransacao(t), 0);
  document.getElementById(prefixo + '-kpi-previsto').textContent = formatBRL(previsto);
  document.getElementById(prefixo + '-kpi-aberto').textContent = formatBRL(abertoTotal);
  document.getElementById(prefixo + '-kpi-vencido').textContent = formatBRL(vencidoTotal);
  document.getElementById(prefixo + '-kpi-pago').textContent = formatBRL(pagoTotal);
}

function removerTransacao(id){
  state.transacoes = state.transacoes.filter(t=>t.id!==id);
  salvarEstado();
  renderTudo();
}

/* ---------- CONTAS FINANCEIRAS — as gavetas de dinheiro (Parte 1.1 do manual) ---------- */
const NOMES_TIPO_CONTA = {banco:'Banco', caixinha:'Caixinha', cartao:'Cartão de crédito', maquininha:'Meios de recebimento'};

function popularSelectsContasFinanceiras(){
  const ativas = state.contasFinanceiras.filter(c=>c.ativo);
  ['tr-origem','tr-destino'].forEach(id=>{
    const sel = document.getElementById(id);
    if(!sel) return;
    const atual = sel.value;
    sel.innerHTML = ativas.map(c=>`<option value="${c.id}">${c.nome} (${c.empresa})</option>`).join('');
    if(ativas.some(c=>c.id===atual)) sel.value = atual;
  });
}

function saldoContaFinanceira(contaId){
  const conta = state.contasFinanceiras.find(c=>c.id===contaId);
  if(!conta) return 0;
  let total = conta.saldoInicial || 0;
  state.transacoes.forEach(t=>{
    (t.baixas||[]).forEach(b=>{
      if(b.contaFinanceiraId !== contaId) return;
      const efetivo = (b.valorEfetivo||0) + (b.juros||0) + (b.multa||0) - (b.desconto||0) - (b.tarifa||0);
      total += (t.tipo === 'receber' ? efetivo : -efetivo);
    });
  });
  state.transferencias.forEach(tr=>{
    if(tr.destinoId === contaId) total += tr.valor;
    if(tr.origemId === contaId) total -= tr.valor;
  });
  return total;
}

function salvarContaFinanceira(){
  const id = document.getElementById('cf-id').value;
  const empresa = document.getElementById('cf-empresa').value;
  const tipo = document.getElementById('cf-tipo').value;
  const nome = document.getElementById('cf-nome').value.trim();
  const saldo = parseMoeda(document.getElementById('cf-saldo').value) || 0;
  const dataSaldo = document.getElementById('cf-data-saldo').value;
  const ativo = document.getElementById('cf-ativo').checked;
  const msg = document.getElementById('cf-form-msg');
  if(!nome){
    msg.textContent = 'Informe o nome da conta.';
    msg.className = 'auth-msg erro';
    return;
  }
  if(id){
    const c = state.contasFinanceiras.find(x=>x.id===id);
    Object.assign(c, {empresa, tipo, nome, saldoInicial: saldo, dataSaldoInicial: dataSaldo, ativo});
  } else {
    state.contasFinanceiras.push({id: uid(), empresa, tipo, nome, saldoInicial: saldo, dataSaldoInicial: dataSaldo, ativo});
  }
  msg.textContent = 'Conta salva.';
  msg.className = 'auth-msg sucesso';
  cancelarEdicaoContaFinanceira();
  salvarEstado();
  renderTudo();
}
function editarContaFinanceira(id){
  const c = state.contasFinanceiras.find(x=>x.id===id);
  if(!c) return;
  document.getElementById('cf-id').value = c.id;
  document.getElementById('cf-empresa').value = c.empresa;
  document.getElementById('cf-tipo').value = c.tipo;
  document.getElementById('cf-nome').value = c.nome;
  document.getElementById('cf-saldo').value = formatBRL(c.saldoInicial || 0);
  document.getElementById('cf-data-saldo').value = c.dataSaldoInicial || '';
  document.getElementById('cf-ativo').checked = c.ativo;
  document.getElementById('cf-form-titulo').textContent = 'Editar conta financeira';
  document.getElementById('cf-btn-cancelar').style.display = '';
  document.querySelector('#view-fin-contas .panel').scrollIntoView({behavior:'smooth'});
}
function cancelarEdicaoContaFinanceira(){
  document.getElementById('cf-id').value = '';
  document.getElementById('cf-nome').value = '';
  document.getElementById('cf-saldo').value = '';
  document.getElementById('cf-data-saldo').value = '';
  document.getElementById('cf-ativo').checked = true;
  document.getElementById('cf-form-titulo').textContent = 'Nova conta financeira';
  document.getElementById('cf-btn-cancelar').style.display = 'none';
}
function toggleAtivoContaFinanceira(id){
  const c = state.contasFinanceiras.find(x=>x.id===id);
  if(!c) return;
  c.ativo = !c.ativo;
  salvarEstado();
  renderTudo();
}
function removerContaFinanceira(id){
  const usada = state.transacoes.some(t=>(t.baixas||[]).some(b=>b.contaFinanceiraId===id))
    || state.transferencias.some(tr=>tr.origemId===id || tr.destinoId===id);
  if(usada){
    alert('Esta conta já tem baixas ou transferências lançadas. Marque como inativa em vez de excluir, para não quebrar o histórico do fluxo de caixa.');
    return;
  }
  if(!confirm('Excluir esta conta financeira?')) return;
  state.contasFinanceiras = state.contasFinanceiras.filter(x=>x.id!==id);
  salvarEstado();
  renderTudo();
}
function renderContasFinanceiras(){
  popularSelectsContasFinanceiras();
  const tbody = document.getElementById('cf-tbody');
  if(!tbody) return;
  const lista = state.contasFinanceiras.slice().sort((a,b)=> (a.empresa+a.nome).localeCompare(b.empresa+b.nome));
  document.getElementById('cf-empty').style.display = lista.length ? 'none' : 'block';
  tbody.innerHTML = lista.map(c=>`<tr>
    <td>${c.nome}</td>
    <td>${NOMES_TIPO_CONTA[c.tipo] || c.tipo}</td>
    <td>${c.empresa}</td>
    <td class="num">${formatBRL(c.saldoInicial || 0)}</td>
    <td class="num">${formatBRL(saldoContaFinanceira(c.id))}</td>
    <td><span class="tag ${c.ativo ? 'pago':'pendente'}" style="cursor:pointer" onclick="toggleAtivoContaFinanceira('${c.id}')" title="Clique para ${c.ativo?'inativar':'reativar'}">${c.ativo ? 'Ativa' : 'Inativa'}</span></td>
    <td style="white-space:nowrap;">
      <button class="ghost" onclick="editarContaFinanceira('${c.id}')">Editar</button>
      <button class="ghost" onclick="removerContaFinanceira('${c.id}')">Excluir</button>
    </td>
  </tr>`).join('');
}

/* ---------- TRANSFERÊNCIAS ENTRE CONTAS (Parte 4.4 do manual) ---------- */
function salvarTransferencia(){
  const empresa = document.getElementById('tr-empresa').value;
  const data = document.getElementById('tr-data').value;
  const origemId = document.getElementById('tr-origem').value;
  const destinoId = document.getElementById('tr-destino').value;
  const valor = parseMoeda(document.getElementById('tr-valor').value);
  const obs = document.getElementById('tr-obs').value.trim();
  const msg = document.getElementById('tr-form-msg');
  if(!data || !origemId || !destinoId || isNaN(valor) || valor <= 0){
    msg.textContent = 'Preencha data, conta de origem, conta de destino e um valor válido.';
    msg.className = 'auth-msg erro';
    return;
  }
  if(origemId === destinoId){
    msg.textContent = 'Origem e destino não podem ser a mesma conta.';
    msg.className = 'auth-msg erro';
    return;
  }
  state.transferencias.push({id: uid(), empresa, data, origemId, destinoId, valor, obs});
  document.getElementById('tr-valor').value = '';
  document.getElementById('tr-obs').value = '';
  msg.textContent = 'Transferência registrada.';
  msg.className = 'auth-msg sucesso';
  salvarEstado();
  renderTudo();
}
function removerTransferencia(id){
  state.transferencias = state.transferencias.filter(x=>x.id!==id);
  salvarEstado();
  renderTudo();
}
function renderTransferencias(){
  const tbody = document.getElementById('tr-tbody');
  if(!tbody) return;
  const porId = {};
  state.contasFinanceiras.forEach(c=> porId[c.id] = c.nome);
  const lista = state.transferencias.slice().sort((a,b)=> b.data.localeCompare(a.data));
  document.getElementById('tr-empty').style.display = lista.length ? 'none' : 'block';
  tbody.innerHTML = lista.map(tr=>`<tr>
    <td>${parseDate(tr.data).toLocaleDateString('pt-BR')}</td>
    <td>${tr.empresa}</td>
    <td>${porId[tr.origemId] || '—'}</td>
    <td>&rarr;</td>
    <td>${porId[tr.destinoId] || '—'}</td>
    <td class="num">${formatBRL(tr.valor)}</td>
    <td><button class="ghost" onclick="removerTransferencia('${tr.id}')">Excluir</button></td>
  </tr>`).join('');
}

/* ---------- CATEGORIAS DO FLUXO DE CAIXA (Parte 1.2 do manual) ---------- */
function categoriasFinanceirasDistintas(){
  const set = new Set();
  state.transacoes.forEach(t=>{ if(t.categoria && t.categoria !== '—') set.add(t.categoria); });
  return Array.from(set).sort();
}
function atualizarFormCategoriaFluxo(){
  const tipo = document.getElementById('cfl-tipo').value;
  document.getElementById('cfl-pai-wrap').style.display = tipo === 'subcategoria' ? '' : 'none';
  document.getElementById('cfl-vinculo-wrap').style.display = tipo === 'totalizador' ? 'none' : '';
  if(tipo === 'subcategoria'){
    const sel = document.getElementById('cfl-pai');
    const categorias = state.categoriasFluxo.filter(c=>c.tipo==='categoria');
    sel.innerHTML = categorias.map(c=>`<option value="${c.id}">${c.nome}</option>`).join('');
  }
  if(tipo === 'totalizador'){
    renderVinculoTotalizador();
  } else {
    renderVinculoCategoriaFinanceira();
  }
}
function renderVinculoCategoriaFinanceira(){
  const wrap = document.getElementById('cfl-vinculo-lista');
  const distintas = categoriasFinanceirasDistintas();
  document.getElementById('cfl-vinculo-vazio').style.display = distintas.length ? 'none' : 'block';
  const idAtual = document.getElementById('cfl-id').value;
  const atual = idAtual ? state.categoriasFluxo.find(c=>c.id===idAtual) : null;
  const marcadas = atual ? (atual.categoriasFinanceiras || []) : [];
  wrap.innerHTML = distintas.map(nome=>`<label class="fx-conta-chip">
    <input type="checkbox" class="cfl-vinculo-check" value="${nome.replace(/"/g,'&quot;')}" ${marcadas.includes(nome)?'checked':''}> ${nome}
  </label>`).join('');
}
function renderVinculoTotalizador(){
  const wrap = document.getElementById('cfl-vinculo-lista');
  document.getElementById('cfl-vinculo-vazio').style.display = 'none';
  const categorias = state.categoriasFluxo.filter(c=>c.tipo==='categoria');
  const idAtual = document.getElementById('cfl-id').value;
  const atual = idAtual ? state.categoriasFluxo.find(c=>c.id===idAtual) : null;
  const marcadas = atual ? (atual.categoriasSomadas || []) : [];
  wrap.innerHTML = categorias.map(c=>`<label class="fx-conta-chip">
    <input type="checkbox" class="cfl-vinculo-check" value="${c.id}" ${marcadas.includes(c.id)?'checked':''}> ${c.nome}
  </label>`).join('');
}
function salvarCategoriaFluxo(){
  const id = document.getElementById('cfl-id').value;
  const tipo = document.getElementById('cfl-tipo').value;
  const nome = document.getElementById('cfl-nome').value.trim();
  const paiId = tipo === 'subcategoria' ? document.getElementById('cfl-pai').value : null;
  const marcadas = Array.from(document.querySelectorAll('.cfl-vinculo-check:checked')).map(el=>el.value);
  const msg = document.getElementById('cfl-form-msg');
  if(!nome){
    msg.textContent = 'Informe o nome da categoria.';
    msg.className = 'auth-msg erro';
    return;
  }
  if(tipo === 'subcategoria' && !paiId){
    msg.textContent = 'Cadastre uma categoria do fluxo antes de criar subcategorias.';
    msg.className = 'auth-msg erro';
    return;
  }
  const dados = {nome, tipo, paiId: tipo==='subcategoria' ? paiId : null};
  dados.classeDre = tipo==='totalizador' ? '' : (document.getElementById('cfl-dre') ? document.getElementById('cfl-dre').value : '');   /* v103-GF (GF4) */
  dados.classeDva = tipo==='totalizador' ? '' : (document.getElementById('cfl-dva') ? document.getElementById('cfl-dva').value : '');   /* v104-GF (GF10) */
  if(tipo === 'totalizador') dados.categoriasSomadas = marcadas;
  else dados.categoriasFinanceiras = marcadas;
  if(id){
    const c = state.categoriasFluxo.find(x=>x.id===id);
    Object.assign(c, dados);
  } else {
    state.categoriasFluxo.push(Object.assign({id: uid()}, dados));
  }
  msg.textContent = 'Categoria salva.';
  msg.className = 'auth-msg sucesso';
  cancelarEdicaoCategoriaFluxo();
  salvarEstado();
  renderTudo();
}
function editarCategoriaFluxo(id){
  const c = state.categoriasFluxo.find(x=>x.id===id);
  if(!c) return;
  document.getElementById('cfl-id').value = c.id;
  document.getElementById('cfl-tipo').value = c.tipo;
  document.getElementById('cfl-nome').value = c.nome;
  if(document.getElementById('cfl-dre')) document.getElementById('cfl-dre').value = c.classeDre || '';   /* v103-GF (GF4) */
  if(document.getElementById('cfl-dva')) document.getElementById('cfl-dva').value = c.classeDva || 'insumos';   /* v104-GF (GF10) */
  atualizarFormCategoriaFluxo();
  if(c.tipo === 'subcategoria') document.getElementById('cfl-pai').value = c.paiId;
  document.getElementById('cfl-form-titulo').textContent = 'Editar categoria';
  document.getElementById('cfl-btn-cancelar').style.display = '';
  document.querySelectorAll('#view-fin-categorias .panel')[1].scrollIntoView({behavior:'smooth'});
}
function cancelarEdicaoCategoriaFluxo(){
  document.getElementById('cfl-id').value = '';
  document.getElementById('cfl-nome').value = '';
  document.getElementById('cfl-tipo').value = 'categoria';
  document.getElementById('cfl-form-titulo').textContent = 'Nova categoria do fluxo';
  document.getElementById('cfl-btn-cancelar').style.display = 'none';
  atualizarFormCategoriaFluxo();
}
function removerCategoriaFluxo(id){
  const temFilhas = state.categoriasFluxo.some(c=>c.paiId===id);
  if(temFilhas){
    alert('Esta categoria tem subcategorias vinculadas. Exclua-as primeiro.');
    return;
  }
  if(!confirm('Excluir esta categoria?')) return;
  state.categoriasFluxo = state.categoriasFluxo.filter(x=>x.id!==id);
  salvarEstado();
  renderTudo();
}
function renderCategoriasFluxo(){
  atualizarFormCategoriaFluxo();
  const arvore = document.getElementById('cfl-arvore');
  if(!arvore) return;
  const categorias = state.categoriasFluxo.filter(c=>c.tipo==='categoria');
  document.getElementById('cfl-arvore-vazio').style.display = categorias.length ? 'none' : 'block';
  arvore.innerHTML = categorias.map(c=>{
    const subs = state.categoriasFluxo.filter(s=>s.tipo==='subcategoria' && s.paiId===c.id);
    const chipsCat = (c.categoriasFinanceiras||[]).map(f=>`<span class="cf-chip-fin">${f}</span>`).join('') || '<span style="color:var(--ink-soft); font-size:12px;">Nenhuma categoria financeira vinculada</span>';
    return `<div class="cf-tree-cat">
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <strong style="color:var(--gold);">${c.nome}</strong>${c.classeDre ? ' <span class="cf-chip-fin">'+(NOMES_CLASSE_DRE[c.classeDre]||c.classeDre)+'</span>' : ''}
        <span>
          <button class="ghost" onclick="editarCategoriaFluxo('${c.id}')">Editar</button>
          <button class="ghost" onclick="removerCategoriaFluxo('${c.id}')">Excluir</button>
        </span>
      </div>
      <div style="margin-top:6px;">${chipsCat}</div>
      ${subs.map(s=>{
        const chipsSub = (s.categoriasFinanceiras||[]).map(f=>`<span class="cf-chip-fin">${f}</span>`).join('') || '<span style="color:var(--ink-soft); font-size:12px;">Nenhuma categoria financeira vinculada</span>';
        return `<div class="cf-tree-sub">
          <div style="display:flex; justify-content:space-between; align-items:center;">
            <span>${s.nome}</span>
            <span>
              <button class="ghost" onclick="editarCategoriaFluxo('${s.id}')">Editar</button>
              <button class="ghost" onclick="removerCategoriaFluxo('${s.id}')">Excluir</button>
            </span>
          </div>
          <div style="margin-top:6px;">${chipsSub}</div>
        </div>`;
      }).join('')}
    </div>`;
  }).join('');

  const totalizadores = state.categoriasFluxo.filter(c=>c.tipo==='totalizador');
  const wrapTot = document.getElementById('cfl-totalizadores');
  document.getElementById('cfl-totalizadores-vazio').style.display = totalizadores.length ? 'none' : 'block';
  wrapTot.innerHTML = totalizadores.map(t=>{
    const nomesSomados = (t.categoriasSomadas||[]).map(id=>{
      const c = state.categoriasFluxo.find(x=>x.id===id);
      return c ? c.nome : null;
    }).filter(Boolean);
    return `<div class="cf-tree-cat">
      <div style="display:flex; justify-content:space-between; align-items:center;">
        <strong style="color:var(--gold);">${t.nome}</strong>
        <span>
          <button class="ghost" onclick="editarCategoriaFluxo('${t.id}')">Editar</button>
          <button class="ghost" onclick="removerCategoriaFluxo('${t.id}')">Excluir</button>
        </span>
      </div>
      <div style="margin-top:6px; font-size:12.5px; color:var(--ink-soft);">Soma: ${nomesSomados.join(' + ') || 'nenhuma categoria selecionada'}</div>
    </div>`;
  }).join('');
}

/* ---------- BAIXA — pagamento/recebimento total ou parcial (Prompt 154) ----------
   Cada transação acumula um histórico de baixas (state pode ter várias
   baixas parciais até completar o valor). status é sempre CALCULADO a
   partir da soma das baixas, nunca marcado à mão — evita esconder
   inadimplência atrás de um "pago" prematuro. */
function valorPagoTransacao(t){
  return (t.baixas || []).reduce((s,b)=> s + b.valorEfetivo, 0);
}
function statusCalculadoTransacao(t){
  const pago = valorPagoTransacao(t);
  if(pago <= 0) return 'pendente';
  if(pago < t.valor) return 'parcial';
  return 'pago';
}

function abrirModalBaixa(id){
  if(bloquearSeContador('Contador não dá baixa — é leitura e exportação. Peça ao financeiro.')) return;
  const t = state.transacoes.find(x=>x.id===id);
  if(!t) return;
  document.getElementById('baixa-transacao-id').value = id;
  document.getElementById('baixa-titulo').textContent = t.tipo === 'receber' ? 'Informar recebimento' : 'Informar pagamento';
  document.getElementById('baixa-data').value = new Date().toISOString().slice(0,10);
  const contasDaEmpresa = state.contasFinanceiras.filter(c=>c.ativo && c.empresa===t.empresa);
  document.getElementById('baixa-conta').innerHTML = '<option value="">-- Não especificada --</option>' +
    contasDaEmpresa.map(c=>'<option value="'+c.id+'">'+c.nome+' ('+(NOMES_TIPO_CONTA[c.tipo]||c.tipo)+')</option>').join('');
  const saldoRestante = t.valor - valorPagoTransacao(t);
  document.getElementById('baixa-valor').value = formatBRL(saldoRestante);
  document.getElementById('baixa-juros').value = '';
  document.getElementById('baixa-multa').value = '';
  document.getElementById('baixa-desconto').value = '';
  document.getElementById('baixa-tarifa').value = '';
  document.getElementById('baixa-obs').value = '';
  document.getElementById('baixa-msg').textContent = '';
  atualizarResumoBaixa();
  document.getElementById('baixa-overlay').style.display = 'flex';
}
function fecharModalBaixa(){
  document.getElementById('baixa-overlay').style.display = 'none';
}
function atualizarResumoBaixa(){
  const id = document.getElementById('baixa-transacao-id').value;
  const t = state.transacoes.find(x=>x.id===id);
  if(!t) return;
  const saldoRestante = t.valor - valorPagoTransacao(t);
  const efetivo = parseMoeda(document.getElementById('baixa-valor').value) || 0;
  const juros = parseMoeda(document.getElementById('baixa-juros').value) || 0;
  const multa = parseMoeda(document.getElementById('baixa-multa').value) || 0;
  const desconto = parseMoeda(document.getElementById('baixa-desconto').value) || 0;
  const liquido = efetivo + juros + multa - desconto;
  const restanteApos = Math.max(0, saldoRestante - liquido);
  document.getElementById('baixa-resumo').innerHTML = `
    <div class="result-line"><span class="k">Valor original</span><span class="v">${formatBRL(t.valor)}</span></div>
    <div class="result-line"><span class="k">Saldo em aberto</span><span class="v">${formatBRL(saldoRestante)}</span></div>
    <div class="result-line total"><span class="k">Líquido desta baixa</span><span class="v">${formatBRL(liquido)}</span></div>
    ${restanteApos > 0 ? `<div class="note warn">Ficará em aberto: ${formatBRL(restanteApos)} — status vira "Pago parcial".</div>` : '<div class="note">Quita o saldo — status vira "Pago".</div>'}
  `;
}
['baixa-valor','baixa-juros','baixa-multa','baixa-desconto'].forEach(id=>{
  document.getElementById(id).addEventListener('input', ()=> setTimeout(atualizarResumoBaixa, 10));
});

function confirmarBaixa(){
  if(bloquearSeContador()) return;
  const id = document.getElementById('baixa-transacao-id').value;
  const t = state.transacoes.find(x=>x.id===id);
  const msg = document.getElementById('baixa-msg');
  if(!t) return;

  const dataInput = document.getElementById('baixa-data');
  const valorInput = document.getElementById('baixa-valor');
  const valido = validarCampos([
    {input: dataInput, obrigatorio:true, mensagemVazio:'Informe a data da baixa.'},
    {input: valorInput, obrigatorio:true, tipo:'numero', moeda:true, minimo:0.01, mensagemVazio:'Informe o valor efetivo.', mensagemInvalido:'Informe um valor efetivo válido.'}
  ]);
  if(!valido){
    msg.textContent = 'Corrija os campos destacados antes de confirmar.';
    msg.className = 'auth-msg erro';
    return;
  }

  /* v103-GF (GF1): com conta cadastrada para a empresa, a baixa exige a conta.
     Sem ela o saldo por conta, a conciliação e a DFC não fecham. */
  const baixaContaSel = document.getElementById('baixa-conta');
  if(!baixaContaSel.value && baixaContaSel.options.length > 1){
    msg.textContent = 'Escolha a conta financeira desta baixa. Sem ela, o saldo por conta e a Demonstração de Fluxo de Caixa não fecham.';
    msg.className = 'auth-msg erro';
    return;
  }
  if(!t.baixas) t.baixas = [];
  t.baixas.push({
    id: uid(),
    data: dataInput.value,
    valorEfetivo: parseMoeda(valorInput.value),
    juros: parseMoeda(document.getElementById('baixa-juros').value) || 0,
    multa: parseMoeda(document.getElementById('baixa-multa').value) || 0,
    desconto: parseMoeda(document.getElementById('baixa-desconto').value) || 0,
    tarifa: parseMoeda(document.getElementById('baixa-tarifa').value) || 0,
    observacoes: document.getElementById('baixa-obs').value.trim(),
    contaFinanceiraId: document.getElementById('baixa-conta').value || null
  });
  t.status = statusCalculadoTransacao(t);
  salvarEstado();
  fecharModalBaixa();
  renderTudo();
}

/* ---------- MODAL IMPORTAR XML (Prompt 152) ---------- */
let ultimoResultadoValidacaoXML = null;
let ultimoArquivoValidadoXML = null;

function abrirModalImportarXML(){
  document.getElementById('importar-xml-input').value = '';
  document.getElementById('importar-xml-checklist').style.display = 'none';
  document.getElementById('importar-xml-confirmar').style.display = 'none';
  document.getElementById('importar-xml-msg').textContent = '';
  document.getElementById('importar-xml-resumo').style.display = 'none';
  document.getElementById('importar-xml-issues').innerHTML = '';
  ultimoResultadoValidacaoXML = null;
  ultimoArquivoValidadoXML = null;
  document.getElementById('importar-xml-overlay').style.display = 'flex';
}
function fecharModalImportarXML(){
  document.getElementById('importar-xml-overlay').style.display = 'none';
}

function atualizarItemChecklist(id, ok){
  const el = document.getElementById(id);
  el.className = 'check-item ' + (ok ? 'ok' : 'falhou');
  el.querySelector('.check-icone').textContent = ok ? '✓' : '✗';
}

async function lidarComArquivoXMLSelecionado(){
  const input = document.getElementById('importar-xml-input');
  const arquivo = input.files[0];
  const checklist = document.getElementById('importar-xml-checklist');
  const btnConfirmar = document.getElementById('importar-xml-confirmar');
  const msg = document.getElementById('importar-xml-msg');
  const resumo = document.getElementById('importar-xml-resumo');
  const issuesEl = document.getElementById('importar-xml-issues');

  msg.textContent = '';
  btnConfirmar.style.display = 'none';
  if(!arquivo) { checklist.style.display = 'none'; return; }

  checklist.style.display = 'block';
  ['chk-arquivo','chk-wellformed','chk-schema','chk-assinatura','chk-chave'].forEach(id=>{
    const el = document.getElementById(id);
    el.className = 'check-item';
    el.querySelector('.check-icone').textContent = '—';
  });
  resumo.style.display = 'none';
  issuesEl.innerHTML = '<p style="color:var(--ink-soft); font-size:12.5px;">Validando...</p>';

  const companyId = (document.getElementById('rel-empresa') && document.getElementById('rel-empresa').value) || 'empresa-padrao';

  let texto;
  try{
    texto = await arquivo.text();
  }catch(e){
    issuesEl.innerHTML = '<div class="xml-issue error">Não foi possível ler o arquivo.</div>';
    return;
  }

  const r = validarXMLFiscal(texto, arquivo.size, arquivo.name, companyId);
  ultimoResultadoValidacaoXML = r;
  ultimoArquivoValidadoXML = { nome: arquivo.name, texto };

  const codigos = r.issues.map(i=>i.code);
  const temErro = c => r.issues.some(i=>i.code===c && i.severity==='error');

  atualizarItemChecklist('chk-arquivo', !temErro('EXTENSAO_INVALIDA') && !temErro('ARQUIVO_MUITO_GRANDE'));
  atualizarItemChecklist('chk-wellformed', !temErro('XML_MAL_FORMADO'));
  atualizarItemChecklist('chk-schema', !temErro('TIPO_NAO_RECONHECIDO') && !temErro('ELEMENTO_INF_AUSENTE'));
  atualizarItemChecklist('chk-assinatura', r.valid_signature !== false);
  atualizarItemChecklist('chk-chave', !temErro('CHAVE_INVALIDA') && !temErro('CNPJ_INVALIDO') && !temErro('VALOR_TOTAL_INVALIDO') && !temErro('DATA_EMISSAO_INVALIDA'));

  if(r.type){
    resumo.style.display = 'block';
    resumo.innerHTML = `
      <div><strong>Tipo:</strong> ${r.type.toUpperCase()}${r.layout_version ? ' — layout '+r.layout_version : ''}</div>
      ${r.access_key ? `<div><strong>Chave:</strong> ${r.access_key}</div>` : ''}
      ${r.issuer_tax_id ? `<div><strong>CNPJ emitente:</strong> ${r.issuer_tax_id}</div>` : ''}
      ${r.amount ? `<div><strong>Valor:</strong> ${formatBRL(r.amount)}</div>` : ''}
    `;
  }

  issuesEl.innerHTML = r.issues.length
    ? r.issues.map(i => `<div class="xml-issue ${i.severity}"><strong>${i.code}</strong> — ${i.message}</div>`).join('')
    : '<div class="xml-issue" style="border-color:#3ecb99; color:var(--text);">Nenhuma pendência encontrada.</div>';

  if(r.valid_schema){
    const jaDuplicado = codigos.includes('DUPLICATE');
    if(jaDuplicado){
      msg.textContent = 'Este documento já foi importado — confirme apenas se quiser registrar mesmo assim.';
      msg.className = 'auth-msg';
    }
    btnConfirmar.style.display = 'inline-block';
  } else {
    msg.textContent = 'Corrija os erros acima antes de importar — documento não será gravado (422).';
    msg.className = 'auth-msg erro';
  }
}
document.getElementById('importar-xml-input').addEventListener('change', lidarComArquivoXMLSelecionado);

function confirmarImportacaoXML(){
  const r = ultimoResultadoValidacaoXML;
  if(!r || !r.valid_schema) return; // 422 nunca vira sucesso — nunca grava sem schema valido

  const companyId = (document.getElementById('rel-empresa') && document.getElementById('rel-empresa').value) || 'empresa-padrao';
  state.documentosFiscais.push({
    id: uid(),
    company_id: companyId,
    type: r.type,
    layout_version: r.layout_version,
    access_key: r.access_key,
    issuer_tax_id: r.issuer_tax_id,
    amount: r.amount,
    valid_signature: r.valid_signature,
    nome_arquivo: ultimoArquivoValidadoXML ? ultimoArquivoValidadoXML.nome : null,
    importado_em: new Date().toISOString(),
    issues: r.issues,
  });
  salvarEstado();
  fecharModalImportarXML();
  renderDocumentosFiscais();
}

/* ---------- AMBIENTE E CERTIFICADO (Prompt 153 — só a fatia real) ----------
   Nenhum segredo (senha, .pfx) é armazenado aqui — só o nome do arquivo
   como referência e um flag booleano "configurado". Isso é o suficiente
   para acionar os estados de UI corretos (banner de ambiente, botões
   desabilitados sem certificado) sem fingir um cofre de segredos que
   este ambiente client-only não tem como oferecer de verdade. */
function renderParametrizacaoFiscal(){
  const p = state.parametrizacaoFiscal;
  const selAmbiente = document.getElementById('param-ambiente');
  const inputCert = document.getElementById('param-certificado-nome');
  const chkCert = document.getElementById('param-certificado-configurado');
  if(!selAmbiente) return;
  selAmbiente.value = p.ambiente;
  inputCert.value = p.certificadoNome || '';
  chkCert.checked = !!p.certificadoConfigurado;
}
function salvarParametrizacaoFiscal(){
  state.parametrizacaoFiscal = {
    ambiente: document.getElementById('param-ambiente').value,
    certificadoNome: document.getElementById('param-certificado-nome').value.trim(),
    certificadoConfigurado: document.getElementById('param-certificado-configurado').checked,
  };
  salvarEstado();
  // A ficha do documento (se aberta) reflete o estado imediatamente.
  if(typeof renderFichaDocumentoFiscal === 'function') renderFichaDocumentoFiscal();
}

/* ---------- MAPEAMENTO cStat → BADGE (Prompt 153) ----------
   Só os códigos mais documentados e estáveis do Manual de Orientação
   do Contribuinte (MOC) da NF-e — não é uma lista exaustiva de todos
   os cStat possíveis (são centenas, variam por serviço/UF). Qualquer
   código fora desta tabela cai no fallback "rejected" com o código
   bruto preservado em observation, para nunca esconder um cStat
   desconhecido atrás de um badge genérico sem rastro. */
const CSTAT_PARA_BADGE = {
  100: 'authorized',   // Autorizado o uso da NF-e
  150: 'authorized',   // Autorizado o uso da NF-e (contingência)
  101: 'cancelled',    // Cancelamento homologado
  135: 'cancelled',    // Evento registrado e vinculado a NF-e (cancelamento)
  102: 'cancelled',    // Inutilização homologada
  110: 'denied',       // Uso denegado
  301: 'denied',       // Uso denegado — irregularidade do emitente
  302: 'denied',       // Uso denegado — irregularidade do destinatário
  303: 'denied',       // Uso denegado — irregularidade da NF-e
  210: 'pending_manifest', // Confirmação da operação registrada
};
function mapCStatParaBadge(cStat){
  const codigo = Number(cStat);
  if(CSTAT_PARA_BADGE[codigo]) return CSTAT_PARA_BADGE[codigo];
  return 'rejected'; // fallback honesto — não finge reconhecer um cStat que não está na tabela
}

function renderDocumentosFiscais(){
  const tbody = document.getElementById('docfiscal-tbody');
  if(!tbody) return;
  const lista = state.documentosFiscais.slice().sort((a,b)=> (b.importado_em||'').localeCompare(a.importado_em||''));
  document.getElementById('docfiscal-empty').style.display = lista.length ? 'none' : 'block';

  const NOMES_STATUS = {true:'Assinatura verificada', false:'Sem assinatura válida', unknown:'Assinatura não verificada'};
  tbody.innerHTML = lista.map(d=>{
    const temAlertaBloqueante = (d.issues||[]).some(i=>i.severity==='error');
    return `<tr style="cursor:pointer;" onclick="abrirFichaDocumentoFiscal('${d.id}')">
      <td>${(d.type||'—').toUpperCase()}</td>
      <td style="font-family:monospace; font-size:11px;">${d.access_key || '—'}</td>
      <td>${d.issuer_tax_id || '—'}</td>
      <td class="num">${d.amount ? formatBRL(d.amount) : '—'}</td>
      <td><span class="tag ${d.valid_signature===true?'pago':d.valid_signature===false?'pagar':'pendente'}">${NOMES_STATUS[d.valid_signature]}</span></td>
      <td><button class="ghost" onclick="event.stopPropagation(); removerDocumentoFiscal('${d.id}')">Excluir</button></td>
    </tr>`;
  }).join('');
}
function removerDocumentoFiscal(id){
  state.documentosFiscais = state.documentosFiscais.filter(d=>d.id!==id);
  salvarEstado();
  renderDocumentosFiscais();
}

/* ---------- FICHA DO DOCUMENTO — integração SEFAZ (Prompt 153) ---------- */
let fichaDocumentoAtivoId = null;

function abrirFichaDocumentoFiscal(id){
  fichaDocumentoAtivoId = id;
  renderFichaDocumentoFiscal();
  document.getElementById('ficha-documento-overlay').style.display = 'flex';
}
function fecharFichaDocumentoFiscal(){
  document.getElementById('ficha-documento-overlay').style.display = 'none';
  fichaDocumentoAtivoId = null;
}

const NOMES_BADGE_SEFAZ = {
  authorized: 'Autorizado', rejected: 'Rejeitado', denied: 'Denegado',
  cancelled: 'Cancelado', pending_manifest: 'Pendente de manifestação',
};

function renderFichaDocumentoFiscal(){
  const d = state.documentosFiscais.find(x => x.id === fichaDocumentoAtivoId);
  const container = document.getElementById('ficha-documento-conteudo');
  if(!d || !container) return;

  const p = state.parametrizacaoFiscal;
  const temCertificado = !!p.certificadoConfigurado;
  const ambienteTexto = p.ambiente === 'producao' ? 'PRODUÇÃO' : 'HOMOLOGAÇÃO';
  const corAmbiente = p.ambiente === 'producao' ? '#e2793f' : 'var(--gold)';

  container.innerHTML = `
    <h2>${(d.type||'—').toUpperCase()} — ${d.access_key ? d.access_key.slice(-8) : d.id}</h2>
    <div class="leilao-ficha-sub">Chave: ${d.access_key || '—'} · CNPJ emitente: ${d.issuer_tax_id || '—'} · Valor: ${d.amount ? formatBRL(d.amount) : '—'}</div>

    <div class="note" style="margin:14px 0; border-color:${corAmbiente}; color:${corAmbiente};">Ambiente: ${ambienteTexto}</div>

    ${!temCertificado ? `
      <div class="alert" style="margin-bottom:14px;">Nenhum certificado configurado. <a href="javascript:void(0)" onclick="fecharFichaDocumentoFiscal(); navegarHash('#/gestao-fiscal'); setTimeout(()=>document.querySelector('.nav-item[data-view=\\'fiscal-empresa\\']').click(), 100);" style="color:var(--gold);">Cadastre o A1 em Parametrização</a>.</div>
    ` : ''}

    <div style="display:flex; gap:10px; flex-wrap:wrap; margin-bottom:14px;">
      <button type="button" onclick="consultarSefazDocumento()" ${!temCertificado ? 'disabled' : ''}>Consultar SEFAZ</button>
      <button type="button" class="ghost" onclick="manifestarDocumento('ciencia')" ${!temCertificado ? 'disabled' : ''}>Ciência da operação</button>
      <button type="button" class="ghost" onclick="manifestarDocumento('confirmacao')" ${!temCertificado ? 'disabled' : ''}>Confirmar operação</button>
      <button type="button" class="ghost" onclick="manifestarDocumento('desconhecimento')" ${!temCertificado ? 'disabled' : ''}>Desconhecimento</button>
    </div>

    <div id="ficha-documento-resultado-sefaz"></div>

    <h3 style="font-size:13px; text-transform:uppercase; letter-spacing:.03em; color:var(--gold); margin:18px 0 8px;">Validação local (Prompt 152)</h3>
    <div style="font-size:12.5px; color:var(--ink-soft);">Assinatura: ${d.valid_signature===true?'verificada':d.valid_signature===false?'ausente/inválida':'não verificada offline'}</div>
    ${(d.issues||[]).length ? '<div style="margin-top:8px;">' + d.issues.map(i=>`<div class="xml-issue ${i.severity}">${i.code} — ${i.message}</div>`).join('') + '</div>' : ''}
  `;
}

function consultarSefazDocumento(){
  const el = document.getElementById('ficha-documento-resultado-sefaz');
  if(!el) return;
  // Este ambiente é um HTML único sem backend — não há gateway real para
  // falar com a SEFAZ (isso exigiria certificado em cofre de servidor,
  // chamadas SOAP/REST com mTLS e resolução de endpoint por UF). Em vez
  // de fingir uma resposta, o estado é honesto sobre a limitação.
  el.innerHTML = `<div class="note" style="margin-top:8px;">Integração real com a SEFAZ não está disponível neste ambiente (HTML sem backend). Em produção, este botão chamaria <code>POST /fiscal/sefaz/query</code> pelo gateway <code>sefaz_gateway</code> — contrato documentado na Referência da API.</div>`;
}
function manifestarDocumento(evento){
  const el = document.getElementById('ficha-documento-resultado-sefaz');
  if(!el) return;
  el.innerHTML = `<div class="note" style="margin-top:8px;">Manifestação "${evento}" não enviada — integração real com a SEFAZ não está disponível neste ambiente. Em produção, chamaria <code>POST /fiscal/sefaz/manifest</code>.</div>`;
}

function toggleStatus(id){
  const t = state.transacoes.find(t=>t.id===id);
  if(t) t.status = t.status==='pago' ? 'pendente' : 'pago';
  salvarEstado();
  renderTudo();
}

/* ---------- CADASTROS FINANCEIROS — Clientes e Fornecedores ---------- */
function popularUfClienteFornecedor(){
  const sel = document.getElementById('fc-uf');
  if(!sel || sel.options.length > 1) return;
  sel.innerHTML = '<option value="">-- UF --</option>' + UF_LIST.map(u=>`<option value="${u.sigla}">${u.sigla} — ${u.nome}</option>`).join('');
}

function limparFormClienteFornecedor(){
  document.getElementById('fc-id').value = '';
  document.getElementById('fc-tipo').value = 'cliente';
  document.getElementById('fc-doc').value = '';
  document.getElementById('fc-nome').value = '';
  document.getElementById('fc-email').value = '';
  document.getElementById('fc-tel').value = '';
  document.getElementById('fc-uf').value = '';
  document.getElementById('fc-condicao').value = '';
  document.getElementById('fc-ativo').checked = true;
  document.getElementById('fc-form-titulo').textContent = 'Novo cadastro';
  document.getElementById('fc-btn-cancelar').style.display = 'none';
  limparErroCampo(document.getElementById('fc-doc'));
  limparErroCampo(document.getElementById('fc-nome'));
}

function salvarClienteFornecedor(){
  const idInput = document.getElementById('fc-id');
  const docInput = document.getElementById('fc-doc');
  const nomeInput = document.getElementById('fc-nome');
  const msg = document.getElementById('fc-form-msg');

  const valido = validarCampos([
    {input: nomeInput, obrigatorio:true, mensagemVazio:'Informe o nome ou razão social.'}
  ]);
  const docPreenchido = SolidunsDocs.onlyDigits(docInput.value).length > 0;
  const docValido = !docPreenchido || validarCampoDocumento(docInput);
  if(!valido || !docValido){
    msg.textContent = 'Corrija os campos destacados antes de salvar.';
    msg.className = 'auth-msg erro';
    return;
  }
  msg.textContent = '';

  const idExistente = idInput.value;
  const cadastro = {
    id: idExistente || uid(),
    tipo: document.getElementById('fc-tipo').value,
    documento: docInput.value.trim(),
    nome: nomeInput.value.trim(),
    email: document.getElementById('fc-email').value.trim(),
    telefone: document.getElementById('fc-tel').value.trim(),
    uf: document.getElementById('fc-uf').value,
    condicaoPagamento: document.getElementById('fc-condicao').value.trim(),
    ativo: document.getElementById('fc-ativo').checked
  };

  if(idExistente){
    const idx = state.clientesFornecedores.findIndex(c=>c.id===idExistente);
    if(idx>-1) state.clientesFornecedores[idx] = cadastro;
  } else {
    state.clientesFornecedores.push(cadastro);
  }
  salvarEstado();
  limparFormClienteFornecedor();
  renderClientesFornecedores();
}

function editarClienteFornecedor(id){
  const c = state.clientesFornecedores.find(x=>x.id===id);
  if(!c) return;
  document.getElementById('fc-id').value = c.id;
  document.getElementById('fc-tipo').value = c.tipo;
  document.getElementById('fc-doc').value = c.documento || '';
  document.getElementById('fc-nome').value = c.nome;
  document.getElementById('fc-email').value = c.email || '';
  document.getElementById('fc-tel').value = c.telefone || '';
  document.getElementById('fc-uf').value = c.uf || '';
  document.getElementById('fc-condicao').value = c.condicaoPagamento || '';
  document.getElementById('fc-ativo').checked = c.ativo !== false;
  document.getElementById('fc-form-titulo').textContent = 'Editar cadastro';
  document.getElementById('fc-btn-cancelar').style.display = 'inline-block';
  window.scrollTo(0,0);
}
function cancelarEdicaoClienteFornecedor(){ limparFormClienteFornecedor(); }

function excluirClienteFornecedor(id){
  state.clientesFornecedores = state.clientesFornecedores.filter(c=>c.id!==id);
  salvarEstado();
  renderClientesFornecedores();
}

function renderClientesFornecedores(){
  popularUfClienteFornecedor();
  const filtro = document.getElementById('fc-filtro-tipo').value;
  const tbody = document.getElementById('fc-tbody');
  let lista = state.clientesFornecedores.slice().sort((a,b)=> a.nome.localeCompare(b.nome));
  if(filtro) lista = lista.filter(c=>c.tipo===filtro);

  document.getElementById('fc-empty').style.display = lista.length ? 'none' : 'block';
  tbody.innerHTML = lista.map(c=>`
    <tr>
      <td>${c.nome}</td>
      <td><span class="tag ${c.tipo==='cliente'?'receber':'pagar'}">${c.tipo==='cliente'?'Cliente':'Fornecedor'}</span></td>
      <td>${c.documento || '—'}</td>
      <td>${c.uf || '—'}</td>
      <td><span class="tag ${c.ativo!==false?'pago':'pendente'}">${c.ativo!==false?'Ativo':'Inativo'}</span></td>
      <td>
        <button class="ghost" onclick="editarClienteFornecedor('${c.id}')">Editar</button>
        <button class="ghost" onclick="excluirClienteFornecedor('${c.id}')">Excluir</button>
      </td>
    </tr>
  `).join('');
}

/* ---------- CADASTROS FISCAIS (76º prompt) ----------
   Três registros, espelhando o desenho já documentado na API de referência
   (/fiscal/registries/{partners,items,tax-codes}): produtos/serviços com
   NCM/CEST/LC116/CFOP/CST-CSOSN, dados fiscais dos parceiros (completa o
   mesmo cadastro de Gestão Financeira — não duplica) e uma lista própria de
   códigos fiscais de referência (não é a tabela oficial da SEFAZ/CONFAZ). */
function renderCadastrosFiscais(){
  atualizarFormItemFiscal();
  renderItensFiscais();
  renderParceirosFiscais();
  renderCodigosFiscais();
}

/* -- Produtos e serviços -- */
function atualizarFormItemFiscal(){
  const tipo = document.getElementById('itf-tipo').value;
  document.getElementById('itf-wrap-ncm').style.display = tipo === 'produto' ? 'grid' : 'none';
  document.getElementById('itf-wrap-lc116').style.display = tipo === 'servico' ? 'block' : 'none';

  const regime = document.getElementById('itf-regime').value;
  document.getElementById('itf-wrap-csosn').style.display = regime === 'simples' ? 'block' : 'none';
  document.getElementById('itf-wrap-cst').style.display = regime === 'normal' ? 'block' : 'none';
}
function aplicarMascaraNCM(input){
  const d = SolidunsDocs.onlyDigits(input.value).slice(0,8);
  input.value = d.replace(/^(\d{4})(\d{0,2})(\d{0,2}).*$/, (m,a,b,c)=> c ? `${a}.${b}.${c}` : b ? `${a}.${b}` : a);
}
function aplicarMascaraCEST(input){
  const d = SolidunsDocs.onlyDigits(input.value).slice(0,7);
  input.value = d.replace(/^(\d{2})(\d{0,3})(\d{0,2}).*$/, (m,a,b,c)=> c ? `${a}.${b}.${c}` : b ? `${a}.${b}` : a);
}
function aplicarMascaraLC116(input){
  const d = SolidunsDocs.onlyDigits(input.value).slice(0,4);
  input.value = d.replace(/^(\d{2})(\d{0,2}).*$/, (m,a,b)=> b ? `${a}.${b}` : a);
}

function limparFormItemFiscal(){
  document.getElementById('itf-id').value = '';
  document.getElementById('itf-tipo').value = 'produto';
  document.getElementById('itf-codigo').value = '';
  document.getElementById('itf-nome').value = '';
  document.getElementById('itf-unidade').value = '';
  document.getElementById('itf-valor').value = '';
  document.getElementById('itf-ncm').value = '';
  document.getElementById('itf-cest').value = '';
  document.getElementById('itf-lc116').value = '';
  document.getElementById('itf-cfop').value = '';
  document.getElementById('itf-regime').value = 'simples';
  document.getElementById('itf-csosn').value = '';
  document.getElementById('itf-cst').value = '';
  document.getElementById('itf-vigencia-inicio').value = '';
  document.getElementById('itf-vigencia-fim').value = '';
  document.getElementById('itf-ativo').checked = true;
  document.getElementById('itf-form-titulo').textContent = 'Novo produto ou serviço';
  document.getElementById('itf-btn-cancelar').style.display = 'none';
  document.getElementById('itf-form-msg').textContent = '';
  document.getElementById('itf-form-msg').className = 'auth-msg';
  atualizarFormItemFiscal();
}

function salvarItemFiscal(){
  const nomeInput = document.getElementById('itf-nome');
  const ncmInput = document.getElementById('itf-ncm');
  const lc116Input = document.getElementById('itf-lc116');
  const msg = document.getElementById('itf-form-msg');
  const tipo = document.getElementById('itf-tipo').value;
  const regime = document.getElementById('itf-regime').value;

  const regras = [{input: nomeInput, obrigatorio:true, mensagemVazio:'Informe o nome do produto ou serviço.'}];
  if(tipo === 'produto') regras.push({input: ncmInput, obrigatorio:true, mensagemVazio:'Produto exige NCM — sem ele a nota fiscal não sai.'});
  if(tipo === 'servico') regras.push({input: lc116Input, obrigatorio:true, mensagemVazio:'Serviço exige o código de serviço (LC 116).'});
  const valido = validarCampos(regras);
  if(!valido){
    msg.textContent = 'Corrija os campos destacados antes de salvar.';
    msg.className = 'auth-msg erro';
    return;
  }

  const idExistente = document.getElementById('itf-id').value;
  const item = {
    id: idExistente || uid(),
    tipo: tipo,
    codigo: document.getElementById('itf-codigo').value.trim(),
    nome: nomeInput.value.trim(),
    unidade: document.getElementById('itf-unidade').value.trim(),
    valor: parseMoeda(document.getElementById('itf-valor').value),
    ncm: tipo === 'produto' ? ncmInput.value.trim() : '',
    cest: tipo === 'produto' ? document.getElementById('itf-cest').value.trim() : '',
    lc116: tipo === 'servico' ? lc116Input.value.trim() : '',
    cfop: document.getElementById('itf-cfop').value.trim(),
    regime: regime,
    csosn: regime === 'simples' ? document.getElementById('itf-csosn').value : '',
    cst: regime === 'normal' ? document.getElementById('itf-cst').value : '',
    vigenciaInicio: document.getElementById('itf-vigencia-inicio').value,
    vigenciaFim: document.getElementById('itf-vigencia-fim').value,
    ativo: document.getElementById('itf-ativo').checked
  };

  if(idExistente){
    const idx = state.itensFiscais.findIndex(i=>i.id===idExistente);
    if(idx>-1) state.itensFiscais[idx] = item;
  } else {
    state.itensFiscais.push(item);
  }
  salvarEstado();
  limparFormItemFiscal();
  renderItensFiscais();
}

function editarItemFiscal(id){
  const i = state.itensFiscais.find(x=>x.id===id);
  if(!i) return;
  document.getElementById('itf-id').value = i.id;
  document.getElementById('itf-tipo').value = i.tipo;
  document.getElementById('itf-codigo').value = i.codigo || '';
  document.getElementById('itf-nome').value = i.nome;
  document.getElementById('itf-unidade').value = i.unidade || '';
  document.getElementById('itf-valor').value = i.valor ? formatBRL(i.valor) : '';
  document.getElementById('itf-ncm').value = i.ncm || '';
  document.getElementById('itf-cest').value = i.cest || '';
  document.getElementById('itf-lc116').value = i.lc116 || '';
  document.getElementById('itf-cfop').value = i.cfop || '';
  document.getElementById('itf-regime').value = i.regime || 'simples';
  document.getElementById('itf-csosn').value = i.csosn || '';
  document.getElementById('itf-cst').value = i.cst || '';
  document.getElementById('itf-vigencia-inicio').value = i.vigenciaInicio || '';
  document.getElementById('itf-vigencia-fim').value = i.vigenciaFim || '';
  document.getElementById('itf-ativo').checked = i.ativo !== false;
  document.getElementById('itf-form-titulo').textContent = 'Editar produto ou serviço';
  document.getElementById('itf-btn-cancelar').style.display = 'inline-block';
  atualizarFormItemFiscal();
  window.scrollTo(0,0);
}
function cancelarEdicaoItemFiscal(){ limparFormItemFiscal(); }

function excluirItemFiscal(id){
  state.itensFiscais = state.itensFiscais.filter(i=>i.id!==id);
  salvarEstado();
  renderItensFiscais();
}

function renderItensFiscais(){
  const busca = (document.getElementById('itf-busca').value || '').trim().toLowerCase();
  const filtroTipo = document.getElementById('itf-filtro-tipo').value;
  const tbody = document.getElementById('itf-tbody');
  let lista = state.itensFiscais.slice().sort((a,b)=> a.nome.localeCompare(b.nome));
  if(filtroTipo) lista = lista.filter(i=>i.tipo===filtroTipo);
  if(busca){
    lista = lista.filter(i => [i.nome, i.codigo, i.ncm, i.lc116].join(' ').toLowerCase().includes(busca));
  }
  document.getElementById('itf-empty').style.display = lista.length ? 'none' : 'block';
  tbody.innerHTML = lista.map(i=>`
    <tr>
      <td>${i.nome}${i.codigo ? ' <span style="color:var(--ink-soft); font-size:11.5px;">('+i.codigo+')</span>' : ''}</td>
      <td><span class="tag ${i.tipo==='produto'?'receber':'pagar'}">${i.tipo==='produto'?'Produto':'Serviço'}</span></td>
      <td>${i.tipo==='produto' ? (i.ncm || '—') : (i.lc116 || '—')}</td>
      <td>${i.cfop || '—'}</td>
      <td class="num">${i.valor ? formatBRL(i.valor) : '—'}</td>
      <td><span class="tag ${i.ativo!==false?'pago':'pendente'}">${i.ativo!==false?'Ativo':'Inativo'}</span></td>
      <td>
        <button class="ghost" onclick="editarItemFiscal('${i.id}')">Editar</button>
        <button class="ghost" onclick="excluirItemFiscal('${i.id}')">Excluir</button>
      </td>
    </tr>
  `).join('');
}

/* -- Dados fiscais de clientes/fornecedores (edita state.clientesFornecedores, não duplica) -- */
