/* ---------- COMPLIANCE E AUDITORIA (78º prompt) ----------
   Não é motor de compliance fiscal nem cruza nada com SEFAZ/Receita — só
   aponta, nos dados já cadastrados nas outras telas deste app (Empresas,
   Cadastros Fiscais, Documentos Fiscais, Obrigações), o que está faltando
   ou vencendo. Recalculado do zero a cada render — nunca fica desatualizado
   por conta própria. Status (aberto/resolvido) e comentário são guardados
   por chave estável (regra+id do registro); se o dado subjacente for
   corrigido, o alerta some sozinho na próxima leitura, independente do
   status manual guardado. */
function calcularAlertasCompliance(){
  const alertas = [];
  const hoje = new Date(); hoje.setHours(0,0,0,0);
  const em7dias = new Date(hoje); em7dias.setDate(em7dias.getDate()+7);

  state.empresas.forEach(e=>{
    if(!e.cnpj || e.cnpj === '—'){
      alertas.push({chave:'empresa-sem-cnpj-'+e.id, severidade:'bloqueante', regra:'Empresa sem CNPJ', descricao:e.nome, empresa:e.nome, view:'empresas'});
    }
    if(!e.regimeTributario){
      alertas.push({chave:'empresa-sem-regime-'+e.id, severidade:'atencao', regra:'Empresa sem regime tributário definido', descricao:e.nome, empresa:e.nome, view:'fiscal-empresa'});
    }
  });

  state.clientesFornecedores.filter(c=>c.ativo!==false).forEach(c=>{
    if(!c.documento){
      alertas.push({chave:'parceiro-sem-doc-'+c.id, severidade:'atencao', regra:'Cadastro sem CPF/CNPJ', descricao:c.nome, empresa:'—', view:'fin-cadastros'});
    }
  });

  state.itensFiscais.filter(i=>i.ativo!==false).forEach(i=>{
    if(!i.cfop){
      alertas.push({chave:'item-sem-cfop-'+i.id, severidade:'atencao', regra:'Item sem CFOP', descricao:i.nome, empresa:'—', view:'fiscal-cadastros'});
    }
    if(i.regime==='simples' && !i.csosn){
      alertas.push({chave:'item-sem-csosn-'+i.id, severidade:'atencao', regra:'Item sem CSOSN', descricao:i.nome, empresa:'—', view:'fiscal-cadastros'});
    }
    if(i.regime==='normal' && !i.cst){
      alertas.push({chave:'item-sem-cst-'+i.id, severidade:'atencao', regra:'Item sem CST', descricao:i.nome, empresa:'—', view:'fiscal-cadastros'});
    }
  });

  state.documentosFiscais.forEach(d=>{
    if(d.valid_signature === false){
      alertas.push({chave:'doc-assinatura-invalida-'+d.id, severidade:'bloqueante', regra:'Documento com assinatura inválida', descricao:d.nome_arquivo || d.access_key || d.id, empresa:'—', view:'fiscal-documentos'});
    }
    const errosAbertos = (d.issues||[]).filter(i=>i.severity==='error');
    if(errosAbertos.length){
      alertas.push({chave:'doc-com-erros-'+d.id, severidade:'bloqueante', regra:'Documento com pendências de validação', descricao:(d.nome_arquivo || d.access_key || d.id)+' — '+errosAbertos.length+' erro(s)', empresa:'—', view:'fiscal-documentos'});
    }
  });

  state.obrigacoes.forEach(o=>{
    if(!o.prazo) return;
    const prazo = parseDate(o.prazo);
    if(prazo < hoje){
      alertas.push({chave:'obrigacao-vencida-'+o.id, severidade:'bloqueante', regra:'Obrigação vencida', descricao:o.titulo, empresa:o.empresa||'—', view:'obrigacoes'});
    } else if(prazo <= em7dias){
      alertas.push({chave:'obrigacao-vencendo-'+o.id, severidade:'atencao', regra:'Obrigação vencendo em até 7 dias', descricao:o.titulo, empresa:o.empresa||'—', view:'obrigacoes'});
    }
  });

  return alertas;
}

function alternarStatusAlertaCompliance(chave){
  state.statusAlertasCompliance[chave] = state.statusAlertasCompliance[chave]==='resolvido' ? 'aberto' : 'resolvido';
  salvarEstado();
  renderComplianceFiscal();
}
function salvarComentarioAlertaCompliance(chave, valor){
  state.comentariosAlertasCompliance[chave] = valor.trim();
  salvarEstado();
}

function renderComplianceFiscal(){
  const todos = calcularAlertasCompliance();
  const filtroSeveridade = document.getElementById('cpl-filtro-severidade').value;
  const filtroStatus = document.getElementById('cpl-filtro-status').value;
  const statusMap = state.statusAlertasCompliance;
  const comentarioMap = state.comentariosAlertasCompliance;

  document.getElementById('cpl-count-bloqueante').textContent = todos.filter(a=>a.severidade==='bloqueante' && statusMap[a.chave]!=='resolvido').length;
  document.getElementById('cpl-count-atencao').textContent = todos.filter(a=>a.severidade==='atencao' && statusMap[a.chave]!=='resolvido').length;
  document.getElementById('cpl-count-resolvido').textContent = todos.filter(a=>statusMap[a.chave]==='resolvido').length;

  let lista = todos.map(a=> Object.assign({}, a, {status: statusMap[a.chave] || 'aberto', comentario: comentarioMap[a.chave] || ''}));
  if(filtroSeveridade) lista = lista.filter(a=>a.severidade===filtroSeveridade);
  if(filtroStatus) lista = lista.filter(a=>a.status===filtroStatus);

  const ordemSeveridade = {bloqueante:0, atencao:1};
  lista.sort((a,b)=> (ordemSeveridade[a.severidade]-ordemSeveridade[b.severidade]) || a.regra.localeCompare(b.regra));

  const NOMES_SEVERIDADE = {bloqueante:'Bloqueante', atencao:'Atenção'};
  const TAG_SEVERIDADE = {bloqueante:'vencido', atencao:'pendente'};

  document.getElementById('cpl-empty').style.display = lista.length ? 'none' : 'block';
  document.getElementById('cpl-tbody').innerHTML = lista.map(a=>`
    <tr>
      <td><span class="tag ${TAG_SEVERIDADE[a.severidade]}">${NOMES_SEVERIDADE[a.severidade]}</span></td>
      <td>${a.regra}</td>
      <td>${a.descricao}</td>
      <td>${a.empresa}</td>
      <td><span class="tag ${a.status==='resolvido'?'pago':'pendente'}">${a.status==='resolvido'?'Resolvido':'Aberto'}</span></td>
      <td><input type="text" value="${a.comentario.replace(/"/g,'&quot;')}" placeholder="Nota opcional" style="margin:0; padding:6px 8px; font-size:12px;" onchange="salvarComentarioAlertaCompliance('${a.chave}', this.value)"></td>
      <td style="white-space:nowrap;">
        <button class="ghost" onclick="mostrarViewFiscal('${a.view}')">Ir corrigir</button>
        <button class="ghost" onclick="alternarStatusAlertaCompliance('${a.chave}')">${a.status==='resolvido'?'Reabrir':'Marcar resolvido'}</button>
      </td>
    </tr>
  `).join('');
}

/* ---------- DOCUMENTOS E ARQUIVOS (78º prompt) ----------
   Repositório de arquivos ligados à operação fiscal, mas que não são notas
   fiscais em si (SPED gerados, laudos, contratos, comprovantes de
   transmissão) — complementa a caixa de entrada de Documentos Fiscais
   (que já existia). Guarda o arquivo como Data URL dentro do próprio
   state, seguindo o MESMO padrão já usado para fotos/vídeos de imóveis de
   leilão (v1 sem servidor) — com limite de 4 MB por arquivo para não
   inchar o state inteiro, que é salvo como um único blob no storage. */
const LIMITE_ARQUIVO_FISCAL_MB = 4;
const NOMES_CATEGORIA_ARQUIVO_FISCAL = {sped:'SPED', laudo:'Laudo', contrato:'Contrato', comprovante:'Comprovante', outro:'Outro'};

function preencherNomeArquivoFiscal(input){
  const nomeInput = document.getElementById('arf-nome');
  if(input.files[0] && !nomeInput.value.trim()){
    nomeInput.value = input.files[0].name.replace(/\.[^/.]+$/, '');
  }
}

function limparFormArquivoFiscal(){
  document.getElementById('arf-id').value = '';
  document.getElementById('arf-categoria').value = 'sped';
  document.getElementById('arf-nome').value = '';
  document.getElementById('arf-competencia').value = '';
  document.getElementById('arf-descricao').value = '';
  document.getElementById('arf-arquivo').value = '';
  document.getElementById('arf-form-titulo').textContent = 'Novo arquivo';
  document.getElementById('arf-btn-cancelar').style.display = 'none';
  document.getElementById('arf-form-msg').textContent = '';
  document.getElementById('arf-form-msg').className = 'auth-msg';
}

async function salvarArquivoFiscal(){
  const nomeInput = document.getElementById('arf-nome');
  const arquivoInput = document.getElementById('arf-arquivo');
  const msg = document.getElementById('arf-form-msg');
  const idExistente = document.getElementById('arf-id').value;
  const arquivo = arquivoInput.files[0];

  const valido = validarCampos([{input: nomeInput, obrigatorio:true, mensagemVazio:'Informe um nome de exibição.'}]);
  if(!valido){
    msg.textContent = 'Corrija os campos destacados antes de salvar.';
    msg.className = 'auth-msg erro';
    return;
  }
  if(!idExistente && !arquivo){
    msg.textContent = 'Selecione um arquivo.';
    msg.className = 'auth-msg erro';
    return;
  }
  if(arquivo && arquivo.size > LIMITE_ARQUIVO_FISCAL_MB * 1024 * 1024){
    msg.textContent = `Arquivo maior que ${LIMITE_ARQUIVO_FISCAL_MB} MB — não cabe no armazenamento local desta sessão.`;
    msg.className = 'auth-msg erro';
    return;
  }

  const registro = {
    id: idExistente || uid(),
    categoria: document.getElementById('arf-categoria').value,
    empresa: document.getElementById('arf-empresa').value,
    nome: nomeInput.value.trim(),
    competencia: document.getElementById('arf-competencia').value,
    descricao: document.getElementById('arf-descricao').value.trim(),
    dataUpload: idExistente ? (state.arquivosFiscais.find(a=>a.id===idExistente) || {}).dataUpload : new Date().toISOString()
  };

  if(arquivo){
    try{
      registro.arquivoNome = arquivo.name;
      registro.arquivoTipo = arquivo.type;
      registro.arquivoTamanho = arquivo.size;
      registro.arquivoDataUrl = await lerArquivoComoDataURL(arquivo);
    }catch(e){
      msg.textContent = 'Não foi possível ler o arquivo. Tente novamente.';
      msg.className = 'auth-msg erro';
      return;
    }
  } else if(idExistente){
    // Editando só metadados, sem trocar o arquivo -> preserva o conteúdo já salvo.
    const anterior = state.arquivosFiscais.find(a=>a.id===idExistente);
    if(anterior){
      registro.arquivoNome = anterior.arquivoNome;
      registro.arquivoTipo = anterior.arquivoTipo;
      registro.arquivoTamanho = anterior.arquivoTamanho;
      registro.arquivoDataUrl = anterior.arquivoDataUrl;
    }
  }

  if(idExistente){
    const idx = state.arquivosFiscais.findIndex(a=>a.id===idExistente);
    if(idx>-1) state.arquivosFiscais[idx] = registro;
  } else {
    state.arquivosFiscais.push(registro);
  }
  salvarEstado();
  limparFormArquivoFiscal();
  renderArquivosFiscais();
}

function editarArquivoFiscal(id){
  const a = state.arquivosFiscais.find(x=>x.id===id);
  if(!a) return;
  document.getElementById('arf-id').value = a.id;
  document.getElementById('arf-categoria').value = a.categoria;
  document.getElementById('arf-empresa').value = a.empresa || '';
  document.getElementById('arf-nome').value = a.nome;
  document.getElementById('arf-competencia').value = a.competencia || '';
  document.getElementById('arf-descricao').value = a.descricao || '';
  document.getElementById('arf-arquivo').value = '';
  document.getElementById('arf-form-titulo').textContent = 'Editar arquivo (deixe o campo de arquivo vazio para manter o já salvo)';
  document.getElementById('arf-btn-cancelar').style.display = 'inline-block';
  window.scrollTo(0, document.getElementById('arf-form-titulo').offsetTop - 80);
}
function cancelarEdicaoArquivoFiscal(){ limparFormArquivoFiscal(); }
function excluirArquivoFiscal(id){
  state.arquivosFiscais = state.arquivosFiscais.filter(a=>a.id!==id);
  salvarEstado();
  renderArquivosFiscais();
}

function formatarTamanhoArquivo(bytes){
  if(!bytes) return '—';
  if(bytes < 1024*1024) return (bytes/1024).toFixed(0) + ' KB';
  return (bytes/(1024*1024)).toFixed(1) + ' MB';
}
function formatarCompetenciaArquivo(competencia){
  if(!competencia) return '—';
  const [ano, mes] = competencia.split('-');
  const nomesMes = ['jan','fev','mar','abr','mai','jun','jul','ago','set','out','nov','dez'];
  return `${nomesMes[parseInt(mes,10)-1]}/${ano}`;
}

function renderArquivosFiscais(){
  const busca = (document.getElementById('arf-busca').value || '').trim().toLowerCase();
  const filtroCategoria = document.getElementById('arf-filtro-categoria').value;
  const filtroEmpresa = document.getElementById('arf-filtro-empresa').value;
  const tbody = document.getElementById('arf-tbody');
  let lista = state.arquivosFiscais.slice().sort((a,b)=> new Date(b.dataUpload) - new Date(a.dataUpload));
  if(filtroCategoria) lista = lista.filter(a=>a.categoria===filtroCategoria);
  if(filtroEmpresa) lista = lista.filter(a=>a.empresa===filtroEmpresa);
  if(busca) lista = lista.filter(a=>a.nome.toLowerCase().includes(busca));

  document.getElementById('arf-empty').style.display = lista.length ? 'none' : 'block';
  tbody.innerHTML = lista.map(a=>{
    const dataFmt = a.dataUpload ? new Date(a.dataUpload).toLocaleDateString('pt-BR') : '—';
    const linkVer = a.arquivoDataUrl ? `<a href="${a.arquivoDataUrl}" target="_blank" rel="noopener" download="${a.arquivoNome||a.nome}">Baixar</a>` : '—';
    return `
    <tr>
      <td>${a.nome}${a.descricao ? '<br><span style="color:var(--ink-soft); font-size:11.5px;">'+a.descricao+'</span>' : ''}</td>
      <td><span class="tag pendente">${NOMES_CATEGORIA_ARQUIVO_FISCAL[a.categoria] || a.categoria}</span></td>
      <td>${a.empresa || '—'}</td>
      <td>${formatarCompetenciaArquivo(a.competencia)}</td>
      <td class="num">${formatarTamanhoArquivo(a.arquivoTamanho)}</td>
      <td>${dataFmt}</td>
      <td>
        ${linkVer}
        <button class="ghost" onclick="editarArquivoFiscal('${a.id}')">Editar</button>
        <button class="ghost" onclick="excluirArquivoFiscal('${a.id}')">Excluir</button>
      </td>
    </tr>`;
  }).join('');
}


/* ---------- FLUXO DE CAIXA — relatório real (Parte 5 do manual) ----------
   Diário: cada linha é um dia, valores REALIZADOS (data da baixa).
   Mensal: previsto (vencimento) x realizado (baixa), com geração de caixa
   e saldo final do período no rodapé. Ambos leem baixas de state.transacoes
   e state.transferencias — nenhuma tabela nova de lançamento é criada aqui. */
let __fluxoCaixaModo = 'diario';

function trocarModoFluxoCaixa(modo){
  __fluxoCaixaModo = modo;
  document.getElementById('fx-modo-diario').classList.toggle('active', modo==='diario');
  document.getElementById('fx-modo-mensal').classList.toggle('active', modo==='mensal');
  renderCaixa();
}

function contasFiltroFluxoCaixa(){
  const fEmpresa = document.getElementById('cx-filtro-empresa').value;
  return fEmpresa ? state.contasFinanceiras.filter(c=>c.empresa===fEmpresa) : state.contasFinanceiras;
}

function renderChipsContasFluxoCaixa(){
  const wrap = document.getElementById('fx-contas-lista');
  const contas = contasFiltroFluxoCaixa();
  document.getElementById('fx-contas-vazio').style.display = contas.length ? 'none' : 'block';
  const marcadasAntes = {};
  wrap.querySelectorAll('.fx-conta-check').forEach(chk=> marcadasAntes[chk.value] = chk.checked);
  wrap.innerHTML = contas.map(c=>{
    const jaVista = c.id in marcadasAntes;
    const marcada = jaVista ? marcadasAntes[c.id] : c.ativo;
    return '<label class="fx-conta-chip ' + (c.ativo?'':'inativa') + '">' +
      '<input type="checkbox" class="fx-conta-check" value="' + c.id + '" ' + (marcada?'checked':'') + ' onchange="renderCaixa()">' +
      c.nome + ' <span class="cf-tipo-tag">' + (c.ativo?'':'(inativa) ') + (NOMES_TIPO_CONTA[c.tipo]||'') + '</span></label>';
  }).join('');
}
function contasSelecionadasFluxoCaixa(){
  return Array.from(document.querySelectorAll('.fx-conta-check:checked')).map(el=>el.value);
}

function baixaLiquida(b){
  return (b.valorEfetivo||0) + (b.juros||0) + (b.multa||0) - (b.desconto||0) - (b.tarifa||0);
}
function baixaContaOk(b, contasSel){
  if(state.contasFinanceiras.length === 0) return true; // sem cadastro ainda: não filtra por conta
  if(!b.contaFinanceiraId) return true; // baixa antiga, sem conta atribuída: não some do relatório
  return contasSel.includes(b.contaFinanceiraId);
}
function saldoAcumuladoAte(contasSel, dataLimiteExclusiva, fEmpresa){
  let total = 0;
  state.contasFinanceiras.filter(c=>contasSel.includes(c.id)).forEach(c=> total += (c.saldoInicial||0));
  state.transacoes.forEach(t=>{
    if(fEmpresa && t.empresa !== fEmpresa) return;
    (t.baixas||[]).forEach(b=>{
      if(b.data >= dataLimiteExclusiva) return;
      if(!baixaContaOk(b, contasSel)) return;
      total += (t.tipo==='receber' ? baixaLiquida(b) : -baixaLiquida(b));
    });
  });
  state.transferencias.forEach(tr=>{
    if(fEmpresa && tr.empresa !== fEmpresa) return;
    if(tr.data >= dataLimiteExclusiva) return;
    if(contasSel.includes(tr.destinoId)) total += tr.valor;
    if(contasSel.includes(tr.origemId)) total -= tr.valor;
  });
  return total;
}
function movimentoRealizadoDia(dataStr, contasSel, fEmpresa){
  let recebido = 0, pago = 0, transferenciaLiquida = 0;
  const porCategoria = {};
  state.transacoes.forEach(t=>{
    if(fEmpresa && t.empresa !== fEmpresa) return;
    (t.baixas||[]).forEach(b=>{
      if(b.data !== dataStr) return;
      if(!baixaContaOk(b, contasSel)) return;
      const v = baixaLiquida(b);
      if(t.tipo==='receber') recebido += v; else pago += v;
      porCategoria[t.categoria] = (porCategoria[t.categoria]||0) + (t.tipo==='receber' ? v : -v);
    });
  });
  state.transferencias.forEach(tr=>{
    if(fEmpresa && tr.empresa !== fEmpresa) return;
    if(tr.data !== dataStr) return;
    if(contasSel.includes(tr.destinoId)) transferenciaLiquida += tr.valor;
    if(contasSel.includes(tr.origemId)) transferenciaLiquida -= tr.valor;
  });
  return {recebido, pago, transferenciaLiquida, porCategoria};
}
function somaDias(inicio, fim, cb){
  let d = parseDate(inicio);
  const fimD = parseDate(fim);
  while(d <= fimD){
    cb(d.toISOString().slice(0,10));
    d.setDate(d.getDate()+1);
  }
}

function renderCaixa(){
  const inicioEl = document.getElementById('fx-inicio');
  const fimEl = document.getElementById('fx-fim');
  if(!inicioEl || !fimEl) return; // view ainda não montada nesta tela
  if(!fimEl.value){
    const hoje = new Date();
    fimEl.value = hoje.toISOString().slice(0,10);
    const ini = new Date(); ini.setDate(hoje.getDate()-29);
    inicioEl.value = ini.toISOString().slice(0,10);
  }
  const fEmpresa = document.getElementById('cx-filtro-empresa').value;
  const inicio = inicioEl.value, fim = fimEl.value;

  renderChipsContasFluxoCaixa();
  const contasSel = contasSelecionadasFluxoCaixa();

  const thead = document.getElementById('fx-thead');
  const tbody = document.getElementById('fx-tbody');
  const empty = document.getElementById('fx-empty');
  if(!inicio || !fim || inicio > fim){
    thead.innerHTML = ''; tbody.innerHTML = '';
    empty.style.display = 'block';
    empty.textContent = 'Informe um período válido (data final não pode vir antes da inicial).';
    return;
  }

  let totalRecebidoPeriodo = 0, totalPagoPeriodo = 0;
  const linhas = [];

  if(__fluxoCaixaModo === 'diario'){
    document.getElementById('fx-tabela-titulo').textContent = 'Fluxo de caixa diário';
    document.getElementById('fx-tabela-legenda').textContent = 'Cada linha é um dia. Saldo do dia negativo = naquele dia saiu mais do que entrou. Valores realizados (data da baixa), não previsão. Considera automaticamente só as contas selecionadas acima.';
    document.getElementById('fx-label-recebido').textContent = 'Recebido no período';
    document.getElementById('fx-label-pago').textContent = 'Pago no período';
    thead.innerHTML = '<tr><th>Data</th><th class="num">Saldo inicial do dia</th><th class="num">Recebimentos</th><th class="num">Pagamentos</th><th class="num">Transferências</th><th class="num">Saldo do dia</th><th class="num">Saldo acumulado</th></tr>';
    let saldoAcumulado = saldoAcumuladoAte(contasSel, inicio, fEmpresa);
    somaDias(inicio, fim, (dataStr)=>{
      const mov = movimentoRealizadoDia(dataStr, contasSel, fEmpresa);
      const saldoInicialDia = saldoAcumulado;
      const saldoDoDia = mov.recebido - mov.pago + mov.transferenciaLiquida;
      saldoAcumulado += saldoDoDia;
      totalRecebidoPeriodo += mov.recebido; totalPagoPeriodo += mov.pago;
      linhas.push('<tr>' +
        '<td>' + parseDate(dataStr).toLocaleDateString('pt-BR', {weekday:'short', day:'2-digit', month:'2-digit'}) + '</td>' +
        '<td class="num">' + formatBRL(saldoInicialDia) + '</td>' +
        '<td class="num">' + (mov.recebido>0?formatBRL(mov.recebido):'—') + '</td>' +
        '<td class="num">' + (mov.pago>0?formatBRL(mov.pago):'—') + '</td>' +
        '<td class="num">' + (mov.transferenciaLiquida!==0?formatBRL(mov.transferenciaLiquida):'—') + '</td>' +
        '<td class="num" style="color:' + (saldoDoDia<0?'var(--rust)':'inherit') + ';">' + formatBRL(saldoDoDia) + '</td>' +
        '<td class="num" style="font-weight:600;">' + formatBRL(saldoAcumulado) + '</td>' +
      '</tr>');
    });
    document.getElementById('fx-saldo-final').textContent = formatBRL(saldoAcumulado);
  } else {
    document.getElementById('fx-tabela-titulo').textContent = 'Fluxo de caixa mensal';
    document.getElementById('fx-tabela-legenda').textContent = 'Previsto = data de vencimento (era para entrar ou sair). Realizado = data da baixa (entrou ou saiu de verdade). Se todas as contas ficarem marcadas, o mensal soma até conta encerrada — desmarque as encerradas para bater com o diário.';
    document.getElementById('fx-label-recebido').textContent = 'Realizado — recebido';
    document.getElementById('fx-label-pago').textContent = 'Realizado — pago';
    thead.innerHTML = '<tr><th>Mês</th><th class="num">Previsto a receber</th><th class="num">Previsto a pagar</th><th class="num">Realizado — recebido</th><th class="num">Realizado — pago</th><th class="num">Geração de caixa</th><th class="num">Saldo acumulado</th></tr>';
    const meses = [];
    let cursor = inicio.slice(0,7);
    const fimMes = fim.slice(0,7);
    while(cursor <= fimMes){
      meses.push(cursor);
      const partes = cursor.split('-').map(Number);
      const prox = new Date(partes[0], partes[1], 1); // partes[1] já é o mês seguinte em índice 0-based
      cursor = prox.getFullYear()+'-'+String(prox.getMonth()+1).padStart(2,'0');
    }
    let saldoAcumulado = saldoAcumuladoAte(contasSel, inicio.slice(0,7)+'-01', fEmpresa);
    meses.forEach(mes=>{
      const partesMes = mes.split('-').map(Number);
      const y = partesMes[0], m = partesMes[1];
      let previstoReceber = 0, previstoPagar = 0, realizadoReceber = 0, realizadoPagar = 0;
      state.transacoes.forEach(t=>{
        if(fEmpresa && t.empresa !== fEmpresa) return;
        if(t.vencimento && t.vencimento.slice(0,7) === mes){
          if(t.tipo==='receber') previstoReceber += t.valor; else previstoPagar += t.valor;
        }
        (t.baixas||[]).forEach(b=>{
          if(b.data.slice(0,7) !== mes) return;
          if(!baixaContaOk(b, contasSel)) return;
          const v = baixaLiquida(b);
          if(t.tipo==='receber') realizadoReceber += v; else realizadoPagar += v;
        });
      });
      let transferenciaMes = 0;
      state.transferencias.forEach(tr=>{
        if(fEmpresa && tr.empresa !== fEmpresa) return;
        if(tr.data.slice(0,7) !== mes) return;
        if(contasSel.includes(tr.destinoId)) transferenciaMes += tr.valor;
        if(contasSel.includes(tr.origemId)) transferenciaMes -= tr.valor;
      });
      const geracaoMes = realizadoReceber - realizadoPagar + transferenciaMes;
      saldoAcumulado += geracaoMes;
      totalRecebidoPeriodo += realizadoReceber; totalPagoPeriodo += realizadoPagar;
      const nomeMes = new Date(y, m-1, 1).toLocaleDateString('pt-BR', {month:'long', year:'numeric'});
      linhas.push('<tr>' +
        '<td style="text-transform:capitalize;">' + nomeMes + '</td>' +
        '<td class="num">' + formatBRL(previstoReceber) + '</td>' +
        '<td class="num">' + formatBRL(previstoPagar) + '</td>' +
        '<td class="num">' + formatBRL(realizadoReceber) + '</td>' +
        '<td class="num">' + formatBRL(realizadoPagar) + '</td>' +
        '<td class="num" style="color:' + (geracaoMes<0?'var(--rust)':'inherit') + ';">' + formatBRL(geracaoMes) + '</td>' +
        '<td class="num" style="font-weight:600;">' + formatBRL(saldoAcumulado) + '</td>' +
      '</tr>');
    });
    document.getElementById('fx-saldo-final').textContent = formatBRL(saldoAcumulado);
  }

  tbody.innerHTML = linhas.join('');
  empty.style.display = linhas.length ? 'none' : 'block';
  empty.textContent = 'Nenhuma movimentação realizada (baixada) no período e nas contas selecionadas.';
  document.getElementById('fx-total-recebido').textContent = formatBRL(totalRecebidoPeriodo);
  document.getElementById('fx-total-pago').textContent = formatBRL(totalPagoPeriodo);
  document.getElementById('fx-geracao').textContent = formatBRL(totalRecebidoPeriodo - totalPagoPeriodo);

  renderCategoriasFluxoNoRelatorio(inicio, fim, fEmpresa, contasSel);
}

function renderCategoriasFluxoNoRelatorio(inicio, fim, fEmpresa, contasSel){
  const wrap = document.getElementById('fx-categorias-lista');
  const vazio = document.getElementById('fx-categorias-vazio');
  if(!wrap) return;
  const porCategoriaFinanceira = {};
  let totalAbsoluto = 0;
  somaDias(inicio, fim, (dataStr)=>{
    const mov = movimentoRealizadoDia(dataStr, contasSel, fEmpresa);
    Object.keys(mov.porCategoria).forEach(cat=>{
      porCategoriaFinanceira[cat] = (porCategoriaFinanceira[cat]||0) + mov.porCategoria[cat];
      totalAbsoluto += Math.abs(mov.porCategoria[cat]);
    });
  });
  const categoriasTopo = state.categoriasFluxo.filter(c=>c.tipo==='categoria');
  const linhas = categoriasTopo.map(c=>{
    const subs = state.categoriasFluxo.filter(s=>s.tipo==='subcategoria' && s.paiId===c.id);
    let todasFinanceiras = (c.categoriasFinanceiras||[]).slice();
    subs.forEach(s=>{ todasFinanceiras = todasFinanceiras.concat(s.categoriasFinanceiras||[]); });
    const valor = todasFinanceiras.reduce((s,f)=> s + Math.abs(porCategoriaFinanceira[f]||0), 0);
    return {nome: c.nome, valor};
  }).filter(l=>l.valor > 0);
  vazio.style.display = linhas.length ? 'none' : 'block';
  wrap.innerHTML = linhas.sort((a,b)=>b.valor-a.valor).map(l=>{
    const pct = totalAbsoluto > 0 ? (l.valor/totalAbsoluto*100) : 0;
    return '<div class="fx-cat-linha">' +
      '<div class="fx-cat-topo"><span>' + l.nome + '</span><span>' + formatBRL(l.valor) + ' — ' + pct.toFixed(1) + '%</span></div>' +
      '<div class="fx-cat-barra-fundo"><div class="fx-cat-barra" style="width:' + pct.toFixed(1) + '%;"></div></div>' +
    '</div>';
  }).join('');
}

/* ---------- CONCILIAÇÃO BANCÁRIA (73º prompt) ----------
   Bate a lista do banco (state.extratoBancario) com o que já foi lançado
   em Contas a Pagar/Receber (state.transacoes). Conciliar = criar uma
   baixa de verdade (mesma baixas[] usada em Contas a Pagar/Receber e no
   Fluxo de Caixa), então tudo que bate aqui já aparece certo lá.
   v1: extrato demo ou OFX enviado pelo usuário. Sem Open Finance ligado,
   sem senha de banco, sem fetch em servidor de terceiro. */
let __ccLinhaBancoSelecionadaId = null;
let __ofxPendente = null;

function contaConciliacaoSelecionada(){
  const sel = document.getElementById('cc-conta');
  return sel ? sel.value : '';
}

function popularSelectContaConciliacao(){
  const sel = document.getElementById('cc-conta');
  if(!sel) return;
  const atual = sel.value;
  sel.innerHTML = '<option value="">-- Selecione uma conta --</option>' +
    state.contasFinanceiras.map(c=>'<option value="'+c.id+'">'+c.nome+' ('+c.empresa+')</option>').join('');
  if(state.contasFinanceiras.some(c=>c.id===atual)) sel.value = atual;
}
function popularSelectsCriarTransferencia(){
  const contaId = contaConciliacaoSelecionada();
  ['cc-criar-origem','cc-criar-destino'].forEach(id=>{
    const sel = document.getElementById(id);
    if(!sel) return;
    const atual = sel.value;
    sel.innerHTML = state.contasFinanceiras.filter(c=>c.ativo).map(c=>'<option value="'+c.id+'">'+c.nome+' ('+c.empresa+')</option>').join('');
    if(state.contasFinanceiras.some(c=>c.id===atual)) sel.value = atual;
    else if(id==='cc-criar-origem' && contaId) sel.value = contaId;
  });
}

function linhasBancoFiltradas(){
  const contaId = contaConciliacaoSelecionada();
  if(!contaId) return [];
  const inicio = document.getElementById('cc-inicio').value;
  const fim = document.getElementById('cc-fim').value;
  const status = document.getElementById('cc-status').value;
  return state.extratoBancario.filter(l=>{
    if(l.contaFinanceiraId !== contaId) return false;
    if(inicio && l.data < inicio) return false;
    if(fim && l.data > fim) return false;
    if(status && l.status !== status) return false;
    return true;
  }).sort((a,b)=> b.data.localeCompare(a.data));
}

/* candidatosParaConta — por padrão só traz lançamentos da MESMA empresa
   da conta financeira (equivalente, nesta v1, a "somente a mesma conta"
   — contas a pagar/receber só ganham conta financeira quando baixadas).
   Desligar a regra "Somente a mesma conta financeira" amplia a busca
   para todas as empresas — não recomendado, existe para o 75º prompt. */
function candidatosParaConta(contaId){
  const conta = state.contasFinanceiras.find(c=>c.id===contaId);
  if(!conta) return [];
  if(state.regrasConciliacao.somenteMesmaConta === false){
    return state.transacoes.filter(t=> statusCalculadoTransacao(t) !== 'pago');
  }
  return state.transacoes.filter(t=> t.empresa === conta.empresa && statusCalculadoTransacao(t) !== 'pago');
}
function diasEntre(dataA, dataB){
  return Math.round((parseDate(dataA) - parseDate(dataB)) / 86400000);
}

/* sugerirCandidatos — bloco real pedido no 73º prompt, ampliado no 74º/75º
   para respeitar os toggles de Configurar regras.
   Exata roda antes de tudo (é o próprio critério mais restritivo).
   Crédito do banco (valor >= 0) só casa com "a receber"; débito só com
   "a pagar" — a menos que "Respeitar sinal" esteja desligado. */
function sugerirCandidatos(linhaBanco){
  const regras = state.regrasConciliacao;
  const tipoEsperado = linhaBanco.valor >= 0 ? 'receber' : 'pagar';
  const valorAbs = Math.abs(linhaBanco.valor);
  let base = candidatosParaConta(linhaBanco.contaFinanceiraId);
  if(regras.respeitarSinal !== false) base = base.filter(t=>t.tipo===tipoEsperado);

  const resultado = base.map(t=>{
    const saldoAberto = t.valor - valorPagoTransacao(t);
    const diasVenc = Math.abs(diasEntre(linhaBanco.data, t.vencimento));
    const ultimaBaixa = (t.baixas||[]).length ? t.baixas[t.baixas.length-1].data : null;
    const diasBaixa = ultimaBaixa ? Math.abs(diasEntre(linhaBanco.data, ultimaBaixa)) : null;
    const diasMinimos = diasBaixa!==null ? Math.min(diasVenc, diasBaixa) : diasVenc;
    const mesmoValor = Math.abs(saldoAberto - valorAbs) < 0.005;
    const deltaPct = valorAbs > 0 ? Math.abs(saldoAberto - valorAbs) / valorAbs * 100 : 100;
    // Robô da aproximada exige valor idêntico por padrão; se a regra for
    // desligada (não recomendado — ver manual), aceita a tolerância da
    // sugestão também na faixa aproximada.
    const aproximadaOk = regras.robotAproximadaExigeValorIdentico !== false
      ? mesmoValor
      : (mesmoValor || deltaPct <= regras.toleranciaSugestaoPct + 1e-9);

    let tier = 'nenhum';
    if(mesmoValor && diasMinimos === 0) tier = 'exata';
    else if(aproximadaOk && diasMinimos <= regras.janelaAproximadaDias) tier = 'aproximada';
    else if(diasMinimos <= regras.janelaSugestaoDias && deltaPct <= regras.toleranciaSugestaoPct + 1e-9) tier = 'sugestao';

    return {transacao: t, tier, diasMinimos, deltaPct, saldoAberto};
  }).filter(c=>c.tier !== 'nenhum');

  const ordem = {exata:0, aproximada:1, sugestao:2};
  resultado.sort((a,b)=> (ordem[a.tier]-ordem[b.tier]) || (a.diasMinimos-b.diasMinimos));
  return resultado;
}

/* candidatoTemBonusNome — 74º/75º prompt. Se o nome do lançamento (ou
   parte dele, palavras de 3+ letras) aparece no memo da linha do banco,
   esse candidato "vence" um empate por nome — deixa de ser empate. */
function candidatoTemBonusNome(transacao, linhaBanco){
  if(state.regrasConciliacao.bonusNomeContraparte === false) return false;
  const palavras = normalizarTexto(transacao.descricao||'').split(/\s+/).filter(w=>w.length>=3);
  if(!palavras.length) return false;
  const palavrasBanco = normalizarTexto(linhaBanco.descricao||'').split(/\s+/);
  return palavras.some(p=> palavrasBanco.includes(p));
}

/* avaliarEmpate — 74º prompt. Empate = dois ou mais candidatos servem
   com a MESMA força (melhor faixa disponível) para uma linha, e nenhum
   tem bônus exclusivo de nome. 1:N (soma de vários = valor do banco)
   NÃO é empate — é escolha manual de múltiplos candidatos, outro fluxo. */
function avaliarEmpate(linhaBanco){
  const candidatos = sugerirCandidatos(linhaBanco);
  if(candidatos.length === 0) return {tier:null, empate:false, vencedor:null, empatados:[]};
  const melhorTier = candidatos[0].tier;
  const doMelhorTier = candidatos.filter(c=>c.tier===melhorTier);
  if(doMelhorTier.length === 1){
    return {tier:melhorTier, empate:false, vencedor:doMelhorTier[0], empatados:[]};
  }
  const comBonus = doMelhorTier.filter(c=> candidatoTemBonusNome(c.transacao, linhaBanco));
  if(comBonus.length === 1){
    return {tier:melhorTier, empate:false, vencedor:comBonus[0], empatados:doMelhorTier};
  }
  return {tier:melhorTier, empate:true, vencedor:null, empatados:doMelhorTier};
}

/* casarAutomatico — bloco real pedido no 73º prompt.
   Exata primeiro, depois aproximada. Nunca toca linha já conciliada
   (só processa status==='pendente'). Empate (2+ candidatos na melhor
   faixa, sem bônus de nome) nunca fecha sozinho — fica com status
   "empate", esperando escolha manual (75º prompt: opção travada). */
function casarAutomatico(){
  const contaId = contaConciliacaoSelecionada();
  const msg = document.getElementById('cc-import-msg');
  if(!contaId){
    msg.textContent = 'Escolha uma conta financeira antes de tentar o casamento automático.';
    msg.className = 'auth-msg erro';
    return;
  }
  const regras = state.regrasConciliacao;
  const pendentes = state.extratoBancario.filter(l=>l.contaFinanceiraId===contaId && l.status==='pendente');
  let fechadosExata = 0, fechadosAproximada = 0, empatados = 0;
  let fechadosBaixa = 0;   /* v106-GF (GF17) */

  /* v106-GF (GF17): antes de procurar títulos EM ABERTO, procurar BAIXAS JÁ
     LANÇADAS nesta conta com a mesma data, mesmo valor líquido e mesmo
     sentido. Achou exatamente uma (ainda não usada): a linha é conciliada
     SEM criar baixa nova. Duas ou mais iguais: "Empate — escolha". */
  const baixasJaConciliadas = {};
  (state.conciliacoes||[]).forEach(c=>{ if(c.baixaId) baixasJaConciliadas[c.baixaId] = true; });
  function conciliarComBaixaExistente(linha, janelaDias){
    const alvoValor = Math.abs(linha.valor);
    const tipoEsperado = linha.valor >= 0 ? 'receber' : 'pagar';
    const achadas = [];
    state.transacoes.forEach(t=>{
      if(t.tipo !== tipoEsperado) return;
      (t.baixas||[]).forEach(bx=>{
        if(bx.contaFinanceiraId !== contaId) return;
        if(baixasJaConciliadas[bx.id]) return;
        if(Math.abs(diasEntre(linha.data, bx.data)) > janelaDias) return;
        if(Math.abs(baixaLiquida(bx) - alvoValor) >= 0.005) return;
        achadas.push({t, bx});
      });
    });
    if(achadas.length === 0) return false;
    if(achadas.length > 1){
      linha.status = 'empate';
      empatados++;
      return true;   // tratada (ficou para escolha manual)
    }
    const {t, bx} = achadas[0];
    baixasJaConciliadas[bx.id] = true;
    linha.status = 'conciliada';
    state.conciliacoes.push({id: uid(), contaFinanceiraId: contaId, bancoLinhaId: linha.id,
                             tipo: 'baixa-existente', transacaoIds: [t.id], baixaId: bx.id,
                             observacao: 'Conciliada com baixa já lançada (' + (t.descricao||'') + ')'});
    fechadosBaixa++;
    return true;
  }
  /* mesmo dia primeiro; depois, se a regra da aproximada estiver ligada,
     a janela de dias que já vale para os títulos (padrão: 5). */
  pendentes.forEach(l=>{ if(l.status === 'pendente') conciliarComBaixaExistente(l, 0); });
  if(regras.autoAplicarAproximada !== false){
    pendentes.forEach(l=>{ if(l.status === 'pendente') conciliarComBaixaExistente(l, regras.janelaAproximadaDias || 5); });
  }

  function tentarFechar(linha, tierAlvo){
    const avaliacao = avaliarEmpate(linha);
    if(avaliacao.tier !== tierAlvo) return false;
    if(avaliacao.empate){
      linha.status = 'empate';
      empatados++;
      return false;
    }
    const escolhido = avaliacao.vencedor.transacao;
    const saldoAberto = escolhido.valor - valorPagoTransacao(escolhido);
    const baixaId = uid();
    if(!escolhido.baixas) escolhido.baixas = [];
    escolhido.baixas.push({id: baixaId, data: linha.data, valorEfetivo: saldoAberto, juros:0, multa:0, desconto:0, tarifa:0, observacoes:'Casamento automático', contaFinanceiraId: contaId});
    escolhido.status = statusCalculadoTransacao(escolhido);
    linha.status = 'conciliada';
    state.conciliacoes.push({id: uid(), contaFinanceiraId: contaId, bancoLinhaId: linha.id, tipo:'transacoes', transacaoIds:[escolhido.id], baixaIds:[baixaId], transferenciaId:null, origemMatch:'automatica', data: new Date().toISOString().slice(0,10)});
    return true;
  }

  if(regras.autoAplicarExata) pendentes.forEach(l=>{ if(l.status==='pendente' && tentarFechar(l, 'exata')) fechadosExata++; });
  if(regras.autoAplicarAproximada) pendentes.forEach(l=>{ if(l.status==='pendente' && tentarFechar(l, 'aproximada')) fechadosAproximada++; });

  salvarEstado();
  renderTudo();
  msg.textContent = 'Casamento automático: ' + fechadosBaixa + ' conferida(s) com baixa já lançada, '
    + fechadosExata + ' exata(s), ' + fechadosAproximada + ' aproximada(s) fechada(s)' +
    (empatados>0 ? ', ' + empatados + ' com selo Empate — escolha (dois ou mais lançamentos servem igual; escolha na mão).' : '.');
  msg.className = 'auth-msg sucesso';
}

/* ---------- RENDER PRINCIPAL ---------- */
function renderConciliacao(){
  if(!document.getElementById('cc-conta')) return;
  popularSelectContaConciliacao();
  if(!document.getElementById('cc-inicio').value || !document.getElementById('cc-fim').value){
    const hoje = new Date();
    document.getElementById('cc-fim').value = hoje.toISOString().slice(0,10);
    const ini = new Date(); ini.setDate(hoje.getDate()-60);
    document.getElementById('cc-inicio').value = ini.toISOString().slice(0,10);
  }
  const contaId = contaConciliacaoSelecionada();
  const linhas = linhasBancoFiltradas();
  const tbody = document.getElementById('cc-banco-tbody');
  const vazio = document.getElementById('cc-banco-empty');

  if(!contaId){
    tbody.innerHTML = '';
    vazio.style.display = 'block';
    vazio.textContent = 'Escolha uma conta financeira para ver o extrato.';
  } else {
    vazio.style.display = linhas.length ? 'none' : 'block';
    vazio.textContent = 'Nenhuma linha do banco neste filtro. Carregue o extrato demo ou importe um OFX acima.';
    const NOMES_ORIGEM = {demo:'Demo', ofx:'OFX', api:'API'};
    const NOMES_STATUS_BANCO = {pendente:'Pendente', empate:'Empate — escolha', conciliada:'Conciliada', arquivada:'Arquivada'};
    tbody.innerHTML = linhas.map(l=>{
      const selecionada = l.id === __ccLinhaBancoSelecionadaId;
      const corValor = l.valor < 0 ? 'var(--rust)' : 'var(--teal)';
      const tagClasse = l.status==='conciliada' ? 'pago' : l.status==='empate' ? 'empate' : l.status==='arquivada' ? '' : 'pendente';
      return '<tr class="cc-linha-banco ' + (selecionada?'selecionada':'') + '" onclick="selecionarLinhaBanco(\'' + l.id + '\')">' +
        '<td>' + (l.status==='conciliada' ? '&check;' : '') + '</td>' +
        '<td>' + parseDate(l.data).toLocaleDateString('pt-BR') + '</td>' +
        '<td>' + l.descricao + '</td>' +
        '<td class="num" style="color:' + corValor + ';">' + formatBRL(l.valor) + '</td>' +
        '<td>' + (NOMES_ORIGEM[l.origem]||l.origem) + '</td>' +
        '<td><span class="tag ' + tagClasse + '">' + NOMES_STATUS_BANCO[l.status] + '</span></td>' +
      '</tr>';
    }).join('');
  }

  const linhaSel = linhas.find(l=>l.id===__ccLinhaBancoSelecionadaId) || null;
  renderColunaSoliduns(linhaSel);
  renderPainelAcoesConciliacao(linhaSel);
  renderRodapeConciliacao(contaId);
}

function renderColunaSoliduns(linhaBanco){
  const tbody = document.getElementById('cc-soliduns-tbody');
  const vazio = document.getElementById('cc-soliduns-empty');
  const legenda = document.getElementById('cc-soliduns-legenda');
  if(!linhaBanco){
    tbody.innerHTML = '';
    vazio.style.display = 'block';
    vazio.textContent = 'Selecione uma linha do banco à esquerda.';
    legenda.textContent = '— clique numa linha do banco para ver candidatos';
    return;
  }
  const regras = state.regrasConciliacao;
  const tipoEsperado = linhaBanco.valor >= 0 ? 'receber' : 'pagar';
  const candidatosComTier = sugerirCandidatos(linhaBanco);
  const mapaTier = {};
  candidatosComTier.forEach(c=> mapaTier[c.transacao.id] = c);

  // Se a própria linha está com selo de empate, restringe os checkboxes
  // aos candidatos empatados — o resto só aparece pra contexto, sem
  // caixa de marcar (74º prompt: "checkboxes só nos empatados").
  let idsEmpatados = null;
  if(linhaBanco.status === 'empate'){
    const avaliacao = avaliarEmpate(linhaBanco);
    idsEmpatados = new Set(avaliacao.empatados.map(c=>c.transacao.id));
    legenda.textContent = '— empate: marque o lançamento certo (destacado)';
  } else {
    legenda.textContent = '';
  }

  const ordem = {exata:0, aproximada:1, sugestao:2};
  let base = candidatosParaConta(linhaBanco.contaFinanceiraId);
  if(regras.respeitarSinal !== false) base = base.filter(t=>t.tipo===tipoEsperado);
  const todos = base.sort((a,b)=>{
      const ta = mapaTier[a.id] ? ordem[mapaTier[a.id].tier] : 3;
      const tb = mapaTier[b.id] ? ordem[mapaTier[b.id].tier] : 3;
      return ta - tb || a.vencimento.localeCompare(b.vencimento);
    });
  vazio.style.display = todos.length ? 'none' : 'block';
  vazio.textContent = 'Nenhum lançamento em aberto desse tipo, nesta empresa.';
  const NOMES_TIER = {exata:'Exata', aproximada:'Aproximada', sugestao:'Sugestão'};
  tbody.innerHTML = todos.map(t=>{
    const c = mapaTier[t.id];
    const saldoAberto = t.valor - valorPagoTransacao(t);
    const tierClasse = c ? ('cc-tier-'+c.tier) : 'cc-tier-nenhum';
    const tierTexto = c ? NOMES_TIER[c.tier] : '—';
    const restrito = idsEmpatados !== null;
    const destacada = restrito && idsEmpatados.has(t.id);
    const mostraCheckbox = !restrito || destacada;
    return '<tr class="' + (destacada ? 'cc-linha-empatada' : '') + '">' +
      '<td>' + (mostraCheckbox ? '<input type="checkbox" class="cc-candidato-check" value="' + t.id + '" data-saldo="' + saldoAberto + '">' : '') + '</td>' +
      '<td>' + t.descricao + '</td>' +
      '<td>' + parseDate(t.vencimento).toLocaleDateString('pt-BR') + '</td>' +
      '<td class="num">' + formatBRL(saldoAberto) + '</td>' +
      '<td class="' + tierClasse + '">' + tierTexto + (destacada ? ' <span class="tag empate" style="margin-left:4px;">empate</span>' : '') + '</td>' +
    '</tr>';
  }).join('');
  tbody.querySelectorAll('.cc-candidato-check').forEach(chk=>{
    chk.addEventListener('change', atualizarResumoSelecaoConciliacao);
  });
}

function atualizarResumoSelecaoConciliacao(){
  const linhaSel = state.extratoBancario.find(l=>l.id===__ccLinhaBancoSelecionadaId);
  if(!linhaSel) return;
  const checks = Array.from(document.querySelectorAll('.cc-candidato-check:checked'));
  const soma = checks.reduce((s,c)=> s + parseFloat(c.dataset.saldo), 0);
  const info = document.getElementById('cc-selecionada-info');
  const base = 'Selecionado: ' + parseDate(linhaSel.data).toLocaleDateString('pt-BR') + ' — ' + linhaSel.descricao + ' — ' + formatBRL(linhaSel.valor);
  if(checks.length){
    const diff = Math.abs(soma) - Math.abs(linhaSel.valor);
    info.innerHTML = base + '<br>Marcado: ' + formatBRL(soma) + ' em ' + checks.length + ' lançamento(s)' +
      (Math.abs(diff) < 0.01 ? ' — <span style="color:var(--teal);">bate com a linha do banco</span>' : ' — <span style="color:var(--gold);">diferença de ' + formatBRL(Math.abs(diff)) + '</span>');
  } else {
    info.textContent = base;
  }
}

function renderPainelAcoesConciliacao(linhaSel){
  const painel = document.getElementById('cc-acoes-painel');
  const info = document.getElementById('cc-selecionada-info');
  document.getElementById('cc-acao-msg').textContent = '';
  if(!linhaSel){ painel.style.display = 'none'; return; }
  painel.style.display = 'block';
  info.textContent = 'Selecionado: ' + parseDate(linhaSel.data).toLocaleDateString('pt-BR') + ' — ' + linhaSel.descricao + ' — ' + formatBRL(linhaSel.valor);
  // "empate" age igual a "pendente" nos botões — o usuário resolve o
  // empate escolhendo o candidato certo e clicando Conciliar (74º prompt).
  const pendente = linhaSel.status === 'pendente' || linhaSel.status === 'empate';
  if(linhaSel.status === 'empate'){
    info.innerHTML += ' — <span style="color:var(--gold); font-weight:600;">Empate: dois ou mais lançamentos servem igual. Escolha o certo ao lado.</span>';
  }
  document.getElementById('cc-btn-conciliar').style.display = pendente ? '' : 'none';
  document.getElementById('cc-btn-criar-lancamento').style.display = pendente ? '' : 'none';
  document.getElementById('cc-btn-arquivar').style.display = pendente ? '' : 'none';
  document.getElementById('cc-btn-restaurar').style.display = linhaSel.status === 'arquivada' ? '' : 'none';
  document.getElementById('cc-btn-desfazer').style.display = linhaSel.status === 'conciliada' ? '' : 'none';
  if(linhaSel.status === 'conciliada'){
    const conc = state.conciliacoes.find(c=>c.bancoLinhaId===linhaSel.id);
    if(conc) info.textContent += ' — conciliada (' + (conc.origemMatch==='automatica'?'automática':'manual') + ') em ' + parseDate(conc.data).toLocaleDateString('pt-BR');
  }
}

function renderRodapeConciliacao(contaId){
  if(!contaId){
    document.getElementById('cc-saldo-banco').textContent = 'R$ 0,00';
    document.getElementById('cc-saldo-soliduns').textContent = 'R$ 0,00';
    document.getElementById('cc-diferenca').textContent = 'R$ 0,00';
    document.getElementById('cc-bateu-valor').textContent = '—';
    document.getElementById('cc-bateu-valor').style.color = '';
    return;
  }
  const conta = state.contasFinanceiras.find(c=>c.id===contaId);
  const fim = document.getElementById('cc-fim').value || new Date().toISOString().slice(0,10);
  const saldoBanco = (conta ? (conta.saldoInicial||0) : 0) + state.extratoBancario
    .filter(l=> l.contaFinanceiraId===contaId && l.status!=='arquivada' && l.data <= fim)
    .reduce((s,l)=> s+l.valor, 0);
  const saldoSol = saldoContaFinanceira(contaId);
  const diferenca = saldoBanco - saldoSol;
  document.getElementById('cc-saldo-banco').textContent = formatBRL(saldoBanco);
  document.getElementById('cc-saldo-soliduns').textContent = formatBRL(saldoSol);
  document.getElementById('cc-diferenca').textContent = formatBRL(diferenca);
  const bateu = Math.abs(diferenca) < 0.01;
  const elValor = document.getElementById('cc-bateu-valor');
  elValor.textContent = bateu ? 'Bateu' : 'Não bateu';
  elValor.style.color = bateu ? 'var(--teal)' : 'var(--rust)';
}

function selecionarLinhaBanco(id){
  __ccLinhaBancoSelecionadaId = (__ccLinhaBancoSelecionadaId === id) ? null : id;
  renderConciliacao();
}

/* ---------- AÇÕES: conciliar, arquivar, restaurar, desfazer ---------- */
function conciliarSelecionados(){
  const msg = document.getElementById('cc-acao-msg');
  const linhaSel = state.extratoBancario.find(l=>l.id===__ccLinhaBancoSelecionadaId);
  if(!linhaSel || (linhaSel.status !== 'pendente' && linhaSel.status !== 'empate')) return;
  const checks = Array.from(document.querySelectorAll('.cc-candidato-check:checked'));
  if(checks.length === 0){
    msg.textContent = 'Marque ao menos um lançamento à direita antes de conciliar.';
    msg.className = 'auth-msg erro';
    return;
  }
  const contaId = linhaSel.contaFinanceiraId;
  const baixaIds = [];
  const transacaoIds = checks.map(c=>c.value);
  transacaoIds.forEach(tid=>{
    const t = state.transacoes.find(x=>x.id===tid);
    if(!t) return;
    const saldoAberto = t.valor - valorPagoTransacao(t);
    const baixaId = uid();
    if(!t.baixas) t.baixas = [];
    t.baixas.push({id: baixaId, data: linhaSel.data, valorEfetivo: saldoAberto, juros:0, multa:0, desconto:0, tarifa:0, observacoes:'Conciliação bancária', contaFinanceiraId: contaId});
    t.status = statusCalculadoTransacao(t);
    baixaIds.push(baixaId);
  });
  linhaSel.status = 'conciliada';
  state.conciliacoes.push({id: uid(), contaFinanceiraId: contaId, bancoLinhaId: linhaSel.id, tipo:'transacoes', transacaoIds, baixaIds, transferenciaId:null, origemMatch:'manual', data: new Date().toISOString().slice(0,10)});
  salvarEstado();
  renderTudo();
}
function arquivarLinhaBancoAtual(){
  const linhaSel = state.extratoBancario.find(l=>l.id===__ccLinhaBancoSelecionadaId);
  if(!linhaSel || (linhaSel.status !== 'pendente' && linhaSel.status !== 'empate')) return;
  linhaSel.status = 'arquivada';
  salvarEstado();
  renderTudo();
}
function restaurarLinhaBancoAtual(){
  const linhaSel = state.extratoBancario.find(l=>l.id===__ccLinhaBancoSelecionadaId);
  if(!linhaSel || linhaSel.status !== 'arquivada') return;
  linhaSel.status = 'pendente';
  salvarEstado();
  renderTudo();
}
function desfazerConciliacaoAtual(){
  const linhaSel = state.extratoBancario.find(l=>l.id===__ccLinhaBancoSelecionadaId);
  if(!linhaSel || linhaSel.status !== 'conciliada') return;
  const conc = state.conciliacoes.find(c=>c.bancoLinhaId===linhaSel.id);
  if(!conc) return;
  if(conc.tipo === 'transferencia'){
    state.transferencias = state.transferencias.filter(tr=>tr.id !== conc.transferenciaId);
  } else {
    conc.transacaoIds.forEach((tid, idx)=>{
      const t = state.transacoes.find(x=>x.id===tid);
      if(!t) return;
      const baixaId = conc.baixaIds[idx];
      t.baixas = (t.baixas||[]).filter(b=>b.id !== baixaId);
      t.status = statusCalculadoTransacao(t);
    });
  }
  state.conciliacoes = state.conciliacoes.filter(c=>c.id !== conc.id);
  linhaSel.status = 'pendente';
  salvarEstado();
  renderTudo();
}

/* ---------- MODAL: Criar lançamento e conciliar ---------- */
function abrirModalCriarLancamento(){
  const linhaSel = state.extratoBancario.find(l=>l.id===__ccLinhaBancoSelecionadaId);
  if(!linhaSel) return;
  document.getElementById('cc-criar-tipo').value = linhaSel.valor >= 0 ? 'recebimento' : 'pagamento';
  document.getElementById('cc-criar-desc').value = linhaSel.descricao;
  document.getElementById('cc-criar-categoria').value = '';
  document.getElementById('cc-criar-valor').value = formatBRL(Math.abs(linhaSel.valor));
  document.getElementById('cc-criar-msg').textContent = '';
  popularSelectsCriarTransferencia();
  atualizarFormCriarLancamento();
  document.getElementById('cc-criar-overlay').style.display = 'flex';
}
function fecharModalCriarLancamento(){
  document.getElementById('cc-criar-overlay').style.display = 'none';
}
function atualizarFormCriarLancamento(){
  const tipo = document.getElementById('cc-criar-tipo').value;
  const ehTransferencia = tipo === 'transferencia';
  document.getElementById('cc-criar-campos-normais').style.display = ehTransferencia ? 'none' : '';
  document.getElementById('cc-criar-campos-transferencia').style.display = ehTransferencia ? '' : 'none';
  const contaId = contaConciliacaoSelecionada();
  const conta = state.contasFinanceiras.find(c=>c.id===contaId);
  if(ehTransferencia && conta){
    document.getElementById('cc-criar-transf-nota').textContent = 'Uma das pontas é "' + conta.nome + '" (a conta desta tela) — escolha a outra.';
  }
  if(tipo === 'tarifa' && !document.getElementById('cc-criar-categoria').value) document.getElementById('cc-criar-categoria').value = 'Tarifas bancárias';
  if(tipo === 'rendimento' && !document.getElementById('cc-criar-categoria').value) document.getElementById('cc-criar-categoria').value = 'Rendimentos financeiros';
}
function confirmarCriarLancamentoEConciliar(){
  const msg = document.getElementById('cc-criar-msg');
  const linhaSel = state.extratoBancario.find(l=>l.id===__ccLinhaBancoSelecionadaId);
  if(!linhaSel || (linhaSel.status !== 'pendente' && linhaSel.status !== 'empate')) return;
  const tipo = document.getElementById('cc-criar-tipo').value;
  const contaId = linhaSel.contaFinanceiraId;
  const conta = state.contasFinanceiras.find(c=>c.id===contaId);
  const valor = parseMoeda(document.getElementById('cc-criar-valor').value);
  if(isNaN(valor) || valor <= 0){
    msg.textContent = 'Informe um valor válido.';
    msg.className = 'auth-msg erro';
    return;
  }

  if(tipo === 'transferencia'){
    const origemId = document.getElementById('cc-criar-origem').value;
    const destinoId = document.getElementById('cc-criar-destino').value;
    if(!origemId || !destinoId || origemId === destinoId){
      msg.textContent = 'Escolha duas contas diferentes para a transferência.';
      msg.className = 'auth-msg erro';
      return;
    }
    const transferenciaId = uid();
    state.transferencias.push({id: transferenciaId, empresa: conta.empresa, data: linhaSel.data, origemId, destinoId, valor, obs: linhaSel.descricao});
    linhaSel.status = 'conciliada';
    state.conciliacoes.push({id: uid(), contaFinanceiraId: contaId, bancoLinhaId: linhaSel.id, tipo:'transferencia', transacaoIds:[], baixaIds:[], transferenciaId, origemMatch:'manual', data: new Date().toISOString().slice(0,10)});
  } else {
    const desc = document.getElementById('cc-criar-desc').value.trim() || linhaSel.descricao;
    const categoriaPadrao = tipo==='tarifa' ? 'Tarifas bancárias' : tipo==='rendimento' ? 'Rendimentos financeiros' : '—';
    const categoria = document.getElementById('cc-criar-categoria').value.trim() || categoriaPadrao;
    const tipoTransacao = (tipo === 'recebimento' || tipo === 'rendimento') ? 'receber' : 'pagar';
    const transacaoId = uid();
    const baixaId = uid();
    state.transacoes.push({
      id: transacaoId, tipo: tipoTransacao, empresa: conta.empresa, descricao: desc,
      valor, vencimento: linhaSel.data, categoria, status:'pendente',
      baixas: [{id: baixaId, data: linhaSel.data, valorEfetivo: valor, juros:0, multa:0, desconto:0, tarifa:0, observacoes:'Criado na conciliação bancária', contaFinanceiraId: contaId}]
    });
    const t = state.transacoes.find(x=>x.id===transacaoId);
    t.status = statusCalculadoTransacao(t);
    linhaSel.status = 'conciliada';
    state.conciliacoes.push({id: uid(), contaFinanceiraId: contaId, bancoLinhaId: linhaSel.id, tipo:'transacoes', transacaoIds:[transacaoId], baixaIds:[baixaId], transferenciaId:null, origemMatch:'manual', data: new Date().toISOString().slice(0,10)});
  }

  salvarEstado();
  fecharModalCriarLancamento();
  renderTudo();
}

