function regrasFormAtual(){
  return {
    autoAplicarExata: document.getElementById('cc-regra-auto-exata').checked,
    autoAplicarAproximada: document.getElementById('cc-regra-auto-aproximada').checked,
    janelaAproximadaDias: document.getElementById('cc-regra-janela-aproximada').value,
    janelaSugestaoDias: document.getElementById('cc-regra-janela-sugestao').value,
    toleranciaSugestaoPct: document.getElementById('cc-regra-tolerancia').value,
    robotAproximadaExigeValorIdentico: document.getElementById('cc-regra-robo-valor-identico').checked,
    bonusNomeContraparte: document.getElementById('cc-regra-bonus-nome').checked,
    somenteMesmaConta: document.getElementById('cc-regra-mesma-conta').checked,
    respeitarSinal: document.getElementById('cc-regra-respeitar-sinal').checked
  };
}
let __regrasSnapshotAoAbrir = null;
function preencherFormRegras(r){
  document.getElementById('cc-regra-auto-exata').checked = r.autoAplicarExata;
  document.getElementById('cc-regra-auto-aproximada').checked = r.autoAplicarAproximada;
  document.getElementById('cc-regra-janela-aproximada').value = r.janelaAproximadaDias;
  document.getElementById('cc-regra-janela-sugestao').value = r.janelaSugestaoDias;
  document.getElementById('cc-regra-tolerancia').value = r.toleranciaSugestaoPct;
  document.getElementById('cc-regra-robo-valor-identico').checked = r.robotAproximadaExigeValorIdentico !== false;
  document.getElementById('cc-regra-bonus-nome').checked = r.bonusNomeContraparte !== false;
  document.getElementById('cc-regra-mesma-conta').checked = r.somenteMesmaConta !== false;
  document.getElementById('cc-regra-respeitar-sinal').checked = r.respeitarSinal !== false;
}
function abrirModalRegras(){
  preencherFormRegras(state.regrasConciliacao);
  ['erro-janela-aproximada','erro-janela-sugestao','erro-tolerancia'].forEach(id=>document.getElementById(id).textContent='');
  document.getElementById('cc-regras-msg').textContent = '';
  __regrasSnapshotAoAbrir = JSON.stringify(regrasFormAtual());
  document.getElementById('cc-regras-overlay').style.display = 'flex';
}
function regrasFormMudou(){
  return JSON.stringify(regrasFormAtual()) !== __regrasSnapshotAoAbrir;
}
function fecharModalRegras(){
  document.getElementById('cc-regras-overlay').style.display = 'none';
}
/* Usado pelo ESC (fecharTudoAberto): só fecha direto se nada mudou;
   havendo alteração não salva, confirma antes (75º prompt). */
function tentarFecharModalRegras(){
  if(regrasFormMudou() && !confirm('Existem alterações não salvas nas regras. Fechar mesmo assim?')) return false;
  fecharModalRegras();
  return true;
}
function salvarRegrasConciliacao(){
  const janelaAprox = parseInt(document.getElementById('cc-regra-janela-aproximada').value, 10);
  const janelaSug = parseInt(document.getElementById('cc-regra-janela-sugestao').value, 10);
  const tolerancia = parseFloat(document.getElementById('cc-regra-tolerancia').value);
  const erros = {};
  if(isNaN(janelaAprox) || janelaAprox < 1 || janelaAprox > 15 || !Number.isInteger(janelaAprox)) erros['erro-janela-aproximada'] = 'Use um número inteiro entre 1 e 15.';
  if(isNaN(janelaSug) || janelaSug < 1 || janelaSug > 15 || !Number.isInteger(janelaSug)) erros['erro-janela-sugestao'] = 'Use um número inteiro entre 1 e 15.';
  if(isNaN(tolerancia) || tolerancia < 0 || tolerancia > 20) erros['erro-tolerancia'] = 'Use um número entre 0 e 20.';
  ['erro-janela-aproximada','erro-janela-sugestao','erro-tolerancia'].forEach(id=> document.getElementById(id).textContent = erros[id] || '');
  if(Object.keys(erros).length) return;

  state.regrasConciliacao = {
    autoAplicarExata: document.getElementById('cc-regra-auto-exata').checked,
    autoAplicarAproximada: document.getElementById('cc-regra-auto-aproximada').checked,
    janelaAproximadaDias: janelaAprox,
    janelaSugestaoDias: janelaSug,
    toleranciaSugestaoPct: tolerancia,
    robotAproximadaExigeValorIdentico: document.getElementById('cc-regra-robo-valor-identico').checked,
    empateNaoFechaSozinho: true, // travado no v1 — não destravar (75º prompt)
    bonusNomeContraparte: document.getElementById('cc-regra-bonus-nome').checked,
    somenteMesmaConta: document.getElementById('cc-regra-mesma-conta').checked,
    respeitarSinal: document.getElementById('cc-regra-respeitar-sinal').checked,
    transferenciaNuncaReceita: true // já garantido pela estrutura (transferências não entram como candidato)
  };
  salvarRegrasConciliacaoLocalStorage(state.regrasConciliacao);
  salvarEstado();
  __regrasSnapshotAoAbrir = JSON.stringify(regrasFormAtual());
  const msg = document.getElementById('cc-regras-msg');
  msg.textContent = 'Regras salvas.';
  msg.className = 'auth-msg sucesso';
  renderConciliacao();
}
function restaurarPadroesRegrasConciliacao(){
  preencherFormRegras(REGRAS_CONCILIACAO_PADRAO);
  ['erro-janela-aproximada','erro-janela-sugestao','erro-tolerancia'].forEach(id=>document.getElementById(id).textContent='');
  const msg = document.getElementById('cc-regras-msg');
  msg.textContent = 'Padrões restaurados — clique em Salvar regras para confirmar.';
  msg.className = 'auth-msg';
}

