/* ---------- VALIDAÇÃO (74º prompt) ---------- */
/* validarLinhaBanco — porta de entrada de qualquer linha antes de virar
   state.extratoBancario (venha do demo, do OFX ou, no futuro, da API).
   raw: {data, descricao, valor, fitid?}. Retorna {ok, linha, erros[]}. */
function validarLinhaBanco(raw, contaId){
  const erros = [];
  const dataOk = !!raw.data && /^\d{4}-\d{2}-\d{2}$/.test(raw.data) && !isNaN(parseDate(raw.data).getTime());
  if(!dataOk) erros.push('data ausente ou inválida');

  const valorNum = typeof raw.valor === 'number' ? raw.valor : parseFloat(String(raw.valor||'').replace(',', '.'));
  const valorOk = !isNaN(valorNum) && isFinite(valorNum);
  if(!valorOk) erros.push('valor não reconhecido');
  if(valorOk && valorNum === 0 && raw.exigirSinal !== false) erros.push('sinal indefinido (nem crédito nem débito)');

  if(erros.length){
    return {ok:false, linha:null, erros};
  }

  const descricao = (raw.descricao||'').trim() || '(sem descrição)';
  const descNorm = normalizarTexto(descricao);

  // Duplicata: mesmo identificador do banco (FITID) OU mesma tripla
  // data+valor+memo normalizado, sempre dentro da mesma conta.
  const duplicada = state.extratoBancario.some(ex=>{
    if(ex.contaFinanceiraId !== contaId) return false;
    if(raw.fitid && ex.bancoTxId && ex.bancoTxId === raw.fitid) return true;
    if(raw.fitid && ex.bancoTxId) return false; // ambos têm FITID e são diferentes -> não é duplicata por esse critério
    return ex.data === raw.data && Math.abs(ex.valor - valorNum) < 0.005 && normalizarTexto(ex.descricao) === descNorm;
  });
  if(duplicada){
    return {ok:false, linha:null, erros:['duplicata']};
  }

  return {
    ok:true,
    erros:[],
    linha: {
      id: uid(), contaFinanceiraId: contaId, data: raw.data, descricao, valor: valorNum,
      origem: raw.origem||'ofx', status:'pendente', bancoTxId: raw.fitid || null,
      tipoHint: raw.tipoHint || null
    }
  };
}

/* detectarDialeto — 76º prompt. Reconhece a família do arquivo OFX
   antes de tentar extrair transações; não aceita "qualquer .ofx". */
function detectarDialeto(texto){
  const cabecalho = texto.slice(0, 400);
  if(/OFXHEADER/i.test(cabecalho) && /VERSION\s*:\s*10[02]/i.test(texto.slice(0,600))){
    return 'ofx1-money';
  }
  if(/<OFX>/i.test(texto) && /<STMTTRN>/i.test(texto)){
    return 'ofx2-xml';
  }
  // Alguns bancos não repetem VERSION logo no topo — aceitar Money 1.x
  // "de fato" se tiver o cabeçalho OFXHEADER e transações reais.
  if(/OFXHEADER/i.test(cabecalho) && /<STMTTRN>/i.test(texto)){
    return 'ofx1-money';
  }
  return null;
}

function mapearTipoOFX(trntype){
  const t = (trntype||'').toUpperCase();
  if(['CREDIT','DEP','INT'].includes(t)) return 'credito';
  if(['DEBIT','FEE','CHECK'].includes(t)) return 'debito';
  if(t === 'XFER') return 'transferencia';
  return null;
}

/* parseOFX — extrai os blocos <STMTTRN> em bruto (data/valor/memo/FITID/
   TRNTYPE), sem decidir ainda o que é válido. A decisão é da
   validarLinhaBanco, chamada linha a linha por validarArquivoOFX. */
function parseOFX(texto){
  const brutos = [];
  const blocos = texto.split(/<STMTTRN>/i).slice(1);
  blocos.forEach(bloco=>{
    const corpo = bloco.split(/<\/STMTTRN>/i)[0];
    const pega = (tag)=>{
      const m = corpo.match(new RegExp('<'+tag+'>([^<\\r\\n]*)', 'i'));
      return m ? m[1].trim() : '';
    };
    const dtRaw = pega('DTPOSTED');
    const amtRaw = pega('TRNAMT');
    const memo = pega('MEMO') || pega('NAME') || '';
    const fitid = pega('FITID') || null;
    const trntype = pega('TRNTYPE') || null;
    const data = dtRaw ? (dtRaw.slice(0,4) + '-' + dtRaw.slice(4,6) + '-' + dtRaw.slice(6,8)) : '';
    brutos.push({
      data, descricao: memo, valorRaw: amtRaw,
      fitid, tipoHint: mapearTipoOFX(trntype)
    });
  });
  const bankId = (texto.match(/<BANKID>([^<\r\n]*)/i)||[])[1];
  const acctId = (texto.match(/<ACCTID>([^<\r\n]*)/i)||[])[1];
  return {brutos, bankId: bankId ? bankId.trim() : null, acctId: acctId ? acctId.trim() : null};
}

/* validarArquivoOFX — porta de entrada do ARQUIVO (74º/76º prompt).
   Recusa o arquivo inteiro em casos grosseiros (extensão, tamanho, PDF,
   fora do padrão OFX); linhas podres isoladas viram "recusadas", sem
   derrubar o resto. Retorna uma Promise. */
function validarArquivoOFX(file, contaId){
  return new Promise((resolve)=>{
    if(!file){ resolve({ok:false, motivoArquivo:'nenhum arquivo selecionado'}); return; }
    if(!file.name.toLowerCase().endsWith('.ofx')){
      resolve({ok:false, motivoArquivo:'Só aceitamos arquivo .ofx — não converta o extrato para PDF antes de subir.'});
      return;
    }
    if(file.size > 5*1024*1024){
      resolve({ok:false, motivoArquivo:'Arquivo maior que 5 MB. Confira se não é o PDF do extrato em vez do OFX.'});
      return;
    }
    const reader = new FileReader();
    reader.onload = function(){
      const texto = String(reader.result || '');
      if(texto.trim().slice(0,4) === '%PDF' || /application\/pdf/i.test(texto.slice(0,200))){
        resolve({ok:false, motivoArquivo:'Este arquivo é um PDF disfarçado de OFX. Baixe o extrato em formato OFX/Money no internet banking.'});
        return;
      }
      const dialeto = detectarDialeto(texto);
      if(!dialeto){
        resolve({ok:false, motivoArquivo:'Fora do padrão OFX (Money 100/102 ou OFX2). Confira se não é um conversor de PDF para OFX — costuma gerar arquivo sem cabeçalho válido.'});
        return;
      }
      const {brutos, bankId, acctId} = parseOFX(texto);
      if(brutos.length === 0){
        resolve({ok:false, motivoArquivo:'Não encontramos transações neste arquivo (procuramos por blocos <STMTTRN>). Confira se é mesmo um OFX de extrato.'});
        return;
      }
      const linhas = [], recusadas = [], avisos = [];
      let usouFitid = false;
      const fitidsDoLote = {};   /* v106-GF (GF16): FITID repetido no MESMO arquivo */
      brutos.forEach(b=>{
        if(b.fitid){
          if(fitidsDoLote[b.fitid]){
            recusadas.push({linha: b, motivo: 'FITID repetido dentro do próprio arquivo (' + b.fitid + ') — o banco mandou a mesma transação duas vezes.'});
            return;
          }
          fitidsDoLote[b.fitid] = true;
        }
        const r = validarLinhaBanco({data:b.data, descricao:b.descricao, valor: parseFloat((b.valorRaw||'').replace(',', '.')), fitid:b.fitid, tipoHint:b.tipoHint, origem:'ofx'}, contaId);
        if(r.ok){
          linhas.push(r.linha);
          if(b.fitid) usouFitid = true;
        } else {
          recusadas.push({dataTentada: b.data || '(sem data)', descricao: b.descricao || '(sem descrição)', motivo: r.erros.join('; ')});
        }
      });
      const hojeStr = new Date().toISOString().slice(0,10);
      if(linhas.some(l=>l.data===hojeStr)){
        avisos.push('O arquivo traz o dia de hoje (D-0) — a maioria dos bancos só manda D-1 ou anterior; confira se está completo.');
      }
      const datasOrdenadas = brutos.map(b=>b.data).filter(Boolean);
      const crescente = datasOrdenadas.every((d,i)=> i===0 || d >= datasOrdenadas[i-1]);
      if(!crescente) avisos.push('As datas do arquivo não vêm em ordem crescente — importamos mesmo assim.');
      if(!usouFitid && linhas.length) avisos.push('Este arquivo não traz FITID — duplicata é detectada por data + valor + descrição.');

      resolve({ok:true, linhas, recusadas, avisos, dialeto, bankId, acctId});
    };
    reader.readAsText(file);
  });
}

function importarOFX(file){
  const msg = document.getElementById('cc-import-msg');
  const contaId = contaConciliacaoSelecionada();
  document.getElementById('cc-ofx-input').value = '';
  if(!file) return;
  if(!contaId){
    msg.textContent = 'Escolha uma conta financeira antes de importar.';
    msg.className = 'auth-msg erro';
    return;
  }
  validarArquivoOFX(file, contaId).then(resultado=>{
    if(!resultado.ok){
      msg.textContent = resultado.motivoArquivo;
      msg.className = 'auth-msg erro';
      renderPainelRecusadas([]);
      return;
    }
    const conta = state.contasFinanceiras.find(c=>c.id===contaId);
    if(resultado.acctId && conta && conta.acctIdReferencia && conta.acctIdReferencia !== resultado.acctId){
      __ofxPendente = {resultado, contaId};
      msg.innerHTML = 'Este OFX parece ser de outra conta (identificador ' + resultado.acctId + ', diferente do já usado nesta conta). ' +
        '<button type="button" class="ghost" onclick="confirmarImportacaoOFXMesmoAssim()" style="margin-left:8px;">Importar mesmo assim</button>';
      msg.className = 'auth-msg erro';
      return;
    }
    aplicarImportacaoOFX(resultado, contaId);
  });
}
function confirmarImportacaoOFXMesmoAssim(){
  if(!__ofxPendente) return;
  aplicarImportacaoOFX(__ofxPendente.resultado, __ofxPendente.contaId);
  __ofxPendente = null;
}
function aplicarImportacaoOFX(resultado, contaId){
  const msg = document.getElementById('cc-import-msg');
  const conta = state.contasFinanceiras.find(c=>c.id===contaId);
  if(conta && resultado.acctId && !conta.acctIdReferencia) conta.acctIdReferencia = resultado.acctId;
  resultado.linhas.forEach(l=> state.extratoBancario.push(l));

  const NOMES_DIALETO = {'ofx1-money':'Money 100/102', 'ofx2-xml':'OFX2 (XML)'};
  const carimbo = 'Dialeto: ' + (NOMES_DIALETO[resultado.dialeto]||resultado.dialeto) + ' · ' +
    resultado.linhas.length + ' importada(s) · ' + resultado.recusadas.length + ' recusada(s) · ' +
    'conferir conta: ' + (resultado.acctId ? 'sim' : 'não') +
    (resultado.avisos.length ? (' · ' + resultado.avisos.join(' · ')) : '');

  msg.textContent = carimbo + '. Importar não concilia — use Tentar casamento automático ou case na mão.';
  msg.className = 'auth-msg sucesso';
  renderPainelRecusadas(resultado.recusadas);
  salvarEstado();
  renderTudo();
}

/* ---------- PAINEL "Linhas recusadas" (74º prompt) ---------- */
function renderPainelRecusadas(recusadas){
  const painel = document.getElementById('cc-recusadas-painel');
  const contador = document.getElementById('cc-recusadas-contador');
  const tbody = document.getElementById('cc-recusadas-tbody');
  if(!painel) return;
  if(!recusadas || recusadas.length === 0){
    painel.style.display = 'none';
    tbody.innerHTML = '';
    return;
  }
  painel.style.display = 'block';
  contador.textContent = recusadas.length;
  tbody.innerHTML = recusadas.map(r=>
    '<tr><td>' + (r.dataTentada||'(sem data)') + '</td><td>' + (r.descricao||'').slice(0,60) + '</td><td>' + r.motivo + '</td></tr>'
  ).join('');
}
function alternarPainelRecusadas(){
  const corpo = document.getElementById('cc-recusadas-corpo');
  const seta = document.getElementById('cc-recusadas-seta');
  const aberto = corpo.style.display !== 'none';
  corpo.style.display = aberto ? 'none' : 'block';
  seta.textContent = aberto ? '▸' : '▾';
}

/* ---------- TESTES (comentados na view, rodam isolados do state real) ----------
   Casos 1-4: tiers de sugerirCandidatos (73º prompt).
   V1-V4: validação de linha/arquivo (74º prompt).
   E1-E4: regras de empate (74º prompt).
   T1-T6: dialeto/validação específica de OFX (76º prompt).
   Chame await rodarTestesConciliacao() no console — é assíncrona por
   causa dos casos T que leem arquivo via FileReader. */
window.rodarTestesConciliacao = async function(){
  let passou = 0;
  let total = 0;
  function caso(n, descricao, condicao){
    total++;
    console.assert(condicao, `[conciliação] caso ${n} falhou: ${descricao}`);
    if(condicao) passou++;
    console.log(`${condicao ? '[OK]' : '[FALHOU]'} ${n}) ${descricao}`);
  }
  function arquivoFalso(nome, conteudo, tipo){
    return new File([conteudo], nome, {type: tipo||'text/plain'});
  }

  const regrasOriginais = state.regrasConciliacao;
  const contasOriginais = state.contasFinanceiras;
  const transacoesOriginais = state.transacoes;
  const extratoOriginal = state.extratoBancario;
  state.regrasConciliacao = Object.assign({}, REGRAS_CONCILIACAO_PADRAO);
  state.contasFinanceiras = [{id:'__teste_conta__', empresa:'__TESTE__', tipo:'banco', nome:'Conta teste', saldoInicial:0, ativo:true}];
  state.extratoBancario = [];

  state.transacoes = [{id:'tx1', tipo:'receber', empresa:'__TESTE__', descricao:'x', valor:1000, vencimento:'2026-08-15', categoria:'x', status:'pendente', baixas:[]}];
  const cand1 = sugerirCandidatos({id:'l1', contaFinanceiraId:'__teste_conta__', data:'2026-08-15', descricao:'x', valor:1000, origem:'demo', status:'pendente'});
  caso(1, 'valor e data iguais → EXATA', cand1.length===1 && cand1[0].tier==='exata');

  state.transacoes = [{id:'tx2', tipo:'receber', empresa:'__TESTE__', descricao:'x', valor:1000, vencimento:'2026-08-12', categoria:'x', status:'pendente', baixas:[]}];
  const cand2 = sugerirCandidatos({id:'l2', contaFinanceiraId:'__teste_conta__', data:'2026-08-16', descricao:'x', valor:1000, origem:'demo', status:'pendente'});
  caso(2, 'valor igual, 4 dias de diferença → APROXIMADA', cand2.length===1 && cand2[0].tier==='aproximada');

  state.transacoes = [
    {id:'tx3a', tipo:'receber', empresa:'__TESTE__', descricao:'x', valor:1000, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]},
    {id:'tx3b', tipo:'receber', empresa:'__TESTE__', descricao:'y', valor:1000, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]}
  ];
  const cand3 = sugerirCandidatos({id:'l3', contaFinanceiraId:'__teste_conta__', data:'2026-08-16', descricao:'x', valor:1000, origem:'demo', status:'pendente'});
  caso(3, 'dois candidatos com o mesmo valor → empate, não fecha sozinho', cand3.filter(c=>c.tier==='exata').length===2);

  state.transacoes = [{id:'tx4', tipo:'receber', empresa:'__TESTE__', descricao:'x', valor:930, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]}];
  const cand4 = sugerirCandidatos({id:'l4', contaFinanceiraId:'__teste_conta__', data:'2026-08-16', descricao:'x', valor:1000, origem:'demo', status:'pendente'});
  caso(4, 'valor 7% menor → só sugestão, nunca robô', cand4.length===1 && cand4[0].tier==='sugestao');

  // ---------- V1-V4: validação (74º prompt) ----------
  const v1 = validarLinhaBanco({data:'', descricao:'x', valor:100}, '__teste_conta__');
  caso('V1', 'data inválida → recusada', v1.ok===false && v1.erros.includes('data ausente ou inválida'));

  const v2 = validarLinhaBanco({data:'2026-08-15', descricao:'x', valor:'abc'}, '__teste_conta__');
  caso('V2', 'valor "abc" → recusada', v2.ok===false && v2.erros.includes('valor não reconhecido'));

  state.extratoBancario = [{id:'exV3', contaFinanceiraId:'__teste_conta__', data:'2026-08-15', descricao:'PIX X', valor:100, origem:'ofx', status:'pendente', bancoTxId:null}];
  const v3 = validarLinhaBanco({data:'2026-08-15', descricao:'PIX X', valor:100}, '__teste_conta__');
  caso('V3', 'mesmo OFX duas vezes → segunda = duplicata', v3.ok===false && v3.erros.includes('duplicata'));
  state.extratoBancario = [];

  const v4 = await validarArquivoOFX(arquivoFalso('extrato.ofx', '%PDF-1.4 conteudo fake', 'application/pdf'), '__teste_conta__');
  caso('V4', 'PDF → arquivo recusado', v4.ok===false);

  // ---------- E1-E4: empate (74º prompt) ----------
  state.transacoes = [
    {id:'txE1', tipo:'receber', empresa:'__TESTE__', descricao:'Mensalidade Cliente 1', valor:150, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]},
    {id:'txE2', tipo:'receber', empresa:'__TESTE__', descricao:'Mensalidade Cliente 2', valor:150, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]}
  ];
  const e1 = avaliarEmpate({id:'lE1', contaFinanceiraId:'__teste_conta__', data:'2026-08-16', descricao:'PIX RECEBIDO', valor:150, origem:'demo', status:'pendente'});
  caso('E1', 'dois a receber R$150 sem nome no memo → selo empate, auto não fecha', e1.empate===true);

  state.transacoes = [
    {id:'txE3', tipo:'receber', empresa:'__TESTE__', descricao:'Mensalidade Ana Pereira', valor:200, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]},
    {id:'txE4', tipo:'receber', empresa:'__TESTE__', descricao:'Mensalidade Bruno Costa', valor:200, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]}
  ];
  const e2 = avaliarEmpate({id:'lE2', contaFinanceiraId:'__teste_conta__', data:'2026-08-16', descricao:'PIX ANA SILVA', valor:200, origem:'demo', status:'pendente'});
  caso('E2', 'um se chama ANA e o memo tem ANA → sem empate, sugere ANA', e2.empate===false && e2.vencedor && e2.vencedor.transacao.id==='txE3');

  state.transacoes = [{id:'txE5', tipo:'receber', empresa:'__TESTE__', descricao:'Servico X', valor:300, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]}];
  const e3 = avaliarEmpate({id:'lE3', contaFinanceiraId:'__teste_conta__', data:'2026-08-16', descricao:'PIX OUTRO', valor:300, origem:'demo', status:'pendente'});
  caso('E3', 'um único candidato exato → sem empate', e3.empate===false && e3.tier==='exata');

  state.transacoes = [
    {id:'txE6', tipo:'receber', empresa:'__TESTE__', descricao:'Parcela 1', valor:1000, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]},
    {id:'txE7', tipo:'receber', empresa:'__TESTE__', descricao:'Parcela 2', valor:1000, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]},
    {id:'txE8', tipo:'receber', empresa:'__TESTE__', descricao:'Parcela 3', valor:1000, vencimento:'2026-08-16', categoria:'x', status:'pendente', baixas:[]}
  ];
  const e4 = avaliarEmpate({id:'lE4', contaFinanceiraId:'__teste_conta__', data:'2026-08-16', descricao:'TED RECEBIDA GRANDE', valor:3000, origem:'demo', status:'pendente'});
  caso('E4', 'três de R$1.000 vs banco R$3.000 → 1:N, não é selo de empate', e4.empate===false);

  // ---------- T1-T6: validador OFX específico (76º prompt) ----------
  const t1 = await validarArquivoOFX(arquivoFalso('extrato.pdf', 'qualquer coisa'), '__teste_conta__');
  caso('T1', 'arquivo .pdf → recusado', t1.ok===false);

  const ofxMoney = 'OFXHEADER:100\r\nDATA:OFXSGML\r\nVERSION:102\r\n<OFX><BANKMSGSRSV1><STMTTRNRS><STMTRS><BANKTRANLIST>' +
    '<STMTTRN><TRNTYPE>CREDIT<DTPOSTED>20260815120000<TRNAMT>150.00<FITID>T2A<MEMO>PIX UM</STMTTRN>' +
    '<STMTTRN><TRNTYPE>DEBIT<DTPOSTED>20260816120000<TRNAMT>-50.00<FITID>T2B<MEMO>PIX DOIS</STMTTRN>' +
    '</BANKTRANLIST></STMTRS></STMTTRNRS></BANKMSGSRSV1></OFX>';
  const t2 = await validarArquivoOFX(arquivoFalso('extrato.ofx', ofxMoney), '__teste_conta_t2__');
  caso('T2', 'OFXHEADER VERSION:102 com 2 STMTTRN → importadas', t2.ok===true && t2.linhas.length===2 && t2.dialeto==='ofx1-money');
  state.extratoBancario.push(...t2.linhas); // simula aplicarImportacaoOFX, pra T3 achar duplicata de verdade

  const t3 = await validarArquivoOFX(arquivoFalso('extrato.ofx', ofxMoney), '__teste_conta_t2__');
  caso('T3', 'mesmo FITID de novo → duplicata', t3.ok===true && t3.linhas.length===0 && t3.recusadas.every(r=>r.motivo==='duplicata'));

  const ofxXml = '<?xml version="1.0"?><OFX><BANKMSGSRSV1><STMTTRNRS><STMTRS><BANKTRANLIST>' +
    '<STMTTRN><TRNTYPE>CREDIT<DTPOSTED>20260817<TRNAMT>75.00<FITID>T4A<MEMO>TESTE XML</STMTTRN>' +
    '</BANKTRANLIST></STMTRS></STMTTRNRS></BANKMSGSRSV1></OFX>';
  const t4 = await validarArquivoOFX(arquivoFalso('extrato2.ofx', ofxXml), '__teste_conta_t4__');
  caso('T4', 'XML OFX2 com TRNAMT → aceito', t4.ok===true && t4.dialeto==='ofx2-xml');

  const t5 = await validarArquivoOFX(arquivoFalso('extrato3.ofx', 'isso aqui nao eh nada parecido com ofx'), '__teste_conta__');
  caso('T5', 'texto aleatório .ofx → fora do padrão', t5.ok===false);

  const t6 = !document.querySelector('#cc-openfinance-overlay input[type="password"]');
  caso('T6', 'card Ligar banco não tem input type=password', t6===true);

  state.regrasConciliacao = regrasOriginais;
  state.contasFinanceiras = contasOriginais;
  state.transacoes = transacoesOriginais;
  state.extratoBancario = extratoOriginal;

  console.log(`\nResultado: ${passou}/${total}`);
  return passou === total;
};

/* ---------- DASHBOARD ---------- */
let filtroEmpresaDash = null; // null = todas as empresas (consolidado)

function transacoesFiltradasDash(){
  return filtroEmpresaDash
    ? state.transacoes.filter(t=>t.empresa === filtroEmpresaDash)
    : state.transacoes;
}

/* ---------- AUDITORIA FINANCEIRA (local, neste navegador) ----------
   Registro simples de ações sensíveis — usuário, data, ação, detalhe.
   Não substitui um log de servidor real (exigiria backend próprio). */
function nomeUsuarioAtual(){
  return (sessaoAtual && (sessaoAtual.nome || sessaoAtual.email)) || 'Usuário';
}
function auditar(acao, detalhe){
  state.auditoriaFinanceira.unshift({
    id: uid(), data: new Date().toISOString(), usuario: nomeUsuarioAtual(), acao, detalhe: detalhe || ''
  });
  if(state.auditoriaFinanceira.length > 200) state.auditoriaFinanceira.length = 200;
  salvarEstado();
}

/* ---------- 10.0 CONTRATOS RECORRENTES ----------
   Motor recorrente simplificado: cada contrato gera parcelas (contas a
   receber) manualmente, por competência, ao clicar em "Gerar parcela do
   mês" — sem job automático em segundo plano (isso exigiria backend). */
function popularSelectClientesContrato(){
  const sel = document.getElementById('ctr-cliente');
  const clientes = state.clientesFornecedores.filter(c=>c.tipo==='cliente' && c.ativo);
  sel.innerHTML = clientes.map(c=>`<option value="${c.id}">${c.nome}</option>`).join('') || '<option value="">Nenhum cliente cadastrado</option>';
  const selEmp = document.getElementById('ctr-empresa');
  selEmp.innerHTML = state.empresas.map(e=>`<option>${e.nome}</option>`).join('');
}

/* ---------- 10.0 CONTRATOS RECORRENTES ----------
   Contrato NÃO é venda parcelada — é gerador de vendas. Cada item tem
   um valor de PERÍODO (nunca o total do serviço) e pode ter uma
   competência-limite (vigenteAte) — é assim que "implantação diluída +
   mensalidade" funciona: o item implantação simplesmente para de entrar
   na soma depois do mês combinado, sem precisar editar nada na hora.
   Idempotência: nunca gera duas vendas para a mesma (contrato, competência) —
   testado explicitamente mais abaixo. */
const NOMES_STATUS_CONTRATO = {ativo:'Ativo', pausado:'Pausado', cancelado:'Cancelado'};
let itensContratoAtual = [];

function competenciaAtualStr(){
  const hoje = new Date();
  return hoje.getFullYear() + '-' + String(hoje.getMonth()+1).padStart(2,'0');
}
/* Item vigente numa competência = não tem vigenteAte, ou vigenteAte >= competência
   (vigenteAte guarda a ÚLTIMA competência em que o item ainda entra). */
function itensVigentesNaCompetencia(itens, competencia){
  return itens.filter(i => !i.vigenteAte || i.vigenteAte >= competencia);
}
function totalItensVigentes(itens, competencia){
  return itensVigentesNaCompetencia(itens, competencia).reduce((s,i)=> s + (i.valor||0), 0);
}

function renderizarItensContratoForm(){
  const box = document.getElementById('ctr-itens-lista');
  const competenciaAtual = competenciaAtualStr();
  box.innerHTML = itensContratoAtual.map((item,idx)=>`
    <div style="display:flex; gap:8px; margin-bottom:6px; align-items:center; flex-wrap:wrap;">
      <input type="text" placeholder="Descrição (ex.: Implantação, Mensalidade)" value="${item.descricao||''}" oninput="itensContratoAtual[${idx}].descricao=this.value" style="flex:2; min-width:160px;">
      <input type="text" inputmode="decimal" placeholder="R$ 0,00 / período" value="${item.valor?formatBRL(item.valor):''}" oninput="aplicarMascaraMoeda(this); itensContratoAtual[${idx}].valor=parseMoeda(this.value); atualizarPreviewTotalContrato();" onblur="finalizarMascaraMoeda(this)" style="flex:1; min-width:110px;">
      <input type="text" placeholder="Categoria" value="${item.categoria||''}" oninput="itensContratoAtual[${idx}].categoria=this.value" style="flex:1; min-width:110px;">
      <input type="month" title="Vigente até esta competência (deixe em branco para não ter fim)" value="${item.vigenteAte||''}" onchange="itensContratoAtual[${idx}].vigenteAte=this.value||null; renderizarItensContratoForm(); atualizarPreviewTotalContrato();" style="width:150px;">
      <button type="button" onclick="itensContratoAtual.splice(${idx},1); renderizarItensContratoForm(); atualizarPreviewTotalContrato();" style="background:none; border:1px solid var(--line); color:var(--ink-soft); border-radius:6px; padding:6px 10px; cursor:pointer;">×</button>
      ${item.vigenteAte ? `<span style="font-size:11px; color:var(--ink-soft); width:100%;">Para de entrar nas vendas a partir da competência seguinte a ${item.vigenteAte}.</span>` : ''}
    </div>
  `).join('') || '<p style="color:var(--ink-soft); font-size:12px;">Nenhum item ainda.</p>';
}
function adicionarItemContrato(){
  itensContratoAtual.push({descricao:'', valor:0, categoria:'', vigenteAte:null});
  renderizarItensContratoForm();
}
function atualizarPreviewTotalContrato(){
  document.getElementById('ctr-total-preview').textContent = formatBRL(totalItensVigentes(itensContratoAtual, competenciaAtualStr()));
}

function abrirFormularioContrato(id){
  popularSelectClientesContrato();
  document.getElementById('ctr-id').value = '';
  document.getElementById('ctr-periodicidade').value = 'mensal';
  document.getElementById('ctr-dia').value = '';
  document.getElementById('ctr-inicio').value = new Date().toISOString().slice(0,10);
  document.getElementById('ctr-fim').value = '';
  document.getElementById('ctr-status').value = 'ativo';
  document.getElementById('ctr-responsavel').value = '';
  document.getElementById('ctr-emitir-cobranca').checked = false;
  document.getElementById('ctr-emitir-nf').checked = false;
  document.getElementById('contrato-form-msg').textContent = '';
  document.getElementById('contrato-form-titulo').textContent = id ? 'Editar contrato' : 'Novo contrato';
  itensContratoAtual = [{descricao:'', valor:0, categoria:'', vigenteAte:null}];
  if(id){
    const c = state.contratosRecorrentes.find(x=>x.id===id);
    if(c){
      document.getElementById('ctr-id').value = c.id;
      document.getElementById('ctr-cliente').value = c.clienteId;
      document.getElementById('ctr-empresa').value = c.empresa;
      document.getElementById('ctr-periodicidade').value = c.periodicidade;
      document.getElementById('ctr-dia').value = c.diaGeracao;
      document.getElementById('ctr-inicio').value = c.inicio;
      document.getElementById('ctr-fim').value = c.fim || '';
      document.getElementById('ctr-status').value = c.status;
      document.getElementById('ctr-responsavel').value = c.responsavelInterno || '';
      document.getElementById('ctr-emitir-cobranca').checked = !!c.emitirCobranca;
      document.getElementById('ctr-emitir-nf').checked = !!c.emitirNf;
      itensContratoAtual = c.itens.map(i=>({...i}));
    }
  }
  renderizarItensContratoForm();
  atualizarPreviewTotalContrato();
  document.getElementById('contrato-form-overlay').style.display = 'flex';
}
document.getElementById('btn-novo-contrato').addEventListener('click', ()=> abrirFormularioContrato(null));
document.getElementById('contrato-form-cancelar').addEventListener('click', ()=>{
  document.getElementById('contrato-form-overlay').style.display = 'none';
});

function salvarContrato(){
  const msg = document.getElementById('contrato-form-msg');
  const clienteId = document.getElementById('ctr-cliente').value;
  const dia = parseInt(document.getElementById('ctr-dia').value, 10);
  const itensValidos = itensContratoAtual.filter(i=> i.descricao && i.descricao.trim() && i.valor > 0);
  if(!clienteId || isNaN(dia) || dia<1 || dia>28 || itensValidos.length===0){
    msg.textContent = 'Escolha um cliente, um dia de geração entre 1 e 28, e ao menos um item com valor.';
    msg.className = 'auth-msg erro';
    return;
  }
  const idExistente = document.getElementById('ctr-id').value;
  const contrato = {
    id: idExistente || uid(),
    clienteId,
    empresa: document.getElementById('ctr-empresa').value,
    periodicidade: document.getElementById('ctr-periodicidade').value,
    diaGeracao: dia,
    inicio: document.getElementById('ctr-inicio').value,
    fim: document.getElementById('ctr-fim').value || null,
    status: document.getElementById('ctr-status').value,
    itens: itensValidos,
    emitirCobranca: document.getElementById('ctr-emitir-cobranca').checked,
    emitirNf: document.getElementById('ctr-emitir-nf').checked,
    responsavelInterno: document.getElementById('ctr-responsavel').value.trim() || null,
    ultimaInteracao: idExistente ? (state.contratosRecorrentes.find(c=>c.id===idExistente)||{}).ultimaInteracao || null : null,
    competenciasGeradas: idExistente ? (state.contratosRecorrentes.find(c=>c.id===idExistente)||{}).competenciasGeradas || [] : []
  };
  if(idExistente){
    const idx = state.contratosRecorrentes.findIndex(c=>c.id===idExistente);
    if(idx>-1) state.contratosRecorrentes[idx] = contrato;
    auditar('Editou contrato recorrente', clienteId);
  } else {
    state.contratosRecorrentes.push(contrato);
    auditar('Criou contrato recorrente', clienteId);
  }
  salvarEstado();
  document.getElementById('contrato-form-overlay').style.display = 'none';
  renderContratosRecorrentes();
}

function alternarStatusContrato(id){
  const c = state.contratosRecorrentes.find(x=>x.id===id);
  if(!c) return;
  c.status = c.status==='ativo' ? 'pausado' : 'ativo';
  auditar(c.status==='ativo' ? 'Reativou contrato' : 'Pausou contrato', c.id);
  salvarEstado();
  renderContratosRecorrentes();
}
function cancelarContratoRecorrente(id){
  const c = state.contratosRecorrentes.find(x=>x.id===id);
  if(!c) return;
  if(!confirm('Cancelar este contrato? As vendas já geradas continuam existindo — só as competências futuras deixam de nascer.')) return;
  c.status = 'cancelado';
  auditar('Cancelou contrato recorrente', c.id);
  salvarEstado();
  renderContratosRecorrentes();
}
function excluirContrato(id){
  if(!confirm('Excluir este contrato recorrente? As vendas já geradas não são apagadas.')) return;
  const c = state.contratosRecorrentes.find(x=>x.id===id);
  state.contratosRecorrentes = state.contratosRecorrentes.filter(x=>x.id!==id);
  if(c) auditar('Excluiu contrato recorrente', c.id);
  salvarEstado();
  renderContratosRecorrentes();
}

/* Gera a VENDA (não um lançamento avulso) da competência atual, se ainda
   não tiver sido gerada para este contrato — a chave de idempotência é
   (contratoId, competência), nunca duplica mesmo clicando várias vezes.
   Só entram os itens ainda vigentes naquela competência: é assim que o
   item "implantação" para de cobrar sozinho depois do prazo combinado.
   Reaproveita a mesma numeração/parcelas/AR do módulo de Vendas — a
   venda gerada aparece em 15.0 Vendas e em 7.0 Contas a Receber como
   qualquer outra, com origemContratoId marcado. */
function gerarVendaContrato(id, competenciaForcada){
  const c = state.contratosRecorrentes.find(x=>x.id===id);
  if(!c || c.status!=='ativo') return null;
  const competencia = competenciaForcada || competenciaAtualStr();
  c.competenciasGeradas = c.competenciasGeradas || [];
  if(c.competenciasGeradas.includes(competencia)){
    return {jaGerada:true};
  }
  const itensVigentes = itensVigentesNaCompetencia(c.itens, competencia);
  if(itensVigentes.length === 0){
    return {semItens:true};
  }
  const cliente = state.clientesFornecedores.find(x=>x.id===c.clienteId);
  const total = itensVigentes.reduce((s,i)=> s + i.valor, 0);
  const numero = proximoNumeroDocumento('VND', c.empresa, state.vendas);
  const vendaId = uid();
  const dataVenda = competencia + '-' + String(c.diaGeracao).padStart(2,'0');

  const venda = {
    id: vendaId, numero, clienteId: c.clienteId, clienteNome: cliente?cliente.nome:'', empresa: c.empresa,
    tipo:'recorrente', origemContratoId: c.id, competencia, data: dataVenda,
    itens: itensVigentes.map(i=>({descricao:i.descricao, valor:i.valor})),
    desconto:0, frete:0, total, situacao:'faturada',
    prontosParaNf: !!c.emitirNf, criadoEm: new Date().toISOString()
  };
  state.vendas.push(venda);

  state.transacoes.push({
    id: uid(), tipo:'receber', empresa: c.empresa, descricao: `${numero} — ${itensVigentes.map(i=>i.descricao).join(', ')} (${competencia})`,
    valor: total, vencimento: dataVenda, categoria: itensVigentes[0].categoria || 'Contrato recorrente', status:'pendente',
    favorecidoId: c.clienteId, favorecidoNome: cliente ? cliente.nome : null, baixas:[],
    contratoId: c.id, vendaId, origem:'contrato'
  });

  if(c.emitirCobranca){
    const transacaoRecemCriada = state.transacoes[state.transacoes.length-1];
    state.cobrancas.push({id: uid(), transacaoId: transacaoRecemCriada.id, tipo:'pix', status:'gerada', dataGeracao: new Date().toISOString()});
  }

  c.competenciasGeradas.push(competencia);
  auditar('Gerou venda de contrato recorrente', numero + ' — ' + competencia + (itensVigentes.length < c.itens.length ? ' (item encerrado não entrou)' : ''));
  salvarEstado();
  return {venda};
}

function gerarVendaContratoManual(id){
  const resultado = gerarVendaContrato(id);
  if(!resultado){ return; }
  if(resultado.jaGerada){ alert('A venda desta competência já foi gerada para este contrato.'); return; }
  if(resultado.semItens){ alert('Nenhum item está vigente nesta competência — nada foi gerado.'); return; }
  renderContratosRecorrentes();
  renderTudo();
  alert('Venda ' + resultado.venda.numero + ' gerada — apareceu em Vendas e em Contas a Receber.');
}

function renderContratosRecorrentes(){
  const tbody = document.getElementById('contratos-tbody');
  const vazio = document.getElementById('contratos-vazio');
  const lista = state.contratosRecorrentes;
  vazio.style.display = lista.length ? 'none' : 'block';
  const competenciaAtual = competenciaAtualStr();
  tbody.innerHTML = lista.map(c=>{
    const cliente = state.clientesFornecedores.find(x=>x.id===c.clienteId);
    const vigentes = itensVigentesNaCompetencia(c.itens, competenciaAtual);
    const total = vigentes.reduce((s,i)=>s+i.valor,0);
    return `<tr>
      <td>${cliente ? cliente.nome : '—'}</td>
      <td>${c.empresa}</td>
      <td>${vigentes.map(i=>i.descricao).join(', ')}</td>
      <td class="num">${formatBRL(total)}</td>
      <td>${c.periodicidade}</td>
      <td><span class="tag ${c.status==='ativo'?'ok':c.status==='pausado'?'prox':'vencido'}">${NOMES_STATUS_CONTRATO[c.status]}</span></td>
      <td class="acoes">
        <button type="button" onclick="abrirFormularioContrato('${c.id}')">Editar</button>
        <button type="button" onclick="gerarVendaContratoManual('${c.id}')">Gerar venda do mês</button>
        <button type="button" onclick="abrirHistoricoContrato('${c.id}')">Histórico</button>
        ${c.status!=='cancelado' ? `<button type="button" onclick="alternarStatusContrato('${c.id}')">${c.status==='ativo'?'Pausar':'Reativar'}</button><button type="button" onclick="cancelarContratoRecorrente('${c.id}')">Cancelar</button>` : ''}
        <button type="button" onclick="excluirContrato('${c.id}')">Excluir</button>
      </td>
    </tr>`;
  }).join('');
}

/* ---------- CARTEIRA DE CLIENTES (consultoria/clínica) ----------
   NÃO é o Programa de Parceria/dashboard multi-CNPJ do produto de
   referência — isso fica de fora por decisão explícita. É só account
   management leve: lê contratos + vendas filhas + AR já existentes,
   nunca duplica saldo, nunca inventa um segundo livro-caixa. Cliente só
   entra na carteira se tiver pelo menos um contrato recorrente — sem
   contrato não há o que gerenciar aqui (é a diferença de "carteira de
   consultoria" pra "todo cadastro de cliente"). Pessoal nunca aparece:
   contrato recorrente é sempre de uma empresa PJ (empresa!=='Pessoal'
   já é assumido no restante do módulo). */
function montarCarteira(){
  const hojeStr = new Date().toISOString().slice(0,10);
  return state.contratosRecorrentes.filter(c=>c.empresa!=='Pessoal').map(c=>{
    const cliente = state.clientesFornecedores.find(x=>x.id===c.clienteId);
    const mrr = totalItensVigentes(c.itens, competenciaAtualStr());
    const vendasFilhas = state.vendas.filter(v=>v.origemContratoId===c.id);
    const vendaIds = vendasFilhas.map(v=>v.id);
    const parcelas = state.transacoes.filter(t=> t.contratoId===c.id || vendaIds.includes(t.vendaId));
    let aberto = 0, vencido = 0;
    parcelas.forEach(t=>{
      const sv = statusCalculadoTransacao(t);
      const saldoRestante = t.valor - valorPagoTransacao(t);
      if(sv==='pago') return;
      if(t.vencimento < hojeStr) vencido += saldoRestante; else aberto += saldoRestante;
    });
    return {
      contratoId: c.id, clienteNome: cliente ? cliente.nome : '—', empresa: c.empresa,
      statusContrato: c.status, mrr, aberto, vencido,
      proximaRenovacao: c.fim || null, responsavelInterno: c.responsavelInterno || null,
      ultimaInteracao: c.ultimaInteracao || null,
      statusRelacionamento: vencido>0 ? 'inadimplente' : (c.status==='ativo' ? 'em dia' : c.status)
    };
  });
}
function renderCarteira(){
  const filtroEmpresa = document.getElementById('cart-filtro-empresa').value;
  const filtroStatus = document.getElementById('cart-filtro-status').value;
  const filtroResp = document.getElementById('cart-filtro-responsavel').value.trim().toLowerCase();
  let carteira = montarCarteira();
  if(filtroEmpresa) carteira = carteira.filter(c=>c.empresa===filtroEmpresa);
  if(filtroStatus) carteira = carteira.filter(c=>c.statusRelacionamento===filtroStatus);
  if(filtroResp) carteira = carteira.filter(c=> (c.responsavelInterno||'').toLowerCase().includes(filtroResp));

  const tbody = document.getElementById('carteira-fin-tbody');
  const vazio = document.getElementById('carteira-fin-vazio');
  vazio.style.display = carteira.length ? 'none' : 'block';
  const NOMES_STATUS_REL = {'em dia':'Em dia', inadimplente:'Inadimplente', pausado:'Pausado', cancelado:'Cancelado'};
  tbody.innerHTML = carteira.map(c=>`
    <tr>
      <td>${c.clienteNome}</td>
      <td>${c.empresa}</td>
      <td class="num">${formatBRL(c.mrr)}</td>
      <td class="num">${formatBRL(c.aberto)}</td>
      <td class="num" style="${c.vencido>0?'color:var(--rust);':''}">${formatBRL(c.vencido)}</td>
      <td>${c.proximaRenovacao ? formatarDataBR(c.proximaRenovacao) : '—'}</td>
      <td>${c.responsavelInterno || '—'}</td>
      <td><span class="tag ${c.statusRelacionamento==='em dia'?'ok':c.statusRelacionamento==='inadimplente'?'vencido':'prox'}">${NOMES_STATUS_REL[c.statusRelacionamento]||c.statusRelacionamento}</span></td>
      <td class="acoes"><button type="button" onclick="abrirHistoricoContrato('${c.contratoId}')">Ver contrato</button></td>
    </tr>
  `).join('');
}
function popularFiltrosCarteira(){
  const sel = document.getElementById('cart-filtro-empresa');
  if(sel) sel.innerHTML = '<option value="">Todas</option>' + state.empresas.filter(e=>e.nome!=='Pessoal').map(e=>`<option>${e.nome}</option>`).join('');
}

function abrirHistoricoContrato(id){
  const c = state.contratosRecorrentes.find(x=>x.id===id);
  if(!c) return;
  const cliente = state.clientesFornecedores.find(x=>x.id===c.clienteId);
  const vendasFilhas = state.vendas.filter(v=>v.origemContratoId===id).sort((a,b)=> a.competencia.localeCompare(b.competencia));
  const box = document.getElementById('contrato-historico-conteudo');
  box.innerHTML = `
    <h2 style="margin-top:4px;">${cliente ? cliente.nome : '—'} — ${c.empresa}</h2>
    <p class="leilao-ficha-sub">${c.periodicidade} · dia ${c.diaGeracao} · ${NOMES_STATUS_CONTRATO[c.status]}</p>
    <h3 style="margin-top:14px;">Vendas geradas por competência</h3>
    ${vendasFilhas.length ? `<table class="leilao-admin-table"><thead><tr><th>Competência</th><th>Nº</th><th>Itens</th><th class="num">Total</th></tr></thead><tbody>
      ${vendasFilhas.map(v=>`<tr><td>${v.competencia}</td><td>${v.numero}</td><td>${v.itens.map(i=>i.descricao).join(', ')}</td><td class="num">${formatBRL(v.total)}</td></tr>`).join('')}
    </tbody></table>` : '<p class="leilao-ficha-sub">Nenhuma venda gerada ainda.</p>'}
  `;
  document.getElementById('contrato-historico-overlay').style.display = 'flex';
}
document.getElementById('contrato-historico-fechar').addEventListener('click', ()=>{
  document.getElementById('contrato-historico-overlay').style.display = 'none';
});

/* ---------- 11.0 COBRANÇAS ----------
   Registro de intenção de cobrança vinculado a uma conta a receber já
   existente. Provider fake: nenhum boleto/Pix real é emitido, nenhuma
   credencial de provedor existe no front — isso exige integração
   oficial feita no backend, ainda não implementada. */
function popularSelectTransacoesCobranca(){
  const sel = document.getElementById('cob-transacao');
  const pendentes = state.transacoes.filter(t=>t.tipo==='receber' && t.status==='pendente');
  sel.innerHTML = pendentes.length
    ? pendentes.map(t=>`<option value="${t.id}">${t.descricao} — ${formatBRL(t.valor)} — vence ${formatarDataBR(t.vencimento)}</option>`).join('')
    : '<option value="">Nenhuma conta a receber em aberto</option>';
}
function abrirFormularioCobranca(){
  popularSelectTransacoesCobranca();
  document.getElementById('cobranca-form-msg').textContent = '';
  document.getElementById('cobranca-form-overlay').style.display = 'flex';
}
document.getElementById('btn-nova-cobranca').addEventListener('click', abrirFormularioCobranca);
document.getElementById('cobranca-form-cancelar').addEventListener('click', ()=>{
  document.getElementById('cobranca-form-overlay').style.display = 'none';
});
function salvarCobranca(){
  const msg = document.getElementById('cobranca-form-msg');
  const transacaoId = document.getElementById('cob-transacao').value;
  if(!transacaoId){
    msg.textContent = 'Escolha uma conta a receber em aberto.';
    msg.className = 'auth-msg erro';
    return;
  }
  const transacao = state.transacoes.find(t=>t.id===transacaoId);
  state.cobrancas.push({
    id: uid(), transacaoId, tipo: document.getElementById('cob-tipo').value,
    status:'gerada', dataGeracao: new Date().toISOString()
  });
  auditar('Gerou cobrança', transacao ? transacao.descricao : '');
  salvarEstado();
  document.getElementById('cobranca-form-overlay').style.display = 'none';
  renderCobrancas();
}
function renderCobrancas(){
  const tbody = document.getElementById('cobrancas-tbody');
  const vazio = document.getElementById('cobrancas-vazio');
  vazio.style.display = state.cobrancas.length ? 'none' : 'block';
  const NOMES_TIPO = {boleto:'Boleto', pix:'Pix', link:'Link de cartão'};
  const NOMES_STATUS = {gerada:'Gerada', cancelada:'Cancelada', paga:'Paga'};
  tbody.innerHTML = state.cobrancas.map(c=>{
    const t = state.transacoes.find(x=>x.id===c.transacaoId);
    if(!t) return '';
    return `<tr>
      <td>${t.favorecidoNome || '—'}</td>
      <td>${t.descricao}</td>
      <td class="num">${formatBRL(t.valor)}</td>
      <td>${formatarDataBR(t.vencimento)}</td>
      <td>${NOMES_TIPO[c.tipo]}</td>
      <td><span class="tag ${c.status==='paga'?'ok':c.status==='gerada'?'pendente':'vencido'}">${NOMES_STATUS[c.status]}</span></td>
      <td class="acoes">
        ${c.status==='gerada' ? `<button type="button" onclick="cancelarCobranca('${c.id}')">Cancelar</button><button type="button" onclick="reemitirCobranca('${c.id}')">Reemitir</button><button type="button" onclick="simularPagamentoCobranca('${c.id}')" style="color:var(--rust);" title="Só em ambiente de desenvolvimento — dispara o webhook interno fake">Simular pagamento (dev)</button>` : ''}
      </td>
    </tr>`;
  }).join('');
}
function cancelarCobranca(id){
  const c = state.cobrancas.find(x=>x.id===id);
  if(!c) return;
  c.status = 'cancelada';
  auditar('Cancelou cobrança', id);
  salvarEstado();
  renderCobrancas();
}
function reemitirCobranca(id){
  const c = state.cobrancas.find(x=>x.id===id);
  if(!c) return;
  c.dataGeracao = new Date().toISOString();
  auditar('Reemitiu cobrança', id);
  salvarEstado();
  renderCobrancas();
  alert('Cobrança reemitida (registro local — nenhum envio real).');
}

/* Botão só de desenvolvimento — nenhum provedor real dispara isso.
   Simula o webhook assinado que um PaymentProvider de verdade mandaria
   ao confirmar o pagamento: dá baixa no título vinculado (valor cheio,
   na data de hoje, sem juros/multa/desconto) e marca a cobrança como
   paga. O saldo da conta só muda agora, na baixa — nunca ao gerar a
   cobrança. */
function simularPagamentoCobranca(id){
  const c = state.cobrancas.find(x=>x.id===id);
  if(!c || c.status!=='gerada') return;
  const t = state.transacoes.find(x=>x.id===c.transacaoId);
  if(!t){ alert('O título vinculado a esta cobrança não existe mais.'); return; }
  if(statusCalculadoTransacao(t)==='pago'){ alert('Este título já está totalmente baixado.'); return; }
  if(!confirm('Simular o webhook de pagamento (só em dev) para ' + t.descricao + ' — ' + formatBRL(t.valor) + '?')) return;
  if(!t.baixas) t.baixas = [];
  t.baixas.push({
    id: uid(), data: new Date().toISOString().slice(0,10), valorEfetivo: t.valor - valorPagoTransacao(t),
    juros:0, multa:0, desconto:0, tarifa:0, observacoes: 'Baixa automática via webhook simulado (cobrança ' + id + ')',
    contaFinanceiraId: null
  });
  t.status = statusCalculadoTransacao(t);
  c.status = 'paga';
  auditar('Simulou pagamento (webhook dev)', t.descricao + ' — ' + formatBRL(t.valor));
  salvarEstado();
  renderCobrancas();
  renderTudo();
}

/* ---------- 12.0 RELATÓRIOS + AUDITORIA ---------- */
function baixarCSV(nomeArquivo, linhas){
  const conteudo = linhas.map(l=> l.map(c=> `"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n');
  const blob = new Blob([conteudo], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = nomeArquivo;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function relatorioPagarAberto(){ return state.transacoes.filter(t=>t.tipo==='pagar' && t.status==='pendente'); }
function relatorioReceberAberto(){ return state.transacoes.filter(t=>t.tipo==='receber' && t.status==='pendente'); }
function relatorioInadimplencia(){
  const hojeStr = new Date().toISOString().slice(0,10);
  return state.transacoes.filter(t=>t.tipo==='receber' && t.status==='pendente' && t.vencimento < hojeStr);
}

/* ---------- MOTOR DE DRE (competência) — o mesmo lançamento aparece em
   datas diferentes conforme a pergunta: quando o fato aconteceu
   (competência/DRE), quando o dinheiro mudou de mão (baixa/fluxo de
   caixa), ou quando estava combinado pagar (vencimento/posição AR-AP).
   Nenhuma dessas visões "está errada" — são a mesma base de lançamentos
   olhada por três datas diferentes. Transferência entre contas próprias
   nunca entra aqui, porque nem é uma transação — vive em
   state.transferencias, sempre fora do Resultado. */
function competenciaDaTransacao(t){
  return t.competencia || (t.vencimento ? t.vencimento.slice(0,7) : null);
}
function calcularDRE({empresa, de, ate}){
  const porCategoria = {};
  state.transacoes.forEach(t=>{
    if(empresa && t.empresa !== empresa) return;
    if(!empresa && ehContador() && t.empresa === 'Pessoal') return; // contador nunca vê Pessoal, nem em "Todas"
    const comp = competenciaDaTransacao(t);
    if(!comp) return;
    if(de && comp < de) return;
    if(ate && comp > ate) return;
    const cat = t.categoria || (t.tipo==='receber' ? 'Receita' : 'Despesa');
    /* v104-GF (GF11): lançamento de classe patrimonial (aporte, empréstimo,
       imobilizado, retirada) não é receita nem despesa — fora do resultado. */
    if(typeof dmMapaClasses === 'function' && CLASSES_PATRIMONIAIS[dmMapaClasses()[cat.trim().toLowerCase()]]) return;
    if(!porCategoria[cat]) porCategoria[cat] = {receita:0, despesa:0};
    if(t.tipo==='receber') porCategoria[cat].receita += t.valor;
    else porCategoria[cat].despesa += t.valor;
  });
  const linhas = Object.keys(porCategoria).sort().map(cat=>({categoria:cat, ...porCategoria[cat]}));
  const totalReceita = linhas.reduce((s,l)=>s+l.receita,0);
  const totalDespesa = linhas.reduce((s,l)=>s+l.despesa,0);
  return {linhas, totalReceita, totalDespesa, resultado: totalReceita - totalDespesa};
}
function renderDRE(){
  const empresa = document.getElementById('dre-empresa').value;
  const de = document.getElementById('dre-de').value || null;
  const ate = document.getElementById('dre-ate').value || null;
  const dre = calcularDRE({empresa, de, ate});
  const tbody = document.getElementById('dre-tbody');
  tbody.innerHTML = dre.linhas.length ? dre.linhas.map(l=>`
    <tr><td>${l.categoria}</td><td class="num">${l.receita>0?formatarMoedaOuOculto(l.receita):'—'}</td><td class="num">${l.despesa>0?formatarMoedaOuOculto(l.despesa):'—'}</td></tr>
  `).join('') : '<tr><td colspan="3" style="color:var(--ink-soft);">Nenhum lançamento com competência no período.</td></tr>';
  document.getElementById('dre-resultado').textContent =
    `Receita ${formatarMoedaOuOculto(dre.totalReceita)} − Despesa ${formatarMoedaOuOculto(dre.totalDespesa)} = Resultado ${formatarMoedaOuOculto(dre.resultado)}`;
  document.getElementById('dre-timestamp').textContent = 'Calculado agora — ' + new Date().toLocaleString('pt-BR') + '. Base: competência (fato gerador), não caixa.';
  window.__ultimoDRE = dre;
}


/* ==========================================================================
   v103-GF — DEMONSTRAÇÕES FINANCEIRAS (Etapa 1): DRE formal, BP simplificado
   e DFC método direto, por período (mensal/trimestral/anual) e por empresa.
   Lê SÓ o que já existe: state.transacoes (competência p/ DRE; baixas p/
   caixa), state.contasFinanceiras, state.transferencias e state.produtos.
   ========================================================================== */
var NOMES_CLASSE_DRE = {receita_bruta:'Receita bruta', deducao:'Dedução da receita', custo:'Custo (CMV/CSP)',
                        despesa_oper:'Despesa operacional', financeiro:'Resultado financeiro', ir:'IR e CSLL',
                        imobilizado:'Imobilizado', emprestimo:'Empréstimos', aporte_capital:'Aporte de capital', retirada:'Retirada/distribuição'};
var CLASSES_PATRIMONIAIS = {imobilizado:1, emprestimo:1, aporte_capital:1, retirada:1};   /* v104-GF */

function dmTrocaModo(){
  const modo = document.getElementById('dm-modo').value;
  document.getElementById('dm-mes-wrap').style.display = modo==='mensal' ? '' : 'none';
  document.getElementById('dm-tri-wrap').style.display = modo==='trimestral' ? '' : 'none';
  document.getElementById('dm-ano-wrap').style.display = modo==='mensal' ? 'none' : '';
}

function prepararDemonstracoes(){
  const selEmp = document.getElementById('dm-empresa');
  const empresas = (ehContador() ? state.empresas.filter(e=>e.nome!=='Pessoal') : state.empresas);
  selEmp.innerHTML = '<option value="">Todas</option>' + empresas.map(e=>'<option>'+e.nome+'</option>').join('');
  const hoje = new Date();
  if(!document.getElementById('dm-mes').value) document.getElementById('dm-mes').value = hoje.toISOString().slice(0,7);
  const selAno = document.getElementById('dm-ano');
  if(!selAno.options.length){
    let anos = [];
    for(let a = hoje.getFullYear(); a >= hoje.getFullYear()-7; a--) anos.push(a);
    selAno.innerHTML = anos.map(a=>'<option>'+a+'</option>').join('');
    document.getElementById('dm-tri').value = String(Math.floor(hoje.getMonth()/3)+1);
  }
  dmTrocaModo();
  renderDemonstracoes();
}

/* Período escolhido -> {rotulo, mesDe, mesAte (AAAA-MM), diaDe, diaAte (AAAA-MM-DD)} */
function dmPeriodo(){
  const modo = document.getElementById('dm-modo').value;
  const fimDoMes = (am) => { const [a,m] = am.split('-').map(Number); return am + '-' + String(new Date(a, m, 0).getDate()).padStart(2,'0'); };
  if(modo==='mensal'){
    const am = document.getElementById('dm-mes').value || new Date().toISOString().slice(0,7);
    const [a,m] = am.split('-');
    return {rotulo: m+'/'+a, mesDe: am, mesAte: am, diaDe: am+'-01', diaAte: fimDoMes(am)};
  }
  const ano = document.getElementById('dm-ano').value || String(new Date().getFullYear());
  if(modo==='trimestral'){
    const t = Number(document.getElementById('dm-tri').value||1);
    const m1 = String((t-1)*3+1).padStart(2,'0'), m3 = String(t*3).padStart(2,'0');
    return {rotulo: t+'º trimestre de '+ano, mesDe: ano+'-'+m1, mesAte: ano+'-'+m3, diaDe: ano+'-'+m1+'-01', diaAte: fimDoMes(ano+'-'+m3)};
  }
  return {rotulo: 'exercício de '+ano, mesDe: ano+'-01', mesAte: ano+'-12', diaDe: ano+'-01-01', diaAte: ano+'-12-31'};
}

/* nome da categoria (como digitado no lançamento) -> classe da DRE */
function dmMapaClasses(){
  const mapa = {};
  (state.categoriasFluxo||[]).forEach(c=>{
    if(c.tipo==='totalizador' || !c.classeDre) return;
    mapa[(c.nome||'').trim().toLowerCase()] = c.classeDre;
  });
  return mapa;
}

function dmTransacoesDoPeriodo(p, empresa){
  return state.transacoes.filter(t=>{
    if(empresa && t.empresa !== empresa) return false;
    if(!empresa && ehContador() && t.empresa === 'Pessoal') return false;
    const comp = competenciaDaTransacao(t);
    return comp && comp >= p.mesDe && comp <= p.mesAte;
  });
}

function calcularDREFormal(p, empresa){
  const mapa = dmMapaClasses();
  const grupos = {receita_bruta:{}, deducao:{}, custo:{}, despesa_oper:{}, financeiro_rec:{}, financeiro_desp:{}, ir:{},
                  rec_nc:{}, desp_nc:{}, patrimonial:{}};   /* v104-GF: fora da DRE */
  dmTransacoesDoPeriodo(p, empresa).forEach(t=>{
    const cat = (t.categoria||'').trim() || (t.tipo==='receber' ? 'Receita' : 'Despesa');
    const cls = mapa[cat.toLowerCase()];
    let g;
    if(cls==='receita_bruta') g = 'receita_bruta';
    else if(cls==='deducao') g = 'deducao';
    else if(cls==='custo') g = 'custo';
    else if(cls==='despesa_oper') g = 'despesa_oper';
    else if(cls==='financeiro') g = (t.tipo==='receber' ? 'financeiro_rec' : 'financeiro_desp');
    else if(cls==='ir') g = 'ir';
    else if(CLASSES_PATRIMONIAIS[cls]) g = 'patrimonial';   /* v104-GF: não entra no resultado */
    else g = (t.tipo==='receber' ? 'rec_nc' : 'desp_nc');
    grupos[g][cat] = (grupos[g][cat]||0) + t.valor;
  });
  const soma = g => Object.values(grupos[g]).reduce((s,v)=>s+v,0);
  const receitaBruta = soma('receita_bruta') + soma('rec_nc');
  const deducoes = soma('deducao');
  const receitaLiquida = receitaBruta - deducoes;
  const custo = soma('custo');
  const lucroBruto = receitaLiquida - custo;
  const despOper = soma('despesa_oper') + soma('desp_nc');
  const depreciacao = dmDepreciacaoPeriodo(p, empresa);   /* v105-GF (GF12) */
  const ebit = lucroBruto - despOper - depreciacao;
  const financeiro = soma('financeiro_rec') - soma('financeiro_desp');
  const lair = ebit + financeiro;
  const ir = soma('ir');
  const liquido = lair - ir;
  return {grupos, receitaBruta, deducoes, receitaLiquida, custo, lucroBruto, despOper, depreciacao, ebit, financeiro, lair, ir, liquido,
          naoClassificadas: Object.keys(grupos.rec_nc).length + Object.keys(grupos.desp_nc).length};
}

function dmLinhasDRE(d, p){
  const F = formatarMoedaOuOculto;
  const det = (obj, sinal) => Object.keys(obj).sort().map(c =>
    ['    · '+c, (sinal<0?'−':'')+' '+F(obj[c]).replace('R$','R$')]);
  const L = [];
  L.push(['RECEITA BRUTA', F(d.receitaBruta)]);
  det(d.grupos.receita_bruta, 1).forEach(x=>L.push(x));
  Object.keys(d.grupos.rec_nc).sort().forEach(c=>L.push(['    · '+c+' (não classificada)', F(d.grupos.rec_nc[c])]));
  L.push(['(−) Deduções da receita', '− '+F(d.deducoes)]);
  det(d.grupos.deducao, -1).forEach(x=>L.push(x));
  L.push(['= RECEITA LÍQUIDA', F(d.receitaLiquida)]);
  L.push(['(−) Custo (CMV/CSP)', '− '+F(d.custo)]);
  det(d.grupos.custo, -1).forEach(x=>L.push(x));
  L.push(['= LUCRO BRUTO', F(d.lucroBruto)]);
  L.push(['(−) Despesas operacionais', '− '+F(d.despOper)]);
  det(d.grupos.despesa_oper, -1).forEach(x=>L.push(x));
  Object.keys(d.grupos.desp_nc).sort().forEach(c=>L.push(['    · '+c+' (não classificada)', '− '+F(d.grupos.desp_nc[c])]));
  L.push(['(−) Depreciação do imobilizado', '− '+F(d.depreciacao||0)]);
  L.push(['= RESULTADO ANTES DO FINANCEIRO (EBIT)', F(d.ebit)]);
  L.push(['(±) Resultado financeiro', (d.financeiro<0?'− ':'')+F(Math.abs(d.financeiro))]);
  L.push(['= RESULTADO ANTES DO IR E CSLL', F(d.lair)]);
  L.push(['(−) IR e CSLL', '− '+F(d.ir)]);
  L.push(['= RESULTADO LÍQUIDO DO PERÍODO ('+p.rotulo+')', F(d.liquido)]);
  return L;
}

/* saldo em aberto de um título na data de corte (valor - baixas até a data) */
function dmSaldoAbertoAte(t, diaAte){
  const pago = (t.baixas||[]).filter(b=>b.data <= diaAte).reduce((s,b)=>s+(b.valorEfetivo||0),0);
  return Math.max(0, t.valor - pago);
}

function calcularBP(p, empresa){
  const contas = (state.contasFinanceiras||[]).filter(c=>c.ativo && (!empresa || c.empresa===empresa));
  const diaSeguinte = (d => { const x = parseDate(d); x.setDate(x.getDate()+1); return x.toISOString().slice(0,10); })(p.diaAte);
  const caixa = contas.length ? saldoAcumuladoAte(contas.map(c=>c.id), diaSeguinte, empresa||null) : 0;
  let ar = 0, ap = 0;
  state.transacoes.forEach(t=>{
    if(empresa && t.empresa !== empresa) return;
    if(!empresa && ehContador() && t.empresa === 'Pessoal') return;
    const comp = competenciaDaTransacao(t);
    if(!comp || comp > p.mesAte) return;          // fato gerador depois do corte: fora do balanço
    const aberto = dmSaldoAbertoAte(t, p.diaAte);
    if(t.tipo==='receber') ar += aberto; else ap += aberto;
  });
  let estoque = 0;
  (state.produtos||[]).forEach(pr=>{
    if(empresa && pr.empresa !== empresa) return;
    estoque += (pr.saldo||0) * (pr.custoMedio||0);
  });
  /* v104-GF (GF8): imobilizado, empréstimos e capital = saldos iniciais +
     lançamentos patrimoniais com competência até o corte. */
  const pat = dmPatrimonialAte(p.mesAte, empresa);
  const depAcum = dmDepreciacaoAcumuladaAte(p.mesAte, empresa);   /* v105-GF (GF12) */
  const imobLiquido = pat.imobilizado - depAcum;
  const ativo = caixa + ar + estoque + imobLiquido;
  const passivo = ap + pat.emprestimos;
  const pl = ativo - passivo;
  return {caixa, ar, estoque, imobilizado: pat.imobilizado, depAcum, imobLiquido, ativo,
          ap, emprestimos: pat.emprestimos, passivo, pl,
          capital: pat.capital, lucrosAcum: pl - pat.capital};
}

function calcularDFC(p, empresa){
  let recebimentos = 0, pagamentos = 0, baixasSemConta = 0;
  const porCat = {rec:{}, pag:{}};
  const mapaCls = dmMapaClasses();   /* v104-GF (GF9) */
  const fci = {}, fcf = {};          /* investimento e financiamento, por categoria */
  let fciTotal = 0, fcfTotal = 0;
  state.transacoes.forEach(t=>{
    if(empresa && t.empresa !== empresa) return;
    if(!empresa && ehContador() && t.empresa === 'Pessoal') return;
    (t.baixas||[]).forEach(b=>{
      if(b.data < p.diaDe || b.data > p.diaAte) return;
      const v = baixaLiquida(b);
      const cat = (t.categoria||'').trim() || (t.tipo==='receber' ? 'Receita' : 'Despesa');
      const clsB = mapaCls[cat.toLowerCase()];
      const sinal = t.tipo==='receber' ? v : -v;
      if(clsB === 'imobilizado'){ fci[cat] = (fci[cat]||0) + sinal; fciTotal += sinal; }         /* v104-GF */
      else if(CLASSES_PATRIMONIAIS[clsB]){ fcf[cat] = (fcf[cat]||0) + sinal; fcfTotal += sinal; }
      else if(t.tipo==='receber'){ recebimentos += v; porCat.rec[cat]=(porCat.rec[cat]||0)+v; }
      else { pagamentos += v; porCat.pag[cat]=(porCat.pag[cat]||0)+v; }
      if(!b.contaFinanceiraId) baixasSemConta++;
    });
  });
  const contas = (state.contasFinanceiras||[]).filter(c=>c.ativo && (!empresa || c.empresa===empresa));
  const diaSeguinte = (d => { const x = parseDate(d); x.setDate(x.getDate()+1); return x.toISOString().slice(0,10); })(p.diaAte);
  const porConta = contas.map(c=>{
    const ini = saldoAcumuladoAte([c.id], p.diaDe, null);
    const fim = saldoAcumuladoAte([c.id], diaSeguinte, null);
    let ent = 0, sai = 0, transf = 0;
    state.transacoes.forEach(t=>{ (t.baixas||[]).forEach(b=>{
      if(b.contaFinanceiraId !== c.id || b.data < p.diaDe || b.data > p.diaAte) return;
      const v = baixaLiquida(b);
      if(t.tipo==='receber') ent += v; else sai += v;
    });});
    (state.transferencias||[]).forEach(tr=>{
      if(tr.data < p.diaDe || tr.data > p.diaAte) return;
      if(tr.destinoId === c.id) transf += tr.valor;
      if(tr.origemId === c.id) transf -= tr.valor;
    });
    return {nome: c.nome, empresa: c.empresa, ini, ent, sai, transf, fim};
  });
  const saldoInicial = contas.length ? saldoAcumuladoAte(contas.map(c=>c.id), p.diaDe, empresa||null) : 0;
  const saldoFinal = contas.length ? saldoAcumuladoAte(contas.map(c=>c.id), diaSeguinte, empresa||null) : 0;
  return {recebimentos, pagamentos, geracao: recebimentos - pagamentos, porCat, porConta,
          fci, fcf, fciTotal, fcfTotal,
          geracaoTotal: recebimentos - pagamentos + fciTotal + fcfTotal,
          saldoInicial, saldoFinal, baixasSemConta};
}

function renderDemonstracoes(){
  if(!document.getElementById('dm-dre-table')) return;
  dmPopularPatrimonialForm();   /* v104-GF (GF6/GF7) */
  const p = dmPeriodo();
  const empresa = document.getElementById('dm-empresa').value || null;
  const F = formatarMoedaOuOculto;

  const dre = calcularDREFormal(p, empresa);
  window.__ultimaDREFormal = {p, dre};
  const forte = s => /^(RECEITA BRUTA|= )/.test(s);
  document.querySelector('#dm-dre-table tbody').innerHTML = dmLinhasDRE(dre, p).map(l=>
    '<tr><td style="'+(forte(l[0])?'font-weight:600;':'')+(l[0].startsWith('    ')?'padding-left:26px; color:var(--ink-soft);':'')+'">'
    + l[0].trim() + '</td><td class="num" style="'+(forte(l[0])?'font-weight:600;':'')+'">' + l[1] + '</td></tr>').join('');

  const bp = calcularBP(p, empresa);
  window.__ultimoBP = {p, bp};
  const fSinBP = v => (v<0?'− ':'') + F(Math.abs(v));
  document.querySelector('#dm-bp-table tbody').innerHTML = [
    ['ATIVO', F(bp.ativo), 1],
    ['Caixa e equivalentes', F(bp.caixa), 0], ['Contas a receber', F(bp.ar), 0],
    ['Estoques (custo médio — posição atual do kardex)', F(bp.estoque), 0],
    ['Imobilizado (bens)', F(bp.imobilizado), 0],
    ['(−) Depreciação acumulada', '− '+F(bp.depAcum), 0],
    ['= Imobilizado líquido', F(bp.imobLiquido), 0],
    ['PASSIVO + PATRIMÔNIO LÍQUIDO', F(bp.passivo + bp.pl), 1],
    ['Contas a pagar', F(bp.ap), 0],
    ['Empréstimos e financiamentos (principal)', F(bp.emprestimos), 0],
    ['Patrimônio líquido', fSinBP(bp.pl), 1],
    ['· Capital social', F(bp.capital), 0],
    ['· Lucros ou prejuízos acumulados (apurados por diferença)', fSinBP(bp.lucrosAcum), 0]
  ].map(l=>'<tr><td style="'+(l[2]?'font-weight:600;':'padding-left:26px;')+'">'+l[0]+'</td><td class="num" style="'+(l[2]?'font-weight:600;':'')+'">'+l[1]+'</td></tr>').join('');

  const dfc = calcularDFC(p, empresa);
  window.__ultimaDFC = {p, dfc};
  const linhasDfc = [];
  const fSin = v => (v<0?'− ':'') + F(Math.abs(v));
  linhasDfc.push(['ATIVIDADES OPERACIONAIS', '', 1]);
  linhasDfc.push(['Recebimentos de clientes e outras entradas', F(dfc.recebimentos), 0]);
  Object.keys(dfc.porCat.rec).sort().forEach(c=>linhasDfc.push(['· '+c, F(dfc.porCat.rec[c]), 2]));
  linhasDfc.push(['(−) Pagamentos a fornecedores e outras saídas', '− '+F(dfc.pagamentos), 0]);
  Object.keys(dfc.porCat.pag).sort().forEach(c=>linhasDfc.push(['· '+c, '− '+F(dfc.porCat.pag[c]), 2]));
  linhasDfc.push(['= Caixa das operações', fSin(dfc.geracao), 1]);
  linhasDfc.push(['ATIVIDADES DE INVESTIMENTO (imobilizado)', '', 1]);
  Object.keys(dfc.fci).sort().forEach(c=>linhasDfc.push(['· '+c, fSin(dfc.fci[c]), 2]));
  linhasDfc.push(['= Caixa dos investimentos', fSin(dfc.fciTotal), 1]);
  linhasDfc.push(['ATIVIDADES DE FINANCIAMENTO (empréstimos, aportes, retiradas)', '', 1]);
  Object.keys(dfc.fcf).sort().forEach(c=>linhasDfc.push(['· '+c, fSin(dfc.fcf[c]), 2]));
  linhasDfc.push(['= Caixa dos financiamentos', fSin(dfc.fcfTotal), 1]);
  linhasDfc.push(['= VARIAÇÃO DE CAIXA NO PERÍODO ('+p.rotulo+')', fSin(dfc.geracaoTotal), 1]);
  linhasDfc.push(['Saldo de caixa no início do período', F(dfc.saldoInicial), 0]);
  linhasDfc.push(['Saldo de caixa no fim do período', F(dfc.saldoFinal), 1]);
  const difConf = dfc.saldoFinal - dfc.saldoInicial - dfc.geracaoTotal;
  if(Math.abs(difConf) > 0.005){
    linhasDfc.push(['Diferença de conferência (transferências com outra empresa, baixas fora das contas listadas)', fSin(difConf), 0]);
  }
  document.querySelector('#dm-dfc-table tbody').innerHTML = linhasDfc.map(l=>
    '<tr><td style="'+(l[2]===1?'font-weight:600;':l[2]===2?'padding-left:40px; color:var(--ink-soft);':'padding-left:18px;')+'">'+l[0]+'</td><td class="num" style="'+(l[2]===1?'font-weight:600;':'')+'">'+l[1]+'</td></tr>').join('');

  document.querySelector('#dm-dfc-contas-table tbody').innerHTML = dfc.porConta.length ? dfc.porConta.map(c=>
    '<tr><td>'+c.nome+'</td><td>'+c.empresa+'</td><td class="num">'+F(c.ini)+'</td><td class="num">'+F(c.ent)+'</td><td class="num">− '+F(c.sai)+'</td><td class="num">'+F(c.transf)+'</td><td class="num">'+F(c.fim)+'</td></tr>').join('')
    : '<tr><td colspan="7" style="color:var(--ink-soft);">Nenhuma conta financeira cadastrada.</td></tr>';

  renderDMPL(p, empresa, dre, bp);   /* v104-GF (GF10) */
  renderDVA(p, empresa, dre);
  renderOrcadoRealizado(p, empresa);   /* v105-GF (GF14) */
  dmRenderPatrimonialLista();
  dmRenderSaldosIniciais();

  const avisos = [];
  if(dre.naoClassificadas) avisos.push('Há categorias sem classificação na DRE (aparecem como "não classificadas"). Classifique-as na tela 5.0 Categorias do Fluxo.');
  if(dfc.baixasSemConta) avisos.push(dfc.baixasSemConta + ' baixa(s) do período sem conta financeira: o "Caixa por conta" não as separa (o total do caixa continua certo).');
  document.getElementById('dm-avisos').innerHTML = avisos.map(a=>'<div class="note warn" style="margin-top:8px;">'+a+'</div>').join('');
}

function exportarCsvDRE(){
  if(!window.__ultimaDREFormal) renderDemonstracoes();
  const {p, dre} = window.__ultimaDREFormal;
  baixarCSV('dre_'+p.diaDe+'_a_'+p.diaAte+'.csv', [['Linha','Valor']].concat(dmLinhasDRE(dre, p).map(l=>[l[0].trim(), l[1]])));
}
function exportarCsvBP(){
  if(!window.__ultimoBP) renderDemonstracoes();
  const {p, bp} = window.__ultimoBP; const F = formatarMoedaOuOculto;
  baixarCSV('balanco_'+p.diaAte+'.csv', [['Linha','Valor'],
    ['ATIVO', F(bp.ativo)], ['Caixa e equivalentes', F(bp.caixa)], ['Contas a receber', F(bp.ar)], ['Estoques', F(bp.estoque)],
    ['PASSIVO + PL', F(bp.passivo + bp.pl)], ['Contas a pagar', F(bp.ap)], ['Patrimônio líquido (por diferença)', F(bp.pl)]]);
}
function exportarCsvDFC(){
  if(!window.__ultimaDFC) renderDemonstracoes();
  const {p, dfc} = window.__ultimaDFC; const F = formatarMoedaOuOculto;
  const linhas = [['Linha','Valor'], ['Recebimentos', F(dfc.recebimentos)], ['Pagamentos', F(dfc.pagamentos)],
    ['Caixa gerado', F(dfc.geracao)], ['Saldo inicial', F(dfc.saldoInicial)], ['Saldo final', F(dfc.saldoFinal)]];
  dfc.porConta.forEach(c=>linhas.push(['Conta '+c.nome+' ('+c.empresa+')', F(c.ini)+' -> '+F(c.fim)]));
  baixarCSV('dfc_'+p.diaDe+'_a_'+p.diaAte+'.csv', linhas);
}

/* ==========================================================================
   v104-GF — Etapa 2: lançamentos patrimoniais, saldos iniciais, BP completo,
   DMPL e DVA. Tudo dentro do MESMO bloco de estado já gravado.
   ========================================================================== */
var DM_TIPOS_PATRIMONIAIS = {
  compra_bem:        {lado:'pagar',   categoria:'Imobilizado',               classe:'imobilizado'},
  venda_bem:         {lado:'receber', categoria:'Imobilizado',               classe:'imobilizado'},
  capta_emprestimo:  {lado:'receber', categoria:'Empréstimos (principal)',   classe:'emprestimo'},
  amortiza_emprestimo:{lado:'pagar',  categoria:'Empréstimos (principal)',   classe:'emprestimo'},
  aporte:            {lado:'receber', categoria:'Aporte de capital',         classe:'aporte_capital'},
  retirada:          {lado:'pagar',   categoria:'Retiradas e distribuições', classe:'retirada'}
};
var DM_ROTULOS_PL = {compra_bem:'Compra de bem', venda_bem:'Venda de bem', capta_emprestimo:'Captação de empréstimo',
                     amortiza_emprestimo:'Amortização de empréstimo', aporte:'Aporte de capital', retirada:'Retirada/distribuição'};

function dmGarantirCategoriaPatrimonial(nome, classe){
  let c = (state.categoriasFluxo||[]).find(x => x.tipo !== 'totalizador' && (x.nome||'').trim().toLowerCase() === nome.toLowerCase());
  if(!c){
    c = {id: uid(), nome, tipo: 'categoria', paiId: null, categoriasFinanceiras: [], classeDre: classe, classeDva: 'insumos'};
    state.categoriasFluxo.push(c);
  } else if(c.classeDre !== classe){
    c.classeDre = classe;
  }
  return c;
}

/* saldos iniciais + lançamentos patrimoniais com competência até mesAte */
function dmPatrimonialAte(mesAte, empresa){
  const r = {imobilizado: 0, emprestimos: 0, capital: 0};
  const si = state.saldosPatrimoniais || {};
  Object.keys(si).forEach(emp=>{
    if(empresa && emp !== empresa) return;
    if(!empresa && ehContador() && emp === 'Pessoal') return;
    const x = si[emp];
    if(x.data && x.data.slice(0,7) > mesAte) return;   // posição de partida depois do corte: fora
    r.imobilizado += x.imobilizado || 0;
    r.emprestimos += x.emprestimos || 0;
    r.capital += x.capital || 0;
  });
  const mapa = dmMapaClasses();
  state.transacoes.forEach(t=>{
    if(empresa && t.empresa !== empresa) return;
    if(!empresa && ehContador() && t.empresa === 'Pessoal') return;
    const comp = competenciaDaTransacao(t);
    if(!comp || comp > mesAte) return;
    const cls = mapa[(t.categoria||'').trim().toLowerCase()];
    if(!CLASSES_PATRIMONIAIS[cls]) return;
    const entrada = t.tipo === 'receber';
    if(cls === 'imobilizado') r.imobilizado += entrada ? -t.valor : t.valor;   // compra = pagar
    if(cls === 'emprestimo')  r.emprestimos += entrada ? t.valor : -t.valor;   // captação = receber
    if(cls === 'aporte_capital' && entrada) r.capital += t.valor;
  });
  return r;
}

/* aportes, retiradas no PERÍODO (competência) — para a DMPL */
function dmMovimentosPL(p, empresa){
  const mapa = dmMapaClasses();
  let aportes = 0, retiradas = 0;
  state.transacoes.forEach(t=>{
    if(empresa && t.empresa !== empresa) return;
    if(!empresa && ehContador() && t.empresa === 'Pessoal') return;
    const comp = competenciaDaTransacao(t);
    if(!comp || comp < p.mesDe || comp > p.mesAte) return;
    const cls = mapa[(t.categoria||'').trim().toLowerCase()];
    if(cls === 'aporte_capital' && t.tipo === 'receber') aportes += t.valor;
    if(cls === 'retirada' && t.tipo === 'pagar') retiradas += t.valor;
  });
  return {aportes, retiradas};
}

function renderDMPL(p, empresa, dre, bpFim){
  const tb = document.querySelector('#dm-dmpl-table tbody');
  if(!tb) return;
  const F = formatarMoedaOuOculto;
  const fS = v => (v<0?'− ':'') + F(Math.abs(v));
  // posição no dia anterior ao início do período
  const dAnt = parseDate(p.diaDe); dAnt.setDate(dAnt.getDate()-1);
  const pAnt = {mesAte: dAnt.toISOString().slice(0,7), diaAte: dAnt.toISOString().slice(0,10)};
  const bpIni = calcularBP(pAnt, empresa);
  const mov = dmMovimentosPL(p, empresa);
  const capIni = bpIni.capital, lucIni = bpIni.pl - bpIni.capital;
  const capFim = capIni + mov.aportes;
  const lucFim = lucIni + dre.liquido - mov.retiradas;
  const linhas = [
    ['Saldo no início do período', fS(capIni), fS(lucIni), fS(capIni + lucIni), 1],
    ['(+) Aportes de capital', F(mov.aportes), '—', F(mov.aportes), 0],
    ['(−) Retiradas e distribuições de lucros', '—', '− '+F(mov.retiradas), '− '+F(mov.retiradas), 0],
    ['(±) Resultado líquido do período (DRE)', '—', fS(dre.liquido), fS(dre.liquido), 0],
    ['= Saldo no fim do período ('+p.rotulo+')', fS(capFim), fS(lucFim), fS(capFim + lucFim), 1],
    ['Patrimônio líquido pelo balanço (conferência)', '', '', fS(bpFim.pl), 0]
  ];
  const dif = bpFim.pl - (capFim + lucFim);
  if(Math.abs(dif) > 0.005){
    linhas.push(['Diferença de conferência (juros/multas/descontos de baixas, estoque na posição atual)', '', '', fS(dif), 0]);
  }
  tb.innerHTML = linhas.map(l=>'<tr><td style="'+(l[4]?'font-weight:600;':'')+'">'+l[0]+'</td><td class="num">'+l[1]+'</td><td class="num">'+l[2]+'</td><td class="num" style="'+(l[4]?'font-weight:600;':'')+'">'+l[3]+'</td></tr>').join('');
  window.__ultimaDMPL = {p, linhas};
}

function calcularDVA(p, empresa, dre){
  // repartição das despesas operacionais pela coluna "Na DVA" da tela 5.0
  const porDva = {insumos:0, pessoal:0, alugueis:0};
  const cadastro = {};
  (state.categoriasFluxo||[]).forEach(c=>{
    if(c.tipo!=='totalizador') cadastro[(c.nome||'').trim().toLowerCase()] = c.classeDva || 'insumos';
  });
  const somaGrupo = g => Object.keys(g).reduce((s,cat)=>{
    const destino = porDva[cadastro[cat.toLowerCase()]] !== undefined ? cadastro[cat.toLowerCase()] : 'insumos';
    porDva[destino] += g[cat];
    return s + g[cat];
  }, 0);
  somaGrupo(dre.grupos.despesa_oper);
  somaGrupo(dre.grupos.desp_nc);
  const finRec = Object.values(dre.grupos.financeiro_rec).reduce((s,v)=>s+v,0);
  const finDesp = Object.values(dre.grupos.financeiro_desp).reduce((s,v)=>s+v,0);
  const receitas = dre.receitaBruta;
  const insumos = dre.custo + porDva.insumos;
  const vaBruto = receitas - insumos;
  const depreciacao = dre.depreciacao || 0;   /* v105-GF (GF12) */
  const vaLiquido = vaBruto - depreciacao;
  const vaRecebido = finRec;
  const vaTotal = vaLiquido + vaRecebido;
  const pessoal = porDva.pessoal;
  const impostos = dre.deducoes + dre.ir;
  const capTerceiros = finDesp + porDva.alugueis;
  const capProprio = dre.liquido;
  return {receitas, insumos, vaBruto, depreciacao, vaLiquido, vaRecebido, vaTotal, pessoal, impostos,
          juros: finDesp, alugueis: porDva.alugueis, capTerceiros, capProprio,
          somaDistribuicao: pessoal + impostos + capTerceiros + capProprio};
}

function renderDVA(p, empresa, dre){
  const tb = document.querySelector('#dm-dva-table tbody');
  if(!tb) return;
  const F = formatarMoedaOuOculto;
  const fS = v => (v<0?'− ':'') + F(Math.abs(v));
  const d = calcularDVA(p, empresa, dre);
  const linhas = [
    ['1. RECEITAS', F(d.receitas), 1],
    ['2. (−) Insumos adquiridos de terceiros (custos e materiais/serviços)', '− '+F(d.insumos), 0],
    ['3. = VALOR ADICIONADO BRUTO', fS(d.vaBruto), 1],
    ['4. (−) Depreciação', '− '+F(d.depreciacao), 0],
    ['5. = VALOR ADICIONADO LÍQUIDO PRODUZIDO', fS(d.vaLiquido), 1],
    ['6. (+) Valor adicionado recebido em transferência (receitas financeiras)', F(d.vaRecebido), 0],
    ['7. = VALOR ADICIONADO TOTAL A DISTRIBUIR ('+p.rotulo+')', fS(d.vaTotal), 1],
    ['DISTRIBUIÇÃO DO VALOR ADICIONADO', '', 1],
    ['· Pessoal (salários, encargos, benefícios)', F(d.pessoal), 0],
    ['· Impostos, taxas e contribuições', F(d.impostos), 0],
    ['· Remuneração de capital de terceiros (juros ' + F(d.juros) + ' + aluguéis ' + F(d.alugueis) + ')', F(d.capTerceiros), 0],
    ['· Remuneração de capital próprio (resultado do período)', fS(d.capProprio), 0],
    ['= Soma da distribuição (confere com a linha 7)', fS(d.somaDistribuicao), 1]
  ];
  tb.innerHTML = linhas.map(l=>'<tr><td style="'+(l[2]?'font-weight:600;':'padding-left:26px;')+'">'+l[0]+'</td><td class="num" style="'+(l[2]?'font-weight:600;':'')+'">'+l[1]+'</td></tr>').join('');
  window.__ultimaDVA = {p, linhas};
}

function exportarCsvDMPL(){
  if(!window.__ultimaDMPL) renderDemonstracoes();
  const {p, linhas} = window.__ultimaDMPL;
  baixarCSV('dmpl_'+p.diaDe+'_a_'+p.diaAte+'.csv', [['Movimento','Capital social','Lucros acumulados','Total']].concat(linhas.map(l=>[l[0],l[1],l[2],l[3]])));
}
