function dmRenderSaldosIniciais(){
  const alvo = document.getElementById('dm-si-lista');
  if(!alvo) return;
  const si = state.saldosPatrimoniais || {};
  const F = formatarMoedaOuOculto;
  const nomes = Object.keys(si);
  alvo.innerHTML = nomes.length ? nomes.map(emp=>{
    const x = si[emp];
    return '<div class="result-line"><span class="k">'+emp+' — posição de '+formatarDataBR(x.data)+'</span>'
      +'<span class="v">Imobilizado '+F(x.imobilizado)+' · Empréstimos '+F(x.emprestimos)+' · Capital '+F(x.capital)+'</span></div>';
  }).join('') : '<div class="empty">Nenhuma posição de partida registrada — o balanço parte do zero.</div>';
}

/* ==========================================================================
   v105-GF — conclusão do módulo: depreciação, recorrentes, orçado × realizado
   e demonstrações em PDF.
   ========================================================================== */

/* ---------- GF12 — depreciação (linear, mês a mês, a partir do mês SEGUINTE
   à compra/posição; limitada ao valor do bem; venda zera dali em diante não —
   a venda reduz o bruto; a depreciação de bem vendido para de crescer porque
   é limitada ao valor que sobra no grupo? Não: é por BEM, e o bem vendido sai
   do cálculo pela própria transação de venda. Regra simples e documentada.) */
function dmMesesEntre(amIni, amFim){   // meses completos entre AAAA-MM, começando no mês seguinte
  const [a1,m1] = amIni.split('-').map(Number);
  const [a2,m2] = amFim.split('-').map(Number);
  return Math.max(0, (a2*12+m2) - (a1*12+m1));
}
function dmDepreciacaoAcumuladaAte(mesAte, empresa){
  let dep = 0;
  const si = state.saldosPatrimoniais || {};
  Object.keys(si).forEach(emp=>{
    if(empresa && emp !== empresa) return;
    if(!empresa && ehContador() && emp === 'Pessoal') return;
    const x = si[emp];
    if(!x.data || x.data.slice(0,7) > mesAte) return;
    const base = x.imobilizado || 0;
    const taxa = (x.depTaxa || 0) / 100;
    const acumIni = Math.min(base, x.depAcumulada || 0);
    const nova = base * taxa * dmMesesEntre(x.data.slice(0,7), mesAte) / 12;
    dep += Math.min(base, acumIni + nova);
  });
  const mapa = dmMapaClasses();
  state.transacoes.forEach(t=>{
    if(empresa && t.empresa !== empresa) return;
    if(!empresa && ehContador() && t.empresa === 'Pessoal') return;
    if(t.tipo !== 'pagar') return;                            // só compra de bem deprecia
    if(mapa[(t.categoria||'').trim().toLowerCase()] !== 'imobilizado') return;
    const comp = competenciaDaTransacao(t);
    if(!comp || comp > mesAte) return;
    const taxa = (t.depTaxaAnual || 0) / 100;
    if(!taxa) return;
    dep += Math.min(t.valor, t.valor * taxa * dmMesesEntre(comp, mesAte) / 12);
  });
  return dep;
}
function dmDepreciacaoPeriodo(p, empresa){
  const fim = dmDepreciacaoAcumuladaAte(p.mesAte, empresa);
  const dAnt = parseDate(p.diaDe); dAnt.setDate(0);           // último dia do mês anterior
  const ini = dmDepreciacaoAcumuladaAte(dAnt.toISOString().slice(0,7), empresa);
  return Math.max(0, fim - ini);
}

/* ---------- GF13 — lançamentos recorrentes ---------- */
function recSalvar(){
  if(typeof bloquearSeContador === 'function' && bloquearSeContador('Contador não lança — é leitura e exportação.')) return;
  const msg = document.getElementById('rec-msg');
  const lado = document.getElementById('rec-lado').value;
  const empresa = document.getElementById('rec-empresa').value;
  const desc = document.getElementById('rec-desc').value.trim();
  const valor = parseMoeda(document.getElementById('rec-valor').value) || 0;
  const cat = document.getElementById('rec-cat').value.trim();
  const dia = Math.min(28, Math.max(1, Number(document.getElementById('rec-dia').value) || 5));
  const inicio = document.getElementById('rec-inicio').value;
  const fim = document.getElementById('rec-fim').value || null;
  if(!empresa || !desc || valor <= 0 || !cat || !inicio){
    msg.textContent = 'Preencha empresa, descrição, valor, categoria e o primeiro mês.';
    msg.className = 'auth-msg erro'; return;
  }
  if(fim && fim < inicio){
    msg.textContent = 'O último mês não pode ser antes do primeiro.';
    msg.className = 'auth-msg erro'; return;
  }
  if(!state.recorrencias) state.recorrencias = [];
  state.recorrencias.push({id: uid(), lado, empresa, descricao: desc, valor, categoria: cat,
                           dia, inicio, fim, ativo: true});
  document.getElementById('rec-desc').value = '';
  document.getElementById('rec-valor').value = '';
  msg.textContent = 'Recorrente salvo. Os títulos de cada mês serão gerados sozinhos (do primeiro mês até o mês atual, agora mesmo).';
  msg.className = 'auth-msg sucesso';
  recGerarPendentes();
  salvarEstado();
  renderTudo();
  recRender();
}
function recGerarPendentes(){
  if(!state.recorrencias || !state.recorrencias.length) return;
  const mesAtual = new Date().toISOString().slice(0,7);
  let gerou = 0;
  state.recorrencias.forEach(r=>{
    if(!r.ativo) return;
    let am = r.inicio;
    while(am <= mesAtual && (!r.fim || am <= r.fim)){
      const [a,m] = am.split('-').map(Number);
      const jaTem = state.transacoes.some(t=>t.recorrenciaId === r.id && (t.recorrenciaMes === am));
      if(!jaTem){
        const ultimoDia = new Date(a, m, 0).getDate();
        const venc = am + '-' + String(Math.min(r.dia, ultimoDia)).padStart(2,'0');
        state.transacoes.push({id: uid(), tipo: r.lado, empresa: r.empresa, favorecidoId: null, favorecidoNome: '',
                               descricao: r.descricao + ' (' + m.toString().padStart(2,'0') + '/' + a + ')',
                               valor: r.valor, vencimento: venc, categoria: r.categoria,
                               status: 'pendente', criadoEm: new Date().toISOString(), baixas: [],
                               recorrenciaId: r.id, recorrenciaMes: am});
        gerou++;
      }
      am = (m === 12) ? (a+1) + '-01' : a + '-' + String(m+1).padStart(2,'0');
    }
  });
  if(gerou) salvarEstado();
  return gerou;
}
function recAlternar(id){
  const r = (state.recorrencias||[]).find(x=>x.id===id);
  if(!r) return;
  r.ativo = !r.ativo;
  salvarEstado(); recRender();
}
function recExcluir(id){
  if(!confirm('Excluir este recorrente? Os títulos já gerados continuam em Contas a Pagar/Receber.')) return;
  state.recorrencias = (state.recorrencias||[]).filter(x=>x.id!==id);
  salvarEstado(); recRender();
}
function recRender(){
  const tb = document.getElementById('rec-tbody');
  if(!tb) return;
  const selEmp = document.getElementById('rec-empresa');
  if(selEmp){
    const empresas = (ehContador() ? state.empresas.filter(e=>e.nome!=='Pessoal') : state.empresas);
    const atual = selEmp.value;
    selEmp.innerHTML = empresas.map(e=>'<option>'+e.nome+'</option>').join('');
    if([...selEmp.options].some(o=>o.value===atual)) selEmp.value = atual;
  }
  if(document.getElementById('rec-inicio') && !document.getElementById('rec-inicio').value)
    document.getElementById('rec-inicio').value = new Date().toISOString().slice(0,7);
  popularDatalistCategorias();
  const lista = state.recorrencias || [];
  document.getElementById('rec-vazio').style.display = lista.length ? 'none' : 'block';
  const F = formatarMoedaOuOculto;
  tb.innerHTML = lista.map(r=>
    '<tr><td>'+r.descricao+'</td><td>'+(r.lado==='pagar'?'Despesa':'Receita')+'</td><td>'+r.empresa
    +'</td><td class="num">'+F(r.valor)+'</td><td>'+r.dia+'</td><td>'+r.inicio+(r.fim?' a '+r.fim:' em diante')
    +'</td><td>'+(r.ativo?'Ativo':'Pausado')+'</td>'
    +'<td><button class="ghost" onclick="recAlternar(\''+r.id+'\')">'+(r.ativo?'Pausar':'Reativar')+'</button> '
    +'<button class="ghost" onclick="recExcluir(\''+r.id+'\')">Excluir</button></td></tr>').join('');
}

/* ---------- GF14 — orçado × realizado ---------- */
function dmSalvarOrcado(){
  if(typeof bloquearSeContador === 'function' && bloquearSeContador('Contador não lança — é leitura e exportação.')) return;
  const msg = document.getElementById('dm-orc-msg');
  const empresa = document.getElementById('dm-orc-empresa').value;
  const cat = document.getElementById('dm-orc-cat').value.trim();
  const valor = parseMoeda(document.getElementById('dm-orc-valor').value) || 0;
  if(!empresa || !cat || valor <= 0){
    msg.textContent = 'Preencha empresa, categoria e a meta mensal.';
    msg.className = 'auth-msg erro'; return;
  }
  if(!state.orcamentoGerencial) state.orcamentoGerencial = [];
  const existente = state.orcamentoGerencial.find(o=>o.empresa===empresa && o.categoria.toLowerCase()===cat.toLowerCase());
  if(existente) existente.valorMensal = valor;
  else state.orcamentoGerencial.push({id: uid(), empresa, categoria: cat, valorMensal: valor});
  document.getElementById('dm-orc-cat').value = '';
  document.getElementById('dm-orc-valor').value = '';
  msg.textContent = 'Meta salva.';
  msg.className = 'auth-msg sucesso';
  salvarEstado();
  renderDemonstracoes();
}
function dmExcluirOrcado(id){
  state.orcamentoGerencial = (state.orcamentoGerencial||[]).filter(o=>o.id!==id);
  salvarEstado(); renderDemonstracoes();
}
function dmMesesDoPeriodo(p){ return dmMesesEntre(p.mesDe, p.mesAte) + 1; }
function renderOrcadoRealizado(p, empresa){
  const tb = document.querySelector('#dm-orc-table tbody');
  if(!tb) return;
  const selEmp = document.getElementById('dm-orc-empresa');
  if(selEmp && !selEmp.options.length){
    const empresas = (ehContador() ? state.empresas.filter(e=>e.nome!=='Pessoal') : state.empresas);
    selEmp.innerHTML = empresas.map(e=>'<option>'+e.nome+'</option>').join('');
  }
  const metas = (state.orcamentoGerencial||[]).filter(o=>!empresa || o.empresa===empresa);
  document.getElementById('dm-orc-vazio').style.display = metas.length ? 'none' : 'block';
  const meses = dmMesesDoPeriodo(p);
  const F = formatarMoedaOuOculto;
  const trans = dmTransacoesDoPeriodo(p, empresa);
  const linhas = metas.map(o=>{
    const orcado = o.valorMensal * meses;
    const realizado = trans.filter(t=>t.empresa===o.empresa && (t.categoria||'').trim().toLowerCase()===o.categoria.toLowerCase())
                           .reduce((s,t)=>s+t.valor,0);
    const desvio = realizado - orcado;
    const pct = orcado ? (100*realizado/orcado) : 0;
    return {o, orcado, realizado, desvio, pct};
  });
  tb.innerHTML = linhas.map(l=>
    '<tr><td>'+l.o.categoria+'</td><td>'+l.o.empresa+'</td><td class="num">'+F(l.orcado)+'</td><td class="num">'+F(l.realizado)
    +'</td><td class="num" style="color:'+(l.desvio>=0?'var(--gold)':'#c96b5a')+';">'+(l.desvio<0?'− ':'')+F(Math.abs(l.desvio))
    +'</td><td class="num">'+l.pct.toFixed(0)+'%</td>'
    +'<td><button class="ghost" onclick="dmExcluirOrcado(\''+l.o.id+'\')">Excluir</button></td></tr>').join('');
  window.__ultimoOrcado = {p, linhas};
}
function exportarCsvOrcado(){
  if(!window.__ultimoOrcado) renderDemonstracoes();
  const {p, linhas} = window.__ultimoOrcado;
  const F = formatarMoedaOuOculto;
  baixarCSV('orcado_x_realizado_'+p.diaDe+'_a_'+p.diaAte+'.csv',
    [['Categoria','Empresa','Orçado','Realizado','Desvio','% realizado']]
    .concat(linhas.map(l=>[l.o.categoria, l.o.empresa, F(l.orcado), F(l.realizado), F(l.desvio), l.pct.toFixed(0)+'%'])));
}

/* ---------- GF15 — demonstrações em PDF (mesmo mecanismo da ficha dos leilões) */
function dmGerarPdf(){
  renderDemonstracoes();
  const p = dmPeriodo();
  const empresa = document.getElementById('dm-empresa').value || 'Todas as empresas';
  let folha = document.getElementById('dmpdf-folha');
  if(!folha){
    folha = document.createElement('div');
    folha.id = 'dmpdf-folha';
    document.body.appendChild(folha);
  }
  const tabela = (titulo, seletor, comCabecalho) => {
    const t = document.querySelector(seletor);
    if(!t) return '';
    return '<h3>'+titulo+'</h3><table>'+(comCabecalho && t.tHead ? t.tHead.outerHTML : '')+(t.tBodies[0]?t.tBodies[0].outerHTML:'')+'</table>';
  };
  folha.innerHTML =
    '<div class="dmpdf-cab"><strong>SOLIDUNS</strong><span>Demonstrações financeiras — '+p.rotulo+' — '+empresa+'</span></div>'
    + tabela('DRE — Demonstração do Resultado do Exercício', '#dm-dre-table', false)
    + tabela('Balanço Patrimonial — posição em '+formatarDataBR(p.diaAte), '#dm-bp-table', false)
    + tabela('DFC — Demonstração do Fluxo de Caixa (método direto)', '#dm-dfc-table', false)
    + tabela('Caixa por conta financeira', '#dm-dfc-contas-table', true)
    + tabela('DMPL — Mutações do Patrimônio Líquido', '#dm-dmpl-table', true)
    + tabela('DVA — Demonstração do Valor Adicionado', '#dm-dva-table', false)
    + '<div class="dmpdf-rodape">Gerado pela plataforma SOLIDUNS em '+new Date().toLocaleString('pt-BR')
    + '. Regimes: DRE, DMPL, DVA e Orçado×Realizado por competência; DFC e Caixa por conta pelo regime de caixa (baixas). Documento gerencial — não substitui a escrituração contábil oficial.</div>';
  document.body.classList.add('dmpdf-imprimindo');
  const sair = () => { document.body.classList.remove('dmpdf-imprimindo'); window.removeEventListener('afterprint', sair); };
  window.addEventListener('afterprint', sair);
  setTimeout(() => { try{ window.print(); }catch(e){} setTimeout(sair, 1500); }, 60);
}

/* v103-GF (GF2): sugestões de categoria nos lançamentos = Categorias do Fluxo */
function popularDatalistCategorias(){
  const dl = document.getElementById('lista-categorias-fluxo');
  if(!dl) return;
  const nomes = (state.categoriasFluxo||[]).filter(c=>c.tipo!=='totalizador').map(c=>c.nome);
  dl.innerHTML = [...new Set(nomes)].sort().map(n=>'<option value="'+n.replace(/"/g,'&quot;')+'"></option>').join('');
}

function renderRelatoriosFinanceiros(){
  document.getElementById('dre-empresa').innerHTML = '<option value="">Todas</option>' + (ehContador() ? state.empresas.filter(e=>e.nome!=='Pessoal') : state.empresas).map(e=>`<option>${e.nome}</option>`).join('');
  if(!document.getElementById('dre-de').value){
    const hoje = new Date();
    document.getElementById('dre-de').value = hoje.toISOString().slice(0,7);
    document.getElementById('dre-ate').value = hoje.toISOString().slice(0,7);
  }
  renderDRE();

  const tbodyPagar = document.querySelector('#rel-pagar-table tbody');
  const pagar = relatorioPagarAberto();
  tbodyPagar.innerHTML = pagar.length ? pagar.map(t=>`<tr><td>${t.descricao}</td><td>${t.empresa}</td><td class="num">${formatarMoedaOuOculto(t.valor)}</td><td>${formatarDataBR(t.vencimento)}</td></tr>`).join('')
    : '<tr><td colspan="4" style="color:var(--ink-soft);">Nenhuma conta a pagar em aberto.</td></tr>';

  const tbodyReceber = document.querySelector('#rel-receber-table tbody');
  const receber = relatorioReceberAberto();
  tbodyReceber.innerHTML = receber.length ? receber.map(t=>`<tr><td>${t.descricao}</td><td>${t.empresa}</td><td class="num">${formatarMoedaOuOculto(t.valor)}</td><td>${formatarDataBR(t.vencimento)}</td></tr>`).join('')
    : '<tr><td colspan="4" style="color:var(--ink-soft);">Nenhuma conta a receber em aberto.</td></tr>';

  const tbodyInad = document.querySelector('#rel-inadimplencia-table tbody');
  const inad = relatorioInadimplencia();
  const hoje = new Date();
  tbodyInad.innerHTML = inad.length ? inad.map(t=>{
    const dias = Math.max(0, Math.round((hoje - parseDate(t.vencimento)) / 86400000));
    return `<tr><td>${t.favorecidoNome || t.descricao}</td><td class="num">${formatarMoedaOuOculto(t.valor)}</td><td>${dias} dias</td></tr>`;
  }).join('') : '<tr><td colspan="3" style="color:var(--ink-soft);">Nenhuma conta vencida.</td></tr>';

  const tbodySaldo = document.querySelector('#rel-saldo-table tbody');
  const contas = (state.contasFinanceiras || []).filter(c=>c.ativo);
  const amanhaRel = new Date(); amanhaRel.setDate(amanhaRel.getDate()+1);
  const dataLimiteRel = amanhaRel.toISOString().slice(0,10);
  tbodySaldo.innerHTML = contas.length ? contas.map(c=>{
    const saldoReal = saldoAcumuladoAte([c.id], dataLimiteRel, c.empresa);
    return `<tr><td>${c.nome}</td><td>${c.empresa||''}</td><td class="num">${formatarMoedaOuOculto(saldoReal)}</td></tr>`;
  }).join('')
    : '<tr><td colspan="3" style="color:var(--ink-soft);">Nenhuma conta financeira cadastrada.</td></tr>';

  const tbodyAud = document.querySelector('#rel-auditoria-table tbody');
  const vazioAud = document.getElementById('rel-auditoria-vazio');
  vazioAud.style.display = state.auditoriaFinanceira.length ? 'none' : 'block';
  tbodyAud.innerHTML = state.auditoriaFinanceira.slice(0,30).map(a=>
    `<tr><td>${new Date(a.data).toLocaleString('pt-BR')}</td><td>${a.usuario}</td><td>${a.acao}</td><td>${a.detalhe}</td></tr>`
  ).join('');
}

function exportarRelatorioCSV(tipo){
  if(tipo==='pagar'){
    baixarCSV('contas-a-pagar.csv', [['Descrição','Empresa','Valor','Vencimento']].concat(relatorioPagarAberto().map(t=>[t.descricao,t.empresa,t.valor,t.vencimento])));
  } else if(tipo==='receber'){
    baixarCSV('contas-a-receber.csv', [['Descrição','Empresa','Valor','Vencimento']].concat(relatorioReceberAberto().map(t=>[t.descricao,t.empresa,t.valor,t.vencimento])));
  } else if(tipo==='inadimplencia'){
    baixarCSV('inadimplencia.csv', [['Cliente','Valor','Vencimento']].concat(relatorioInadimplencia().map(t=>[t.favorecidoNome||t.descricao,t.valor,t.vencimento])));
  } else if(tipo==='saldo'){
    baixarCSV('saldo-por-conta.csv', [['Conta','Empresa','Saldo']].concat((state.contasFinanceiras||[]).map(c=>[c.nome,c.empresa||'',c.saldoInicial||0])));
  } else if(tipo==='dre'){
    const dre = window.__ultimoDRE || calcularDRE({});
    const empresa = document.getElementById('dre-empresa').value || 'todas';
    const de = document.getElementById('dre-de').value || '';
    const ate = document.getElementById('dre-ate').value || '';
    baixarCSV('dre-gerencial.csv', [
      ['DRE gerencial — base: competência (fato gerador)'],
      ['Empresa', empresa], ['Competência de', de], ['Competência até', ate], ['Gerado em', new Date().toLocaleString('pt-BR')],
      [],
      ['Categoria','Receita','Despesa'],
      ...dre.linhas.map(l=>[l.categoria, l.receita, l.despesa]),
      [],
      ['Total receita', dre.totalReceita], ['Total despesa', dre.totalDespesa], ['Resultado', dre.resultado],
      ...(typeof dre113LinhasCSV === 'function' ? dre113LinhasCSV(dre) : [])   /* v113 */
    ]);
  }
  auditar('Exportou relatório', tipo);
}

/* ---------- 13.0 INTEGRAÇÕES — tokens locais, exportação, referência de API ----------
   Nada aqui fala com um servidor de verdade: é um único arquivo HTML.
   "Tokens" são identificadores gerados neste navegador para simular o
   fluxo (nome, escopo, revogar); a exportação gera um arquivo real com
   os dados locais autorizados; a API é documentação de referência para
   quando existir um backend — nenhum endpoint responde de verdade hoje. */
function gerarTokenFalso(){
  const alfabeto = 'abcdefghijklmnopqrstuvwxyz0123456789';
  let s = 'sk_local_';
  for(let i=0;i<28;i++) s += alfabeto[Math.floor(Math.random()*alfabeto.length)];
  return s;
}

function renderTokensAPI(){
  const tbody = document.getElementById('tokens-tbody');
  const vazio = document.getElementById('tokens-vazio');
  vazio.style.display = state.tokensAPI.length ? 'none' : 'block';
  const NOMES_ESCOPO = {leitura:'Somente leitura', 'leitura-escrita':'Leitura e escrita'};
  tbody.innerHTML = state.tokensAPI.map(t=>`
    <tr>
      <td>${t.nome}</td>
      <td>${NOMES_ESCOPO[t.escopo]}</td>
      <td style="font-family:'IBM Plex Mono',monospace; font-size:11.5px;">${t.token.slice(0,14)}••••••••</td>
      <td>${formatarDataBR(t.criadoEm.slice(0,10))}</td>
      <td><span class="tag ${t.status==='ativo'?'ok':'vencido'}">${t.status==='ativo'?'Ativo':'Revogado'}</span></td>
      <td class="acoes">${t.status==='ativo' ? `<button type="button" onclick="revogarTokenAPI('${t.id}')">Revogar</button>` : ''}</td>
    </tr>
  `).join('');
}
document.getElementById('btn-novo-token').addEventListener('click', ()=>{
  const nome = prompt('Nome do token (ex.: "Exportação contador"):');
  if(!nome) return;
  const escopo = confirm('Este token pode LER e ESCREVER dados? Cancelar = somente leitura.') ? 'leitura-escrita' : 'leitura';
  state.tokensAPI.push({id: uid(), nome: nome.trim(), escopo, token: gerarTokenFalso(), criadoEm: new Date().toISOString(), status:'ativo'});
  auditar('Criou token de acesso', nome.trim());
  salvarEstado();
  renderTokensAPI();
});
function revogarTokenAPI(id){
  const t = state.tokensAPI.find(x=>x.id===id);
  if(!t) return;
  if(!confirm('Revogar este token? Ele para de funcionar imediatamente.')) return;
  t.status = 'revogado';
  auditar('Revogou token de acesso', t.nome);
  salvarEstado();
  renderTokensAPI();
}

function popularSelectEmpresaExportacao(){
  const sel = document.getElementById('exp-empresa');
  sel.innerHTML = '<option value="">Todas as empresas cadastradas</option>' + state.empresas.map(e=>`<option>${e.nome}</option>`).join('');
}

document.getElementById('btn-gerar-exportacao').addEventListener('click', function(){
  const msg = document.getElementById('exportacao-msg');
  const empresa = document.getElementById('exp-empresa').value;
  const dataInicio = document.getElementById('exp-data-inicio').value;
  const dataFim = document.getElementById('exp-data-fim').value;

  const dentroPeriodo = (dataStr)=>{
    if(dataInicio && dataStr < dataInicio) return false;
    if(dataFim && dataStr > dataFim) return false;
    return true;
  };
  const daEmpresa = (item)=> !empresa || item.empresa === empresa;

  const pacote = {geradoEm: new Date().toISOString(), empresa: empresa || 'todas', periodo: {de: dataInicio||null, ate: dataFim||null}};

  if(document.getElementById('exp-inc-lancamentos').checked){
    pacote.lancamentos = state.transacoes.filter(t=> daEmpresa(t) && dentroPeriodo(t.vencimento));
  }
  if(document.getElementById('exp-inc-extrato').checked){
    pacote.extratoBancario = state.extratoBancario.filter(l=> dentroPeriodo(l.data));
  }
  if(document.getElementById('exp-inc-contratos').checked){
    pacote.contratosRecorrentes = state.contratosRecorrentes.filter(daEmpresa);
  }
  if(document.getElementById('exp-inc-cobrancas').checked){
    pacote.cobrancas = state.cobrancas;
  }

  const blob = new Blob([JSON.stringify(pacote, null, 2)], {type:'application/json;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'exportacao-gestao-financeira-' + new Date().toISOString().slice(0,10) + '.json';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);

  auditar('Gerou exportação de dados', (empresa||'todas as empresas') + (dataInicio||dataFim ? ` (${dataInicio||'...'} a ${dataFim||'...'})` : ''));
  salvarEstado();
  msg.textContent = 'Exportação gerada e baixada.';
  msg.className = 'auth-msg ok';
});

