function renderDashboard(){
  const transacoes = transacoesFiltradasDash();
  const totalReceber = transacoes.filter(t=>t.tipo==='receber' && t.status==='pendente').reduce((s,t)=>s+t.valor,0);
  const totalPagar = transacoes.filter(t=>t.tipo==='pagar' && t.status==='pendente').reduce((s,t)=>s+t.valor,0);

  /* "Caixa" precisa ser dinheiro de verdade — reaproveita o MESMO motor
     de 8.0 Fluxo de Caixa (saldoAcumuladoAte: saldo inicial + baixas até
     hoje), não uma conta a receber menos a pagar (isso é PREVISÃO, é
     outra pergunta). Contas da(s) empresa(s) do filtro de pill ativo. */
  const contasParaSaldo = (filtroEmpresaDash ? state.contasFinanceiras.filter(c=>c.empresa===filtroEmpresaDash) : state.contasFinanceiras)
    .filter(c=>c.ativo).map(c=>c.id);
  const amanha = new Date(); amanha.setDate(amanha.getDate()+1);
  const saldo = saldoAcumuladoAte(contasParaSaldo, amanha.toISOString().slice(0,10), filtroEmpresaDash || null);

  const competenciaMesSelecionado = competenciaSelecionadaAtual();
  const [anoComp, mesComp] = competenciaMesSelecionado.split('-').map(Number);
  const mesAtual = mesComp - 1, anoAtual = anoComp;
  const transacoesMes = transacoes.filter(t=>{
    const d = parseDate(t.vencimento);
    return d.getMonth()===mesAtual && d.getFullYear()===anoAtual;
  });
  /* "Resultado do mês" agora usa o MESMO motor de DRE de Relatórios
     (calcularDRE, base competência) — não mais vencimento solto, que
     misturava previsão com resultado gerencial. */
  const dreDoMes = calcularDRE({empresa: filtroEmpresaDash || '', de: competenciaMesSelecionado, ate: competenciaMesSelecionado});
  const resultadoMes = dreDoMes.resultado;

  document.getElementById('dash-receber').textContent = formatarMoedaOuOculto(totalReceber);
  document.getElementById('dash-pagar').textContent = formatarMoedaOuOculto(totalPagar);
  document.getElementById('dash-saldo').textContent = formatarMoedaOuOculto(saldo);
  document.getElementById('dash-resultado-mes').textContent = formatarMoedaOuOculto(resultadoMes);
  document.getElementById('dash-resultado-mes').style.color = resultadoMes >= 0 ? 'var(--gold)' : '#c96b5a';
  document.getElementById('dash-receber-vazio').style.display = transacoes.length ? 'none' : 'block';
  document.getElementById('dash-pagar-vazio').style.display = transacoes.length ? 'none' : 'block';
  document.getElementById('dash-saldo-vazio').style.display = contasParaSaldo.length ? 'none' : 'block';
  document.getElementById('dash-resultado-vazio').style.display = (dreDoMes.totalReceita || dreDoMes.totalDespesa) ? 'none' : 'block';
  const tsDash = document.getElementById('dash-timestamp');
  if(tsDash) tsDash.textContent = 'Atualizado agora — ' + new Date().toLocaleString('pt-BR') + '. Caixa = saldo real (baixas); Resultado do mês = competência (DRE), não vencimento.';

  const obrigacoesFiltradas = filtroEmpresaDash
    ? state.obrigacoes.filter(o=>o.empresa===filtroEmpresaDash || o.empresa==='Todas as empresas')
    : state.obrigacoes;
  const tbodyPrazos = document.getElementById('dash-prazos-table').querySelector('tbody');
  tbodyPrazos.innerHTML = '';
  const ordenados = obrigacoesFiltradas.slice().sort((a,b)=>a.prazo.localeCompare(b.prazo)).slice(0,6);
  if(ordenados.length===0){
    tbodyPrazos.innerHTML = '<tr><td colspan="3" style="color:var(--ink-soft);">Nenhuma obrigação cadastrada.</td></tr>';
  }
  ordenados.forEach(o=>{
    const dias = diasAte(o.prazo);
    let tag = 'ok', label = `${dias} dias`;
    if(dias < 0){ tag='vencido'; label='Vencido'; }
    else if(dias <= 7){ tag='prox'; label = dias===0 ? 'Hoje' : `${dias} dias`; }
    tbodyPrazos.innerHTML += `<tr><td>${o.titulo}</td><td>${parseDate(o.prazo).toLocaleDateString('pt-BR')}</td><td><span class="tag ${tag}">${label}</span></td></tr>`;
  });

  const tbodyLanc = document.getElementById('dash-lanc-table').querySelector('tbody');
  tbodyLanc.innerHTML = '';
  const ultimos = transacoes.slice(-6).reverse();
  if(ultimos.length===0){
    tbodyLanc.innerHTML = '<tr><td colspan="3" style="color:var(--ink-soft);">Nenhum lançamento ainda.</td></tr>';
  }
  ultimos.forEach(t=>{
    tbodyLanc.innerHTML += `<tr><td>${t.descricao}</td><td>${t.empresa}</td><td class="num">${t.tipo==='pagar'?'−':''}${formatBRL(t.valor)}</td></tr>`;
  });

  renderGraficosFluxoCaixa();
  if(typeof renderizarNotificacoes === 'function') renderizarNotificacoes();
}

/* ---------- GRÁFICOS DE FLUXO DE CAIXA (Chart.js) ---------- */
let chartBarras = null, chartLinha = null;
const CHART_CORES = {gold:'#eec617', goldSoft:'rgba(238,198,23,0.35)', teal:'#3ecb99', rust:'#e0563f', grid:'#2e2a1e', texto:'#a89f88'};

function opcoesChartBase(extra){
  return Object.assign({
    responsive:true, maintainAspectRatio:false,
    plugins:{
      legend:{labels:{color:CHART_CORES.texto, font:{family:"'IBM Plex Sans',sans-serif", size:11}}},
      tooltip:{callbacks:{label:(ctx)=> `${ctx.dataset.label||''}: ${formatBRL(ctx.parsed.y!==undefined?ctx.parsed.y:ctx.parsed)}`}}
    },
    scales:{
      x:{ticks:{color:CHART_CORES.texto, font:{size:10}}, grid:{color:CHART_CORES.grid}},
      y:{ticks:{color:CHART_CORES.texto, font:{size:10}, callback:(v)=>formatBRL(v)}, grid:{color:CHART_CORES.grid}}
    }
  }, extra||{});
}

function renderGraficosFluxoCaixa(){
  if(typeof Chart === 'undefined'){
    ['grafico-barras-mes','grafico-linha-6m'].forEach(id=>{
      const canvas = document.getElementById(id);
      const vazio = document.getElementById(id==='grafico-barras-mes' ? 'grafico-barras-vazio' : 'grafico-linha-vazio');
      if(canvas) canvas.closest('.dash-grafico-box').style.display = 'none';
      if(vazio){ vazio.style.display = 'flex'; vazio.textContent = 'Gráfico indisponível no momento.'; }
    });
    return;
  }
  const transacoes = transacoesFiltradasDash();
  const hoje = new Date();

  // 1) Barras do mes: entradas x saidas
  const mesAtual = hoje.getMonth(), anoAtual = hoje.getFullYear();
  const transacoesMes = transacoes.filter(t=>{
    const d = parseDate(t.vencimento);
    return d.getMonth()===mesAtual && d.getFullYear()===anoAtual;
  });
  const entradasMes = transacoesMes.filter(t=>t.tipo==='receber').reduce((s,t)=>s+t.valor,0);
  const saidasMes = transacoesMes.filter(t=>t.tipo==='pagar').reduce((s,t)=>s+t.valor,0);

  const canvasBarras = document.getElementById('grafico-barras-mes');
  const vazioBarras = document.getElementById('grafico-barras-vazio');
  if(transacoesMes.length === 0){
    canvasBarras.closest('.dash-grafico-box').style.display = 'none';
    vazioBarras.style.display = 'flex';
  } else {
    canvasBarras.closest('.dash-grafico-box').style.display = 'block';
    vazioBarras.style.display = 'none';
    // Otimização (prompt 31/08/2026): só cria o Chart.js na primeira vez.
    // Trocar pill/competência/ocultar valores só atualiza os dados do
    // MESMO gráfico via update('none') — sem destroy()+new Chart(), que
    // pesa mais que qualquer gravação no localStorage.
    if(chartBarras){
      chartBarras.data.datasets[0].data = [entradasMes];
      chartBarras.data.datasets[1].data = [saidasMes];
      chartBarras.update('none');
    } else {
      chartBarras = new Chart(canvasBarras.getContext('2d'), {
        type:'bar',
        data:{ labels:['Este mês'], datasets:[
          {label:'Entradas', data:[entradasMes], backgroundColor:CHART_CORES.teal},
          {label:'Saídas', data:[saidasMes], backgroundColor:CHART_CORES.rust}
        ]},
        options: opcoesChartBase()
      });
    }
  }

  // 2) Linha ultimos 6 meses: saldo acumulado
  const meses = [];
  for(let i=5;i>=0;i--){
    const d = new Date(hoje.getFullYear(), hoje.getMonth()-i, 1);
    meses.push({label: d.toLocaleDateString('pt-BR',{month:'short'}).replace('.',''), mes:d.getMonth(), ano:d.getFullYear()});
  }
  let saldoAcum = 0;
  const temAlgumLancamento = transacoes.length > 0;
  const dadosLinha = meses.map(m=>{
    const doMes = transacoes.filter(t=>{ const d=parseDate(t.vencimento); return d.getMonth()===m.mes && d.getFullYear()===m.ano; });
    const ent = doMes.filter(t=>t.tipo==='receber').reduce((s,t)=>s+t.valor,0);
    const sai = doMes.filter(t=>t.tipo==='pagar').reduce((s,t)=>s+t.valor,0);
    saldoAcum += (ent - sai);
    return saldoAcum;
  });

  const canvasLinha = document.getElementById('grafico-linha-6m');
  const vazioLinha = document.getElementById('grafico-linha-vazio');
  if(!temAlgumLancamento){
    canvasLinha.closest('.dash-grafico-box').style.display = 'none';
    vazioLinha.style.display = 'flex';
  } else {
    canvasLinha.closest('.dash-grafico-box').style.display = 'block';
    vazioLinha.style.display = 'none';
    if(chartLinha){
      chartLinha.data.labels = meses.map(m=>m.label);
      chartLinha.data.datasets[0].data = dadosLinha;
      chartLinha.update('none');
    } else {
      chartLinha = new Chart(canvasLinha.getContext('2d'), {
        type:'line',
        data:{ labels: meses.map(m=>m.label), datasets:[
          {label:'Saldo acumulado', data:dadosLinha, borderColor:CHART_CORES.gold, backgroundColor:CHART_CORES.goldSoft, tension:0.3, fill:true}
        ]},
        options: opcoesChartBase()
      });
    }
  }
}

