function aplicarMascaraMoeda(input){
  let valor = input.value.replace(/[^\d,]/g, '');
  // bloqueia qualquer virgula depois da primeira (só UM separador decimal)
  const primeiraVirgula = valor.indexOf(',');
  if(primeiraVirgula !== -1){
    valor = valor.slice(0, primeiraVirgula+1) + valor.slice(primeiraVirgula+1).replace(/,/g, '');
  }
  const partes = valor.split(',');
  let inteiro = partes[0].replace(/^0+(?=\d)/, '');
  inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const decimal = partes.length > 1 ? partes[1].slice(0,2) : null;
  if(!inteiro && decimal===null){ input.value = ''; return; }
  input.value = decimal !== null ? `R$ ${inteiro || '0'},${decimal}` : (inteiro ? `R$ ${inteiro}` : '');
}

function finalizarMascaraMoeda(input){
  if(!input.value){ return; }
  const valor = input.value.replace(/[^\d,]/g, '');
  const partes = valor.split(',');
  let inteiro = partes[0].replace(/^0+(?=\d)/, '') || '0';
  const decimal = (partes.length > 1 ? partes.slice(1).join('') : '').padEnd(2,'0').slice(0,2);
  inteiro = inteiro.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  input.value = `R$ ${inteiro},${decimal}`;
}

function parseMoeda(valor){
  if(!valor) return NaN;
  const limpo = valor.replace(/[R$\s.]/g, '').replace(',', '.');
  return parseFloat(limpo);
}

/* Quartos/área: só inteiro >= 0. Erro em texto curto, sem alert(). */
/* ---------- 60º: validação de formulários na UI (sem alert()) ----------
   Bloqueia o submit se o campo estiver inválido; erro curto aparece
   embaixo do campo com aria-live="polite" (37º). parseBRL roda antes
   de gravar qualquer number no JSON — nunca grava string com máscara. */
function mostrarErroCampo(input, mensagem){
  input.classList.add('campo-invalido');
  let erro = document.getElementById(input.id + '-erro-60');
  if(!erro){
    erro = document.createElement('span');
    erro.className = 'campo-erro';
    erro.id = input.id + '-erro-60';
    erro.setAttribute('aria-live', 'polite');
    input.insertAdjacentElement('afterend', erro);
  }
  erro.textContent = mensagem;
  erro.style.display = 'block';
}
function limparErroCampo(input){
  input.classList.remove('campo-invalido');
  const erro = document.getElementById(input.id + '-erro-60');
  if(erro) erro.style.display = 'none';
}
/* valida vários campos de uma vez; retorna true só se TODOS passarem.
   regras: array de {input, obrigatorio, minimo, mensagemVazio, mensagemInvalido, tipo:'texto'|'numero'|'email'|'select'} */
function validarCampos(regras){
  let tudoValido = true;
  regras.forEach(r=>{
    const valor = r.input.value.trim();
    if(r.obrigatorio && !valor){
      mostrarErroCampo(r.input, r.mensagemVazio || 'Campo obrigatório.');
      tudoValido = false;
      return;
    }
    if(r.tipo === 'email' && valor && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(valor)){
      mostrarErroCampo(r.input, r.mensagemInvalido || 'Informe um e-mail válido (com @).');
      tudoValido = false;
      return;
    }
    if(r.tipo === 'numero'){
      const n = r.moeda ? parseMoeda(valor) : parseFloat(valor.replace(',','.'));
      if(isNaN(n) || (r.minimo !== undefined && n < r.minimo)){
        mostrarErroCampo(r.input, r.mensagemInvalido || `Informe um número válido${r.minimo!==undefined ? ' (mínimo '+r.minimo+')' : ''}.`);
        tudoValido = false;
        return;
      }
    }
    limparErroCampo(r.input);
  });
  return tudoValido;
}

function validarQuartos(input){
  const erro = document.getElementById(input.id + '-erro');
  if(input.value.trim() === ''){
    input.classList.remove('campo-invalido');
    if(erro) erro.style.display = 'none';
    return true;
  }
  const bruto = input.value.trim();
  const n = parseInt(bruto, 10);
  const valido = /^\d+$/.test(bruto) && Number.isInteger(n) && n >= 0;
  if(!valido){
    input.classList.add('campo-invalido');
    if(erro){ erro.textContent = 'Informe um número inteiro maior ou igual a 0.'; erro.style.display = 'block'; }
    input.value = '';
    return false;
  }
  input.classList.remove('campo-invalido');
  if(erro) erro.style.display = 'none';
  return true;
}

/* Faixa de preço (filtros de Leilão e Mercado Imobiliário): o mínimo
   nunca pode ficar maior que o máximo. Se acontecer, corrige o mínimo
   para igualar o máximo e avisa — em vez de só devolver "sem resultado"
   sem explicação. */
function validarFaixaPreco(idMin, idMax, idErro){
  const inputMin = document.getElementById(idMin);
  const inputMax = document.getElementById(idMax);
  const erro = document.getElementById(idErro);
  const min = parseMoeda(inputMin.value);
  const max = parseMoeda(inputMax.value);
  if(!isNaN(min) && !isNaN(max) && min > max){
    inputMin.value = inputMax.value;
    inputMin.classList.add('campo-invalido');
    if(erro){ erro.textContent = 'O valor mínimo não pode ser maior que o máximo — ajustamos para igualar.'; erro.style.display = 'block'; }
    setTimeout(()=> inputMin.classList.remove('campo-invalido'), 1500);
    return false;
  }
  if(erro) erro.style.display = 'none';
  return true;
}

/* ==========================================================================
   MOTOR DE CÁLCULO TRIBUTÁRIO — módulo separado da UI (contrato pedido).
   IMPORTANTE: aqui "API" é um objeto JS (MotorFiscal.calculate(...)),
   não endpoints HTTP reais — este app não tem servidor. O CONTRATO
   (CalculationRequest -> CalculationResult com lines/memory/alerts/
   hash, rule_packs versionadas por vigência, idempotência) é o mesmo
   que um backend real usaria; a diferença é só ONDE roda (navegador
   em vez de servidor). Ver ARQUITETURA.md para a versão com backend
   de verdade (schema SQL + API REST entregues como arquivos à parte).
   As alíquotas do Simples/Presumido são as mesmas já usadas no site
   (LC 123/2006, Lei 9.249/1995); o pack de IBS/CBS é FIXTURE DE TESTE
   — a Reforma Tributária ainda não tem alíquota oficial confirmada.
   ========================================================================== */

