/* ---------- AUTENTICAÇÃO (Supabase Auth via REST) ---------- */
const SUPABASE_URL = 'https://evcsniicnrlrtzpdmeza.supabase.co';
const SUPABASE_KEY = 'sb_publishable_ueRLfhNKU3NH1716UGqtow_NdAB7KNR';
const AUTH_STORAGE_KEY = 'gestao-fiscal-auth-session';

async function supaFetch(path, body){
  try{
    const res = await fetch(SUPABASE_URL + path, {
      method: 'POST',
      headers: {
        'apikey': SUPABASE_KEY,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify(body)
    });
    const data = await res.json().catch(()=>({}));
    return {status: res.status, data};
  }catch(e){
    /* status 0 = a requisição nem saiu (DNS, offline, projeto Supabase pausado).
       Marcado com falhaDeRede para que a tela não confunda isso com senha errada. */
    return {status: 0, data: {falhaDeRede: true, detalhe: e && e.message ? e.message : 'desconhecido',
      error_description: 'Não foi possível falar com o servidor.'}};
  }
}

/* Traduz a resposta de erro do Supabase para uma mensagem útil, dizendo o que
   de fato aconteceu em vez do genérico "e-mail ou senha inválidos". */
function diagnosticarErroLogin(status, data){
  /* Concatena TODOS os campos de erro, e não apenas o primeiro preenchido:
     o Supabase ora devolve a causa em error_code, ora em msg, ora em
     error_description, e pegar só um deles faz o diagnóstico escapar. */
  const bruto = !data ? '' : [data.error_code, data.error, data.msg, data.message, data.error_description]
    .filter(Boolean).join(' | ').toLowerCase();

  if(status === 0 || (data && data.falhaDeRede)){
    return {texto: 'Sem conexão com o servidor. Isso não é senha errada: a requisição nem chegou a sair. Verifique sua internet ou se o projeto no Supabase está ativo.', tipo: 'erro'};
  }
  if(bruto.includes('email_not_confirmed') || bruto.includes('email not confirmed')){
    return {texto: 'Sua conta existe, mas o e-mail ainda não foi confirmado. Procure a mensagem da SOLIDUNS (nao-responda@soliduns.com.br) na caixa de entrada e no Spam e clique em "Confirmar meu e-mail". Se o link expirou, faça o cadastro de novo em "Criar conta", com o mesmo e-mail, para receber outro.', tipo: 'erro'};
  }
  if(bruto.includes('invalid_grant') || bruto.includes('invalid login credentials')){
    return {texto: 'E-mail ou senha incorretos — ou esta conta ainda não existe neste servidor. Se você se cadastrou antes de o projeto ser recriado, use "Criar conta" novamente.', tipo: 'erro'};
  }
  if(bruto.includes('over_email_send_rate_limit') || bruto.includes('rate limit')){
    return {texto: 'Muitas tentativas em pouco tempo. Aguarde alguns minutos e tente de novo.', tipo: 'erro'};
  }
  if(bruto.includes('user_banned')){
    return {texto: 'Esta conta está bloqueada no servidor. Verifique o painel do Supabase.', tipo: 'erro'};
  }
  if(status === 401 || status === 403){
    return {texto: 'A chave pública do aplicativo foi recusada pelo servidor (status ' + status + '). Confira SUPABASE_URL e SUPABASE_KEY no topo do arquivo.', tipo: 'erro'};
  }
  const detalhe = mensagemErroAuth(data);
  return {texto: 'Não foi possível entrar (status ' + status + '): ' + detalhe, tipo: 'erro'};
}

function mensagemErroAuth(data){
  return data.error_description || data.msg || data.message || data.error || 'Ocorreu um erro. Tente novamente.';
}

function trocarAbaAuth(aba){
  document.querySelectorAll('.auth-tab').forEach(t=>t.classList.remove('active'));
  document.querySelector(`[data-authtab="${aba}"]`).classList.add('active');
  document.getElementById('form-login').style.display = aba==='login' ? 'block' : 'none';
  document.getElementById('form-signup').style.display = aba==='signup' ? 'block' : 'none';
}

/* ---------- LOGIN/CADASTRO COM GOOGLE E APPLE (OAuth via Supabase Auth) ----------
   Um único botão serve para entrar OU criar conta: o Supabase cria o usuário
   automaticamente no primeiro login pelo provedor. Requer que os provedores
   Google e Apple estejam habilitados e configurados (client id/secret) no
   painel do Supabase (Authentication > Providers) — sem isso os botões
   redirecionam mas o provedor recusa a autorização. */
function loginComProvedor(provider){
  const msg = document.getElementById('login-msg');
  const origem = window.location.origin;

  /* OAuth exige uma origem http(s) real: o provedor precisa redirecionar de
     volta para um endereço que exista na internet. Arquivo aberto por duplo
     clique roda em file:// e origin vale a string "null" — o redirect_to sai
     inválido e o Google recusa, sem explicar nada ao usuário. Melhor dizer
     aqui do que deixar falhar calado. */
  if(!origem || origem === 'null' || window.location.protocol === 'file:'){
    if(msg){
      msg.textContent = 'Entrar com Google ou Apple só funciona com a plataforma publicada em um endereço https. ' +
        'Como este arquivo está aberto direto do computador (file://), o provedor não tem para onde devolver o login. ' +
        'Use o acesso por e-mail e senha.';
      msg.className = 'auth-msg erro';
    }
    return;
  }

  if(msg){ msg.textContent = 'Redirecionando para o provedor…'; msg.className = 'auth-msg'; }
  const redirectTo = origem + window.location.pathname;
  window.location.href = SUPABASE_URL + '/auth/v1/authorize?provider=' + provider + '&redirect_to=' + encodeURIComponent(redirectTo);
}

/* O Supabase devolve o resultado do OAuth como fragmento na URL
   (#access_token=...&refresh_token=...&expires_in=...) quando o provedor
   redireciona de volta para cá. Precisa ser tratado ANTES do roteamento
   normal, e a própria URL precisa ser limpa logo em seguida — os tokens não
   podem ficar visíveis na barra de endereço nem salvos no histórico. */
async function processarRetornoOAuth(){
  const hash = window.location.hash || '';
  const busca = window.location.search || '';
  /* v11: o Supabase devolve erros de OAuth na QUERY (?error=...) e às vezes
     também no hash. Antes só o hash era lido, a URL ficava suja com o erro
     e a mensagem aparecia crua, em inglês e com %3A/%2F. */
  const erroNaBusca = busca.indexOf('error=') !== -1;

  /* v22: link de recuperação no formato do modelo de e-mail SOLIDUNS
     (https://soliduns.com.br/?token_hash=...&type=recovery). O link aponta
     para o PRÓPRIO domínio, e não para supabase.co: e-mail com link de outro
     domínio parece golpe para o Gmail. O site troca o token_hash por uma
     sessão temporária (POST /auth/v1/verify) e abre "Definir nova senha". */
  const pBusca = new URLSearchParams(busca);
  const tokenHash = pBusca.get('token_hash');
  if(tokenHash && (pBusca.get('type') || '') === 'recovery'){
    history.replaceState(null, '', window.location.pathname);
    mostrarTela('auth');
    trocarAbaAuth('login');
    const m = document.getElementById('login-msg');
    m.textContent = 'Validando o link de recuperação...'; m.className = 'auth-msg';
    let st = 0, dados = {};
    try{
      const r = await fetch(SUPABASE_URL + '/auth/v1/verify', {
        method: 'POST',
        headers: {'apikey': SUPABASE_KEY, 'Content-Type': 'application/json'},
        body: JSON.stringify({type: 'recovery', token_hash: tokenHash})
      });
      st = r.status;
      dados = await r.json().catch(()=>({}));
    }catch(e){ st = 0; }
    if(st === 200 && dados && dados.access_token){
      m.textContent = ''; m.className = 'auth-msg';
      await abrirNovaSenha(dados.access_token);
      return true;
    }
    m.textContent = st === 0
      ? 'Sem conexão com o servidor. Verifique sua internet e abra o link do e-mail de novo.'
      : 'Este link de e-mail expirou ou já foi usado. Para trocar a senha, digite seu e-mail acima e clique em "Esqueci minha senha" para receber um link novo (vale por pouco tempo e só uma vez).';
    m.className = 'auth-msg erro';
    return true;
  }

  /* v23: link de CONFIRMAÇÃO DE CADASTRO no formato do modelo de e-mail
     SOLIDUNS (https://soliduns.com.br/?token_hash=...&type=email). Mesmo
     motivo da v22: link para o próprio domínio, e não para supabase.co, que
     o Gmail tratava como suspeito e fazia o e-mail sumir. O site confirma o
     e-mail (POST /auth/v1/verify), consulta a fila de aprovação, encerra a
     sessão do link e mostra a situação no login. Ninguém entra por este
     link: o acesso continua dependendo da aprovação e da senha. */
  const tipoLink = (pBusca.get('type') || '').toLowerCase();
  if(tokenHash && (tipoLink === 'email' || tipoLink === 'signup')){
    history.replaceState(null, '', window.location.pathname);
    mostrarTela('auth');
    trocarAbaAuth('login');
    const m = document.getElementById('login-msg');
    m.textContent = 'Confirmando o seu e-mail...'; m.className = 'auth-msg';
    let st = 0, dados = {};
    try{
      const r = await fetch(SUPABASE_URL + '/auth/v1/verify', {
        method: 'POST',
        headers: {'apikey': SUPABASE_KEY, 'Content-Type': 'application/json'},
        body: JSON.stringify({type: tipoLink, token_hash: tokenHash})
      });
      st = r.status;
      dados = await r.json().catch(()=>({}));
    }catch(e){ st = 0; }
    if(st === 200 && dados && dados.access_token){
      const tokenLink = dados.access_token;
      const usuario = dados.user || {};
      const liberacao = await consultarLiberacao(tokenLink, usuario.id);
      try{
        await fetch(SUPABASE_URL + '/auth/v1/logout', {
          method: 'POST', headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + tokenLink}
        });
      }catch(e){ /* o token do link expira sozinho em pouco tempo */ }
      const campoEmail = document.getElementById('login-email');
      if(campoEmail && usuario.email) campoEmail.value = usuario.email;
      if(!liberacao.erro && liberacao.status === 'aprovado'){
        m.textContent = 'E-mail confirmado com sucesso. Entre agora com seu e-mail e senha.';
        m.className = 'auth-msg ok';
        const campoSenha = document.getElementById('password');
        if(campoSenha) campoSenha.focus();
      } else if(!liberacao.erro && liberacao.status === 'recusado'){
        m.textContent = 'E-mail confirmado. Este cadastro, porém, não foi autorizado. Fale com a administração da SOLIDUNS.';
        m.className = 'auth-msg erro';
      } else {
        m.textContent = 'E-mail confirmado com sucesso. Seu cadastro está aguardando liberação de um administrador. Você será avisado assim que for aprovado.';
        m.className = 'auth-msg ok';
      }
      return true;
    }
    m.textContent = st === 0
      ? 'Sem conexão com o servidor. Verifique sua internet e abra o link do e-mail de novo.'
      : 'Este link de confirmação expirou ou já foi usado. Se você já confirmou o e-mail antes, é só entrar com seu e-mail e senha. Se não, faça o cadastro de novo em "Criar conta", com o mesmo e-mail, para receber um link novo.';
    m.className = 'auth-msg erro';
    return true;
  }

  if(hash.indexOf('access_token=') === -1 && hash.indexOf('error=') === -1 && !erroNaBusca) return false;

  const params = new URLSearchParams(hash.replace(/^#\/?/, ''));
  const paramsBusca = new URLSearchParams(busca);
  const accessToken = params.get('access_token');
  const codigoErro = params.get('error') || paramsBusca.get('error') || '';
  const detalheErro = params.get('error_description') || paramsBusca.get('error_description') || '';
  history.replaceState(null, '', window.location.pathname);

  /* v22: link de RECUPERAÇÃO DE SENHA. O Supabase devolve os tokens no hash
     com type=recovery. Antes o site tratava como login e a pessoa entrava sem
     nunca poder trocar a senha. Agora abre a tela "Definir nova senha". */
  const tipoRetorno = params.get('type') || paramsBusca.get('type') || '';
  if(accessToken && tipoRetorno === 'recovery'){
    await abrirNovaSenha(accessToken);
    return true;
  }

  /* v22: link de e-mail vencido ou já usado (recuperação ou confirmação).
     Antes aparecia "login com Google cancelado", o que confundia. */
  const codigoDetalhado = (params.get('error_code') || paramsBusca.get('error_code') || '').toLowerCase();
  const textoErro = (codigoErro + ' ' + codigoDetalhado + ' ' + detalheErro).toLowerCase();
  if(!accessToken && (codigoDetalhado === 'otp_expired' || textoErro.includes('email link') ||
                      (textoErro.includes('expired') && !textoErro.includes('provider')))){
    mostrarTela('auth');
    trocarAbaAuth('login');
    const m = document.getElementById('login-msg');
    m.textContent = 'Este link de e-mail expirou ou já foi usado. Se era para trocar a senha, digite seu e-mail acima e clique em "Esqueci minha senha" para receber um link novo. Se era para confirmar o cadastro e você já clicou nele antes, é só entrar com seu e-mail e senha.';
    m.className = 'auth-msg erro';
    return true;
  }

  if(!accessToken){
    if(codigoErro || detalheErro) console.warn('[oauth] retorno com erro:', codigoErro, detalheErro);
    mostrarTela('auth');
    const msg = document.getElementById('login-msg');
    msg.textContent = (codigoErro === 'access_denied')
      ? 'Login com Google cancelado. Tente novamente ou entre com e-mail e senha.'
      : 'Não foi possível concluir o login com Google. Tente novamente em instantes. Se o problema continuar, entre com e-mail e senha ou escreva para contato@soliduns.com.br.';
    msg.className = 'auth-msg erro';
    return true;
  }

  let userData = null;
  try{
    const res = await fetch(SUPABASE_URL + '/auth/v1/user', {
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + accessToken}
    });
    userData = await res.json().catch(()=>null);
  }catch(e){ /* segue sem os dados completos do usuário; a sessão ainda funciona */ }

  const email = (userData && userData.email) || '';
  const nome = (userData && userData.user_metadata && (userData.user_metadata.nome || userData.user_metadata.full_name || userData.user_metadata.name)) || '';

  /* PORTEIRO DE APROVAÇÃO TAMBÉM NO GOOGLE (v10). Antes, o retorno do OAuth
     abria a plataforma direto, sem consultar public.acessos — qualquer conta
     Google entraria sem aprovação. Agora segue a mesma regra do e-mail/senha:
     pendente ou recusado não entra, e o perfil vem do servidor. */
  const avisarOAuth = (texto, erro) => {
    mostrarTela('auth');
    const m = document.getElementById('login-msg');
    if(m){ m.textContent = texto; m.className = erro ? 'auth-msg erro' : 'auth-msg'; }
  };
  if(!userData || !userData.id){
    avisarOAuth('Não foi possível confirmar sua conta Google agora. Tente novamente em instantes.', true);
    return true;
  }
  const liberacao = await consultarLiberacao(accessToken, userData.id);
  if(liberacao.erro){
    avisarOAuth('Não foi possível confirmar sua autorização de acesso agora. Tente novamente em instantes.', true);
    console.warn('[acesso] falha ao consultar liberação (OAuth):', liberacao.detalhe);
    return true;
  }
  if(liberacao.status === 'pendente'){
    avisarOAuth('Seu cadastro foi recebido e está aguardando liberação de um administrador. Você será avisado assim que for aprovado.', false);
    return true;
  }
  if(liberacao.status === 'recusado'){
    avisarOAuth('Este cadastro não foi autorizado. Fale com a administração da SOLIDUNS.', true);
    return true;
  }

  const sessao = {
    access_token: accessToken,
    refresh_token: params.get('refresh_token'),
    user: userData,
    expires_at: Date.now() + (parseInt(params.get('expires_in'), 10) || 3600) * 1000,
    email: email,
    nome: nome,
    perfil: liberacao.perfil || 'usuario'
  };
  await salvarSessaoAuth(sessao);
  await entrarNoApp(sessao);
  return true;
}

function onSubmitLogin(event){
  event.preventDefault();
  fazerLogin();
  return false;
}

function onSubmitCadastro(event){
  event.preventDefault();
  fazerCadastro();
  return false;
}

function alternarSenha(inputId, btn){
  const input = document.getElementById(inputId);
  const mostrando = input.type === 'text';
  input.type = mostrando ? 'password' : 'text';
  btn.classList.toggle('showing', !mostrando);
}

async function fazerCadastro(){
  const nome = document.getElementById('signup-nome').value.trim();
  const cpfDig = document.getElementById('signup-cpf').value.replace(/\D/g, '');
  const email = document.getElementById('signup-email').value.trim();
  const senha = document.getElementById('signup-senha').value;
  const senhaConfirma = document.getElementById('signup-senha-confirma').value;
  const msg = document.getElementById('signup-msg');

  if(!nome || !cpfDig || !email || !senha || !senhaConfirma){
    msg.textContent = 'Preencha todos os campos.'; msg.className = 'auth-msg erro'; return;
  }
  /* v26: CPF no cadastro. O banco (SQL 22) confere de novo, grava na tabela
     protegida usuarios_cpf e apaga o CPF dos metadados da conta. */
  if(!contaCPFValido(cpfDig)){
    msg.textContent = cpfDig.length < 11 ? 'Digite os 11 números do CPF.' : 'CPF inválido. Confira os números digitados.';
    msg.className = 'auth-msg erro';
    document.getElementById('signup-cpf').focus();
    return;
  }
  if(senha.length < 6){
    msg.textContent = 'A senha precisa ter ao menos 6 caracteres.'; msg.className = 'auth-msg erro'; return;
  }
  if(senha !== senhaConfirma){
    msg.textContent = 'As senhas não coincidem.'; msg.className = 'auth-msg erro'; return;
  }
  msg.textContent = 'Enviando...'; msg.className = 'auth-msg';

  const {status, data} = await supaFetch('/auth/v1/signup', {
    email, password: senha, data: {nome, cpf: cpfDig}
  });

  if(status===200 || status===201){
    await salvarCredencialNavegador(email, senha, nome);
    msg.textContent = `Enviamos um e-mail de confirmação para ${email}, do remetente nao-responda@soliduns.com.br. Abra a mensagem e clique em "Confirmar meu e-mail". Se não aparecer em alguns minutos, confira o Spam.`;
    msg.className = 'auth-msg ok';
  } else {
    msg.textContent = mensagemErroAuth(data);
    msg.className = 'auth-msg erro';
  }
}

async function salvarCredencialNavegador(email, senha, nome){
  try{
    if('credentials' in navigator && window.PasswordCredential){
      const cred = new PasswordCredential({
        id: email,
        password: senha,
        name: nome || email
      });
      await navigator.credentials.store(cred);
    }
  }catch(e){
    // Credential Management API indisponível ou recusada — segue normalmente,
    // o gerenciador de senhas do navegador ainda pode oferecer salvar via heurística própria.
  }
}

/* ==========================================================================
   README (10 linhas) — sessão local × sessão no servidor
   HOJE: o login autentica direto no Supabase Auth a partir do navegador;
   o navegador guarda access_token/perfil em localStorage. Qualquer
   pessoa com DevTools pode editar esse localStorage e escrever
   perfil:"admin" — exigirAdmin() só ESCONDE a tela, não PROTEGE dado
   nenhum de verdade (não há servidor nosso conferindo).
   AMANHÃ (com backend, 36º): o front chama POST /api/sessao; o
   SERVIDOR confere e devolve um cookie httpOnly ou um JWT assinado
   por ele — nunca o contrário. O front nunca fabrica token; só guarda
   o que o servidor mandou e reenvia (Authorization: Bearer). Sem esse
   servidor, "JWT no localStorage" seria um crachá falso: pareceria
   profissional e não protegeria nada que hoje já não esteja assim.
   ========================================================================== */

/* Produção: POST /api/sessao devolve cookie httpOnly ou JWT assinado
   pelo SERVIDOR. O front NÃO gera token — só chama e guarda o que o
   servidor mandar. PROIBIDO neste passo: jwt.sign no navegador, token
   inventado tipo "eyJhbGciOi..." hardcoded, ou achar que um Bearer
   guardado no localStorage protege a Equipe de verdade. */
const API_URL = null; // vira a URL do NOSSO backend quando ele existir (36º) — hoje é sempre null

async function enviarCredencial(email, senha){
  if(API_URL){
    // AMANHÃ: const resp = await fetch(API_URL + '/api/sessao', {method:'POST', body: JSON.stringify({email, senha})});
    // O servidor devolve cookie httpOnly ou JWT assinado — o front só guarda o que veio, nunca gera.
    throw new Error('API_URL configurada mas /api/sessao ainda não existe.');
  }
  // HOJE: fluxo atual, direto no Supabase Auth (sem backend próprio ainda).
  return await supaFetch('/auth/v1/token?grant_type=password', {email, password: senha});
}

async function fazerLogin(){
  const emailInput = document.getElementById('login-email');
  const senhaInput = document.getElementById('password');
  const email = emailInput.value.trim();
  const senha = senhaInput.value;
  const msg = document.getElementById('login-msg');

  const valido = validarCampos([
    {input: emailInput, obrigatorio:true, tipo:'email', mensagemVazio:'Informe seu e-mail.', mensagemInvalido:'Informe um e-mail válido (com @).'},
    {input: senhaInput, obrigatorio:true, mensagemVazio:'Informe sua senha.'}
  ]);
  if(!valido) return;
  msg.textContent = 'Entrando...'; msg.className = 'auth-msg';

  const {status, data} = await enviarCredencial(email, senha);

  if(status===200 && data.access_token){
    const nome = (data.user && data.user.user_metadata && (data.user.user_metadata.nome || data.user.user_metadata.full_name || data.user.user_metadata.name)) || '';

    /* PORTEIRO DE APROVAÇÃO — autenticar não é o mesmo que ter acesso.
       O Supabase confirma que a senha está certa; a tabela public.acessos
       diz se um administrador liberou esta pessoa. Enquanto o status for
       'pendente' ou 'recusado', a sessão não é gravada e nada é aberto. */
    const liberacao = await consultarLiberacao(data.access_token, data.user && data.user.id);

    if(liberacao.erro){
      msg.textContent = 'Não foi possível confirmar sua autorização de acesso agora. Tente novamente em instantes.';
      msg.className = 'auth-msg erro';
      console.warn('[acesso] falha ao consultar liberação:', liberacao.detalhe);
      return;
    }
    if(liberacao.status === 'pendente'){
      msg.textContent = 'Seu cadastro foi recebido e está aguardando liberação de um administrador. Você será avisado assim que for aprovado.';
      msg.className = 'auth-msg';
      return;
    }
    if(liberacao.status === 'recusado'){
      msg.textContent = 'Este cadastro não foi autorizado. Fale com a administração da SOLIDUNS.';
      msg.className = 'auth-msg erro';
      return;
    }

    const sessao = {
      access_token: data.access_token,
      refresh_token: data.refresh_token,
      user: data.user,
      expires_at: Date.now() + (data.expires_in||3600)*1000,
      email: email,
      nome: nome,
      /* O perfil vem do servidor, não do roster local: é o administrador
         quem decide, e a decisão precisa valer em qualquer navegador. */
      perfil: liberacao.perfil || 'usuario'
    };
    await salvarCredencialNavegador(email, senha, nome);
    await registrarSenhaParaModoLocal(email, senha, nome);
    await lembrarEmail(email);
    await salvarSessaoAuth(sessao);
    // Login bem-sucedido -> Página 3 (Dashboard), não entra direto no módulo fiscal
    await entrarNoApp(sessao);
  } else {
    /* Uma só porta de saída para todos os erros, com a causa real identificada.
       Antes, qualquer falha (inclusive queda de rede) virava "senha inválida". */
    const d = diagnosticarErroLogin(status, data);
    msg.textContent = d.texto;
    msg.className = 'auth-msg ' + d.tipo;
    console.warn('[login] status=', status, 'resposta=', data);
    if(status === 0 || (data && data.falhaDeRede)) oferecerAcessoLocal(email);
  }
}

/* =====================================================================
   ACESSO LOCAL DE EMERGÊNCIA (modo offline)

   Por que existe: a autenticação desta plataforma é 100% Supabase. Se o
   projeto no Supabase estiver pausado, excluído ou fora do ar, NINGUÉM
   entra — nem o administrador — embora todos os dados (progresso dos
   cursos, gestão fiscal, carteira) continuem intactos no localStorage
   deste navegador.

   O que este modo faz: permite abrir a plataforma neste dispositivo,
   usando os dados que já estão aqui, enquanto o servidor não volta.

   O que ele NÃO é: não é autenticação de verdade. Não há servidor para
   validar nada. A senha é conferida contra um resumo (SHA-256) gravado
   NESTE navegador. Quem tiver acesso físico a este dispositivo e a este
   arquivo consegue entrar. A fronteira real de segurança aqui é o
   próprio dispositivo — e já era, porque os dados sempre estiveram no
   localStorage dele.

   A sessão criada é marcada com modoLocal:true e NÃO sincroniza com o
   servidor. Quando o Supabase voltar, faça login normal para retomar a
   sincronização.
   ===================================================================== */

const SENHA_LOCAL_KEY = 'soliduns-acesso-local';

async function resumoSenha(senha){
  /* SHA-256 via WebCrypto. Guardamos o resumo, nunca a senha em claro. */
  try{
    const dados = new TextEncoder().encode('soliduns::' + senha);
    const buf = await crypto.subtle.digest('SHA-256', dados);
    return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
  }catch(e){
    return null; // WebCrypto exige contexto seguro (https ou file://)
  }
}

function lerCofreLocal(){
  try{ return JSON.parse(localStorage.getItem(SENHA_LOCAL_KEY) || '{}'); }
  catch(e){ return {}; }
}

function gravarCofreLocal(cofre){
  try{ localStorage.setItem(SENHA_LOCAL_KEY, JSON.stringify(cofre)); }
  catch(e){ console.error('Falha ao gravar acesso local', e); }
}

/* Chamado após QUALQUER login bem-sucedido no servidor: guarda o resumo
   da senha para que, se o servidor cair depois, este dispositivo ainda
   consiga abrir a plataforma. */
async function registrarSenhaParaModoLocal(email, senha, nome){
  const h = await resumoSenha(senha);
  if(!h) return;
  const cofre = lerCofreLocal();
  /* Guarda também o perfil apurado no login do servidor. O modo local passa a
     ler o perfil daqui, em vez de recalcular pelo e-mail digitado. */
  cofre[(email||'').trim().toLowerCase()] = {
    hash: h, nome: nome || '', perfil: calcularPerfil(email, nome), em: Date.now()
  };
  gravarCofreLocal(cofre);
}

/* Mostra o acesso local APENAS em navegadores que já autenticaram no servidor.

   Por que essa restrição: com a plataforma publicada em soliduns.com.br,
   qualquer pessoa alcança a tela de login. Se o projeto Supabase pausar — o
   que já aconteceu —, um visitante desconhecido poderia criar um acesso local
   e entrar na estrutura da plataforma. Não veria dados de ninguém, porque o
   localStorage é por navegador, mas veria o sistema por dentro, e ao digitar
   um e-mail de administrador receberia esse perfil na própria máquina.

   A regra passa a ser: só entra em modo local quem já entrou pelo servidor
   neste mesmo navegador. O resumo da senha é gravado no login bem-sucedido
   (registrarSenhaParaModoLocal), então quem nunca autenticou não tem cofre e
   não recebe a oferta. */
function oferecerAcessoLocal(email){
  const msg = document.getElementById('login-msg');
  if(!msg || document.getElementById('caixa-acesso-local')) return;

  const cofre = lerCofreLocal();
  const chave = (email||'').trim().toLowerCase();
  if(!cofre[chave]) return;   /* sem login prévio no servidor: nada é oferecido */

  const box = document.createElement('div');
  box.id = 'caixa-acesso-local';
  box.style.cssText = 'margin-top:14px;padding:12px;border:1px solid #6b5a1a;border-radius:8px;background:#1a1710;';

  const aviso = document.createElement('div');
  aviso.style.cssText = 'font-size:12px;line-height:1.5;color:#c9b77a;margin-bottom:10px;';
  aviso.textContent = 'O servidor está fora do ar, mas seus dados continuam neste navegador. '
    + 'Você pode abrir a plataforma em modo local, com a mesma senha de sempre, usando apenas o que está gravado aqui.';
  box.appendChild(aviso);

  const btn = document.createElement('button');
  btn.id = 'btn-acesso-local';
  btn.type = 'button';
  btn.textContent = 'Entrar em modo local';
  btn.style.cssText = 'width:100%;padding:10px;border:1px solid #e0b800;border-radius:6px;background:transparent;color:#e0b800;font-weight:600;cursor:pointer;';
  btn.onclick = () => entrarModoLocal();
  box.appendChild(btn);

  msg.parentNode.insertBefore(box, msg.nextSibling);
}

async function entrarModoLocal(){
  const email = document.getElementById('login-email').value.trim();
  const senha = document.getElementById('password').value;
  const msg = document.getElementById('login-msg');
  const chave = email.toLowerCase();

  if(!email || !senha){
    msg.textContent = 'Preencha e-mail e senha para usar o acesso local.';
    msg.className = 'auth-msg erro';
    return;
  }

  const h = await resumoSenha(senha);
  if(!h){
    msg.textContent = 'Este navegador não permite o acesso local (WebCrypto indisponível). Use outro navegador.';
    msg.className = 'auth-msg erro';
    return;
  }

  const cofre = lerCofreLocal();

  /* Caminho único: o cofre precisa existir, gravado por um login anterior no
     servidor. Não há mais criação de acesso a partir da tela de erro — era por
     ali que um visitante desconhecido entraria com a plataforma publicada. */
  if(!cofre[chave]){
    msg.textContent = 'Este navegador não tem acesso local registrado para esta conta. '
      + 'O modo local só fica disponível depois de um login bem-sucedido no servidor, neste mesmo navegador.';
    msg.className = 'auth-msg erro';
    return;
  }
  if(cofre[chave].hash !== h){
    msg.textContent = 'Senha diferente da registrada neste dispositivo para o acesso local.';
    msg.className = 'auth-msg erro';
    return;
  }

  const nome = cofre[chave].nome || '';
  const sessao = {
    access_token: null,
    refresh_token: null,
    user: {email: email, user_metadata: {nome: nome}},
    expires_at: Date.now() + 12*60*60*1000,
    email: email,
    nome: nome,
    /* O perfil vem do cofre, gravado no login do servidor — e não recalculado
       a partir do e-mail digitado. Sem isso, digitar um e-mail de
       administrador concederia esse perfil. */
    perfil: cofre[chave].perfil || 'usuario',
    modoLocal: true
  };
  await lembrarEmail(email);
  await salvarSessaoAuth(sessao);
  await entrarNoApp(sessao);
}

/* A faixa fixa no topo foi removida: ela cobria a barra de navegação.
   A sessão continua marcada com modoLocal:true — o estado offline segue
   registrado em sessaoAtual e no localStorage para quem precisar consultar,
   apenas sem aviso visual ocupando a tela. */
function mostrarFaixaModoLocal(){
  /* sem efeito — mantida para não quebrar chamadas existentes */
}

/* Limpa a faixa de versões anteriores que ainda esteja no DOM ou salva. */
window.addEventListener('load', function(){
  const antiga = document.getElementById('faixa-modo-local');
  if(antiga && antiga.parentNode) antiga.parentNode.removeChild(antiga);
});

/* =====================================================================
   FILA DE APROVAÇÃO DE ACESSO

   Autenticar e ter acesso passaram a ser coisas diferentes. O Supabase
   continua validando a senha; a tabela public.acessos guarda a decisão
   do administrador. Toda conta nasce 'pendente' (gatilho no banco) e só
   vira 'aprovado' por ação de um administrador.

   Limite honesto: a verificação abaixo roda no navegador e pode ser
   contornada por quem saiba chamar a API direto. Quem fizer isso obtém
   uma plataforma vazia, porque os dados ficam no localStorage de cada
   navegador. A barreira real, para dados no servidor, são as políticas
   RLS de cada tabela — as de public.acessos estão no arquivo
   soliduns_fila_aprovacao.sql.
   ===================================================================== */

async function consultarLiberacao(token, userId){
  if(!userId) return {erro: true, detalhe: 'id de usuário ausente'};
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/acessos?id=eq.' + encodeURIComponent(userId)
                          + '&select=status,perfil,nome', {
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + token,
        'Accept': 'application/json'
      }
    });
    if(!r.ok) return {erro: true, detalhe: 'HTTP ' + r.status};
    const linhas = await r.json();
    if(!Array.isArray(linhas) || linhas.length === 0){
      /* Sem linha: conta criada antes da fila existir, ou o SQL ainda não
         foi executado. Tratada como pendente — falhar fechado, nunca aberto. */
      return {status: 'pendente', perfil: 'usuario'};
    }
    return {status: linhas[0].status, perfil: linhas[0].perfil, nome: linhas[0].nome};
  }catch(e){
    return {erro: true, detalhe: e && e.message ? e.message : 'falha de rede'};
  }
}

/* Lê a fila inteira. Só retorna dados para administrador: a política RLS
   acessos_admin_le_tudo é quem decide, não esta função. */
async function carregarFilaAcessos(){
  const sessao = sessaoAtual;
  if(!sessao || !sessao.access_token) return {erro: true, detalhe: 'sem sessão de servidor'};
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/acessos?select=id,email,nome,status,perfil,criado_em,plano,plano_validade&order=criado_em.desc', {
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + sessao.access_token,
        'Accept': 'application/json'
      }
    });
    if(!r.ok) return {erro: true, detalhe: 'HTTP ' + r.status};
    const lista = await r.json();
    /* v25: CPFs (tabela usuarios_cpf; o administrador lê todos pela RLS).
       Se a consulta falhar, a fila aparece do mesmo jeito, sem a coluna. */
    let cpfOk = false;
    try{
      const rc = await fetch(SUPABASE_URL + '/rest/v1/usuarios_cpf?select=id,cpf', {
        headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + sessao.access_token, 'Accept': 'application/json'}
      });
      if(rc.ok){
        const cpfs = await rc.json();
        const mapa = {};
        (Array.isArray(cpfs) ? cpfs : []).forEach(c => { mapa[c.id] = String(c.cpf || ''); });
        lista.forEach(u => { u.cpf = mapa[u.id] || null; });
        cpfOk = true;
      }
    }catch(e){}
    return {lista: lista, cpfOk: cpfOk};
  }catch(e){
    return {erro: true, detalhe: e && e.message ? e.message : 'falha de rede'};
  }
}

function escHtml(s){
  return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

/* Remove a linha da fila. A conta continua existindo no Supabase Auth —
   apagar de lá exige a chave de serviço, que não pode viver no HTML sob
   nenhuma hipótese. Sem linha na fila, consultarLiberacao devolve
   'pendente' e a pessoa segue bloqueada; o gatilho só cria linha em
   cadastro novo, então ela não reaparece. */
async function excluirAcesso(id){
  const sessao = sessaoAtual;
  if(!sessao || !sessao.access_token) return {erro: true, detalhe: 'sem sessão de servidor'};
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/acessos?id=eq.' + encodeURIComponent(id), {
      method: 'DELETE',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + sessao.access_token,
        'Prefer': 'return=representation'
      }
    });
    if(!r.ok) return {erro: true, detalhe: 'HTTP ' + r.status};
    const linhas = await r.json();
    if(!Array.isArray(linhas) || linhas.length === 0){
      return {erro: true, detalhe: 'sem permissão para excluir — rode soliduns_permitir_exclusao.sql'};
    }
    return {ok: true};
  }catch(e){
    return {erro: true, detalhe: e && e.message ? e.message : 'falha de rede'};
  }
}

async function decidirAcesso(id, novoStatus, novoPerfil){
  const sessao = sessaoAtual;
  if(!sessao || !sessao.access_token) return {erro: true, detalhe: 'sem sessão de servidor'};
  const corpo = {
    status: novoStatus,
    decidido_em: new Date().toISOString(),
    decidido_por: sessao.email || ''
  };
  if(novoPerfil) corpo.perfil = novoPerfil;
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/acessos?id=eq.' + encodeURIComponent(id), {
      method: 'PATCH',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': 'Bearer ' + sessao.access_token,
        'Content-Type': 'application/json',
        'Prefer': 'return=representation'
      },
      body: JSON.stringify(corpo)
    });
    if(!r.ok) return {erro: true, detalhe: 'HTTP ' + r.status};
    const linhas = await r.json();
    if(!Array.isArray(linhas) || linhas.length === 0){
      /* PATCH aceito porém sem linha afetada: a RLS barrou. Quem não é
         administrador cai aqui, e é assim que deve ser. */
      return {erro: true, detalhe: 'sem permissão para decidir'};
    }
    return {ok: true, linha: linhas[0]};
  }catch(e){
    return {erro: true, detalhe: e && e.message ? e.message : 'falha de rede'};
  }
}

/* ---------- v22: DEFINIR NOVA SENHA (retorno do link de recuperação) ----------
   O token do link fica só em memória (nunca no localStorage). A senha nova é
   gravada com PUT /auth/v1/user; depois a sessão do link é encerrada e a
   pessoa entra normalmente com a senha nova, passando pela fila de aprovação
   como qualquer login. */
var _tokenRecuperacao = null;

function modoNovaSenha(ativo){
  const vis = (sel, mostrar, tipo) => document.querySelectorAll(sel).forEach(el => { el.style.display = mostrar ? (tipo || '') : 'none'; });
  vis('#auth-screen .auth-tabs', !ativo);
  vis('#auth-screen .auth-provedores', !ativo);
  vis('#auth-screen .auth-divisor', !ativo);
  document.getElementById('form-login').style.display = ativo ? 'none' : 'block';
  document.getElementById('form-signup').style.display = 'none';
  document.getElementById('form-nova-senha').style.display = ativo ? 'block' : 'none';
  if(!ativo){
    document.querySelectorAll('.auth-tab').forEach(t=>t.classList.remove('active'));
    const aba = document.querySelector('[data-authtab="login"]');
    if(aba) aba.classList.add('active');
  }
}

async function abrirNovaSenha(accessToken){
  _tokenRecuperacao = accessToken;
  mostrarTela('auth');
  modoNovaSenha(true);
  setTituloPagina('Definir nova senha');
  ['nova-senha','nova-senha-confirma'].forEach(id => { const el = document.getElementById(id); if(el) el.value = ''; });
  const msg = document.getElementById('nova-senha-msg');
  msg.textContent = ''; msg.className = 'auth-msg';
  const conta = document.getElementById('nova-senha-conta');
  conta.textContent = 'Escolha a nova senha da sua conta.';
  try{
    const res = await fetch(SUPABASE_URL + '/auth/v1/user', {
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + accessToken}
    });
    const u = await res.json().catch(()=>null);
    if(u && u.email){
      conta.textContent = 'Conta: ' + u.email;
      conta.dataset.email = u.email;
    }
  }catch(e){ /* sem o e-mail na tela; a troca de senha funciona do mesmo jeito */ }
  const campo = document.getElementById('nova-senha');
  if(campo) campo.focus();
}

async function onSubmitNovaSenha(ev){
  if(ev) ev.preventDefault();
  const msg = document.getElementById('nova-senha-msg');
  const btn = document.getElementById('btn-nova-senha');
  const senha = document.getElementById('nova-senha').value;
  const confirma = document.getElementById('nova-senha-confirma').value;
  if(!_tokenRecuperacao){
    msg.textContent = 'Este link não é mais válido. Volte ao login e peça um novo em "Esqueci minha senha".';
    msg.className = 'auth-msg erro';
    return false;
  }
  if(senha.length < 6){
    msg.textContent = 'A senha precisa ter pelo menos 6 caracteres.';
    msg.className = 'auth-msg erro';
    return false;
  }
  if(senha !== confirma){
    msg.textContent = 'As duas senhas não são iguais. Digite de novo.';
    msg.className = 'auth-msg erro';
    return false;
  }
  msg.textContent = 'Salvando a nova senha...'; msg.className = 'auth-msg';
  if(btn) btn.disabled = true;
  let status = 0, data = {};
  try{
    const res = await fetch(SUPABASE_URL + '/auth/v1/user', {
      method: 'PUT',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + _tokenRecuperacao, 'Content-Type': 'application/json'},
      body: JSON.stringify({password: senha})
    });
    status = res.status;
    data = await res.json().catch(()=>({}));
  }catch(e){
    status = 0;
  }
  if(btn) btn.disabled = false;
  if(status === 200){
    const email = document.getElementById('nova-senha-conta').dataset.email || '';
    const token = _tokenRecuperacao;
    _tokenRecuperacao = null;
    /* Encerra a sessão aberta pelo link: quem entra agora é a senha nova. */
    try{
      await fetch(SUPABASE_URL + '/auth/v1/logout', {
        method: 'POST', headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token}
      });
    }catch(e){ /* o token do link expira sozinho em pouco tempo */ }
    modoNovaSenha(false);
    setTituloPagina('Entrar');
    const campoEmail = document.getElementById('login-email');
    if(campoEmail && email) campoEmail.value = email;
    const campoSenha = document.getElementById('password');
    if(campoSenha){ campoSenha.value = ''; campoSenha.focus(); }
    const m = document.getElementById('login-msg');
    m.textContent = 'Senha alterada com sucesso. Entre agora com a nova senha.';
    m.className = 'auth-msg ok';
    return false;
  }
  const bruto = [data.error_code, data.error, data.msg, data.message, data.error_description]
    .filter(Boolean).join(' | ').toLowerCase();
  let texto;
  if(status === 0) texto = 'Sem conexão com o servidor. Verifique sua internet e tente de novo.';
  else if(bruto.includes('same_password') || bruto.includes('different from the old'))
    texto = 'A nova senha precisa ser diferente da senha atual.';
  else if(bruto.includes('weak_password') || bruto.includes('weak'))
    texto = 'Senha fraca. Use pelo menos 6 caracteres, misturando letras e números.';
  else if(status === 401 || status === 403 || bruto.includes('expired') || bruto.includes('jwt'))
    texto = 'Este link expirou. Volte ao login e peça um novo em "Esqueci minha senha".';
  else texto = 'Não foi possível salvar a nova senha (status ' + status + '): ' + mensagemErroAuth(data);
  msg.textContent = texto;
  msg.className = 'auth-msg erro';
  return false;
}

function cancelarNovaSenha(){
  _tokenRecuperacao = null;
  modoNovaSenha(false);
  setTituloPagina('Entrar');
  const m = document.getElementById('login-msg');
  m.textContent = ''; m.className = 'auth-msg';
}

async function recuperarSenha(){
  const email = document.getElementById('login-email').value.trim();
  const msg = document.getElementById('login-msg');
  if(!email){
    msg.textContent = 'Digite seu e-mail no campo acima e clique em "Esqueci minha senha" novamente.';
    msg.className = 'auth-msg erro';
    return;
  }
  msg.textContent = 'Enviando link de recuperação...'; msg.className = 'auth-msg';
  const {status, data} = await supaFetch('/auth/v1/recover', {email});
  /* v22: o link do e-mail volta para o Site URL do Supabase (soliduns.com.br),
     onde o site abre a tela "Definir nova senha". */
  if(status===200){
    msg.textContent = `Se ${email} estiver cadastrado, enviamos um link de recuperação de senha.`;
    msg.className = 'auth-msg ok';
  } else {
    msg.textContent = mensagemErroAuth(data);
    msg.className = 'auth-msg erro';
  }
}

// Aviso curto no canto da tela, na paleta do site público.
// Existe porque "Sair" a partir de um cabeçalho público (landing, Quem somos,
// Nosso Time, Serviços, Executivo) termina na PRÓPRIA landing: sem uma
// confirmação, a tela fica idêntica e o botão parece morto.
function avisoGlobal(texto){
  let pilha = document.getElementById('aviso-global-stack');
  if(!pilha){
    pilha = document.createElement('div');
    pilha.id = 'aviso-global-stack';
    pilha.style.cssText = 'position:fixed; bottom:20px; right:20px; z-index:9999; display:flex; flex-direction:column; gap:8px; max-width:340px;';
    document.body.appendChild(pilha);
  }
  const el = document.createElement('div');
  el.textContent = texto;
  el.setAttribute('role','status');
  el.style.cssText = 'background:#0d0d0c; border:1px solid var(--gold); color:var(--gold); padding:12px 18px; border-radius:8px; font-size:13px; box-shadow:0 8px 24px rgba(0,0,0,.55);';
  pilha.appendChild(el);
  setTimeout(()=> el.remove(), 4000);
}

async function fazerLogout(){
  // A ORDEM IMPORTA. Antes, a primeira coisa era um `await fetch` na API de
  // logout do Supabase — a tela só reagia depois da resposta da rede, sem
  // timeout. Com rede lenta o botão parecia morto por vários segundos.
  // Agora: derruba a sessão local e a interface na hora; o aviso ao servidor
  // vai depois, em segundo plano, como melhor esforço.
  const sessao = await lerSessaoAuth();

  try{ localStorage.removeItem(AUTH_STORAGE_KEY); }catch(e){}
  sessaoAtual = null;
  const elDash = document.getElementById('topbar-user-dash');
  const elFiscal = document.getElementById('topbar-user-fiscal');
  if(elDash) elDash.textContent = '';
  if(elFiscal) elFiscal.textContent = '';
  ['dash','fiscal'].forEach(suf => { const av = document.getElementById('topbar-avatar-' + suf); if(av) av.textContent = ''; });
  fecharConta(true);
  fecharCpfGate();
  const campoEmail = document.getElementById('login-email');
  const campoSenha = document.getElementById('password');
  if(campoEmail) campoEmail.value = '';
  if(campoSenha) campoSenha.value = '';
  // Sair -> landing pública, nunca a tela de login e nunca uma tela preta.
  window.location.hash = '#/';
  mostrarTela('landing');
  window.scrollTo(0,0);
  avisoGlobal('Você saiu da sua conta.');

  // Revogação no servidor: sem await, para não travar a interface.
  if(sessao && sessao.access_token){
    fetch(SUPABASE_URL + '/auth/v1/logout', {
      method:'POST',
      headers:{'apikey':SUPABASE_KEY, 'Authorization':'Bearer '+sessao.access_token}
    }).catch(function(){ /* melhor esforço — a sessão local já caiu */ });
  }
}

async function salvarSessaoAuth(sessao){
  // localStorage de verdade do navegador — window.storage só existe
  // dentro do artifact do Claude; fora dele o login não sobrevivia a
  // um F5 (falhava calado, sem sessão salva nenhuma).
  try{ localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(sessao)); }
  catch(e){ console.error('Falha ao salvar sessão', e); }
}

async function lerSessaoAuth(){
  try{
    const raw = localStorage.getItem(AUTH_STORAGE_KEY);
    return raw ? JSON.parse(raw) : null;
  }catch(e){ return null; }
}

async function renovarSessao(sessao){
  const {status, data} = await supaFetch('/auth/v1/token?grant_type=refresh_token', {refresh_token: sessao.refresh_token});
  if(status===200 && data.access_token){
    const nova = {
      access_token: data.access_token,
      refresh_token: data.refresh_token,
      user: data.user || sessao.user,
      expires_at: Date.now() + (data.expires_in||3600)*1000,
      email: sessao.email,
      nome: sessao.nome,
      perfil: sessao.perfil || calcularPerfil(sessao.email, sessao.nome)
    };
    await salvarSessaoAuth(nova);
    return nova;
  }
  return null;
}

let sessaoAtual = null;

// Sufixos dos cinco cabeçalhos públicos (landing, quem-somos, equipe,
// serviço e executivo). Cada um tem o par de botões
// #landing-btn-entrar-header<sufixo> / #landing-btn-sair-header<sufixo>.
const SUFIXOS_CABECALHO_PUBLICO = ['', '-qs', '-equipe', '-servico', '-executivo', '-nt'];   /* v119: -nt = Notícias */

// Sem sessão, o cabeçalho público mostra só "Entrar".
// Com sessão (o usuário clicou no logo pra ver a landing sem sair), o rótulo
// CONTINUA "Entrar" — irParaLogin() reconhece a sessão e devolve direto pro
// dashboard, sem pedir login de novo — e o "Sair" aparece ao lado, como na
// topbar do dashboard.
function sincronizarCabecalhosPublicos(){
  const logado = !!sessaoAtual;
  SUFIXOS_CABECALHO_PUBLICO.forEach(function(suf){
    const btnSair = document.getElementById('landing-btn-sair-header' + suf);
    if(btnSair) btnSair.style.display = logado ? '' : 'none';
    const btnEntrar = document.getElementById('landing-btn-entrar-header' + suf);   /* v46 */
    if(btnEntrar) btnEntrar.textContent = logado ? 'Acessar plataforma' : 'Entrar';
  });
}

SUFIXOS_CABECALHO_PUBLICO.forEach(function(suf){
  const btnSair = document.getElementById('landing-btn-sair-header' + suf);
  if(btnSair) btnSair.addEventListener('click', fazerLogout);
});

function mostrarTela(nome){
  /* v22: saindo da tela de login no meio da troca de senha, o link deixa de valer. */
  if(nome !== 'auth' && typeof _tokenRecuperacao !== 'undefined' && _tokenRecuperacao){
    _tokenRecuperacao = null; modoNovaSenha(false);
  }
  sincronizarCabecalhosPublicos();
  document.getElementById('tela-landing').style.display = nome==='landing' ? 'block' : 'none';
  document.getElementById('tela-quem-somos').style.display = nome==='quem-somos' ? 'block' : 'none';
  document.getElementById('tela-noticias').style.display = nome==='noticias' ? 'block' : 'none';   /* v119 */
  document.getElementById('tela-servico').style.display = nome==='servico' ? 'block' : 'none';
  document.getElementById('tela-executivo').style.display = nome==='executivo' ? 'block' : 'none';
  document.getElementById('tela-equipe').style.display = nome==='equipe' ? 'block' : 'none';
  document.getElementById('tela-splash').style.display = nome==='splash' ? 'flex' : 'none';
  document.getElementById('auth-screen').style.display = nome==='auth' ? 'flex' : 'none';
  document.getElementById('tela-dashboard').style.display = nome==='dashboard' ? 'block' : 'none';
  document.getElementById('main-app').style.display = nome==='fiscal' ? 'flex' : 'none';
  if(typeof vmAudAgendar === 'function') vmAudAgendar();   /* v155: audiência */

  // Título da aba (helper único setTituloPagina, 31º prompt): os casos simples
  // são resolvidos aqui mesmo; "dashboard" e "fiscal" têm o título mais
  // específico (do painel/módulo) setado logo em seguida por quem chamou
  // mostrarTela (mostrarPainelDash / abrirModuloFiscal), sobrescrevendo isto.
  if(nome === 'landing') setTituloPagina(null);
  else if(nome === 'auth') setTituloPagina('Entrar');
  else if(nome === 'quem-somos') setTituloPagina('Quem somos');
  else if(nome === 'noticias') setTituloPagina('Valor e Mercado | Notícias', 'Valor e Mercado: conteúdo e notícias de economia e mercado.');   /* v120 */

  // Estado ativo do nav de /quem-somos: reforçado aqui (não só no HTML) porque
  // o header desta página reusa a classe .landing-nav do header da landing, e
  // o observer de âncora ativa da landing (#inicio/#contato) usa essa mesma
  // classe no seletor — sem isso, a marcação inicial podia ser limpa por ele.
  if(nome === 'quem-somos'){
    document.querySelectorAll('#tela-quem-somos .landing-nav a[data-anchor]').forEach(a=>a.classList.remove('landing-ativo'));
    const linkQS = document.querySelector('#tela-quem-somos .landing-nav a[data-anchor="quem-somos"]');
    if(linkQS) linkQS.classList.add('landing-ativo');
  }
}

async function entrarNoApp(sessao){
  sessaoAtual = sessao;
  atualizarUsuarioTopbar();
  if(typeof window.__pilhaPaineisDash !== 'undefined') window.__pilhaPaineisDash = [];
  // Bug corrigido (109º): antes só tratava hash VAZIO. Se o usuário chegasse
  // à tela de login com um hash inválido já na URL (link antigo, erro de
  // digitação, rota que nunca existiu), o login funcionava mas o roteador
  // caía direto na 404 — sessão ok, rota de destino inválida. Agora qualquer
  // hash que não seja uma rota conhecida do mapa ÚNICO (ROTAS/ROTAS_REDIRECT)
  // volta para a home logada.
  const caminhoAtual = (window.location.hash || '').replace(/^#\/?/, '').split('?')[0];
  // Corrigido: a área de Educação é resolvida por PREFIXO no roteador
  // (educacao/...), não pelo mapa ROTAS. Testar só a igualdade com
  // 'educacao' jogava todo link profundo — certificações, artigos e as
  // rotas internas do curso C-Pro R — de volta para a home logada, o que
  // quebrava favoritos e links compartilhados. A condição agora espelha
  // exatamente a do roteador.
  const rotaConhecida = !caminhoAtual || caminhoAtual === 'educacao' || (ROTAS_SO_DESLOGADO.includes(caminhoAtual) || VM_SC_RE.test(caminhoAtual))   /* v119 */ || caminhoAtual.indexOf('educacao/') === 0 || !!ROTAS[caminhoAtual] || !!ROTAS_REDIRECT[caminhoAtual]
    || /^(gestao-financeira|gestao-fiscal)\/[a-z0-9-]+$/.test(caminhoAtual)   /* v46: opções da Gestão (o roteador valida) */
    || /^investimentos\/mercado-financeiro\/[a-z0-9\/-]+$/.test(caminhoAtual)   /* v50: telas do Mercado financeiro */
    || /^investimentos\/mercado-financeiro\/(eua\/)?comparador\/[A-Za-z0-9.,-]+$/.test(caminhoAtual)   /* v55: comparador com tickers */
    || /^investimentos\/mercado-financeiro\/(comparador-fiis|eua\/comparador-etfs)\/[A-Za-z0-9.,-]+$/.test(caminhoAtual)   /* v69 */
    || /^investimentos\/mercado-financeiro\/(eua\/)?analises\/[A-Z0-9.]{2,12}(\/v\/\d{1,3})?$/.test(caminhoAtual)   /* agente v66: página do Relatório de Análise */;
  if(!window.location.hash || window.location.hash === '#' || !rotaConhecida){
    window.location.hash = '#/educacao';
  }
  /* v36: áreas do plano antes de pintar a primeira tela (até 4 s; sem
     resposta, nada é bloqueado e o servidor continua protegendo o que é dele). */
  areasLimpar();
  await Promise.race([areasCarregar(), new Promise(res => setTimeout(res, 4000))]);
  areasMarcarMenus();
  roteador();
  verificarCpfObrigatorio();
  vitrineCarregarServidor();   /* v40: leilões, imóveis e empresas do servidor */
}

function atualizarUsuarioTopbar(){
  if(!sessaoAtual) return;
  const nome = sessaoAtual.nome || (sessaoAtual.user && sessaoAtual.user.user_metadata && sessaoAtual.user.user_metadata.nome) || '';
  const email = sessaoAtual.email || (sessaoAtual.user && sessaoAtual.user.email) || '';
  const texto = nome || email || 'Usuário';
  const elDash = document.getElementById('topbar-user-dash');
  const elFiscal = document.getElementById('topbar-user-fiscal');
  if(elDash) elDash.textContent = texto;
  if(elFiscal) elFiscal.textContent = texto;
  const iniciais = contaIniciais(nome, email);
  ['dash','fiscal'].forEach(suf => {
    const av = document.getElementById('topbar-avatar-' + suf);
    if(av) av.textContent = iniciais;
    const bt = document.getElementById('btn-conta-' + suf);
    if(bt){ bt.title = 'Minha conta — ' + texto; bt.setAttribute('aria-label', 'Minha conta: ' + texto); }
  });
  aplicarVisibilidadeAdmin();
}

function ehAdmin(){
  return !!(sessaoAtual && sessaoAtual.perfil === 'admin');
}

/* v29: dois níveis de administrador.
   - ehAdmin(): perfil 'admin' na fila = administrador de CONTEÚDO (leilões,
     imóveis, empresas, artigos, educação).
   - ehAdminSistema(): lista FIXA = aprova usuários, vê CPFs, altera planos,
     abre a tela Equipe. Espelha public.eh_admin() do banco (SQL 23): quem
     não está na lista não consegue nada disso nem chamando a API direto.
   Para incluir alguém: mudar aqui E no SQL (public.eh_admin). */
const ADMINS_SISTEMA = ['dr.thiago.viegas@gmail.com', 'thales.viegas@gmail.com'];
function ehAdminSistema(){
  const email = ((sessaoAtual && (sessaoAtual.email || (sessaoAtual.user && sessaoAtual.user.email))) || '').trim().toLowerCase();
  return !!(sessaoAtual && ADMINS_SISTEMA.indexOf(email) >= 0);
}

