/* =====================================================================
   MINHA CONTA (v24) — identificador do usuário na barra superior.
   Três abas: Plano (campo reservado para a assinatura), Dados pessoais
   (nome, celular, empresa e cargo, gravados em user_metadata do Supabase)
   e Segurança (troca de senha sem precisar do "Esqueci minha senha").

   Troca de senha: a senha atual é conferida num login novo; a senha nova
   é gravada com o token desse login recém-feito. Assim a troca funciona
   mesmo se a opção "Secure password change" do Supabase estiver ligada,
   e ninguém troca a senha só por achar um navegador com a sessão aberta.

   O plano NÃO fica em user_metadata (o próprio usuário conseguiria
   alterá-lo). Ele é lido da coluna public.acessos.plano (SQL 21), que só
   o administrador altera. Sem o SQL 21, a tela mostra "Nenhum plano".
   ===================================================================== */
let _contaUsuario = null;
let _contaBotaoOrigem = null;
/* CPF (v24): tabela própria public.usuarios_cpf (SQL 21), protegida por RLS —
   cada pessoa lê só o seu; depois de gravado, só o administrador altera.
   Não vai para user_metadata porque ali viajaria no token de login. */
let _contaCpf = null;          // 11 dígitos, quando já vinculado
let _contaCpfEstado = 'carregando'; // carregando | livre | vinculado | indisponivel

function contaFormatarCPF(valor){
  const d = String(valor || '').replace(/\D/g, '').slice(0, 11);
  if(d.length <= 3) return d;
  if(d.length <= 6) return d.slice(0,3) + '.' + d.slice(3);
  if(d.length <= 9) return d.slice(0,3) + '.' + d.slice(3,6) + '.' + d.slice(6);
  return d.slice(0,3) + '.' + d.slice(3,6) + '.' + d.slice(6,9) + '-' + d.slice(9);
}

function contaCPFValido(d){
  if(!/^\d{11}$/.test(d) || /^(\d)\1{10}$/.test(d)) return false;
  let s = 0;
  for(let i = 0; i < 9; i++) s += Number(d[i]) * (10 - i);
  let dv = (s * 10) % 11; if(dv === 10) dv = 0;
  if(dv !== Number(d[9])) return false;
  s = 0;
  for(let i = 0; i < 10; i++) s += Number(d[i]) * (11 - i);
  dv = (s * 10) % 11; if(dv === 10) dv = 0;
  return dv === Number(d[10]);
}

function contaMascararCPF(d){
  return '***.' + d.slice(3,6) + '.' + d.slice(6,9) + '-**';
}

function contaPreencherCPF(){
  const campo = document.getElementById('conta-cpf');
  const dica = document.getElementById('conta-cpf-dica');
  if(sessaoAtual && sessaoAtual.modoLocal) _contaCpfEstado = 'indisponivel';
  if(_contaCpfEstado === 'vinculado' && _contaCpf){
    campo.value = contaMascararCPF(_contaCpf); campo.disabled = true;
    dica.textContent = 'CPF vinculado a esta conta. Para corrigir, escreva para contato@soliduns.com.br.';
  } else if(_contaCpfEstado === 'livre'){
    campo.disabled = false;
    if(/\*/.test(campo.value)) campo.value = '';
    dica.textContent = 'O CPF identifica o titular da assinatura e ajuda a evitar fraudes. Cada CPF pode estar em uma única conta e, depois de salvo, só a SOLIDUNS altera.';
  } else if(_contaCpfEstado === 'indisponivel'){
    campo.value = ''; campo.disabled = true;
    dica.textContent = 'O cadastro do CPF está indisponível no momento. Tente novamente mais tarde.';
  } else {
    campo.value = ''; campo.disabled = true;
    dica.textContent = 'Carregando...';
  }
}

/* Grava o CPF da própria conta. Devolve {ok:true} ou {erro, jaTem}. */
async function gravarCpfServidor(token, cpfDig){
  let st = 0, corpo = {};
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/usuarios_cpf', {
      method: 'POST',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json', 'Prefer': 'return=minimal'},
      body: JSON.stringify({id: sessaoAtual && sessaoAtual.user && sessaoAtual.user.id, cpf: cpfDig})
    });
    st = r.status;
    if(!r.ok) corpo = await r.json().catch(() => ({}));
  }catch(e){ st = 0; }
  if(st === 201 || st === 200 || st === 204) return {ok: true};
  const cod = String(corpo.code || '');
  const txt = String(corpo.message || corpo.details || '').toLowerCase();
  if(st === 0) return {erro: 'Sem conexão com o servidor. Verifique sua internet e tente de novo.'};
  if(cod === '23505' && txt.includes('pkey')) return {erro: 'Esta conta já tem um CPF vinculado.', jaTem: true};
  if(cod === '23505') return {erro: 'Este CPF já está vinculado a outra conta. Se for o seu, escreva para contato@soliduns.com.br.'};
  if(cod === '23514') return {erro: 'CPF inválido. Confira os números digitados.'};
  if(st === 401 || st === 403) return {erro: 'Sua sessão expirou. Saia e entre novamente.'};
  return {erro: 'Não foi possível salvar o CPF (status ' + st + '). Tente de novo em instantes.'};
}

async function contaCarregarCPF(token, uid){
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/usuarios_cpf?id=eq.' + encodeURIComponent(uid) + '&select=cpf', {
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Accept': 'application/json'}
    });
    if(!r.ok) return {erro: true};
    const linhas = await r.json();
    return {cpf: Array.isArray(linhas) && linhas.length ? String(linhas[0].cpf || '').trim() : null};
  }catch(e){ return {erro: true}; }
}

function contaIniciais(nome, email){
  const partes = String(nome || '').trim().split(/\s+/).filter(Boolean);
  if(partes.length){
    const a = partes[0].charAt(0);
    const b = partes.length > 1 ? partes[partes.length - 1].charAt(0) : '';
    return (a + b).toUpperCase();
  }
  const e = String(email || '').trim();
  return e ? e.charAt(0).toUpperCase() : '?';
}

function contaDataBR(valor){
  if(!valor) return '—';
  /* v34: data pura (AAAA-MM-DD, ex.: validade do plano) é um dia do
     calendário, não um instante: new Date() a leria como meia-noite UTC e,
     em Brasília, mostraria o dia anterior. */
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(valor));
  if(m) return m[3] + '/' + m[2] + '/' + m[1];
  const d = new Date(valor);
  if(isNaN(d.getTime())) return '—';
  return d.toLocaleDateString('pt-BR', {day:'2-digit', month:'2-digit', year:'numeric', timeZone:'America/Sao_Paulo'});
}

function contaFormatarCelular(valor){
  const d = String(valor || '').replace(/\D/g, '').slice(0, 11);
  if(d.length <= 2) return d.length ? '(' + d : '';
  if(d.length <= 6) return '(' + d.slice(0,2) + ') ' + d.slice(2);
  if(d.length <= 10) return '(' + d.slice(0,2) + ') ' + d.slice(2,6) + '-' + d.slice(6);
  return '(' + d.slice(0,2) + ') ' + d.slice(2,7) + '-' + d.slice(7);
}

function contaMsg(id, texto, tipo){
  const m = document.getElementById(id);
  if(!m) return;
  m.textContent = texto || '';
  m.className = 'auth-msg' + (tipo ? ' ' + tipo : '');
}

function contaProvedores(u){
  const am = (u && u.app_metadata) || {};
  let lista = Array.isArray(am.providers) ? am.providers.slice() : [];
  if(!lista.length && am.provider) lista = [am.provider];
  if(!lista.length && u && Array.isArray(u.identities)) lista = u.identities.map(i => i.provider);
  return lista;
}

/* Token válido para falar com o Supabase; renova se estiver perto de vencer. */
async function contaTokenValido(){
  if(!sessaoAtual || sessaoAtual.modoLocal || !sessaoAtual.access_token) return null;
  if(sessaoAtual.expires_at && Date.now() < sessaoAtual.expires_at - 60000) return sessaoAtual.access_token;
  const nova = await renovarSessao(sessaoAtual);
  if(!nova) return null;
  sessaoAtual = nova;
  return nova.access_token;
}

async function contaBuscar(caminho, token){
  try{
    const r = await fetch(SUPABASE_URL + caminho, {
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Accept': 'application/json'}
    });
    if(!r.ok) return null;
    return await r.json().catch(() => null);
  }catch(e){ return null; }
}

function contaMostrarAba(aba, focar){
  document.querySelectorAll('#conta-overlay .conta-aba').forEach(b => {
    const ativa = b.dataset.aba === aba;
    b.classList.toggle('ativa', ativa);
    b.setAttribute('aria-selected', ativa ? 'true' : 'false');
    b.tabIndex = ativa ? 0 : -1;
    if(ativa && focar) b.focus();
  });
  ['plano','dados','seguranca'].forEach(n => {
    const p = document.getElementById('conta-painel-' + n);
    if(p) p.hidden = (n !== aba);
  });
}

function contaPreencherCabecalho(){
  const nome = (sessaoAtual && sessaoAtual.nome) || '';
  const email = (sessaoAtual && (sessaoAtual.email || (sessaoAtual.user && sessaoAtual.user.email))) || '';
  document.getElementById('conta-avatar').textContent = contaIniciais(nome, email);
  document.getElementById('conta-titulo').textContent = nome || 'Minha conta';
  document.getElementById('conta-identificacao').textContent = email;
}

function contaPreencherPlano(acesso, usuario){
  const nomesPerfil = {admin: 'Administrador', contador: 'Contador', usuario: 'Usuário'};
  const nomesSituacao = {aprovado: 'Liberado', pendente: 'Aguardando liberação', recusado: 'Não autorizado'};
  const perfil = (acesso && acesso.perfil) || (sessaoAtual && sessaoAtual.perfil) || 'usuario';
  const situacao = (acesso && acesso.status) || 'aprovado';
  document.getElementById('conta-perfil').textContent = nomesPerfil[perfil] || perfil;
  document.getElementById('conta-situacao').textContent = nomesSituacao[situacao] || situacao;
  document.getElementById('conta-desde').textContent = contaDataBR((acesso && acesso.criado_em) || (usuario && usuario.created_at));

  const prov = contaProvedores(usuario);
  const entrada = [];
  if(prov.includes('email')) entrada.push('E-mail e senha');
  if(prov.includes('google')) entrada.push('Google');
  document.getElementById('conta-entrada').textContent = entrada.length ? entrada.join(' e ') : (sessaoAtual && sessaoAtual.modoLocal ? 'Modo offline' : '—');

  const plano = acesso && typeof acesso.plano === 'string' ? acesso.plano.trim() : '';
  const item = document.getElementById('conta-plano-item');
  document.getElementById('conta-plano').textContent = plano || 'Nenhum plano contratado';
  item.classList.toggle('conta-plano-vazio', !plano);
  document.getElementById('conta-plano-nota').hidden = !!plano;
  const validade = acesso && acesso.plano_validade;
  document.getElementById('conta-plano-validade-item').hidden = !(plano && validade);
  document.getElementById('conta-plano-validade').textContent = contaDataBR(validade);
}

function contaPreencherDados(usuario){
  const md = (usuario && usuario.user_metadata) || {};
  const nome = md.nome || md.full_name || md.name || (sessaoAtual && sessaoAtual.nome) || '';
  document.getElementById('conta-nome').value = nome;
  document.getElementById('conta-email').value = (usuario && usuario.email) || (sessaoAtual && sessaoAtual.email) || '';
  document.getElementById('conta-telefone').value = contaFormatarCelular(md.telefone || '');
  document.getElementById('conta-empresa').value = md.empresa || '';
  document.getElementById('conta-cargo').value = md.cargo || '';
}

function contaPreencherSeguranca(usuario){
  const prov = contaProvedores(usuario);
  /* Sem a lista de provedores (dados ainda carregando ou offline), mostra o
     formulário: é o caso comum, e o servidor recusa se não houver senha. */
  const soGoogle = prov.length > 0 && !prov.includes('email');
  document.getElementById('conta-senha-google').hidden = !soGoogle;
  document.getElementById('conta-senha-bloco').hidden = soGoogle;
}

function contaBloquearEdicao(bloquear){
  document.getElementById('conta-aviso-offline').hidden = !bloquear;
  ['conta-nome','conta-telefone','conta-empresa','conta-cargo','conta-senha-atual','conta-senha-nova','conta-senha-confirma',
   'btn-conta-salvar-dados','btn-conta-trocar-senha','btn-conta-sair-outros'].forEach(id => {
    const el = document.getElementById(id);
    if(el) el.disabled = !!bloquear;
  });
}

async function abrirConta(aba){
  if(!sessaoAtual) return;
  _contaBotaoOrigem = document.activeElement;
  contaMsg('conta-dados-msg', '');
  contaMsg('conta-senha-msg', '');
  contaMsg('conta-sessoes-msg', '');
  ['conta-senha-atual','conta-senha-nova','conta-senha-confirma'].forEach(id => { document.getElementById(id).value = ''; });
  _contaUsuario = sessaoAtual.user || null;
  contaPreencherCabecalho();
  contaPreencherPlano(null, _contaUsuario);
  contaPreencherDados(_contaUsuario);
  contaPreencherSeguranca(_contaUsuario);
  contaBloquearEdicao(!!sessaoAtual.modoLocal);
  _contaCpf = null; _contaCpfEstado = 'carregando';
  contaPreencherCPF();
  contaMostrarAba(aba || 'plano');
  document.getElementById('conta-overlay').style.display = 'flex';
  setTituloPagina('Minha conta');
  const abaAtiva = document.querySelector('#conta-overlay .conta-aba.ativa');
  if(abaAtiva) abaAtiva.focus();

  if(sessaoAtual.modoLocal) return;
  const token = await contaTokenValido();
  if(!token){
    _contaCpfEstado = 'indisponivel'; contaPreencherCPF();
    contaMsg('conta-dados-msg', 'Sua sessão expirou. Saia e entre novamente para alterar seus dados.', 'erro');
    return;
  }
  const uid = (sessaoAtual.user && sessaoAtual.user.id) || '';
  const [usuario, linhas, cpf] = await Promise.all([
    contaBuscar('/auth/v1/user', token),
    contaBuscar('/rest/v1/acessos?id=eq.' + encodeURIComponent(uid) + '&select=*', token),
    contaCarregarCPF(token, uid)
  ]);
  if(document.getElementById('conta-overlay').style.display === 'none') return;
  if(cpf.erro) _contaCpfEstado = 'indisponivel';
  else if(cpf.cpf){ _contaCpf = cpf.cpf; _contaCpfEstado = 'vinculado'; }
  else _contaCpfEstado = 'livre';
  contaPreencherCPF();
  if(usuario && usuario.id){
    _contaUsuario = usuario;
    sessaoAtual.user = usuario;
    contaPreencherDados(usuario);
    contaPreencherSeguranca(usuario);
  }
  contaPreencherPlano(Array.isArray(linhas) && linhas.length ? linhas[0] : null, _contaUsuario);
}

function fecharConta(semFoco){
  const ov = document.getElementById('conta-overlay');
  if(!ov || ov.style.display === 'none') return;
  ov.style.display = 'none';
  ['conta-senha-atual','conta-senha-nova','conta-senha-confirma'].forEach(id => { const el = document.getElementById(id); if(el) el.value = ''; });
  if(sessaoAtual) restaurarTituloAposFecharEquipe();
  if(!semFoco && _contaBotaoOrigem && document.body.contains(_contaBotaoOrigem)){
    try{ _contaBotaoOrigem.focus(); }catch(e){}
  }
}

async function salvarDadosConta(){
  const btn = document.getElementById('btn-conta-salvar-dados');
  const nome = document.getElementById('conta-nome').value.trim().replace(/\s+/g, ' ');
  const telDig = document.getElementById('conta-telefone').value.replace(/\D/g, '');
  const empresa = document.getElementById('conta-empresa').value.trim();
  const cargo = document.getElementById('conta-cargo').value.trim();
  if(nome.length < 3){
    contaMsg('conta-dados-msg', 'Informe seu nome completo.', 'erro');
    document.getElementById('conta-nome').focus();
    return;
  }
  if(telDig && (telDig.length < 10 || telDig.length > 11)){
    contaMsg('conta-dados-msg', 'Celular incompleto. Use DDD e número, por exemplo (61) 99999-9999.', 'erro');
    document.getElementById('conta-telefone').focus();
    return;
  }
  const campoCpf = document.getElementById('conta-cpf');
  const cpfDig = (_contaCpfEstado === 'livre') ? campoCpf.value.replace(/\D/g, '') : '';
  if(cpfDig && !contaCPFValido(cpfDig)){
    contaMsg('conta-dados-msg', 'CPF inválido. Confira os números digitados.', 'erro');
    campoCpf.focus();
    return;
  }
  const token = await contaTokenValido();
  if(!token){
    contaMsg('conta-dados-msg', 'Sua sessão expirou. Saia e entre novamente para alterar seus dados.', 'erro');
    return;
  }
  contaMsg('conta-dados-msg', 'Salvando...');
  btn.disabled = true;
  let cpfGravado = false;
  if(cpfDig){
    const res = await gravarCpfServidor(token, cpfDig);
    if(!res.ok){
      btn.disabled = false;
      if(res.jaTem){
        _contaCpfEstado = 'carregando'; contaPreencherCPF();
        contaMsg('conta-dados-msg', 'Esta conta já tem um CPF vinculado. Feche e abra Minha conta novamente.', 'erro');
      } else {
        contaMsg('conta-dados-msg', res.erro + ' Nada foi alterado.', 'erro');
      }
      return;
    }
    cpfGravado = true;
    _contaCpf = cpfDig; _contaCpfEstado = 'vinculado';
    contaPreencherCPF();
  }
  let status = 0, data = {};
  try{
    const r = await fetch(SUPABASE_URL + '/auth/v1/user', {
      method: 'PUT',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'},
      body: JSON.stringify({data: {nome: nome, telefone: telDig ? contaFormatarCelular(telDig) : '', empresa: empresa, cargo: cargo}})
    });
    status = r.status;
    data = await r.json().catch(() => ({}));
  }catch(e){ status = 0; }
  btn.disabled = false;
  if(status === 200 && data && data.id){
    _contaUsuario = data;
    sessaoAtual.user = data;
    sessaoAtual.nome = nome;
    await salvarSessaoAuth(sessaoAtual);
    atualizarUsuarioTopbar();
    contaPreencherCabecalho();
    contaPreencherDados(data);
    contaMsg('conta-dados-msg', cpfGravado ? 'CPF vinculado e dados atualizados.' : 'Dados atualizados.', 'ok');
    return;
  }
  if(status === 0) contaMsg('conta-dados-msg', 'Sem conexão com o servidor. Verifique sua internet e tente de novo.', 'erro');
  else if(status === 401 || status === 403) contaMsg('conta-dados-msg', 'Sua sessão expirou. Saia e entre novamente para alterar seus dados.', 'erro');
  else contaMsg('conta-dados-msg', 'Não foi possível salvar (status ' + status + '): ' + mensagemErroAuth(data), 'erro');
}

async function trocarSenhaConta(){
  const btn = document.getElementById('btn-conta-trocar-senha');
  const campoAtual = document.getElementById('conta-senha-atual');
  const campoNova = document.getElementById('conta-senha-nova');
  const campoConf = document.getElementById('conta-senha-confirma');
  const atual = campoAtual.value, nova = campoNova.value, confirma = campoConf.value;
  const email = (_contaUsuario && _contaUsuario.email) || (sessaoAtual && sessaoAtual.email) || '';
  if(!atual){ contaMsg('conta-senha-msg', 'Digite sua senha atual.', 'erro'); campoAtual.focus(); return; }
  if(nova.length < 6){ contaMsg('conta-senha-msg', 'A nova senha precisa ter pelo menos 6 caracteres.', 'erro'); campoNova.focus(); return; }
  if(nova !== confirma){ contaMsg('conta-senha-msg', 'A confirmação não é igual à nova senha. Digite de novo.', 'erro'); campoConf.focus(); return; }
  if(nova === atual){ contaMsg('conta-senha-msg', 'A nova senha precisa ser diferente da senha atual.', 'erro'); campoNova.focus(); return; }
  if(!email || !sessaoAtual || sessaoAtual.modoLocal){ contaMsg('conta-senha-msg', 'Não foi possível identificar sua conta. Saia e entre novamente.', 'erro'); return; }

  btn.disabled = true;
  contaMsg('conta-senha-msg', 'Conferindo a senha atual...');
  /* 1) Confere a senha atual com um login novo. */
  const login = await supaFetch('/auth/v1/token?grant_type=password', {email: email, password: atual});
  if(login.status !== 200 || !login.data || !login.data.access_token){
    btn.disabled = false;
    const bruto = [login.data && login.data.error_code, login.data && login.data.error, login.data && login.data.msg, login.data && login.data.error_description]
      .filter(Boolean).join(' | ').toLowerCase();
    if(login.status === 0) contaMsg('conta-senha-msg', 'Sem conexão com o servidor. Verifique sua internet e tente de novo.', 'erro');
    else if(bruto.includes('rate limit') || login.status === 429) contaMsg('conta-senha-msg', 'Muitas tentativas em pouco tempo. Aguarde alguns minutos e tente de novo.', 'erro');
    else if(bruto.includes('invalid') || login.status === 400){ contaMsg('conta-senha-msg', 'A senha atual não confere.', 'erro'); campoAtual.focus(); }
    else contaMsg('conta-senha-msg', 'Não foi possível conferir a senha atual (status ' + login.status + '): ' + mensagemErroAuth(login.data || {}), 'erro');
    return;
  }
  /* 2) Grava a nova senha com o token do login que acabou de ser feito. */
  contaMsg('conta-senha-msg', 'Salvando a nova senha...');
  let status = 0, data = {};
  try{
    const r = await fetch(SUPABASE_URL + '/auth/v1/user', {
      method: 'PUT',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + login.data.access_token, 'Content-Type': 'application/json'},
      body: JSON.stringify({password: nova})
    });
    status = r.status;
    data = await r.json().catch(() => ({}));
  }catch(e){ status = 0; }
  btn.disabled = false;
  if(status === 200){
    /* Passa a usar a sessão nova (a do login de conferência). */
    sessaoAtual.access_token = login.data.access_token;
    sessaoAtual.refresh_token = login.data.refresh_token;
    sessaoAtual.expires_at = Date.now() + (login.data.expires_in || 3600) * 1000;
    if(data && data.id){ sessaoAtual.user = data; _contaUsuario = data; }
    await salvarSessaoAuth(sessaoAtual);
    try{ await registrarSenhaParaModoLocal(email, nova, sessaoAtual.nome || ''); }catch(e){}
    campoAtual.value = ''; campoNova.value = ''; campoConf.value = '';
    contaMsg('conta-senha-msg', 'Senha alterada. Enviamos um aviso de segurança para ' + email + '. Use a nova senha no próximo acesso. Se trocou por suspeita de acesso indevido, use também "Sair dos outros dispositivos", logo abaixo.', 'ok');
    return;
  }
  const bruto = [data.error_code, data.error, data.msg, data.message, data.error_description].filter(Boolean).join(' | ').toLowerCase();
  let texto;
  if(status === 0) texto = 'Sem conexão com o servidor. Verifique sua internet e tente de novo.';
  else if(bruto.includes('same_password') || bruto.includes('different from the old')) texto = 'A nova senha precisa ser diferente da senha atual.';
  else if(bruto.includes('weak_password') || bruto.includes('weak')) texto = 'Senha fraca. Use pelo menos 6 caracteres, misturando letras e números.';
  else if(bruto.includes('reauthentication')) texto = 'O servidor pediu uma nova confirmação de identidade. Saia, entre novamente e repita a troca.';
  else texto = 'Não foi possível salvar a nova senha (status ' + status + '): ' + mensagemErroAuth(data);
  contaMsg('conta-senha-msg', texto, 'erro');
}

['dash','fiscal'].forEach(suf => {
  const b = document.getElementById('btn-conta-' + suf);
  if(b) b.addEventListener('click', () => abrirConta('plano'));
});
document.getElementById('conta-fechar').addEventListener('click', () => fecharConta());
document.getElementById('conta-overlay').addEventListener('click', ev => { if(ev.target.id === 'conta-overlay') fecharConta(); });
document.addEventListener('keydown', ev => {
  const ov = document.getElementById('conta-overlay');
  if(ev.key === 'Escape' && ov && ov.style.display !== 'none') fecharConta();
});
document.querySelectorAll('#conta-overlay .conta-aba').forEach(b => {
  b.addEventListener('click', () => contaMostrarAba(b.dataset.aba));
  b.addEventListener('keydown', ev => {
    if(ev.key !== 'ArrowRight' && ev.key !== 'ArrowLeft') return;
    const abas = Array.from(document.querySelectorAll('#conta-overlay .conta-aba'));
    const i = abas.indexOf(b);
    const prox = abas[(i + (ev.key === 'ArrowRight' ? 1 : abas.length - 1)) % abas.length];
    contaMostrarAba(prox.dataset.aba, true);
    ev.preventDefault();
  });
});
document.getElementById('conta-telefone').addEventListener('input', ev => { ev.target.value = contaFormatarCelular(ev.target.value); });
document.getElementById('conta-cpf').addEventListener('input', ev => { ev.target.value = contaFormatarCPF(ev.target.value); });
document.getElementById('btn-conta-salvar-dados').addEventListener('click', salvarDadosConta);
document.getElementById('btn-conta-trocar-senha').addEventListener('click', trocarSenhaConta);
['conta-senha-atual','conta-senha-nova','conta-senha-confirma'].forEach(id => {
  document.getElementById(id).addEventListener('keydown', ev => { if(ev.key === 'Enter') trocarSenhaConta(); });
});

/* =====================================================================
   SAIR DOS OUTROS DISPOSITIVOS (v27). Pede ao Supabase Auth para encerrar
   todas as outras sessões da conta (logout com scope=others): os
   "refresh tokens" dos outros aparelhos são revogados na hora; o acesso
   que já estiver aberto lá expira em até 1 hora (validade do token).
   Esta sessão continua valendo.
   ===================================================================== */
async function sairOutrosDispositivos(){
  const btn = document.getElementById('btn-conta-sair-outros');
  if(!sessaoAtual || sessaoAtual.modoLocal){
    contaMsg('conta-sessoes-msg', 'Indisponível no modo offline: é preciso estar conectado ao servidor.', 'erro');
    return;
  }
  if(!confirm('Encerrar a sua conta SOLIDUNS em todos os OUTROS aparelhos e navegadores?\n\nEste aqui continua conectado. Nos outros, será preciso entrar de novo.')) return;
  const token = await contaTokenValido();
  if(!token){ contaMsg('conta-sessoes-msg', 'Sua sessão expirou. Saia e entre novamente.', 'erro'); return; }
  btn.disabled = true;
  contaMsg('conta-sessoes-msg', 'Encerrando as outras sessões...');
  let status = 0;
  try{
    const r = await fetch(SUPABASE_URL + '/auth/v1/logout?scope=others', {
      method: 'POST',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token}
    });
    status = r.status;
  }catch(e){ status = 0; }
  btn.disabled = false;
  if(status === 204 || status === 200){
    contaMsg('conta-sessoes-msg', 'Pronto. Os outros aparelhos foram desconectados; um acesso que já estivesse aberto lá se encerra em até 1 hora. Este continua conectado.', 'ok');
  } else if(status === 0){
    contaMsg('conta-sessoes-msg', 'Sem conexão com o servidor. Verifique sua internet e tente de novo.', 'erro');
  } else if(status === 401 || status === 403){
    contaMsg('conta-sessoes-msg', 'Sua sessão expirou. Saia e entre novamente.', 'erro');
  } else {
    contaMsg('conta-sessoes-msg', 'Não foi possível encerrar as outras sessões (status ' + status + '). Tente de novo em instantes.', 'erro');
  }
}
document.getElementById('btn-conta-sair-outros').addEventListener('click', sairOutrosDispositivos);

/* =====================================================================
   CPF OBRIGATÓRIO (v25). Ao entrar na área logada, quem ainda não tem
   CPF vinculado vê uma tela que só fecha depois de salvar o CPF (ou
   saindo da conta). Vale para todos os perfis, inclusive administrador.
   Se o servidor não responder, a pessoa entra normalmente e a tela
   aparece no próximo acesso: uma falha de rede não tranca ninguém fora.
   Modo offline: sem verificação (não há servidor).
   ===================================================================== */
async function verificarCpfObrigatorio(){
  if(!sessaoAtual || sessaoAtual.modoLocal) return;
  const token = await contaTokenValido();
  if(!token) return;
  const uid = (sessaoAtual.user && sessaoAtual.user.id) || '';
  if(!uid) return;
  const res = await contaCarregarCPF(token, uid);
  if(res.erro || res.cpf) return;
  if(!sessaoAtual) return;
  abrirCpfGate();
}

function abrirCpfGate(){
  const g = document.getElementById('cpf-gate');
  document.getElementById('cpf-gate-campo').value = '';
  contaMsg('cpf-gate-msg', '');
  document.getElementById('btn-cpf-gate-salvar').disabled = false;
  g.style.display = 'flex';
  setTimeout(() => { try{ document.getElementById('cpf-gate-campo').focus(); }catch(e){} }, 50);
}

function fecharCpfGate(){
  const g = document.getElementById('cpf-gate');
  if(g) g.style.display = 'none';
}

async function salvarCpfGate(){
  const campo = document.getElementById('cpf-gate-campo');
  const btn = document.getElementById('btn-cpf-gate-salvar');
  const dig = campo.value.replace(/\D/g, '');
  if(!contaCPFValido(dig)){
    contaMsg('cpf-gate-msg', dig.length < 11 ? 'Digite os 11 números do CPF.' : 'CPF inválido. Confira os números digitados.', 'erro');
    campo.focus();
    return;
  }
  const token = await contaTokenValido();
  if(!token){ contaMsg('cpf-gate-msg', 'Sua sessão expirou. Saia e entre novamente.', 'erro'); return; }
  btn.disabled = true;
  contaMsg('cpf-gate-msg', 'Salvando...');
  const res = await gravarCpfServidor(token, dig);
  btn.disabled = false;
  if(res.ok || res.jaTem){
    _contaCpf = dig; _contaCpfEstado = 'vinculado';
    fecharCpfGate();
    return;
  }
  contaMsg('cpf-gate-msg', res.erro, 'erro');
  campo.focus();
}

document.getElementById('cpf-gate-campo').addEventListener('input', ev => { ev.target.value = contaFormatarCPF(ev.target.value); });
document.getElementById('signup-cpf').addEventListener('input', ev => { ev.target.value = contaFormatarCPF(ev.target.value); });
document.getElementById('cpf-gate-campo').addEventListener('keydown', ev => { if(ev.key === 'Enter') salvarCpfGate(); });
document.getElementById('btn-cpf-gate-salvar').addEventListener('click', salvarCpfGate);
document.getElementById('btn-cpf-gate-sair').addEventListener('click', () => { fecharCpfGate(); fazerLogout(); });

/* Desenha a fila de aprovação vinda do servidor. Erros são mostrados na
   tela em vez de virarem tabela vazia — uma fila vazia por falha de rede
   pareceria "ninguém pediu acesso", que é exatamente a leitura errada. */
let _filaCpfOk = false;
async function renderizarFilaAcessos(){
  const sub = document.getElementById('fila-subtitulo');
  const caixa = document.getElementById('fila-secoes');
  if(!sub || !caixa) return;

  if(sessaoAtual && sessaoAtual.modoLocal){
    caixa.innerHTML = '';
    sub.textContent = 'Indisponível em modo local: a fila vive no servidor.';
    return;
  }

  sub.textContent = 'Carregando…';
  caixa.innerHTML = '';

  const r = await carregarFilaAcessos();
  if(r.erro){
    sub.textContent = 'Não foi possível carregar a fila (' + r.detalhe + ').';
    return;
  }

  const lista = r.lista || [];
  const pendentes = lista.filter(x => x.status === 'pendente');
  const aprovados = lista.filter(x => x.status === 'aprovado');
  const negados   = lista.filter(x => x.status === 'recusado');

  _filaCpfOk = !!r.cpfOk;
  const semCpf = r.cpfOk ? aprovados.filter(x => !x.cpf).length : 0;
  sub.textContent = (pendentes.length === 0
    ? 'Nenhuma solicitação pendente. ' + lista.length + ' cadastro(s) no total.'
    : pendentes.length + ' aguardando decisão, de ' + lista.length + ' cadastro(s).')
    + (semCpf ? ' ' + semCpf + ' usuário(s) liberado(s) ainda sem CPF: o CPF é pedido no próximo acesso.' : '');

  /* Três tabelas separadas, na ordem em que exigem atenção: o que depende
     de decisão vem primeiro; o histórico de negados fica por último. */
  const livre = _regraCadastroLivre === true;
  if(!livre || pendentes.length) montarSecao(caixa, 'Solicitações pendentes', pendentes,
    'Ninguém aguardando decisão no momento.', sub);
  montarSecao(caixa, livre ? 'Contas ativas' : 'Usuários permitidos', aprovados,
    'Nenhum usuário liberado ainda.', sub);
  montarSecao(caixa, livre ? 'Contas bloqueadas' : 'Cadastros negados', negados,
    livre ? 'Nenhuma conta bloqueada.' : 'Nenhum cadastro negado.', sub);
}

/* Desenha um bloco título + tabela. Seção vazia mostra uma linha de texto
   em vez de sumir: a ausência precisa ser visível, senão o administrador
   não sabe se está vazia ou se falhou ao carregar. */
function montarSecao(caixa, titulo, linhas, textoVazio, sub){
  const h = document.createElement('h3');
  h.style.cssText = 'margin:20px 0 6px; font-size:15px;';
  h.textContent = titulo + ' (' + linhas.length + ')';
  caixa.appendChild(h);

  if(linhas.length === 0){
    const p = document.createElement('div');
    p.className = 'leilao-ficha-sub';
    p.style.cssText = 'margin-bottom:6px;';
    p.textContent = textoVazio;
    caixa.appendChild(p);
    return;
  }

  const tab = document.createElement('table');
  tab.className = 'leilao-admin-table';
  tab.innerHTML = '<thead><tr><th>Nome</th><th>E-mail</th>' + (_filaCpfOk ? '<th>CPF</th>' : '') + '<th>Perfil</th>' + (_planosOk ? '<th>Plano</th>' : '') + '<th></th></tr></thead>';
  const tbody = document.createElement('tbody');

  linhas.forEach(u => {
    const tr = document.createElement('tr');
    const ehMestreEsta = (u.email||'').toLowerCase() === EMAIL_ADMIN_MESTRE;

    let acoes = '';
    if(ehMestreEsta){
      acoes = '<span style="color:var(--ink-soft); font-size:11.5px;">admin-mestre</span>';
      if(_planosOk && u.status === 'aprovado') acoes = '<button type="button" class="ac-editar ac-plano">Plano</button> ' + acoes;
    } else if(u.status === 'aprovado'){
      acoes = u.perfil === 'admin'
        ? '<button type="button" class="ac-editar ac-usuario">Tornar usuário</button> '
        : '<button type="button" class="ac-editar ac-admin">Tornar administrador</button> ';
      acoes += '<button type="button" class="ac-editar ac-recusar">' + (_regraCadastroLivre ? 'Bloquear' : 'Negar') + '</button> '
             + '<button type="button" class="ac-editar ac-excluir">Excluir</button>';
      if(_planosOk) acoes = '<button type="button" class="ac-editar ac-plano">Plano</button> ' + acoes;
    } else if(u.status === 'recusado'){
      acoes = '<button type="button" class="ac-editar ac-aprovar">' + (_regraCadastroLivre ? 'Desbloquear' : 'Permitir') + '</button> '
            + '<button type="button" class="ac-editar ac-excluir">Excluir</button>';
    } else {
      acoes = '<button type="button" class="ac-editar ac-aprovar">Permitir</button> '
            + '<button type="button" class="ac-editar ac-admin">Permitir como admin</button> '
            + '<button type="button" class="ac-editar ac-recusar">Negar</button> '
            + '<button type="button" class="ac-editar ac-excluir">Excluir</button>';
    }

    /* v25: nome e e-mail vêm do próprio usuário (cadastro e Minha conta):
       sempre escapados antes de entrar no HTML. */
    let celCpf = '';
    if(_filaCpfOk){
      celCpf = u.cpf && /^\d{11}$/.test(u.cpf)
        ? '<td><button type="button" class="cpf-ver" title="Clique para mostrar ou ocultar">' + contaMascararCPF(u.cpf) + '</button></td>'
        : '<td><span class="cpf-pendente">' + (u.status === 'aprovado' ? 'pendente' : '—') + '</span></td>';
    }
    tr.innerHTML = '<td>' + escHtml(u.nome || '—') + '</td>'
                 + '<td>' + escHtml(u.email) + '</td>'
                 + celCpf
                 + '<td>' + escHtml(u.perfil) + '</td>'
                 + (_planosOk ? '<td class="plano-coluna">' + (u.status !== 'aprovado' ? '—'
                      : (u.plano ? escHtml(u.plano) + '<div class="plano-slug">' + (u.plano_validade ? 'até ' + contaDataBR(u.plano_validade) : 'sem prazo') + '</div>'
                                 : '<span class="cpf-pendente">sem plano</span>')) + '</td>' : '')
                 + '<td class="acoes">' + acoes + '</td>';
    const btPlano = tr.querySelector('.ac-plano');
    if(btPlano) btPlano.addEventListener('click', () => abrirAssinaturas(u));
    const btCpf = tr.querySelector('.cpf-ver');
    if(btCpf){
      btCpf.addEventListener('click', () => {
        const aberto = btCpf.dataset.aberto === '1';
        btCpf.textContent = aberto ? contaMascararCPF(u.cpf) : contaFormatarCPF(u.cpf);
        btCpf.dataset.aberto = aberto ? '' : '1';
      });
    }

    const ligaDecisao = (sel, status, perfil) => {
      const b = tr.querySelector(sel);
      if(!b) return;
      b.addEventListener('click', async () => {
        b.disabled = true;
        const res = await decidirAcesso(u.id, status, perfil);
        if(res.erro){
          sub.textContent = 'Falha ao gravar a decisão (' + res.detalhe + ').';
          b.disabled = false;
          return;
        }
        await renderizarFilaAcessos();
      });
    };
    ligaDecisao('.ac-aprovar', 'aprovado', 'usuario');
    ligaDecisao('.ac-admin',   'aprovado', 'admin');
    ligaDecisao('.ac-usuario', 'aprovado', 'usuario');
    ligaDecisao('.ac-recusar', 'recusado', null);

    const btnEx = tr.querySelector('.ac-excluir');
    if(btnEx){
      btnEx.addEventListener('click', async () => {
        const ok = confirm('Excluir ' + u.email + ' da fila de acesso?\n\n'
          + 'A pessoa some desta tela e continua sem entrar na plataforma.\n\n'
          + 'A conta permanece no Supabase (Authentication > Users). Para liberar '
          + 'este e-mail para um novo cadastro, apague-a também por lá.');
        if(!ok) return;
        btnEx.disabled = true;
        const res = await excluirAcesso(u.id);
        if(res.erro){
          sub.textContent = 'Falha ao excluir (' + res.detalhe + ').';
          btnEx.disabled = false;
          return;
        }
        await renderizarFilaAcessos();
      });
    }

    tbody.appendChild(tr);
  });

  tab.appendChild(tbody);
  caixa.appendChild(tab);
}

function renderizarListaEquipe(){
  /* v34: planos primeiro (a fila usa _planosOk para mostrar a coluna Plano). */
  renderizarPlanosEquipe().catch(() => {}).finally(() => renderizarFilaAcessos());
  const lista = carregarUsuarios();
  const mestre = ehMestre();
  document.getElementById('equipe-subtitulo').textContent = mestre
    ? 'Você é o admin-mestre — pode promover ou rebaixar qualquer pessoa da lista.'
    : 'Quem tem acesso à administração do site. Só o admin-mestre promove ou rebaixa.';

  const tbody = document.getElementById('equipe-tbody');
  tbody.innerHTML = '';
  lista.forEach(u=>{
    const ehEsteMestre = u.email.toLowerCase() === EMAIL_ADMIN_MESTRE;
    const tr = document.createElement('tr');
    let acoesHtml = '';
    if(mestre && !ehEsteMestre){
      acoesHtml = `<button type="button" class="ac-editar">${u.perfil==='admin' ? 'Tornar usuário' : 'Tornar admin'}</button>`;
    } else if(ehEsteMestre){
      acoesHtml = '<span style="color:var(--ink-soft); font-size:11.5px;">admin-mestre</span>';
    }
    tr.innerHTML = `
      <td>${u.nome}</td>
      <td>${u.email}</td>
      <td>${u.perfil}</td>
      <td class="acoes">${acoesHtml}</td>
    `;
    const btnAcao = tr.querySelector('.ac-editar');
    if(btnAcao){
      btnAcao.addEventListener('click', ()=>{
        alternarPerfilUsuario(u.email);
      });
    }
    tbody.appendChild(tr);
  });
}

function alternarPerfilUsuario(email){
  if(!ehMestre()) return; // só o mestre promove/rebaixa — sem exceção
  if(email.toLowerCase() === EMAIL_ADMIN_MESTRE) return; // mestre nunca muda
  const lista = carregarUsuarios();
  const u = lista.find(x=>x.email.toLowerCase()===email.toLowerCase());
  if(!u) return;
  u.perfil = u.perfil === 'admin' ? 'usuario' : 'admin';
  salvarUsuarios(lista);
  if(sessaoAtual && sessaoAtual.email && sessaoAtual.email.toLowerCase()===email.toLowerCase()){
    sessaoAtual.perfil = u.perfil;
    salvarSessaoAuth(sessaoAtual);
    aplicarVisibilidadeAdmin();
  }
  renderizarListaEquipe();
}

document.getElementById('btn-recarregar-fila').addEventListener('click', ()=>{
  renderizarFilaAcessos();
});

document.getElementById('btn-abrir-convidar').addEventListener('click', ()=>{
  document.getElementById('cv-nome').value = '';
  document.getElementById('cv-email').value = '';
  document.getElementById('cv-admin').checked = false;
  document.getElementById('cv-admin-wrap').style.display = ehMestre() ? 'flex' : 'none';
  document.getElementById('convidar-msg').textContent = '';
  document.getElementById('convidar-overlay').style.display = 'flex';
});
document.getElementById('convidar-cancelar').addEventListener('click', ()=>{
  document.getElementById('convidar-overlay').style.display = 'none';
});
document.getElementById('btn-salvar-convite').addEventListener('click', function(){
  const nome = document.getElementById('cv-nome').value.trim();
  const email = document.getElementById('cv-email').value.trim().toLowerCase();
  const msg = document.getElementById('convidar-msg');
  if(!nome || !email || !email.includes('@')){
    msg.textContent = 'Preencha nome e e-mail válidos.';
    msg.className = 'auth-msg erro';
    return;
  }
  const lista = carregarUsuarios();
  if(lista.some(u=>u.email.toLowerCase()===email)){
    msg.textContent = 'Já existe alguém com esse e-mail na equipe.';
    msg.className = 'auth-msg erro';
    return;
  }
  const comoAdmin = ehMestre() && document.getElementById('cv-admin').checked;
  lista.push({nome, email, perfil: comoAdmin ? 'admin' : 'usuario'});
  salvarUsuarios(lista);
  document.getElementById('convidar-overlay').style.display = 'none';
  renderizarListaEquipe();
});

/* ==========================================================================
   v36 — ÁREAS POR PLANO e CONTA GRATUITA (SQL 34: public.minhas_areas)
   Cada plano libera áreas da plataforma (Grátis = filtro de ações e
   cotações). Com o cadastro aberto ou a exigência de plano ligados, o site
   mostra "Disponível nos planos pagos" no lugar da área não contratada.
   Com as chaves desligadas (ou sem o SQL 34, ou sem rede), nada é
   bloqueado: o servidor responde "tudo".
   Leilões, mercado imobiliário, empresas, calculadoras e gestão guardam os
   dados no próprio navegador; o bloqueio dessas áreas é da tela.
   ========================================================================== */
var AREAS_PLANO = [
  ['filtro_acoes', 'Filtro de ações e cotações'],
  ['artigos', 'Artigos técnicos (todos)'],
  ['cursos_livres', 'Cursos livres (todos)'],
  ['noticias', 'Notícias'],
  ['calculadoras', 'Calculadoras'],
  ['mercado_financeiro', 'Mercado financeiro completo'],
  ['relatorios', 'Relatórios de empresas'],
  ['relatorios_analise', 'Relatórios de Análise SOLIDUNS'],
  ['leiloes', 'Leilões de imóveis'],
  ['mercado_imobiliario', 'Mercado imobiliário'],
  ['avaliacao_imoveis', 'Avaliação de imóveis (laudos)'],   /* v83-AVA */
  ['empresas', 'Compra e venda de empresas'],
  ['gestao_financeira', 'Gestão financeira'],
  ['gestao_fiscal', 'Gestão fiscal']
];
var AREA_DO_PAINEL = {'acoes':'filtro_acoes', 'leilao':'leiloes', 'leilao-veiculos':'leiloes', 'avaliacao-imoveis':'avaliacao_imoveis', 'mercado-imobiliario':'mercado_imobiliario',
                      'empresas':'empresas', 'calculadoras':'calculadoras'};
var _areas = null;              /* {tudo, areas:Set, exige, livre, em, dono} */
var _areasPromessa = null;

function areaRotulo(cod){
  const a = AREAS_PLANO.find(x => x[0] === cod);
  return a ? a[1] : cod;
}
function areasLimpar(){ _areas = null; _areasPromessa = null; }

async function areasCarregar(){
  if(!sessaoAtual || sessaoAtual.modoLocal) return null;
  const dono = (sessaoAtual.user && sessaoAtual.user.id) || null;
  if(_areas && _areas.dono === dono && Date.now() - _areas.em < 5 * 60 * 1000) return _areas;
  if(!_areasPromessa){
    _areasPromessa = (async () => {
      const token = await contaTokenValido();
      if(!token) return null;
      try{
        const r = await fetch(SUPABASE_URL + '/rest/v1/rpc/minhas_areas', {
          method: 'POST',
          headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token,
                    'Content-Type': 'application/json', 'Accept': 'application/json'},
          body: '{}'
        });
        if(!r.ok) return null;
        const j = await r.json().catch(() => null);
        if(!j || typeof j !== 'object') return null;
        _areas = {tudo: !!j.tudo, areas: new Set(Array.isArray(j.areas) ? j.areas : []),
                  exige: !!j.exige_plano, livre: !!j.cadastro_livre, em: Date.now(), dono};
        return _areas;
      }catch(e){ return null; }
    })().finally(() => { _areasPromessa = null; });
  }
  return _areasPromessa;
}

/* Sem resposta do servidor = liberado (o servidor protege o que é dele). */
function areaLiberada(cod){
  if(!cod || !_areas || _areas.tudo) return true;
  const dono = sessaoAtual && sessaoAtual.user && sessaoAtual.user.id;
  if(_areas.dono !== dono) return true;
  return _areas.areas.has(cod);
}

function areaHtmlBloqueio(cod){
  return `<div class="area-bloqueio">
      <span class="area-bloqueio-selo">Planos pagos</span>
      <h2>${escHtml(areaRotulo(cod))}</h2>
      <p>Esta área não faz parte do seu plano atual. Na conta gratuita estão liberados o filtro de ações e as cotações,
         além dos cursos livres e artigos técnicos marcados como gratuitos.</p>
      <p>Veja o seu plano em <a href="#" data-area-conta="1">Minha conta</a> ou escreva para
         <a href="mailto:contato@soliduns.com.br">contato@soliduns.com.br</a> para contratar.</p>
    </div>`;
}
function areaLigarLinks(raiz){
  raiz.querySelectorAll('[data-area-conta]').forEach(a => a.addEventListener('click', ev => { ev.preventDefault(); abrirConta('plano'); }));
}

/* Painel inteiro bloqueado (Leilão, Imobiliário, Empresas, Calculadoras, Gestão). */
function areaMostrarBloqueio(cod){
  const caixa = document.getElementById('plano-bloqueado-conteudo');
  if(!caixa) return;
  caixa.innerHTML = areaHtmlBloqueio(cod);
  areaLigarLinks(caixa);
  if(document.getElementById('tela-dashboard').style.display === 'none') mostrarTela('dashboard');
  window.mostrarPainelDash('plano-bloqueado');
  setTituloPagina(areaRotulo(cod), 'Disponível nos planos pagos');
}

/* Dentro do Mercado financeiro: usa a mesma caixa do "em implantação". */
function mfMostrarBloqueio(chaveMenu, cod){
  relEsconder();   /* v42 */
  relAlternarScreener(false);   /* v45 */
  const p = document.getElementById('mf-painel-implantacao');
  document.getElementById('mf-conteudo-padrao').style.display = 'none';
  p.innerHTML = areaHtmlBloqueio(cod);
  areaLigarLinks(p);
  p.style.display = 'block';
  marcarItemAtivoMF(chaveMenu || null);
  fecharTodosDropdownsMF();
}

/* Selo nos menus e nos cartões das áreas fora do plano. */
function areasMarcarMenus(){
  const marcar = (el, cod) => {
    if(!el) return;
    const fora = !areaLiberada(cod);
    el.classList.toggle('area-fora-plano', fora);
    if(fora) el.setAttribute('data-area-selo', 'Planos pagos'); else el.removeAttribute('data-area-selo');
  };
  document.querySelectorAll('#painel-investimentos-escolha .escolha-card[data-painel]').forEach(c => marcar(c, AREA_DO_PAINEL[c.getAttribute('data-painel')]));
  ['dash', ''].forEach(suf => {
    marcar(document.getElementById('item-calculadoras' + (suf ? '-' + suf : '')), 'calculadoras');
    marcar(document.getElementById('item-financeira' + (suf ? '-' + suf : '')), 'gestao_financeira');
    marcar(document.getElementById('item-fiscal' + (suf ? '-' + suf : '')), 'gestao_fiscal');
  });
  raMenu();   /* v65 */
}

/* Botão "Mercado americano": parte do mercado financeiro completo. */
document.addEventListener('click', ev => {
  const b = ev.target.closest && ev.target.closest('[data-mercado-set="us"]');
  if(b && !areaLiberada('mercado_financeiro')){
    ev.stopImmediatePropagation(); ev.preventDefault();
    mfMostrarBloqueio('internacional', 'mercado_financeiro');
  }
}, true);

/* =====================================================================
   v34 — PLANOS E ASSINATURAS (SQL 31), só para o administrador do SISTEMA.
   Tabelas: public.planos, public.planos_cursos, public.assinaturas e
   public.regras_acesso (chave educacao_exige_plano). As políticas RLS do
   banco são a proteção real: quem não é public.eh_admin() não grava nada,
   mesmo chamando a API direto.
   Enquanto a chave estiver DESLIGADA, todo aprovado estuda todos os cursos
   (regra de antes). Ligada: cada um estuda só os cursos do plano vigente;
   Premium ("libera toda a plataforma") = todos; administrador = todos.
   O resumo do plano (nome e validade) é copiado pelo banco para
   acessos.plano/plano_validade, que a "Minha conta" já mostra.
   ===================================================================== */
var _planosOk = false;          /* SQL 31 presente e lido */
var _planos = [];               /* todos os planos (admin lê também os inativos) */
var _planosCursosMapa = {};     /* plano_id -> [curso_id] */
var _eduCursosLista = [];       /* [{id, slug, titulo}] */
var _assinaturasTodas = [];     /* para contar quem está sem plano */
var _regraExigePlano = null;    /* true / false / null (desconhecida) */
var _regraCadastroLivre = null; /* v36 (SQL 34) */
var _planosNovasColunas = false; /* v36: SQL 34 executado */
var _eduEntidades = [];
var _cursoEntidade = {};
var PLANO_PERIODICIDADES = {mensal:'Mensal', trimestral:'Trimestral', semestral:'Semestral', anual:'Anual', unico:'Pagamento único'};

async function planosApi(metodo, caminho, corpo, extras){
  const token = await contaTokenValido();
  if(!token) return {ok:false, status:401, erro:'Sua sessão expirou. Saia e entre novamente.'};
  const headers = {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Accept': 'application/json'};
  if(corpo !== undefined){ headers['Content-Type'] = 'application/json'; }
  if(metodo !== 'GET'){ headers['Prefer'] = 'return=representation'; }
  Object.assign(headers, extras || {});
  let r;
  try{
    r = await fetch(SUPABASE_URL + '/rest/v1/' + caminho, {method: metodo, headers,
      body: corpo !== undefined ? JSON.stringify(corpo) : undefined});
  }catch(e){ return {ok:false, status:0, erro:'Sem conexão com o servidor. Verifique sua internet.'}; }
  const dados = await r.json().catch(() => null);
  if(!r.ok){
    const msg = dados && (dados.message || dados.hint || '') || '';
    let erro = 'O servidor recusou (status ' + r.status + ').';
    if(r.status === 401) erro = 'Sua sessão expirou. Saia e entre novamente.';
    else if(r.status === 404 || /does not exist|schema cache/i.test(msg)) erro = 'As tabelas de planos ainda não existem no banco (rode o SQL 31).';
    else if(r.status === 403 || /row-level security/i.test(msg)) erro = 'Sem permissão: só o administrador do sistema altera planos.';
    else if(/duplicate key|unique/i.test(msg)) erro = 'Já existe um plano com esse identificador.';
    else if(/validade_depois_do_inicio/i.test(msg)) erro = 'A validade não pode ser anterior ao início.';
    return {ok:false, status:r.status, erro, detalhe: msg};
  }
  return {ok:true, status:r.status, dados};
}

function planoHojeISO(){
  /* Data de hoje em Brasília, no formato AAAA-MM-DD (o banco usa o mesmo fuso). */
  const p = new Intl.DateTimeFormat('en-CA', {timeZone:'America/Sao_Paulo', year:'numeric', month:'2-digit', day:'2-digit'}).format(new Date());
  return p;
}
function planoSomarDias(iso, dias){
  const [a, m, d] = iso.split('-').map(Number);
  const dt = new Date(Date.UTC(a, m - 1, d + dias));
  return dt.toISOString().slice(0, 10);
}
function planoVigente(s, hoje){
  return s.status === 'ativa' && s.inicio <= hoje && (!s.validade || s.validade >= hoje);
}
function planoPreco(v){
  if(v === null || v === undefined || v === '') return '—';
  return Number(v).toLocaleString('pt-BR', {style:'currency', currency:'BRL'});
}
function planoSlug(nome){
  return String(nome || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40);
}
function planoNome(id){
  const p = _planos.find(x => x.id === id);
  return p ? p.nome : '(plano removido)';
}

async function carregarPlanosEquipe(){
  const [rp, rpc, rc, rr, ra] = await Promise.all([
    planosApi('GET', 'planos?select=*&order=ordem.asc,nome.asc'),
    planosApi('GET', 'planos_cursos?select=plano_id,curso_id'),
    eduBuscar('cursos?select=id,slug,titulo,ordem,certificacao_id&order=ordem.asc,titulo.asc').then(d => ({ok:true, dados:d})).catch(() => ({ok:false})),
    planosApi('GET', 'regras_acesso?select=chave,valor&chave=in.(educacao_exige_plano,cadastro_livre)'),
    planosApi('GET', 'assinaturas?select=id,user_id,plano_id,inicio,validade,status')
  ]);
  if(!rp.ok) return {erro: rp.erro};
  _planos = Array.isArray(rp.dados) ? rp.dados : [];
  _planosCursosMapa = {};
  (rpc.ok && Array.isArray(rpc.dados) ? rpc.dados : []).forEach(x => {
    (_planosCursosMapa[x.plano_id] = _planosCursosMapa[x.plano_id] || []).push(x.curso_id);
  });
  _eduCursosLista = rc.ok && Array.isArray(rc.dados) ? rc.dados : [];
  const regra = ch => { const x = rr.ok && Array.isArray(rr.dados) ? rr.dados.find(y => y.chave === ch) : null; return x ? !!x.valor : null; };
  _regraExigePlano = regra('educacao_exige_plano');
  _regraCadastroLivre = regra('cadastro_livre');
  /* v36: colunas do SQL 34 (todos_cursos, entidades, areas) */
  if(_planos.length) _planosNovasColunas = Object.prototype.hasOwnProperty.call(_planos[0], 'areas');
  else { const pr = await planosApi('GET', 'planos?select=areas&limit=1'); _planosNovasColunas = pr.ok; }
  _eduEntidades = []; _cursoEntidade = {};
  try{
    const certIds = Array.from(new Set(_eduCursosLista.map(c => c.certificacao_id).filter(Boolean)));
    const [certs, ents] = await Promise.all([
      certIds.length ? eduBuscar('certificacoes?select=id,entidade_id&id=in.(' + certIds.map(encodeURIComponent).join(',') + ')') : Promise.resolve([]),
      eduBuscar('entidades_certificadoras?select=id,sigla,nome&order=sigla.asc')]);
    const certEnt = {}; certs.forEach(c => { certEnt[c.id] = c.entidade_id; });
    _eduCursosLista.forEach(c => { if(c.certificacao_id) _cursoEntidade[c.id] = certEnt[c.certificacao_id]; });
    _eduEntidades = ents;
  }catch(e){ /* sem a lista, o formulário mostra só as entidades já marcadas */ }
  _assinaturasTodas = ra.ok && Array.isArray(ra.dados) ? ra.dados : [];
  return {ok: true};
}

async function renderizarPlanosEquipe(){
  const caixa = document.getElementById('planos-lista');
  const regra = document.getElementById('planos-regra');
  if(!caixa || !regra) return;
  if(!sessaoAtual || sessaoAtual.modoLocal){
    _planosOk = false;
    regra.innerHTML = ''; caixa.innerHTML = '<div class="leilao-ficha-sub">Indisponível em modo local: os planos vivem no servidor.</div>';
    return;
  }
  regra.innerHTML = ''; caixa.innerHTML = '<div class="leilao-ficha-sub">Carregando planos…</div>';
  const r = await carregarPlanosEquipe();
  if(r.erro){
    _planosOk = false;
    caixa.innerHTML = '<div class="leilao-ficha-sub">Não foi possível carregar os planos: ' + escHtml(r.erro) + '</div>';
    document.getElementById('btn-novo-plano').disabled = true;
    return;
  }
  _planosOk = true;
  document.getElementById('btn-novo-plano').disabled = false;
  desenharRegraPlanos();

  if(_planos.length === 0){
    caixa.innerHTML = '<div class="leilao-ficha-sub">Nenhum plano cadastrado. Use "+ Novo plano".</div>';
    return;
  }
  const hoje = planoHojeISO();
  const nomeCurso = id => { const c = _eduCursosLista.find(x => x.id === id); return c ? (c.titulo || c.slug) : '?'; };
  const linhas = _planos.map(p => {
    let cursos = p.libera_tudo ? '<span class="plano-tag-premium">Toda a plataforma</span>'
      : ((_planosCursosMapa[p.id] || []).map(nomeCurso).map(escHtml).join(', ') || '<span class="cpf-pendente">nenhum curso</span>');
    if(!p.libera_tudo && _planosNovasColunas){
      const extras = [];
      if(p.todos_cursos) extras.push('todas as certificações, inclusive futuras');
      else if(Array.isArray(p.entidades) && p.entidades.length){
        const sig = p.entidades.map(id => { const e = _eduEntidades.find(x => x.id === id); return e ? e.sigla : id; });
        extras.push('todos os cursos ' + sig.join(', ') + ', inclusive futuros');
      }
      if(extras.length) cursos += '<div class="plano-slug">+ ' + escHtml(extras.join('; ')) + '</div>';
      if(Array.isArray(p.areas) && p.areas.length) cursos += '<div class="plano-slug">Áreas: ' + escHtml(p.areas.map(areaRotulo).join(', ')) + '</div>';
    }
    const vig = _assinaturasTodas.filter(s => s.plano_id === p.id && planoVigente(s, hoje)).length;
    return '<tr data-id="' + escHtml(p.id) + '">'
      + '<td><strong>' + escHtml(p.nome) + '</strong><div class="plano-slug">' + escHtml(p.slug) + '</div></td>'
      + '<td>' + planoPreco(p.preco) + '<div class="plano-slug">' + escHtml(PLANO_PERIODICIDADES[p.periodicidade] || p.periodicidade) + (p.validade_dias ? ' · ' + p.validade_dias + ' dias' : '') + '</div></td>'
      + '<td>' + cursos + '</td>'
      + '<td>' + vig + '</td>'
      + '<td>' + (p.ativo ? 'Ativo' : '<span class="cpf-pendente">Inativo</span>') + '</td>'
      + '<td class="acoes"><button type="button" class="ac-editar ac-plano-editar">Editar</button></td></tr>';
  }).join('');
  caixa.innerHTML = '<table class="leilao-admin-table"><thead><tr><th>Plano</th><th>Preço</th><th>Libera</th><th>Assinantes</th><th>Situação</th><th></th></tr></thead><tbody>' + linhas + '</tbody></table>';
  caixa.querySelectorAll('.ac-plano-editar').forEach(b => {
    b.addEventListener('click', () => abrirFormPlano(b.closest('tr').dataset.id));
  });
}

function desenharRegraPlanos(){
  const regra = document.getElementById('planos-regra');
  desenharRegraPlanosExigencia();
  if(_regraCadastroLivre === null) return;
  const livre = _regraCadastroLivre;
  const caixa = document.createElement('div');
  caixa.className = 'planos-regra-caixa' + (livre ? ' ligada' : '');
  caixa.innerHTML = '<div><strong>Cadastro aberto (conta gratuita sem aprovação): ' + (livre ? 'LIGADO' : 'DESLIGADO') + '</strong>'
    + '<span>' + (livre
        ? 'Quem confirma o e-mail já entra com o plano Grátis. A fila virou lista de contas: use Bloquear para impedir alguém.'
        : 'Cada cadastro novo espera a sua aprovação na fila (regra de hoje).')
    + '</span></div><button type="button" class="btn-leilao-admin" id="btn-cadastro-livre">' + (livre ? 'Desligar' : 'Ligar') + '</button>';
  regra.appendChild(caixa);
  document.getElementById('btn-cadastro-livre').addEventListener('click', alternarCadastroLivre);
}

async function alternarCadastroLivre(){
  const ligar = !_regraCadastroLivre;
  let texto;
  if(ligar){
    const fila = await carregarFilaAcessos();
    const hoje = planoHojeISO();
    const pagos = new Set(_assinaturasTodas.filter(s => planoVigente(s, hoje) && Number((_planos.find(p => p.id === s.plano_id) || {}).preco) > 0).map(s => s.user_id));
    const semPago = (fila.lista || []).filter(u => u.status === 'aprovado' && u.perfil !== 'admin' && !pagos.has(u.id));
    const pend = (fila.lista || []).filter(u => u.status === 'pendente');
    texto = 'LIGAR o cadastro aberto?\n\nQuem confirmar o e-mail entra na hora, com o plano Grátis (filtro de ações e cotações).\n'
      + 'A exigência de plano é ligada junto: cada conta passa a ver só o que o próprio plano libera.\n\n'
      + (fila.erro ? 'Não foi possível conferir a fila agora.' :
          (pend.length ? pend.length + ' cadastro(s) pendente(s) serão liberados agora.\n' : '')
          + semPago.length + ' conta(s) liberada(s) SEM plano pago ficam só com o Grátis'
          + (semPago.length ? ':\n' + semPago.slice(0, 15).map(u => '• ' + (u.nome || u.email)).join('\n') + (semPago.length > 15 ? '\n…' : '') : '.'))
      + '\n\nAdministradores continuam com tudo.';
  } else {
    texto = 'DESLIGAR o cadastro aberto?\n\nCadastros novos voltam a esperar aprovação na fila. Quem já entrou continua com a conta como está.';
  }
  if(!confirm(texto)) return;
  const b = document.getElementById('btn-cadastro-livre');
  b.disabled = true;
  let r;
  try{
    const token = await contaTokenValido();
    r = await fetch(SUPABASE_URL + '/rest/v1/rpc/definir_cadastro_livre', {
      method: 'POST',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json', 'Accept': 'application/json'},
      body: JSON.stringify({p_ligar: ligar})
    });
  }catch(e){ r = null; }
  b.disabled = false;
  if(!r || !r.ok){
    alert('Não foi possível alterar o cadastro aberto' + (r ? ' (status ' + r.status + ').' : ': sem conexão.') + ' Só o administrador do sistema altera.');
    return;
  }
  eduMeusLimpar(); areasLimpar();
  await renderizarPlanosEquipe();
  renderizarFilaAcessos();
}

function desenharRegraPlanosExigencia(){
  const regra = document.getElementById('planos-regra');
  if(_regraExigePlano === null){
    regra.innerHTML = '<div class="planos-regra-caixa">Não foi possível ler a regra de exigência de plano.</div>';
    return;
  }
  const ligada = _regraExigePlano || _regraCadastroLivre === true;
  regra.innerHTML = '<div class="planos-regra-caixa ' + (ligada ? 'ligada' : '') + '">'
    + '<div><strong>Exigência de plano: ' + (ligada ? 'LIGADA' : 'DESLIGADA') + (_regraCadastroLivre && !_regraExigePlano ? ' (pelo cadastro aberto)' : '') + '</strong>'
    + '<span>' + (ligada
        ? 'Cada conta vê só os cursos e as áreas do próprio plano (GOLD = tudo). Administradores veem tudo.'
        : 'Toda conta liberada na fila vê todos os cursos e áreas, com ou sem plano (regra provisória).')
    + '</span></div>'
    + (_regraCadastroLivre ? '' : '<button type="button" class="btn-leilao-admin" id="btn-regra-plano">' + (ligada ? 'Desligar' : 'Ligar') + '</button>') + '</div>';
  const bt = document.getElementById('btn-regra-plano');
  if(bt) bt.addEventListener('click', alternarRegraPlano);
}

async function alternarRegraPlano(){
  const btn = document.getElementById('btn-regra-plano');
  const ligar = !_regraExigePlano;
  let texto;
  if(ligar){
    /* Conta quem perderia o acesso: liberado, não administrador e sem plano vigente. */
    const fila = await carregarFilaAcessos();
    const hoje = planoHojeISO();
    const comPlano = new Set(_assinaturasTodas.filter(s => planoVigente(s, hoje)).map(s => s.user_id));
    const semPlano = (fila.lista || []).filter(u => u.status === 'aprovado' && u.perfil !== 'admin' && !comPlano.has(u.id));
    texto = 'LIGAR a exigência de plano?\n\nA partir de agora, cada usuário só estuda os cursos do próprio plano.\n\n'
      + (fila.erro ? 'Não foi possível conferir a fila agora.'
         : semPlano.length + ' usuário(s) liberado(s) estão SEM plano vigente e deixam de ver as apostilas, as questões e os simulados'
           + (semPlano.length ? ':\n' + semPlano.slice(0, 15).map(u => '• ' + (u.nome || u.email)).join('\n') + (semPlano.length > 15 ? '\n…' : '') : '.'))
      + '\n\nAdministradores continuam com tudo. Dá para desligar a qualquer momento.';
  } else {
    texto = 'DESLIGAR a exigência de plano?\n\nTodo usuário liberado na fila volta a estudar todos os cursos, com ou sem plano.';
  }
  if(!confirm(texto)) return;
  btn.disabled = true;
  const r = await planosApi('PATCH', 'regras_acesso?chave=eq.educacao_exige_plano', {valor: ligar});
  btn.disabled = false;
  if(!r.ok || !Array.isArray(r.dados) || !r.dados.length){
    alert('Não foi possível alterar a regra. ' + (r.erro || 'Sem permissão: só o administrador do sistema altera.'));
    return;
  }
  _regraExigePlano = !!r.dados[0].valor;
  eduMeusLimpar(); areasLimpar();
  desenharRegraPlanos();
}

/* ---------- Formulário de plano (novo / editar) ---------- */
var _planoEditando = null;
function abrirFormPlano(id){
  _planoEditando = id ? _planos.find(p => p.id === id) : null;
  const p = _planoEditando || {nome:'', slug:'', descricao:'', preco:'', periodicidade:'mensal', validade_dias:30, libera_tudo:false, ativo:true, ordem:0};
  document.getElementById('plano-form-titulo').textContent = _planoEditando ? 'Editar plano' : 'Novo plano';
  document.getElementById('pl-nome').value = p.nome || '';
  const slug = document.getElementById('pl-slug');
  slug.value = p.slug || '';
  slug.readOnly = !!_planoEditando;
  slug.dataset.manual = _planoEditando ? '1' : '';
  document.getElementById('pl-descricao').value = p.descricao || '';
  document.getElementById('pl-preco').value = (p.preco === null || p.preco === undefined || p.preco === '') ? '' : Number(p.preco).toFixed(2).replace('.', ',');
  document.getElementById('pl-periodicidade').value = p.periodicidade || 'mensal';
  document.getElementById('pl-dias').value = p.validade_dias || '';
  document.getElementById('pl-premium').checked = !!p.libera_tudo;
  document.getElementById('pl-ativo').checked = p.ativo !== false;
  document.getElementById('pl-ordem').value = p.ordem || 0;
  const marcados = new Set(_planoEditando ? (_planosCursosMapa[_planoEditando.id] || []) : []);
  const box = document.getElementById('pl-cursos');
  box.innerHTML = _eduCursosLista.length
    ? _eduCursosLista.map(c => '<label class="plano-curso-op"><input type="checkbox" value="' + escHtml(c.id) + '"' + (marcados.has(c.id) ? ' checked' : '') + '> ' + escHtml(c.titulo || c.slug) + '</label>').join('')
    : '<div class="leilao-ficha-sub">Não foi possível ler a lista de cursos.</div>';
  /* v36: regras do SQL 34 */
  document.getElementById('pl-regras-novas').hidden = !_planosNovasColunas;
  document.getElementById('pl-areas-bloco').hidden = !_planosNovasColunas;
  document.getElementById('pl-todos-cursos').checked = !!p.todos_cursos;
  const entsMarcadas = new Set(Array.isArray(p.entidades) ? p.entidades : []);
  const entsComCurso = new Set(Object.values(_cursoEntidade).filter(Boolean));
  const entsMostrar = _eduEntidades.filter(e => entsComCurso.has(e.id) || entsMarcadas.has(e.id));
  entsMarcadas.forEach(id => { if(!entsMostrar.find(e => e.id === id)) entsMostrar.push({id, sigla: id}); });
  document.getElementById('pl-entidades').innerHTML = entsMostrar.length
    ? entsMostrar.map(e => '<label class="plano-curso-op"><input type="checkbox" value="' + escHtml(e.id) + '"' + (entsMarcadas.has(e.id) ? ' checked' : '') + '> ' + escHtml(e.sigla) + '</label>').join('')
    : '<div class="leilao-ficha-sub">Nenhuma entidade com curso cadastrado.</div>';
  const areasMarc = new Set(Array.isArray(p.areas) ? p.areas : (_planoEditando ? [] : ['filtro_acoes']));
  document.getElementById('pl-areas').innerHTML = AREAS_PLANO.map(a => '<label class="plano-curso-op"><input type="checkbox" value="' + a[0] + '"' + (areasMarc.has(a[0]) ? ' checked' : '') + '> ' + escHtml(a[1]) + '</label>').join('');
  planoAtualizarPremium();
  contaMsg('plano-msg', '');
  document.getElementById('plano-overlay').style.display = 'flex';
  setTimeout(() => { try{ document.getElementById('pl-nome').focus(); }catch(e){} }, 50);
}
function planoAtualizarPremium(){
  const premium = document.getElementById('pl-premium').checked;
  const todos = premium || document.getElementById('pl-todos-cursos').checked;
  document.querySelectorAll('#pl-cursos input, #pl-entidades input').forEach(i => { i.disabled = todos; });
  document.getElementById('pl-cursos').classList.toggle('desativado', todos);
  document.getElementById('pl-entidades').classList.toggle('desativado', todos);
  document.getElementById('pl-todos-cursos').disabled = premium;
  document.querySelectorAll('#pl-areas input').forEach(i => { i.disabled = premium; });
  document.getElementById('pl-areas').classList.toggle('desativado', premium);
}

async function salvarPlano(){
  const btn = document.getElementById('btn-salvar-plano');
  const nome = document.getElementById('pl-nome').value.trim();
  const slug = document.getElementById('pl-slug').value.trim();
  const precoTxt = document.getElementById('pl-preco').value.trim().replace(/\./g, '').replace(',', '.');
  const dias = document.getElementById('pl-dias').value.trim();
  const premium = document.getElementById('pl-premium').checked;
  const cursos = Array.from(document.querySelectorAll('#pl-cursos input:checked')).map(i => i.value);
  if(!nome){ contaMsg('plano-msg', 'Informe o nome do plano.', 'erro'); return; }
  if(!/^[a-z0-9-]+$/.test(slug)){ contaMsg('plano-msg', 'Identificador: só letras minúsculas sem acento, números e hífen.', 'erro'); return; }
  if(precoTxt && !(Number(precoTxt) >= 0)){ contaMsg('plano-msg', 'Preço inválido. Exemplo: 49,90', 'erro'); return; }
  if(dias && !(Number.isInteger(Number(dias)) && Number(dias) > 0)){ contaMsg('plano-msg', 'Validade sugerida: número inteiro de dias (ou deixe vazio para "sem prazo").', 'erro'); return; }
  const todosCursos = _planosNovasColunas && document.getElementById('pl-todos-cursos').checked;
  const entidades = _planosNovasColunas ? Array.from(document.querySelectorAll('#pl-entidades input:checked')).map(i => i.value) : [];
  const areas = _planosNovasColunas ? Array.from(document.querySelectorAll('#pl-areas input:checked')).map(i => i.value) : [];
  if(!premium && !todosCursos && !entidades.length && cursos.length === 0 && !areas.length && !confirm('Este plano não libera nenhum curso nem área. Salvar assim mesmo?')) return;

  const corpo = {
    nome, descricao: document.getElementById('pl-descricao').value.trim() || null,
    preco: precoTxt ? Number(precoTxt) : null,
    periodicidade: document.getElementById('pl-periodicidade').value,
    validade_dias: dias ? Number(dias) : null,
    libera_tudo: premium,
    ativo: document.getElementById('pl-ativo').checked,
    ordem: Number(document.getElementById('pl-ordem').value) || 0
  };
  if(_planosNovasColunas){ corpo.todos_cursos = todosCursos; corpo.entidades = entidades; corpo.areas = areas; }
  btn.disabled = true;
  contaMsg('plano-msg', 'Salvando...');
  let r;
  if(_planoEditando){
    r = await planosApi('PATCH', 'planos?id=eq.' + encodeURIComponent(_planoEditando.id), corpo);
  } else {
    corpo.slug = slug;
    r = await planosApi('POST', 'planos', corpo);
  }
  if(!r.ok || !Array.isArray(r.dados) || !r.dados.length){
    btn.disabled = false;
    contaMsg('plano-msg', r.erro || 'Sem permissão: só o administrador do sistema altera planos.', 'erro');
    return;
  }
  const planoId = r.dados[0].id;
  /* Cursos do plano: remove os desmarcados e acrescenta os novos.
     Premium não precisa de lista (libera tudo), mas a lista é mantida. */
  const antes = new Set(_planosCursosMapa[planoId] || []);
  const sair = Array.from(antes).filter(id => !cursos.includes(id));
  const entrar = cursos.filter(id => !antes.has(id));
  let falha = '';
  if(sair.length){
    const rd = await planosApi('DELETE', 'planos_cursos?plano_id=eq.' + encodeURIComponent(planoId) + '&curso_id=in.(' + sair.map(encodeURIComponent).join(',') + ')');
    if(!rd.ok) falha = rd.erro;
  }
  if(entrar.length && !falha){
    const ri = await planosApi('POST', 'planos_cursos?on_conflict=plano_id,curso_id',
      entrar.map(id => ({plano_id: planoId, curso_id: id})), {'Prefer': 'return=representation,resolution=ignore-duplicates'});
    if(!ri.ok) falha = ri.erro;
  }
  btn.disabled = false;
  if(falha){
    contaMsg('plano-msg', 'O plano foi salvo, mas os cursos não: ' + falha + ' Clique em Salvar de novo.', 'erro');
    _planoEditando = r.dados[0];
    await carregarPlanosEquipe();
    return;
  }
  document.getElementById('plano-overlay').style.display = 'none';
  eduMeusLimpar();
  await renderizarPlanosEquipe();
  renderizarFilaAcessos();
}

/* ---------- Assinaturas de um usuário ---------- */
var _assinUsuario = null;
async function abrirAssinaturas(u){
  _assinUsuario = u;
  document.getElementById('assin-titulo').textContent = 'Plano de ' + (u.nome || u.email);
  document.getElementById('assin-email').textContent = u.email || '';
  const sel = document.getElementById('as-plano');
  const ativos = _planos.filter(p => p.ativo);
  sel.innerHTML = ativos.length
    ? ativos.map(p => '<option value="' + escHtml(p.id) + '">' + escHtml(p.nome) + (p.libera_tudo ? ' (toda a plataforma)' : '') + '</option>').join('')
    : '<option value="">Nenhum plano ativo — cadastre um plano primeiro</option>';
  document.getElementById('as-inicio').value = planoHojeISO();
  document.getElementById('as-sem-prazo').checked = false;
  document.getElementById('as-origem').value = 'manual';
  document.getElementById('as-obs').value = '';
  assinSugerirValidade();
  document.getElementById('btn-salvar-assin').disabled = !ativos.length;
  contaMsg('assin-msg', '');
  document.getElementById('assin-overlay').style.display = 'flex';
  await desenharAssinaturasUsuario();
}

function assinSugerirValidade(){
  const p = _planos.find(x => x.id === document.getElementById('as-plano').value);
  const inicio = document.getElementById('as-inicio').value || planoHojeISO();
  const semPrazo = !p || !p.validade_dias;
  document.getElementById('as-sem-prazo').checked = semPrazo;
  document.getElementById('as-validade').value = semPrazo ? '' : planoSomarDias(inicio, p.validade_dias - 1);
  document.getElementById('as-validade').disabled = semPrazo;
}

async function desenharAssinaturasUsuario(){
  const caixa = document.getElementById('assin-lista');
  caixa.innerHTML = '<div class="leilao-ficha-sub">Carregando…</div>';
  const r = await planosApi('GET', 'assinaturas?select=*&user_id=eq.' + encodeURIComponent(_assinUsuario.id) + '&order=criado_em.desc');
  if(!r.ok){ caixa.innerHTML = '<div class="leilao-ficha-sub">Não foi possível carregar: ' + escHtml(r.erro) + '</div>'; return; }
  const lista = Array.isArray(r.dados) ? r.dados : [];
  if(!lista.length){ caixa.innerHTML = '<div class="leilao-ficha-sub">Nenhum plano dado a esta pessoa ainda.</div>'; return; }
  const hoje = planoHojeISO();
  const origens = {manual:'Manual', cortesia:'Cortesia', pagamento:'Pagamento'};
  caixa.innerHTML = '<table class="leilao-admin-table"><thead><tr><th>Plano</th><th>Início</th><th>Validade</th><th>Situação</th><th></th></tr></thead><tbody>'
    + lista.map(s => {
        let sit;
        if(s.status === 'cancelada') sit = '<span class="cpf-pendente">Cancelada</span>';
        else if(s.inicio > hoje) sit = 'Começa em ' + contaDataBR(s.inicio);
        else if(s.validade && s.validade < hoje) sit = '<span class="cpf-pendente">Vencida</span>';
        else sit = '<span class="plano-vigente">Vigente</span>';
        return '<tr data-id="' + escHtml(s.id) + '"><td>' + escHtml(planoNome(s.plano_id))
          + '<div class="plano-slug">' + escHtml(origens[s.origem] || s.origem) + (s.observacao ? ' · ' + escHtml(s.observacao) : '') + '</div></td>'
          + '<td>' + contaDataBR(s.inicio) + '</td><td>' + (s.validade ? contaDataBR(s.validade) : 'Sem prazo') + '</td><td>' + sit + '</td>'
          + '<td class="acoes">' + (s.status === 'ativa' ? '<button type="button" class="ac-editar ac-assin-cancelar">Cancelar</button>' : '') + '</td></tr>';
      }).join('') + '</tbody></table>';
  caixa.querySelectorAll('.ac-assin-cancelar').forEach(b => {
    b.addEventListener('click', async () => {
      const id = b.closest('tr').dataset.id;
      if(!confirm('Cancelar este plano de ' + (_assinUsuario.nome || _assinUsuario.email) + '?\n\nO histórico fica guardado. Com a exigência de plano ligada, a pessoa perde na hora os cursos que só este plano liberava.')) return;
      b.disabled = true;
      const rc = await planosApi('PATCH', 'assinaturas?id=eq.' + encodeURIComponent(id), {status: 'cancelada'});
      if(!rc.ok || !Array.isArray(rc.dados) || !rc.dados.length){
        b.disabled = false;
        contaMsg('assin-msg', rc.erro || 'Sem permissão para cancelar.', 'erro');
        return;
      }
      contaMsg('assin-msg', 'Plano cancelado.', 'ok');
      await assinRecarregarTudo();
    });
  });
}

async function assinRecarregarTudo(){
  await desenharAssinaturasUsuario();
  await carregarPlanosEquipe();
  await renderizarPlanosEquipe();
  renderizarFilaAcessos();
}

async function salvarAssinatura(){
  const btn = document.getElementById('btn-salvar-assin');
  const plano = document.getElementById('as-plano').value;
  const inicio = document.getElementById('as-inicio').value;
  const semPrazo = document.getElementById('as-sem-prazo').checked;
  const validade = semPrazo ? null : document.getElementById('as-validade').value;
  if(!plano){ contaMsg('assin-msg', 'Escolha um plano.', 'erro'); return; }
  if(!/^\d{4}-\d{2}-\d{2}$/.test(inicio)){ contaMsg('assin-msg', 'Informe a data de início.', 'erro'); return; }
  if(!semPrazo && !/^\d{4}-\d{2}-\d{2}$/.test(validade || '')){ contaMsg('assin-msg', 'Informe a validade ou marque "Sem prazo".', 'erro'); return; }
  if(validade && validade < inicio){ contaMsg('assin-msg', 'A validade não pode ser anterior ao início.', 'erro'); return; }
  btn.disabled = true;
  contaMsg('assin-msg', 'Salvando...');
  const r = await planosApi('POST', 'assinaturas', {
    user_id: _assinUsuario.id, plano_id: plano, inicio, validade,
    origem: document.getElementById('as-origem').value,
    observacao: document.getElementById('as-obs').value.trim() || null,
    criado_por: (sessaoAtual && sessaoAtual.email) || null
  });
  btn.disabled = false;
  if(!r.ok || !Array.isArray(r.dados) || !r.dados.length){
    contaMsg('assin-msg', r.erro || 'Sem permissão: só o administrador do sistema dá planos.', 'erro');
    return;
  }
  contaMsg('assin-msg', 'Plano dado a ' + (_assinUsuario.nome || _assinUsuario.email) + '.', 'ok');
  document.getElementById('as-obs').value = '';
  await assinRecarregarTudo();
}

