document.getElementById('assin-fechar').addEventListener('click', () => { document.getElementById('assin-overlay').style.display = 'none'; });
document.getElementById('btn-salvar-assin').addEventListener('click', salvarAssinatura);
document.getElementById('as-plano').addEventListener('change', assinSugerirValidade);
