/* ==========================================================================
   v40 — VITRINES NO SERVIDOR (SQL 39: public.vitrine_itens)
   Leilões, Mercado imobiliário e Compra e venda de empresas deixam de
   viver só no navegador de quem cadastra. Com login online:
   - a lista vem do servidor (todas as contas veem a mesma vitrine);
   - carregarBaseX() devolve a cópia em memória do servidor e
     salvarBaseX(lista) compara com ela e grava no servidor só os itens
     novos/alterados/excluídos — o resto do código (formulários,
     administração, fichas) continua igual;
   - o que o administrador tinha só no navegador aparece numa faixa
     "N itens só neste navegador — Enviar para o servidor".
   Offline/modo local: tudo como antes (localStorage).
   ========================================================================== */
var VITRINE_CFG = {
  leilao:  {chave: 'soliduns-leiloes-base-v2', nome: 'lote(s)',     area: 'leiloes'},
  imovel:  {chave: 'soliduns-imoveis-base',    nome: 'imóvel(is)',   area: 'mercado_imobiliario'},
  empresa: {chave: 'soliduns-empresas-base',   nome: 'operação(ões)', area: 'empresas'}
};
var _vit = {leilao: null, imovel: null, empresa: null};   /* null = servidor ainda não carregado */
var _vitDono = null;

function vitOnline(){ return !!(sessaoAtual && !sessaoAtual.modoLocal); }
function vitAtivo(tipo){
  const dono = sessaoAtual && sessaoAtual.user && sessaoAtual.user.id;
  return vitOnline() && _vit[tipo] !== null && _vitDono === dono;
}

async function vitRest(metodo, caminho, corpo, prefer){
  const token = await contaTokenValido();
  if(!token) return {ok:false, erro:'Sua sessão expirou. Saia e entre novamente.'};
  let r;
  try{
    r = await fetch(SUPABASE_URL + '/rest/v1/' + caminho, {
      method: metodo,
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Accept': 'application/json',
                'Content-Type': 'application/json', 'Prefer': prefer || 'return=minimal'},
      body: corpo !== undefined ? JSON.stringify(corpo) : undefined
    });
  }catch(e){ return {ok:false, erro:'Sem conexão com o servidor.'}; }
  const dados = await r.json().catch(() => null);
  if(!r.ok){
    const msg = (dados && dados.message) || '';
    let erro = 'O servidor recusou (status ' + r.status + ').';
    if(r.status === 401) erro = 'Sua sessão expirou. Saia e entre novamente.';
    else if(r.status === 403 || /row-level security/i.test(msg)) erro = 'Sem permissão: só administrador de conteúdo cadastra.';
    else if(r.status === 404 || /does not exist|schema cache/i.test(msg)) erro = 'A tabela das vitrines ainda não existe no banco (rode o SQL 39).';
    else if(/vitrine_item_ate_8mb/i.test(msg)) erro = 'O item passou de 8 MB (fotos/vídeos grandes demais).';
    return {ok:false, erro};
  }
  return {ok:true, dados};
}

/* Lê as três vitrines do servidor e redesenha as telas. */
async function vitrineCarregarServidor(){
  if(!vitOnline()) return;
  const dono = (sessaoAtual.user && sessaoAtual.user.id) || null;
  const r = await vitRest('GET', 'vitrine_itens?select=tipo,id,dados&order=ordem.asc,criado_em.asc');
  if(!r.ok){ console.warn('[vitrines]', r.erro); return; }
  const novo = {leilao: [], imovel: [], empresa: []};
  (r.dados || []).forEach(x => { if(novo[x.tipo]) novo[x.tipo].push(x.dados); });
  _vit = novo; _vitDono = dono;
  try{ leiloesDados = carregarBaseLeiloes(); renderizarLeiloes(); }catch(e){}
  try{ imoveisDados = carregarBaseImoveis(); renderizarImoveis(); }catch(e){}
  try{ empresasDados = carregarBaseEmpresas(); renderizarEmpresas(); }catch(e){}
  vitMostrarMigracao();
  radarCarregar();   /* v63: Radar de leilões (não bloqueia a tela) */
}

/* Grava no servidor só a diferença entre a lista nova e a anterior. */
function vitSalvar(tipo, lista){
  /* Compara com a lista VALIDADA (a mesma que a tela recebeu): item do
     servidor que o site não reconhece nunca é apagado por engano. */
  const brutos = _vit[tipo] || [];
  const validos = validarLista(tipo, JSON.parse(JSON.stringify(brutos)));
  const idsValidos = new Set(validos.map(x => String(x.id)));
  const antes = new Map(validos.map(x => [String(x.id), JSON.stringify(x)]));
  const depois = new Map((lista || []).map(x => [String(x.id), x]));
  const gravar = [], apagar = [];
  depois.forEach((x, id) => { if(antes.get(id) !== JSON.stringify(x)) gravar.push(x); });
  antes.forEach((_, id) => { if(!depois.has(id)) apagar.push(id); });
  const naoReconhecidos = brutos.filter(x => !idsValidos.has(String(x.id)) && !depois.has(String(x.id)));
  _vit[tipo] = JSON.parse(JSON.stringify(lista || [])).concat(naoReconhecidos);
  if(!gravar.length && !apagar.length) return Promise.resolve(true);
  return (async () => {
    let ok = true, erro = '';
    if(gravar.length){
      const ordem = new Map((lista || []).map((x, i) => [x.id, i]));
      const r = await vitRest('POST', 'vitrine_itens?on_conflict=tipo,id',
        gravar.map(x => ({tipo, id: String(x.id), dados: x, ordem: ordem.get(x.id) || 0})),
        'resolution=merge-duplicates,return=minimal');
      if(!r.ok){ ok = false; erro = r.erro; }
    }
    if(apagar.length && ok){
      const r = await vitRest('DELETE', 'vitrine_itens?tipo=eq.' + tipo + '&id=in.(' + apagar.map(i => '"' + String(i).replace(/"/g, '') + '"').join(',') + ')',
                              undefined, 'return=representation');
      if(!r.ok){ ok = false; erro = r.erro; }
      /* Sem permissão, o banco não apaga nada e não dá erro: confere. */
      else if(!Array.isArray(r.dados) || r.dados.length < apagar.length){ ok = false; erro = 'Sem permissão: só administrador de conteúdo exclui.'; }
    }
    if(!ok){
      alert('A alteração NÃO foi gravada no servidor: ' + erro + '\n\nA lista será recarregada do servidor.');
      await vitrineCarregarServidor();
    }
    return ok;
  })();
}

/* ---------- Leitura/gravação usadas por todo o código das vitrines ---------- */
function carregarBaseLeiloes(){
  if(vitAtivo('leilao')) return validarLista('leilao', JSON.parse(JSON.stringify(_vit.leilao)));
  return carregarBaseLeiloesLocal();
}
function salvarBaseLeiloes(lista){
  if(vitAtivo('leilao')) return vitSalvar('leilao', lista);
  return salvarBaseLeiloesLocal(lista);
}
function carregarBaseImoveis(){
  if(vitAtivo('imovel')) return validarLista('imovel', JSON.parse(JSON.stringify(_vit.imovel)));
  return carregarBaseImoveisLocal();
}
function salvarBaseImoveis(lista){
  if(vitAtivo('imovel')) return vitSalvar('imovel', lista);
  return salvarBaseImoveisLocal(lista);
}
function carregarBaseEmpresas(){
  if(vitAtivo('empresa')) return validarLista('empresa', JSON.parse(JSON.stringify(_vit.empresa)));
  return carregarBaseEmpresasLocal();
}
function salvarBaseEmpresas(lista){
  if(vitAtivo('empresa')) return vitSalvar('empresa', lista);
  return salvarBaseEmpresasLocal(lista);
}

/* ---------- O que o administrador tinha só neste navegador ---------- */
function vitLocais(tipo){
  try{
    const bruto = localStorage.getItem(VITRINE_CFG[tipo].chave);
    const l = bruto ? JSON.parse(bruto) : [];
    return Array.isArray(l) ? l.filter(x => x && x.id) : [];
  }catch(e){ return []; }
}
function vitFaltando(tipo){
  if(!vitAtivo(tipo)) return [];
  const noServ = new Set(_vit[tipo].map(x => String(x.id)));
  return vitLocais(tipo).filter(x => !noServ.has(String(x.id)));
}
var VITRINE_FAIXA = {leilao: 'painel-leilao', imovel: 'painel-mercado-imobiliario', empresa: 'painel-empresas'};
function vitMostrarMigracao(){
  Object.keys(VITRINE_CFG).forEach(tipo => {
    const painel = document.getElementById(VITRINE_FAIXA[tipo]);
    if(!painel) return;
    let faixa = document.getElementById('vit-migrar-' + tipo);
    const faltam = ehAdmin() ? vitFaltando(tipo) : [];
    if(!faltam.length){ if(faixa) faixa.remove(); return; }
    if(!faixa){
      faixa = document.createElement('div');
      faixa.id = 'vit-migrar-' + tipo;
      faixa.className = 'gestao-aviso';
      const cab = painel.querySelector('.page-head');
      if(cab && cab.nextSibling) painel.insertBefore(faixa, cab.nextSibling); else painel.appendChild(faixa);
    }
    faixa.innerHTML = '<strong>' + faltam.length + ' ' + VITRINE_CFG[tipo].nome + ' só neste navegador</strong>, cadastrado(s) antes do servidor '
      + '(pode incluir os exemplos de demonstração). Os clientes não veem esses itens. '
      + '<button type="button" class="btn-leilao-admin" data-vit-migrar="' + tipo + '">Enviar para o servidor</button> '
      + '<button type="button" class="leilao-limpar-filtros" data-vit-ver="' + tipo + '">ver quais são</button>';
    faixa.querySelector('[data-vit-migrar]').onclick = () => vitMigrar(tipo);
    faixa.querySelector('[data-vit-ver]').onclick = () => alert(faltam.map(x => '• ' + (x.titulo || x.nome || x.id)).join('\n'));
  });
}
async function vitMigrar(tipo){
  const faltam = vitFaltando(tipo);
  if(!faltam.length) return;
  if(!confirm('Enviar ' + faltam.length + ' ' + VITRINE_CFG[tipo].nome + ' deste navegador para o servidor?\n\n'
      + 'Depois disso, todas as contas com a área no plano passam a ver esses itens. '
      + 'Se houver exemplos de demonstração na lista, exclua-os depois pela administração.')) return;
  const nova = (_vit[tipo] || []).concat(JSON.parse(JSON.stringify(faltam)));
  const ok = await vitSalvar(tipo, nova);
  if(ok){
    await vitrineCarregarServidor();
    toastFinanceiro(faltam.length + ' ' + VITRINE_CFG[tipo].nome + ' enviado(s) para o servidor.');
  }
}

/* ==========================================================================
   v39 — GESTÃO FINANCEIRA E FISCAL NO SERVIDOR (SQL 38: "cadernos")
   Opção 3 do Thiago (02/10): caderno da CASA (MEDMENTOR / SOLIDUNS)
   compartilhado com a equipe; cada cliente com o seu caderno fechado;
   o administrador do sistema enxerga todos.
   O caderno guarda o MESMO bloco "state" que o navegador guardava. Com
   login online, o navegador deixa de ser a fonte: carrega do servidor ao
   abrir a Gestão e grava no servidor (1,5 s depois da última alteração),
   com VERSÃO — se outra pessoa gravou antes, avisa e recarrega em vez de
   apagar o trabalho dela. Modo offline/local: continua como antes.
   O bloco antigo do navegador (gestao-fiscal-state) fica intacto e pode
   ser enviado para um caderno vazio pela faixa "Enviar para o servidor".
   ========================================================================== */
var _gEspacos = [];
var _gEspacoId = null, _gVersao = 0, _gPapel = null, _gTipo = null, _gNome = '';
var _gTimer = null, _gEnviando = null, _gPendente = false, _gSujo = false, _gErroEnvio = null, _gRetry = null;
var _gAvisoLeitura = false;
var GESTAO_ESCOLHA_KEY = 'soliduns-gestao-caderno';

/* v45: mede o menu do topo da Gestão para a barra lateral caber na tela. */
function ajustarAlturaTopbarGestao(){
  const t = document.querySelector('#main-app header.topbar');
  if(t && t.offsetHeight) document.documentElement.style.setProperty('--topbar-h', t.offsetHeight + 'px');
}
window.addEventListener('resize', ajustarAlturaTopbarGestao);

function gestaoOnline(){ return !!(sessaoAtual && !sessaoAtual.modoLocal); }

var GESTAO_MENSAGENS = {
  'SEM_PERMISSAO': 'Sem permissão para este caderno.',
  'FORA_DO_PLANO': 'A Gestão financeira e fiscal não faz parte do seu plano.',
  'CONTA_NAO_ENCONTRADA': 'Não existe conta na SOLIDUNS com esse e-mail. A pessoa precisa se cadastrar primeiro.',
  'PAPEL_INVALIDO': 'Papel inválido.',
  'CADERNO_GRANDE_DEMAIS': 'O caderno passou de 20 MB. Exporte e arquive anos antigos antes de continuar.',
  'ESTADO_INVALIDO': 'Dados inválidos para gravar.',
  'rede': 'Sem conexão com o servidor.',
  'sessao': 'Sua sessão expirou. Saia e entre de novo.',
  'servidor': 'O servidor não respondeu como esperado.'
};

async function gestaoRpc(nome, corpo){
  const token = await contaTokenValido();
  if(!token) throw {tipo:'sessao'};
  let r;
  try{
    r = await fetch(SUPABASE_URL + '/rest/v1/rpc/' + nome, {
      method: 'POST',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json', 'Accept': 'application/json'},
      body: JSON.stringify(corpo || {})
    });
  }catch(e){ throw {tipo:'rede'}; }
  const j = await r.json().catch(() => null);
  if(!r.ok){
    const msg = (j && j.message) || '';
    const cod = Object.keys(GESTAO_MENSAGENS).find(k => k === k.toUpperCase() && msg.indexOf(k) !== -1);
    if(cod) throw {tipo: cod};
    if(r.status === 401) throw {tipo:'sessao'};
    if(r.status === 404) throw {tipo:'servidor', semSql:true};
    throw {tipo:'servidor'};
  }
  return j;
}
function gestaoMsg(e){ return GESTAO_MENSAGENS[e && e.tipo] || GESTAO_MENSAGENS.servidor; }

/* ---------- Faixa do caderno (topo da Gestão) ---------- */
function gestaoBarra(){
  const b = document.getElementById('gestao-barra');
  if(!b) return;
  if(!gestaoOnline()){ b.hidden = true; return; }
  b.hidden = false;
  const papelTxt = {dono:'dono', editor:'editor', leitor:'somente leitura', admin:'administrador'}[_gPapel] || '';
  const sel = _gEspacos.length > 1
    ? '<select id="gestao-espaco-sel">' + _gEspacos.map(e => '<option value="' + escHtml(e.id) + '"' + (e.id === _gEspacoId ? ' selected' : '') + '>'
        + escHtml(e.nome) + (e.tipo === 'casa' ? ' (casa)' : '') + '</option>').join('') + '</select>'
    : '<strong>' + escHtml(_gNome || '—') + '</strong>';
  b.querySelector('.gestao-barra-caderno').innerHTML = 'Caderno: ' + sel + (papelTxt ? ' <span class="gestao-papel">' + papelTxt + '</span>' : '');
  const s = document.getElementById('gestao-status');
  let st = '', cls = '';
  if(!_gEspacoId){ st = ''; }
  else if(_gPapel === 'leitor'){ st = 'Somente leitura: alterações não são gravadas'; cls = 'aviso'; }
  else if(_gErroEnvio){ st = 'NÃO SALVO — ' + _gErroEnvio + ' Tentando de novo…'; cls = 'erro'; }
  else if(_gEnviando || _gTimer){ st = 'Salvando no servidor…'; }
  else if(_gVersao > 0){ st = '✓ Salvo no servidor'; cls = 'ok'; }
  else { st = 'Caderno novo (ainda vazio no servidor)'; }
  s.textContent = st; s.className = 'gestao-status ' + cls;
  document.getElementById('btn-gestao-membros').hidden = !(_gPapel === 'dono' || _gPapel === 'admin');
  const selEl = document.getElementById('gestao-espaco-sel');
  if(selEl) selEl.onchange = () => gestaoTrocarCaderno(selEl.value);
}

function gestaoAvisoBarra(html){
  const a = document.getElementById('gestao-aviso');
  if(!a) return;
  a.innerHTML = html || '';
  a.hidden = !html;
}

/* ---------- Abrir / carregar ---------- */
async function gestaoAbrir(){
  if(!gestaoOnline()){ gestaoBarra(); return carregarEstado(); }
  await gestaoEsperarEnvio();
  gestaoAvisoBarra('');
  document.getElementById('gestao-status').textContent = 'Abrindo o caderno…';
  let lista;
  try{
    lista = await gestaoRpc('gestao_meus_espacos');
    if(!lista.length){
      await gestaoRpc('gestao_criar_espaco_pessoal');
      lista = await gestaoRpc('gestao_meus_espacos');
    }
  }catch(e){
    _gEspacoId = null; _gEspacos = [];
    gestaoEstadoVazio();
    gestaoAvisoBarra('<strong>Não foi possível abrir o caderno no servidor.</strong> ' + escHtml(e && e.semSql ? 'As tabelas da Gestão ainda não existem no banco (rode o SQL 38).' : gestaoMsg(e))
      + ' Nada do que for feito agora será gravado. <button type="button" class="btn-leilao-admin" id="btn-gestao-tentar">Tentar de novo</button>');
    const t = document.getElementById('btn-gestao-tentar'); if(t) t.onclick = gestaoAbrir;
    gestaoBarra();
    return;
  }
  _gEspacos = lista;
  const dono = (sessaoAtual.user && sessaoAtual.user.id) || '';
  let escolha = null;
  try{ escolha = JSON.parse(localStorage.getItem(GESTAO_ESCOLHA_KEY) || '{}')[dono] || null; }catch(e){}
  const alvo = lista.find(e => e.id === escolha) || lista[0];
  await gestaoCarregarCaderno(alvo.id);
}

function gestaoEstadoVazio(){
  state = Object.assign(JSON.parse(GESTAO_ESTADO_PADRAO), {});
  state.regrasConciliacao = Object.assign({}, REGRAS_CONCILIACAO_PADRAO, state.regrasConciliacao || {});
  renderTudo();
}

async function gestaoCarregarCaderno(id){
  let r;
  try{ r = await gestaoRpc('gestao_carregar', {p_espaco: id}); }
  catch(e){
    gestaoAvisoBarra('<strong>Não foi possível carregar o caderno.</strong> ' + escHtml(gestaoMsg(e)));
    return;
  }
  const meta = _gEspacos.find(e => e.id === id) || {};
  _gEspacoId = id; _gVersao = Number(r.versao) || 0; _gPapel = r.papel; _gTipo = meta.tipo || 'cliente'; _gNome = meta.nome || '';
  _gErroEnvio = null; _gSujo = false; _gAvisoLeitura = false;
  try{
    const dono = (sessaoAtual.user && sessaoAtual.user.id) || '';
    const m = JSON.parse(localStorage.getItem(GESTAO_ESCOLHA_KEY) || '{}'); m[dono] = id;
    localStorage.setItem(GESTAO_ESCOLHA_KEY, JSON.stringify(m));
  }catch(e){}
  state = Object.assign(JSON.parse(GESTAO_ESTADO_PADRAO), r.estado || {});
  state.regrasConciliacao = Object.assign({}, REGRAS_CONCILIACAO_PADRAO, state.regrasConciliacao || {});
  seedObrigacoesPadrao();
  seedEmpresasPadrao();
  renderTudo();
  gestaoBarra();
  gestaoOferecerMigracao();
}

async function gestaoTrocarCaderno(id){
  await gestaoEsperarEnvio();
  await gestaoCarregarCaderno(id);
}

/* ---------- Gravar ---------- */
/* Chamado por flushEstado (cada alteração da Gestão). */
function gestaoAgendarEnvio(){
  if(!_gEspacoId) return;
  if(_gPapel === 'leitor'){
    if(!_gAvisoLeitura){ _gAvisoLeitura = true; toastFinanceiro('Caderno em somente leitura: esta alteração não será gravada.'); }
    return;
  }
  _gSujo = true;
  clearTimeout(_gTimer);
  _gTimer = setTimeout(() => { _gTimer = null; gestaoEnviar(); }, 1500);
  gestaoBarra();
}

async function gestaoEnviar(){
  if(!_gEspacoId || _gPapel === 'leitor') return;
  if(_gEnviando){ _gPendente = true; return _gEnviando; }
  const espaco = _gEspacoId, versao = _gVersao;
  _gSujo = false;
  _gEnviando = (async () => {
    try{
      const r = await gestaoRpc('gestao_salvar', {p_espaco: espaco, p_estado: state, p_versao: versao});
      if(espaco !== _gEspacoId) return;
      if(r && r.ok){
        _gVersao = Number(r.versao); _gErroEnvio = null; clearTimeout(_gRetry);
      } else if(r && r.conflito){
        _gSujo = false; _gPendente = false;
        alert((r.atualizado_por || 'Outra pessoa da equipe') + ' alterou este caderno enquanto você trabalhava.\n\n'
          + 'Para não apagar o trabalho dessa pessoa, a versão mais recente será carregada agora. '
          + 'Confira e refaça a sua última alteração, se ela não aparecer.');
        _gEnviando = null;
        await gestaoCarregarCaderno(espaco);
        return;
      }
    }catch(e){
      _gErroEnvio = gestaoMsg(e);
      _gSujo = true;
      clearTimeout(_gRetry);
      if(e && (e.tipo === 'rede' || e.tipo === 'servidor')) _gRetry = setTimeout(gestaoEnviar, 15000);
    }
  })();
  try{ await _gEnviando; } finally {
    _gEnviando = null;
    gestaoBarra();
    if(_gPendente){ _gPendente = false; gestaoEnviar(); }
  }
}

async function gestaoEsperarEnvio(){
  if(_gTimer){ clearTimeout(_gTimer); _gTimer = null; await gestaoEnviar(); }
  while(_gEnviando){ try{ await _gEnviando; }catch(e){} }
}

window.addEventListener('beforeunload', function(ev){
  if(gestaoOnline() && _gEspacoId && (_gSujo || _gTimer || _gEnviando)){
    ev.preventDefault(); ev.returnValue = '';
  }
});

/* ---------- Dados antigos deste navegador ---------- */
function gestaoLegado(){
  try{
    const raw = localStorage.getItem(STORAGE_KEY);
    if(!raw) return null;
    const l = JSON.parse(raw);
    const n = k => Array.isArray(l[k]) ? l[k].length : 0;
    const total = ['transacoes','contasFinanceiras','extratoBancario','conciliacoes','contratosRecorrentes','vendas','compras','produtos','documentosFiscais','notasFiscaisServico','clientesFornecedores']
      .reduce((s, k) => s + n(k), 0);
    if(total === 0) return null;
    return {dados: l, lancamentos: n('transacoes'), empresas: n('empresas'), contas: n('contasFinanceiras'), total};
  }catch(e){ return null; }
}

function gestaoOferecerMigracao(){
  if(_gVersao !== 0 || _gPapel === 'leitor'){ gestaoAvisoBarra(''); return; }
  const l = gestaoLegado();
  if(!l){ gestaoAvisoBarra(''); return; }
  gestaoAvisoBarra('<strong>Este navegador tem dados da Gestão de antes do servidor</strong> ('
    + l.lancamentos + ' lançamento(s), ' + l.empresas + ' empresa(s), ' + l.contas + ' conta(s) e outros registros). '
    + 'O caderno <strong>' + escHtml(_gNome) + '</strong> está vazio no servidor. '
    + '<button type="button" class="btn-leilao-admin" id="btn-gestao-migrar">Enviar para este caderno</button>');
  document.getElementById('btn-gestao-migrar').onclick = gestaoMigrar;
}

async function gestaoMigrar(){
  const l = gestaoLegado();
  if(!l) return;
  if(!confirm('Enviar os dados deste navegador para o caderno "' + _gNome + '"?\n\n'
      + 'Depois disso, todos os membros do caderno passam a ver e editar esses dados. '
      + 'A cópia antiga continua guardada neste navegador.')) return;
  const b = document.getElementById('btn-gestao-migrar'); if(b) b.disabled = true;
  clearTimeout(_gTimer); _gTimer = null;
  const novo = Object.assign(JSON.parse(GESTAO_ESTADO_PADRAO), l.dados);
  let r;
  try{ r = await gestaoRpc('gestao_salvar', {p_espaco: _gEspacoId, p_estado: novo, p_versao: 0}); }
  catch(e){ if(b) b.disabled = false; alert('Não foi possível enviar: ' + gestaoMsg(e)); return; }
  if(!r || !r.ok){
    alert('Este caderno já recebeu dados de outra pessoa. Nada foi enviado; os dados antigos continuam neste navegador.');
    await gestaoCarregarCaderno(_gEspacoId);
    return;
  }
  try{ localStorage.setItem(STORAGE_KEY + ':enviado-' + new Date().toISOString().slice(0, 10), localStorage.getItem(STORAGE_KEY)); localStorage.removeItem(STORAGE_KEY); }catch(e){}
  await gestaoCarregarCaderno(_gEspacoId);
  toastFinanceiro('Dados enviados para o caderno ' + _gNome + '.');
}

/* ---------- Membros do caderno ---------- */
async function gestaoAbrirMembros(){
  const ov = document.getElementById('gestao-membros-overlay');
  document.getElementById('gestao-membros-titulo').textContent = 'Membros — ' + _gNome;
  contaMsg('gestao-membros-msg', '');
  ov.style.display = 'flex';
  await gestaoDesenharMembros();
}
async function gestaoDesenharMembros(){
  const caixa = document.getElementById('gestao-membros-lista');
  caixa.innerHTML = '<div class="leilao-ficha-sub">Carregando…</div>';
  let l;
  try{ l = await gestaoRpc('gestao_membros_listar', {p_espaco: _gEspacoId}); }
  catch(e){ caixa.innerHTML = '<div class="leilao-ficha-sub">' + escHtml(gestaoMsg(e)) + '</div>'; return; }
  const nomes = {dono:'Dono', editor:'Editor', leitor:'Somente leitura'};
  caixa.innerHTML = '<table class="leilao-admin-table"><thead><tr><th>Nome</th><th>E-mail</th><th>Papel</th><th></th></tr></thead><tbody>'
    + l.map(m => '<tr data-id="' + escHtml(m.user_id) + '"><td>' + escHtml(m.nome || '—') + '</td><td>' + escHtml(m.email || '') + '</td><td>' + (nomes[m.papel] || m.papel) + '</td>'
      + '<td class="acoes">' + (m.papel === 'dono' ? '' : '<button type="button" class="ac-editar ac-gm-remover">Remover</button>') + '</td></tr>').join('')
    + '</tbody></table>';
  caixa.querySelectorAll('.ac-gm-remover').forEach(b => b.addEventListener('click', async () => {
    const id = b.closest('tr').dataset.id;
    if(!confirm('Remover esta pessoa do caderno "' + _gNome + '"? Ela deixa de ver e editar os dados na hora.')) return;
    try{ await gestaoRpc('gestao_membro_remover', {p_espaco: _gEspacoId, p_user: id}); contaMsg('gestao-membros-msg', 'Removido.', 'ok'); }
    catch(e){ contaMsg('gestao-membros-msg', gestaoMsg(e), 'erro'); }
    gestaoDesenharMembros();
  }));
}
async function gestaoAdicionarMembro(){
  const email = document.getElementById('gm-email').value.trim();
  const papel = document.getElementById('gm-papel').value;
  if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){ contaMsg('gestao-membros-msg', 'Informe um e-mail válido.', 'erro'); return; }
  try{
    await gestaoRpc('gestao_membro_adicionar', {p_espaco: _gEspacoId, p_email: email, p_papel: papel});
    document.getElementById('gm-email').value = '';
    contaMsg('gestao-membros-msg', 'Adicionado: ' + email + '.', 'ok');
  }catch(e){ contaMsg('gestao-membros-msg', gestaoMsg(e), 'erro'); }
  gestaoDesenharMembros();
}
document.getElementById('btn-gestao-membros').addEventListener('click', gestaoAbrirMembros);
document.getElementById('gestao-membros-fechar').addEventListener('click', () => { document.getElementById('gestao-membros-overlay').style.display = 'none'; });
document.getElementById('btn-gm-adicionar').addEventListener('click', gestaoAdicionarMembro);

/* ---------- MÓDULO FISCAL — dois modos: financeiro | fiscal ---------- */
function aplicarModoSidebar(modo){
  const sub = document.getElementById('spine-sub');
  if(sub) sub.textContent = modo === 'fiscal' ? 'Gestão Fiscal' : 'Gestão Financeira';
  document.querySelectorAll('.nav-item[data-grupo]').forEach(item=>{
    item.style.display = item.getAttribute('data-grupo') === modo ? '' : 'none';
  });
  const disclaimer = document.getElementById('fiscal-disclaimer-fixo');
  if(disclaimer) disclaimer.style.display = modo === 'fiscal' ? 'block' : 'none';
}

let __pilhaViewsFiscal = [];
function mostrarViewFiscal(viewId, viaVoltar){
  const atual = document.querySelector('.view.active');
  const atualId = atual ? atual.id.replace('view-','') : null;
  if(!viaVoltar && atualId && atualId !== viewId){
    __pilhaViewsFiscal.push(atualId);
  }
  document.querySelectorAll('.nav-item').forEach(i=>i.classList.remove('active'));
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  const item = document.querySelector(`.nav-item[data-view="${viewId}"]`);
  if(item) item.classList.add('active');
  const view = document.getElementById('view-'+viewId);
  if(view) view.classList.add('active');
  window.scrollTo(0,0);
  if(viewId === 'dashboard') setTimeout(renderGraficosFluxoCaixa, 30);
  if(viewId === 'fin-cadastros') renderClientesFornecedores();
  if(viewId === 'fin-contas'){ renderContasFinanceiras(); renderTransferencias(); }
  if(viewId === 'fin-categorias') renderCategoriasFluxo();
  if(viewId === 'caixa') renderCaixa();
  if(viewId === 'fin-conciliacao'){ renderConciliacao(); setTituloPagina('Conciliação bancária'); }
  if(viewId === 'fin-contratos'){ renderContratosRecorrentes(); recGerarPendentes(); recRender(); }
  if(viewId === 'fin-cobrancas') renderCobrancas();
  if(viewId === 'fin-relatorios') renderRelatoriosFinanceiros();
  if(viewId === 'fin-demonstracoes'){ prepararDemonstracoes(); setTituloPagina('Demonstrações financeiras'); }
  if(viewId === 'fin-integracoes') renderIntegracoesFinanceiro();
  if(viewId === 'fin-orcamentos') renderOrcamentos();
  if(viewId === 'fin-vendas') renderVendas();
  if(viewId === 'fiscal-nfse'){ popularSelectsNfse(); renderNotasFiscaisServico(); }
  if(viewId === 'fin-compras') renderCompras();
  if(viewId === 'fin-estoque'){ renderProdutos(); renderInventarios(); }
  if(viewId === 'fin-carteira'){ popularFiltrosCarteira(); renderCarteira(); }
  if(viewId === 'fiscal-documentos') renderDocumentosFiscais();
  if(viewId === 'fiscal-cadastros') renderCadastrosFiscais();
  if(viewId === 'fiscal-empresa'){ renderParametrizacaoFiscal(); renderEmpresaFiscalTudo(); }
  if(viewId === 'fiscal-compliance') renderComplianceFiscal();
  if(viewId === 'fiscal-arquivos') renderArquivosFiscais();
  if(viewId === 'fin-pagar') renderContasTipo('pagar', 'ap');
  if(viewId === 'fin-receber') renderContasTipo('receber', 'ar');
  if(viewId === 'simulacao-futura') popularFormSimulacaoFutura();
  if(viewId === 'fiscal-visao-geral'){
    renderizarKpisFiscal();
    renderizarAtalhosFiscais();
    fiscalHistoricoSelecionados = [];
    renderizarHistoricoSimulacoes();
  }
}
function voltarViewAnteriorFiscal(){
  if(__pilhaViewsFiscal.length === 0) return false;
  const anterior = __pilhaViewsFiscal.pop();
  mostrarViewFiscal(anterior, true);
  return true;
}

function abrirModuloFiscal(modo){
  modo = modo || 'financeiro';
  /* v36: gestão fora do plano (SQL 34) */
  const areaGestao = modo === 'fiscal' ? 'gestao_fiscal' : 'gestao_financeira';
  if(!areaLiberada(areaGestao)){ areaMostrarBloqueio(areaGestao); return; }
  window.__moduloFiscalModoAtual = modo; // usado por outros pontos (ex.: fechar modal Equipe) para saber o título certo
  mostrarTela('fiscal');
  atualizarUsuarioTopbar();
  setTimeout(ajustarAlturaTopbarGestao, 0);   /* v45 */
  gestaoAbrir();   /* v39: caderno do servidor (offline: carregarEstado) */
  aplicarModoSidebar(modo);
  __pilhaViewsFiscal = [];
  mostrarViewFiscal(modo === 'fiscal' ? 'fiscal-visao-geral' : 'dashboard', true);
  setTituloPagina(modo === 'fiscal' ? 'Gestão fiscal' : 'Gestão financeira');
}

function voltarAoDashboardDoFiscal(painelId){
  // "Mercado financeiro" (acoes) nunca teve hash próprio -> o roteador
  // mostra o hub de Investimentos em '#/investimentos'. Sem o passo
  // seguinte, o clique "voltar" do módulo fiscal jogava sempre pro hub,
  // perdendo a subárea específica de onde o usuário tinha vindo — mesmo
  // bug que existia em navegarParaPainel(), corrigido aqui também.
  if(painelId === 'acoes'){ navegarHash('#/investimentos/mercado-financeiro'); return; }   /* v46 */
  navegarHash('#/' + painelId);
}

/* v46: cada opção do menu lateral da Gestão grava o endereço (sem recarregar) */
document.querySelectorAll('.spine .nav-item[data-view]').forEach(function(el){
  el.addEventListener('click', function(){
    const fiscal = el.getAttribute('data-grupo') === 'fiscal';
    const base = fiscal ? '#/gestao-fiscal' : '#/gestao-financeira';
    const v = el.getAttribute('data-view');
    const alvo = (v === 'dashboard' || v === 'fiscal-visao-geral') ? base : base + '/' + v;
    if(window.location.hash !== alvo) history.replaceState(null, '', alvo);
  });
});

/* ---------- MAPA ÚNICO DE ROTAS (fonte única de verdade) ----------
   Cada entrada documenta pai/filho/hash. O roteador (mais abaixo) só
   consulta este objeto — não inventa caminho novo por fora dele. */
const ROTAS = {
  'educacao':               {tipo:'painel', painel:'educacao', pai:null,          filho:'Educação Continuada'},
  'investimentos':          {tipo:'painel', painel:'investimentos-escolha', pai:null, filho:'Investimentos', marcarRota:'investimentos'},
  'leilao':                 {tipo:'painel', painel:'leilao', pai:'Investimentos',   filho:'Leilão de imóveis', marcarRota:'investimentos'},
  'leilao-veiculos':        {tipo:'painel', painel:'leilao-veiculos', pai:'Investimentos', filho:'Leilão de automóveis', marcarRota:'investimentos'},   /* v77-LEI */
  'mercado-imobiliario':    {tipo:'painel', painel:'mercado-imobiliario', pai:'Investimentos', filho:'Mercado imobiliário', marcarRota:'investimentos'},
  'avaliacao-imoveis':      {tipo:'painel', painel:'avaliacao-imoveis', pai:'Investimentos', filho:'Avaliação de imóveis', marcarRota:'investimentos'},   /* v83-AVA */
  'gestao-financeira':      {tipo:'fiscal', modulo:'financeiro', pai:null,        filho:'Gestão financeira', marcarRota:'financeira'},
  'gestao-financeira/conciliacao': {tipo:'fiscal', modulo:'financeiro', pai:'Gestão financeira', filho:'Conciliação bancária', marcarRota:'financeira', viewFiscal:'fin-conciliacao'},
  'gestao-fiscal':          {tipo:'fiscal', modulo:'fiscal', pai:null,            filho:'Gestão fiscal', marcarRota:'fiscal'},
  'calculadoras':           {tipo:'painel', painel:'calculadoras', pai:null,      filho:'Calculadoras'},
  'admin/equipe':           {tipo:'equipe', pai:null,                            filho:'Equipe'},
  'investimentos/empresas': {tipo:'painel', painel:'empresas', pai:'Investimentos', filho:'Compra e venda de empresas', marcarRota:'investimentos'},
  /* v46: o Mercado financeiro ganhou endereço próprio (antes usava o do hub) */
  'investimentos/mercado-financeiro': {tipo:'painel', painel:'acoes', pai:'Investimentos', filho:'Mercado financeiro', marcarRota:'investimentos'}
};
/* Hashes antigos que ainda podem estar em favoritos/links -> redirecionam
   para o hash atual, sem quebrar o clique de quem ainda usa o antigo. */
const ROTAS_REDIRECT = {
  'gestao-fiscal-e-financeira': '#/gestao-financeira',
  /* v46: endereços antigos/alternativos (favoritos, links compartilhados) */
  'acoes': '#/investimentos/mercado-financeiro',
  'investimentos/acoes': '#/investimentos/mercado-financeiro',
  'mercado-financeiro': '#/investimentos/mercado-financeiro',
  'empresas': '#/investimentos/empresas',
  'investimentos/leilao': '#/leilao',
  'investimentos/leilao-veiculos': '#/leilao-veiculos', 'leilao-automoveis': '#/leilao-veiculos', 'leilao-de-automoveis': '#/leilao-veiculos',   /* v77-LEI */
  'investimentos/mercado-imobiliario': '#/mercado-imobiliario',
  'investimentos/avaliacao-imoveis': '#/avaliacao-imoveis', 'avaliacao': '#/avaliacao-imoveis', 'avaliacao-de-imoveis': '#/avaliacao-imoveis', 'laudos': '#/avaliacao-imoveis',   /* v83-AVA */
  'login': '#/educacao'   /* logado: o login não tem o que mostrar */
};
/* "Mercado financeiro" (acoes) nunca teve hash próprio — um link salvo,
   compartilhado ou o botão voltar do navegador com #/acoes ou
   #/investimentos/acoes precisa continuar abrindo esse painel, não só
   o hub de Investimentos (mesmo bug do navegarParaPainel/
   voltarAoDashboardDoFiscal, corrigido aqui pro caso de hash direto). */
const ROTAS_REDIRECT_PARA_ACOES = [];   /* v46: substituído por ROTAS_REDIRECT + rota própria */

/* Traduz um painelId (ex.: "leilao", "calculadoras") para o hash que o
   mostra de fato — consultando a própria ROTAS acima, única fonte de
   verdade. Usado por qualquer clique que hoje troca de painel (cards de
   escolha, "voltar", itens de topbar) para NUNCA deixar a URL desatualizada
   em relação ao que está na tela — sem isso, F5, favoritar ou compartilhar
   o link levava para o painel errado (bug encontrado e corrigido no 76º
   prompt: Investimentos e Educação Continuada na topbar do dashboard, e os
   cards de Leilão/Mercado imobiliário dentro do hub de Investimentos).
   "acoes" nunca teve hash próprio (ver ROTAS_REDIRECT) — cai no hub. */
function hashParaPainel(painelId){
  for(var chave in ROTAS){
    if(ROTAS[chave].painel === painelId) return '#/' + chave;
  }
  return null;
}
function navegarParaPainel(painelId){
  var hash = hashParaPainel(painelId);
  if(hash){
    navegarHash(hash);
    // "acoes" (Mercado financeiro) não tem hash próprio — o roteador
    // mostra o hub de Investimentos em '#/investimentos'. Quando foi
    // essa subárea específica que pediram (não o hub em si), abre ela
    // por cima do hub logo em seguida, sem trocar a URL de novo.
    if(painelId !== 'investimentos-escolha' && hash === '#/investimentos'){
      mostrarPainelDash(painelId);
    }
  } else {
    mostrarPainelDash(painelId); // sem hash próprio conhecido — só troca o painel visível mesmo
  }
}
/* Rotas da landing pública que também respondem estando logado (ex.:
   usuário clicou na logomarca pra ver a landing sem sair da sessão, e
   continuou navegando dentro dela). Nome mantido por compatibilidade
   com o restante do código; hoje funcionam nos dois estados. */
var VM_SC_RE = /^noticias\/(?:scanner(\/\d{4}-\d{2}-\d{2})?|artigo\/(\d{1,9}))$/;   /* v125: leitura do Scanner do Dia; v131: página do artigo */
const ROTAS_SO_DESLOGADO = ['quem-somos', 'noticias', 'noticias/eua'];   /* v119: Notícias pública */

/* ---------- ROTEADOR (hash, sem reload) ---------- */
function marcarRotaAtivaGlobal(rota){
  document.querySelectorAll('[data-rota]').forEach(el=>el.classList.remove('active'));
  document.querySelectorAll(`[data-rota="${rota}"]`).forEach(el=>el.classList.add('active'));
}

function navegarHash(hash){
  if(window.location.hash === hash) roteador();
  else window.location.hash = hash;
}

function mostrar404(){
  mostrarTela('dashboard');
  document.querySelectorAll('#tela-dashboard .painel').forEach(p=>p.classList.remove('ativo'));
  document.getElementById('painel-404').classList.add('ativo');
  document.querySelectorAll('#topbar-nav-dash .topbar-item').forEach(b=>b.classList.remove('active'));
  setTituloPagina('Página não encontrada');
}
document.getElementById('btn-404-voltar').addEventListener('click', ()=> navegarHash('#/educacao'));

/* v45: janelas "donas" de uma seção fecham quando a rota sai dela.
   Antes, navegar pelo VOLTAR do navegador (ou digitando o endereço) com a
   Equipe, o leitor de artigos ou uma ficha aberta deixava a janela por
   cima da tela nova, bloqueando os cliques. Janelas que não pertencem a
   uma seção (ex.: Minha conta) não são tocadas. */
var JANELAS_POR_SECAO = [
  [/^artigo-viewer-overlay$/, c => /^educacao\/(artigos|livres|preparatorios)\/[^/]+$/.test(c) && !/\/(certificacoes|curso)$/.test(c)],
  [/^(equipe|equipe-ficha|plano|assin|convidar)-overlay$/, c => c === 'admin/equipe'],
  [/^(artigos-admin|artigo-form)-overlay$/, c => false],   /* v46: abertas por botão, não por endereço */
  [/^cert-ficha-overlay$/, c => c === '' || c.indexOf('educacao') === 0],
  [/^(leilao-[a-z]+|lei-mais-filtros)-overlay$/, c => c === 'leilao' || c.indexOf('leilao/') === 0],
  [/^vei-[a-z-]+-overlay$/, c => c === 'leilao-veiculos'],   /* v77-LEI */
  [/^im-[a-z-]+-overlay$/, c => c === 'mercado-imobiliario' || c.indexOf('mercado-imobiliario/') === 0],
  [/^empresas-[a-z]+-overlay$/, c => c === 'investimentos/empresas' || c === 'empresas'],
  [/^(indicadores-admin|relatorio-ficha|b3-modal|ativo-form)-overlay$/, c => c.indexOf('investimentos') === 0 || ROTAS_REDIRECT_PARA_ACOES.indexOf(c) !== -1],
  [/^(cc-[a-z-]+|venda-[a-z]+|compra-form|baixa|kardex|lancamento-rapido|nfse-detalhe|ficha-documento|importar-xml|inventario-form|orcamento-form|produto-form|contrato-[a-z]+|cobranca-form|gestao-membros)-overlay$/, c => c.indexOf('gestao') === 0 || c.indexOf('fiscal') === 0]
];
function fecharJanelasForaDaRota(caminho){
  document.querySelectorAll('[id$="-overlay"]').forEach(el => {
    if(el.style.display === 'none' || getComputedStyle(el).display === 'none') return;
    const regra = JANELAS_POR_SECAO.find(r => r[0].test(el.id));
    if(!regra || regra[1](caminho)) return;
    el.style.display = 'none';
    if(el.id === 'artigo-viewer-overlay') el.innerHTML = '';
  });
}

function roteador(){
  if(!sessaoAtual) return; // so roteia depois do login
  if(window.__mostrarLandingForcado){ window.__mostrarLandingForcado = false; return; } // usuário logado pediu a landing de propósito (clicou "SOLIDUNS")
  const bruto = (window.location.hash || '').replace(/^#\/?/, '');
  const [caminho, query] = bruto.split('?');
  fecharJanelasForaDaRota(caminho);   /* v45 */

  if(ROTAS_REDIRECT_PARA_ACOES.indexOf(caminho) !== -1){
    window.__abrirAcoesAposHub = true;
    window.location.hash = '#/investimentos';
    return;
  }

  if(ROTAS_REDIRECT[caminho]){
    /* v46: troca sem criar entrada no histórico (o Voltar não fica preso) */
    history.replaceState(null, '', ROTAS_REDIRECT[caminho]);
    roteador();
    return;
  }

  if(!caminho || caminho === 'educacao' || caminho.indexOf('educacao/') === 0){
    mostrarTela('dashboard'); mostrarPainelDash('educacao'); marcarRotaAtivaGlobal('educacao');
    const partesEdu = caminho ? caminho.split('/') : [];
    const categoriasValidas = ['preparatorios','livres','artigos'];
    if(partesEdu.length <= 1){
      selecionarCategoriaEducacao(null);
    } else if(partesEdu.length === 2){
      if(categoriasValidas.indexOf(partesEdu[1]) === -1){ mostrar404(); return; }
      selecionarCategoriaEducacao(partesEdu[1]);
    } else {
      const categoriaEdu = partesEdu[1], itemEdu = partesEdu[2];
      if(categoriasValidas.indexOf(categoriaEdu) === -1){ mostrar404(); return; }
      if(categoriaEdu === 'preparatorios' && itemEdu === 'certificacoes'){
        mostrarPainelDash('certificacoes');
      } else if(categoriaEdu === 'preparatorios' && itemEdu === 'curso' && partesEdu[3]){
        // Segmentos após o slug alimentam a navegação interna do curso
        // (#/.../curso/c-pro-r/modulo/3/cap/9, .../simulado/3/2).
        abrirCursoCertificacao(partesEdu[3], partesEdu.slice(4));
      } else {
        // Terceira camada genérica (artigo dentro da categoria): mesma
        // grade da categoria, com o artigo aberto no viewer por cima.
        selecionarCategoriaEducacao(categoriaEdu);
        abrirViewerArtigo(itemEdu);   /* v37: o leitor busca no servidor e avisa se não houver */
      }
    }
    return;
  }

  /* v50: telas internas do Mercado financeiro */
  const mMF = /^investimentos\/mercado-financeiro\/(.+)$/.exec(caminho);
  if(mMF){
    if(MF_SUBROTAS.indexOf(mMF[1]) === -1 && !MF_COMPARADOR_RE.test(mMF[1]) && !MF_COMPARA2_RE.test(mMF[1]) && !RA_PAGINA_RE.test(mMF[1])){ mostrar404(); return; }   /* v55; v69; agente v66 */
    mostrarTela('dashboard'); mostrarPainelDash('acoes'); marcarRotaAtivaGlobal('investimentos');
    if(typeof tkRotaV108 === 'function' && tkRotaV108(mMF[1], query)) return;   /* v108: relatorios?ticker=…&mercado=… */
    mfAbrirSubrota(mMF[1]);
    return;
  }
  let rota = ROTAS[caminho];
  /* v46: #/gestao-financeira/<opção> e #/gestao-fiscal/<opção> */
  const mG = !rota && /^(gestao-financeira|gestao-fiscal)\/([a-z0-9-]+)$/.exec(caminho);
  if(mG){
    const modulo = mG[1] === 'gestao-fiscal' ? 'fiscal' : 'financeiro';
    const item = document.querySelector('.spine .nav-item[data-view="' + mG[2] + '"]');
    if(item && ((item.getAttribute('data-grupo') === 'fiscal') === (modulo === 'fiscal'))){
      rota = Object.assign({}, ROTAS[mG[1]], {viewFiscal: mG[2]});
    }
  }
  if(rota){
    if(rota.tipo === 'painel'){
      mostrarTela('dashboard'); mostrarPainelDash(rota.painel);
      if(rota.marcarRota) marcarRotaAtivaGlobal(rota.marcarRota);
      if(rota.painel === 'investimentos-escolha' && window.__abrirAcoesAposHub){
        window.__abrirAcoesAposHub = false;
        mostrarPainelDash('acoes');
      }
    } else if(rota.tipo === 'fiscal'){
      // Entrar no módulo fiscal a partir de um painel do dashboard (ex.:
      // Calculadoras, Educação) deixava o indicador de lá aceso junto
      // com "Gestão fiscal"/"Gestão financeira" — marcarRotaAtivaGlobal
      // só limpa data-rota; aqui limpamos também os data-painel do
      // dashboard, sem risco de conflito (este branch nunca chama
      // marcarAtivo()).
      document.querySelectorAll('#topbar-nav-dash .topbar-item[data-painel]').forEach(el=>el.classList.remove('active'));
      abrirModuloFiscal(rota.modulo); marcarRotaAtivaGlobal(rota.marcarRota);
      if(rota.modulo === 'fiscal' && query && query.includes('sim=futuro')) mostrarViewFiscal('simulacao-futura');
      if(rota.viewFiscal) mostrarViewFiscal(rota.viewFiscal);
    } else if(rota.tipo === 'equipe'){
      abrirEquipe(); // dentro, ja redireciona sozinho se nao for admin
    }
    return;
  }

  if(caminho === 'inicio' || caminho === 'contato' || caminho === 'equipe' || (ROTAS_SO_DESLOGADO.includes(caminho) || VM_SC_RE.test(caminho)) || caminho.indexOf('servicos/') === 0 || caminho.indexOf('executivo/') === 0){
    // Rotas da landing pública. Um usuário LOGADO pode estar vendo a
    // landing de propósito (clicou na logomarca — irParaLandingPublica
    // nunca desloga) e continuar navegando dentro dela (Início, Quem
    // somos, Serviços, Contato). Antes, esse hash caía aqui e forçava
    // de volta pro dashboard (ou 404 pra "inicio"/"contato", que nem
    // estavam nessa lista) — agora mostra o conteúdo público de
    // verdade, igual ao que acontece deslogado.
    if(caminho === 'quem-somos'){ mostrarTela('quem-somos'); }
    else if(caminho === 'noticias' || caminho === 'noticias/eua' || VM_SC_RE.test(caminho)){ ntpAbrir(caminho); }   /* v119 */
    else if(caminho === 'equipe'){ mostrarTela('equipe'); }
    else if(caminho.indexOf('servicos/') === 0){ mostrarTela('servico'); renderizarServico(caminho.slice('servicos/'.length)); }
    else if(caminho.indexOf('executivo/') === 0){ mostrarTela('executivo'); renderizarExecutivo(caminho.slice('executivo/'.length)); }
    else { mostrarTela('landing'); aplicarScrollPendente(); }
    return;
  }

  // Rota genuinamente desconhecida (nunca existiu, erro de digitação, link
  // quebrado) -> página 404 de verdade, não tela preta nem redirect silencioso.
  mostrar404();
}
