async function initAuth(){
  const sessao = await lerSessaoAuth();
  if(!sessao){
    mostrarTela('auth');
    await preencherEmailLembrado();
    return;
  }
  if(Date.now() < sessao.expires_at - 30000){
    await entrarNoApp(sessao);
  } else {
    const nova = await renovarSessao(sessao);
    if(nova) await entrarNoApp(nova);
    else {
      (()=>{ try{ localStorage.removeItem(AUTH_STORAGE_KEY); }catch(e){} })();
      mostrarTela('auth');
      await preencherEmailLembrado();
    }
  }
}

/* ---------- BOOTSTRAP: landing (deslogado) x app (logado) ----------
   Visitante em "/" ou "#/" -> landing. Quem já está logado nunca vê a
   landing, vai direto para a home logada. "#/login" abre a tela de
   login que já existe, sem passar pela landing. */
async function iniciarApp(){
  if(await processarRetornoOAuth()) return;
  const rotaLimpa = (window.location.hash || '').replace(/^#\/?/, '');
  const sessao = await lerSessaoAuth();

  let sessaoValida = null;
  if(sessao && Date.now() < sessao.expires_at - 30000){
    sessaoValida = sessao;
  } else if(sessao){
    sessaoValida = await renovarSessao(sessao);
    if(!sessaoValida){ (()=>{ try{ localStorage.removeItem(AUTH_STORAGE_KEY); }catch(e){} })(); }
  }
  if(sessaoValida){
    /* v11: a sessão salva no navegador não bastava. Quem tinha o acesso
       revogado (Negar/Excluir na tela de Equipe) continuava entrando a cada
       F5, porque a liberação só era checada no momento do login e o token
       se renova sozinho. Agora cada abertura consulta public.acessos de novo,
       e o perfil (admin/usuário) é sempre o do servidor. Falha fechada. */
    const uid = sessaoValida.user && sessaoValida.user.id;
    const lib = await consultarLiberacao(sessaoValida.access_token, uid);
    if(!lib.erro && lib.status === 'aprovado'){
      if(lib.perfil && lib.perfil !== sessaoValida.perfil){
        sessaoValida.perfil = lib.perfil;
        await salvarSessaoAuth(sessaoValida);
      }
      await entrarNoApp(sessaoValida); // logado -> nunca ve a landing
      return;
    }
    (()=>{ try{ localStorage.removeItem(AUTH_STORAGE_KEY); }catch(e){} })();
    mostrarTela('auth');
    await preencherEmailLembrado();
    const m = document.getElementById('login-msg');
    if(m){
      if(lib.erro){
        console.warn('[acesso] falha ao revalidar liberação:', lib.detalhe);
        m.textContent = 'Não foi possível confirmar sua autorização de acesso agora. Entre novamente em instantes.';
        m.className = 'auth-msg erro';
      } else if(lib.status === 'recusado'){
        m.textContent = 'Seu acesso não está autorizado. Fale com a administração da SOLIDUNS.';
        m.className = 'auth-msg erro';
      } else {
        m.textContent = 'Seu cadastro está aguardando liberação de um administrador.';
        m.className = 'auth-msg';
      }
    }
    return;
  }

  if(rotaLimpa === 'login'){
    mostrarTela('auth');
    await preencherEmailLembrado();
  } else if(rotaLimpa === 'quem-somos'){
    mostrarTela('quem-somos');
  } else if(rotaLimpa === 'noticias' || rotaLimpa === 'noticias/eua' || VM_SC_RE.test(rotaLimpa)){   /* v119 */
    ntpAbrir(rotaLimpa);
  } else if(rotaLimpa === 'equipe'){
    mostrarTela('equipe');
  } else if(rotaLimpa.indexOf('servicos/') === 0){
    mostrarTela('servico');
    renderizarServico(rotaLimpa.slice('servicos/'.length));
  } else if(rotaLimpa.indexOf('executivo/') === 0){
    mostrarTela('executivo');
    renderizarExecutivo(rotaLimpa.slice('executivo/'.length));
  } else {
    mostrarTela('landing');
  }
}

function irParaLogin(){
  if(sessaoAtual){
    // Já existe sessão (ex.: usuário clicou "SOLIDUNS" pra ver a landing
    // sem sair) — o login RECONHECE a sessão, não mostra o formulário
    // de novo, não inventa um terceiro fluxo ("Área logada" etc.).
    /* v46: das páginas públicas (Quem somos, Time, Serviços) o botão não
       fazia nada — agora leva sempre para dentro da plataforma */
    if(window.location.hash !== '#/educacao') window.location.hash = '#/educacao';
    else roteador();
    return;
  }
  window.location.hash = '#/login';
  mostrarTela('auth');
  preencherEmailLembrado();
}

/* SOLIDUNS na barra (landing e app logado) -> sempre a landing pública,
   nunca desloga. */
/* Voltar pra landing pública "de propósito" — usada pelo logo, pelo botão
   Voltar das páginas públicas (serviço/executivo) e pelo link Contato/
   Início que pende uma rolagem até a seção certa. O ponto crítico: só
   marca __mostrarLandingForcado quando o hash for REALMENTE mudar pra
   "#/" — se já estiver em "#/", setar de novo não dispara hashchange
   nenhum, então a flag nunca seria consumida e ficaria "presa" ligada,
   cancelando silenciosamente a PRÓXIMA navegação real de um clique
   futuro. E o motivo de nunca deixar isso cair só no roteador(): pra um
   usuário LOGADO, hash "#/" (caminho vazio) é a rota do painel padrão
   Educação Continuada — sem essa função chamando mostrarTela('landing')
   diretamente, "Contato"/"Voltar" jogavam um usuário logado pro
   dashboard em vez de manter a landing pública que ele pediu. */
function irParaLandingPublica(idAncoraPendente){
  /* v13: quando ligada direto no addEventListener, esta função recebia o
     evento de clique como se fosse uma âncora. Só texto é âncora. */
  if(typeof idAncoraPendente !== 'string') idAncoraPendente = null;
  document.querySelectorAll('.aberto').forEach(el=>{
    if(el.id && /^landing-(nav-mobile|dropdown-servicos)/.test(el.id)) el.classList.remove('aberto');
  });
  if(idAncoraPendente) window.__scrollPendente = idAncoraPendente;
  if(window.location.hash !== '#/'){
    window.__mostrarLandingForcado = true;
    window.location.hash = '#/';
  }
  mostrarTela('landing');
  if(idAncoraPendente) aplicarScrollPendente();
  else window.scrollTo({top:0, behavior:'smooth'});
}
/* Todos os logotipos (cabeçalhos públicos e barra da área logada) levam
   sempre à página inicial da landing, por clique ou por Enter/Espaço. */
['landing-logo-link','landing-logo-link-qs','landing-logo-link-nt','landing-logo-link-equipe','landing-logo-link-servico',
 'landing-logo-link-executivo','brand-dash','brand-fiscal'].forEach(function(id){
  const el = document.getElementById(id);
  if(!el) return;
  el.addEventListener('keydown', function(e){
    if(e.key === 'Enter' || e.key === ' '){ e.preventDefault(); irParaLandingPublica(); }
  });
});
document.getElementById('landing-logo-link').addEventListener('click', ()=> irParaLandingPublica());
document.getElementById('brand-dash').addEventListener('click', ()=> irParaLandingPublica());
document.getElementById('brand-fiscal').addEventListener('click', ()=> irParaLandingPublica());

window.addEventListener('hashchange', function(){
  if(sessaoAtual) return; // logado: quem cuida disso e o roteador() do app
  const rota = (window.location.hash || '').replace(/^#\/?/, '');
  if(rota === 'login'){ mostrarTela('auth'); preencherEmailLembrado(); }
  else if(rota === 'quem-somos'){ mostrarTela('quem-somos'); }
  else if(rota === 'noticias' || rota === 'noticias/eua' || VM_SC_RE.test(rota)){ ntpAbrir(rota); }   /* v119 */
  else if(rota === 'equipe'){ mostrarTela('equipe'); }
  else if(rota.indexOf('servicos/') === 0){ mostrarTela('servico'); renderizarServico(rota.slice('servicos/'.length)); }
  else if(rota.indexOf('executivo/') === 0){ mostrarTela('executivo'); renderizarExecutivo(rota.slice('executivo/'.length)); }
  else { mostrarTela('landing'); aplicarScrollPendente(); }
});
