/* ---------- LANDING: âncora ativa (linha dourada) ---------- */
(function(){
  const secoesObservadas = ['inicio','contato'].map(id=>document.getElementById(id)).filter(Boolean);
  if(!secoesObservadas.length || typeof IntersectionObserver === 'undefined') return;
  const observer = new IntersectionObserver((entradas)=>{
    entradas.forEach(entrada=>{
      if(entrada.isIntersecting){
        document.querySelectorAll('.landing-nav a[data-anchor]').forEach(a=>a.classList.remove('landing-ativo'));
        const ativo = document.querySelector(`.landing-nav a[data-anchor="${entrada.target.id}"]`);
        if(ativo) ativo.classList.add('landing-ativo');
      }
    });
  }, {threshold:0.4});
  secoesObservadas.forEach(s=>observer.observe(s));
})();

