  if(_vmArt.ban !== undefined) vmPubNoTexto(document.getElementById('vm-texto'));   /* v131 */
  const palavras = [m.titulo, m.linha_fina].concat(corpo).join(' ').split(/\s+/).filter(Boolean).length;
