    const probs = ver.filter(c => !c.ok).flatMap(c => (c.detalhe || []).map(d => '<li class="' + (c.bloqueia ? '' : 'alerta') + '">' + escHtml((ROT[c.checagem] || c.checagem) + ': ' + d) + '</li>'));
    const refs = (Array.isArray(g.referencias) ? g.referencias : []).map(r => { const id = String(r.identificador ?? r.id ?? r.registro ?? r.id_registro ?? ''); const fo = (m.fontes || []).find(x => x.id === id) || {};
      return '<tr><td>' + escHtml(String(r.numero ?? r['número'] ?? r.valor ?? '')) + '</td><td>' + escHtml(id) + '</td><td>' + (fo.url ? '<a href="' + escHtml(fo.url) + '" target="_blank" rel="noopener noreferrer">' + escHtml(fo.fonte || fo.url) + '</a>' : '') + '</td></tr>'; }).join('');
    const pars = (Array.isArray(g.paragrafos) ? g.paragrafos : []).join('\n\n');
    return '<div class="vm-red-card" data-vm-red="' + m.id + '">'
