      + '<label for="vm-red-instr-' + m.id + '">Instrução para gerar de novo</label><textarea id="vm-red-instr-' + m.id + '" placeholder="Ex.: destaque o dólar no título"></textarea>'
      + '<div class="vm-red-linha"><button type="button" class="vm-red-bt vm-red-sec" data-vm-red-acao="regerar" data-id="' + m.id + '">Gerar de novo</button></div>'
