document.getElementById('vm-red-gerar').addEventListener('click', async ev => {
  const b = ev.currentTarget; b.disabled = true; vmRedMsg('Pedido enviado: o rascunho aparece aqui em 1 a 2 minutos (use “Atualizar”).');
  try{ await vmRpcAuth('vm_scanner_gerar'); }catch(e){ vmRedMsg(e.message); } finally { b.disabled = false; }
});
['vm-red-fila', 'vm-red-publicados'].forEach(alvo => document.getElementById(alvo).addEventListener('click', async ev => {
  const b = ev.target.closest('[data-vm-red-acao]'); if(!b) return;
  const id = Number(b.getAttribute('data-id')), acao = b.getAttribute('data-vm-red-acao'), val = k => (document.getElementById('vm-red-' + k + '-' + id).value || '').trim();
  b.disabled = true;
  let msg = '';
  try{
    if(acao === 'aprovar'){
      const c = vmRedCampos(id);
      await vmRpcAuth('vm_materia_aprovar', {p_id: id, p_titulo: c.titulo, p_linha_fina: c.linha_fina, p_paragrafos: c.paragrafos, p_chapeu: c.chapeu, p_justificativa: val('just') || null});
      _vmsc.d = undefined; vmCarregarScanner(); msg = 'Publicado. O Scanner aprovado já aparece na página.';
    } else if(acao === 'descartar'){
      await vmRpcAuth('vm_materia_descartar', {p_id: id, p_motivo: val('motivo')}); msg = 'Rascunho descartado.';
    } else if(acao === 'despublicar'){
      await vmRpcAuth('vm_materia_despublicar', {p_id: id, p_motivo: (document.getElementById('vm-red-motivopub-' + id).value || '').trim()});
      _vmsc.d = undefined; vmCarregarScanner(); msg = 'Scanner tirado do ar.';
    } else if(acao === 'regerar'){
      await vmRpcAuth('vm_materia_regerar', {p_id: id, p_instrucao: val('instr')}); msg = 'Pedido enviado: a nova versão aparece em 1 a 2 minutos (use “Atualizar”).';
    }
    await vmRedCarregar(msg);
  }catch(e){ vmRedMsg(e.message); b.disabled = false; }
}));

