/* Início / Serviços / Contato a partir de /quem-somos: o roteador só guarda
   um valor no hash por vez (rota OU âncora, nunca os dois), então a volta
   pra landing usa uma "âncora pendente": navega pra "#/" e, quando a
   landing aparecer, rola até a seção certa. */
window.__scrollPendente = null;
function aplicarScrollPendente(){
  if(!window.__scrollPendente) return;
  const idAlvo = window.__scrollPendente;
  window.__scrollPendente = null;
  const alvo = document.getElementById(idAlvo);
  if(alvo) setTimeout(()=> alvo.scrollIntoView({behavior:'smooth'}), 50);
}
document.querySelectorAll('#tela-quem-somos [data-alvo-pendente], #tela-noticias [data-alvo-pendente], #tela-servico [data-alvo-pendente], #tela-executivo [data-alvo-pendente], #tela-equipe [data-alvo-pendente]').forEach(a=>{
  a.addEventListener('click', function(e){
    e.preventDefault();
    ['landing-nav-mobile-qs','landing-dropdown-servicos-qs','landing-nav-mobile-nt','landing-dropdown-servicos-nt','landing-nav-mobile-servico','landing-nav-mobile-executivo'].forEach(id=>{
      const el = document.getElementById(id);
      if(el) el.classList.remove('aberto');
    });
    irParaLandingPublica(a.getAttribute('data-alvo-pendente'));
  });
});

