function renderizarExecutivo(slug){
  const info = EXECUTIVO_INFO[slug];
  if(!info){ mostrarTela('landing'); aplicarScrollPendente(); return; }
  document.querySelectorAll('#tela-executivo [data-slug-exec]').forEach(a=>{
    a.classList.toggle('landing-ativo', a.getAttribute('data-slug-exec')===slug);
  });
  document.getElementById('executivo-kicker').textContent = info.kicker;
  document.getElementById('executivo-titulo').textContent = info.titulo;
  document.getElementById('executivo-atualizado').textContent = 'Atualizado agora — ' + new Date().toLocaleString('pt-BR') + '. Números ilustrativos, a parametrizar com a operação real.';
  document.getElementById('executivo-kpis').innerHTML = info.kpis.map(k=>`
    <div class="exec-kpi">
      <span class="exec-kpi-label">${k.label}</span>
      <b class="exec-kpi-valor">${k.valor}</b>
      <span class="exec-kpi-delta ${k.tom}">${k.delta}</span>
    </div>`).join('');
  document.getElementById('executivo-paineis').innerHTML = info.paineis.map(p=>`
    <div class="exec-painel"><h4>${p.titulo}</h4><p>${p.texto}</p></div>`).join('');
  const idx = EXECUTIVO_ORDEM.indexOf(slug);
  document.getElementById('executivo-passo').textContent = (idx+1) + ' de ' + EXECUTIVO_ORDEM.length;
  if(typeof setTituloPagina === 'function') setTituloPagina(info.kicker.charAt(0) + info.kicker.slice(1).toLowerCase());
  window.scrollTo(0,0);
}
function slugExecutivoAdjacente(delta){
  const atual = (window.location.hash || '').replace(/^#\/?/, '').split('?')[0];
  const slugAtual = atual.indexOf('executivo/') === 0 ? atual.slice('executivo/'.length) : EXECUTIVO_ORDEM[0];
  const idx = EXECUTIVO_ORDEM.indexOf(slugAtual);
  const novoIdx = (idx + delta + EXECUTIVO_ORDEM.length) % EXECUTIVO_ORDEM.length;
  return EXECUTIVO_ORDEM[novoIdx];
}
