/* ---------- LANDING: carrossel executivo (4 slides, setas, dots, teclado) ----------
   Slide 0 é o brand splash — só a marca, sem nenhum outro elemento
   (nem os botões Entrar/Conhecer do rodapé do hero, que pertencem ao
   carrossel como um todo, não a um slide específico). Slides 1-3 são
   as 3 visões institucionais (Consultoria, Ativos, Educação e
   tributário). Cada seta/dot troca de fato o conteúdo, nunca a tela de
   login repetida. Loop nas duas pontas. Sem autoplay: usuário decide
   o ritmo. */
(function(){
  const slides = document.querySelectorAll('#landing-carousel .landing-slide-exec');
  const dots = document.querySelectorAll('#landing-dots button');
  const carousel = document.getElementById('landing-carousel');
  const ctaWrap = document.getElementById('landing-hero-cta-wrap');
  if(!slides.length) return;
  let atual = 0;

  function irPara(indice){
    slides[atual].classList.remove('ativo');
    dots[atual].classList.remove('ativo');
    atual = (indice + slides.length) % slides.length;
    slides[atual].classList.add('ativo');
    dots[atual].classList.add('ativo');
    if(ctaWrap) ctaWrap.style.display = slides[atual].classList.contains('landing-slide-splash') ? 'none' : 'flex';
  }
  function proximo(){ irPara(atual+1); }
  function anterior(){ irPara(atual-1); }

  document.getElementById('landing-seta-dir').addEventListener('click', proximo);
  document.getElementById('landing-seta-esq').addEventListener('click', anterior);
  dots.forEach(d=>{
    d.addEventListener('click', ()=> irPara(parseInt(d.getAttribute('data-ir'),10)));
  });
  document.addEventListener('keydown', function(e){
    if(document.getElementById('tela-landing').style.display === 'none') return;
    if(e.key === 'ArrowRight') proximo();
    if(e.key === 'ArrowLeft') anterior();
  });
})();

const EMAIL_LEMBRADO_KEY = 'gestao-fiscal-email-lembrado';

async function preencherEmailLembrado(){
  try{
    const valor = localStorage.getItem(EMAIL_LEMBRADO_KEY);
    if(valor){
      document.getElementById('login-email').value = valor;
    }
  }catch(e){ /* sem e-mail lembrado ainda, ou localStorage bloqueado — segue normalmente */ }
}

async function lembrarEmail(valor){
  try{
    valor = (valor || '').trim();
    if(valor){
      localStorage.setItem(EMAIL_LEMBRADO_KEY, valor);
    } else {
      localStorage.removeItem(EMAIL_LEMBRADO_KEY);
    }
  }catch(e){ /* falha ao salvar — não impede o uso normal do login */ }
}

document.getElementById('login-email').addEventListener('change', function(){
  lembrarEmail(this.value);
});

/* ---------- BARRA SUPERIOR DO MÓDULO FISCAL (Página 4) ---------- */
(function(){
  var wrapInvestimentos = document.getElementById('wrap-investimentos');
  var itemInvestimentos = document.getElementById('item-investimentos');
  var burger = document.getElementById('topbar-burger');
  var nav = document.getElementById('topbar-nav');

  document.querySelector('#topbar .topbar-item[data-destino="educacao"]').addEventListener('click', function(){
    voltarAoDashboardDoFiscal('educacao');
  });

  itemInvestimentos.addEventListener('click', function(){
    wrapInvestimentos.classList.toggle('aberto');
  });

  document.querySelectorAll('#submenu-investimentos button[data-destino]').forEach(function(btn){
    btn.addEventListener('click', function(){
      voltarAoDashboardDoFiscal(btn.getAttribute('data-destino'));
    });
  });

  document.addEventListener('click', function(e){
    if(!wrapInvestimentos.contains(e.target)) wrapInvestimentos.classList.remove('aberto');
  });

  burger.addEventListener('click', function(){
    nav.classList.toggle('aberto');
  });

  // "Gestão Fiscal e Financeira" já é o módulo desta própria página — fica sempre ativo, sem navegação
})();

/* ---------- BARRA SUPERIOR DO DASHBOARD (Página 3) ---------- */
(function(){
  var paineis = document.querySelectorAll('#tela-dashboard .painel');
  var itensTopbar = document.querySelectorAll('#topbar-nav-dash .topbar-item[data-painel]');
  var itemInvestimentos = document.getElementById('item-investimentos-dash');
  var burger = document.getElementById('topbar-burger-dash');
  var nav = document.getElementById('topbar-nav-dash');

  function marcarAtivo(painelId){
    // Limpa TODOS os indicadores do topbar (inclusive Gestão financeira/
    // fiscal, que usam data-rota em vez de data-painel) — senão o
    // sublinhado fica preso no último item do outro mecanismo.
    document.querySelectorAll('#topbar-nav-dash .topbar-item').forEach(function(b){ b.classList.remove('active'); });
    if(painelId === 'educacao' || painelId === 'certificacoes' || painelId === 'curso-certificacao'){
      document.querySelector('#topbar-nav-dash .topbar-item[data-painel="educacao"]').classList.add('active');
    } else if(painelId === 'investimentos-escolha' || painelId === 'leilao' || painelId === 'leilao-veiculos' || painelId === 'avaliacao-imoveis' || painelId === 'acoes' || painelId === 'mercado-imobiliario' || painelId === 'empresas'){
      itemInvestimentos.classList.add('active');
    } else if(painelId === 'calculadoras'){
      document.querySelector('#topbar-nav-dash .topbar-item[data-painel="calculadoras"]').classList.add('active');
    }
  }

  window.__pilhaPaineisDash = [];
  window.mostrarPainelDash = function(painelId, viaVoltar){
    // exigirLogin() centralizado (auth.js) — cobre todo painel logado,
    // inclusive Leilão (que é "público" dentro da área logada: qualquer
    // perfil vê, não só admin). Sem sessão, nunca chega a pintar a view.
    if(!exigirLogin()) return;
    if(painelId === 'fiscal'){
      abrirModuloFiscal();
      return;
    }
    /* v36: área fora do plano (SQL 34) */
    if(AREA_DO_PAINEL[painelId] && !areaLiberada(AREA_DO_PAINEL[painelId])){
      areaMostrarBloqueio(AREA_DO_PAINEL[painelId]);
      return;
    }
    var atual = document.querySelector('#tela-dashboard .painel.ativo');
    var atualId = atual ? atual.id.replace('painel-','') : null;
    if(painelId === 'educacao' && atualId !== 'educacao'){
      educacaoCategoriaAtiva = null; // entrando de fora -> sempre mostra as 3 categorias primeiro
      if(typeof renderizarEducacao === 'function') renderizarEducacao();
    }
    if(painelId === 'certificacoes' && typeof inicializarBuscaCertificacoes === 'function'){
      inicializarBuscaCertificacoes();
    }
    if(painelId === 'acoes' && typeof carregarCotacoesEOD === 'function'){
      carregarCotacoesEOD(); // v17: fechamento do último pregão (SQL 05)
      if(typeof carregarIndicadoresReais === 'function') carregarIndicadoresReais(); // v19: base CVM (SQL 08)
    }
    if(!viaVoltar && atualId && atualId !== painelId){
      window.__pilhaPaineisDash.push(atualId);
    }
    paineis.forEach(function(p){ p.classList.remove('ativo'); });
    var alvo = document.getElementById('painel-' + painelId);
    if(alvo) alvo.classList.add('ativo');
    marcarAtivo(painelId);
    nav.classList.remove('aberto');

    // aria-current (129º/134º): "você está aqui" no card da subárea visitada
    // por último, quando o usuário volta pro hub de Investimentos — nunca só
    // cor, o CSS também desenha um filete embaixo do card (ver .escolha-card[aria-current]).
    var subareasInvestimentos = ['acoes','leilao','leilao-veiculos','mercado-imobiliario','avaliacao-imoveis','empresas'];
    if(subareasInvestimentos.indexOf(painelId) !== -1){
      window.__ultimaSubareaInvestimentos = painelId;
    }
    document.querySelectorAll('#painel-investimentos-escolha .escolha-card[data-painel]').forEach(function(c){
      if(c.getAttribute('data-painel') === window.__ultimaSubareaInvestimentos) c.setAttribute('aria-current','true');
      else c.removeAttribute('aria-current');
    });

    // Título da aba / metadados — cada painel do dashboard tem o seu,
    // via o helper único setTituloPagina() (31º prompt).
    if(painelId === 'acoes'){
      setTituloPagina(
        'Mercado financeiro',
        'Cotações, screener de ações e simulação de carteira — Mercado financeiro Soliduns.'
      );
    } else if(painelId === 'educacao'){
      setTituloPagina('Educação continuada');
    } else if(painelId === 'leilao'){
      setTituloPagina('Leilão de imóveis');
    } else if(painelId === 'mercado-imobiliario'){
      setTituloPagina('Mercado imobiliário');
    } else if(painelId === 'empresas'){
      setTituloPagina('Compra e venda de empresas');
    } else if(painelId === 'investimentos-escolha'){
      setTituloPagina('Investimentos');
    } else if(painelId === 'calculadoras'){
      setTituloPagina('Calculadoras');
    } else if(painelId === 'certificacoes'){
      setTituloPagina('Certificações do Mercado Financeiro');
    } else {
      setTituloPagina(null);
    }
  };
  window.voltarPainelAnteriorDash = function(){
    if(window.__pilhaPaineisDash.length === 0) return false;
    var anterior = window.__pilhaPaineisDash.pop();
    window.mostrarPainelDash(anterior, true);
    return true;
  };

  itensTopbar.forEach(function(btn){
    btn.addEventListener('click', function(){
      navegarParaPainel(btn.getAttribute('data-painel'));
    });
  });

  document.querySelectorAll('#tela-dashboard .escolha-card[data-painel]').forEach(function(btn){
    btn.addEventListener('click', function(){
      navegarParaPainel(btn.getAttribute('data-painel'));
    });
  });

  document.querySelectorAll('#tela-dashboard .voltar-link[data-painel], #tela-dashboard .breadcrumb-link[data-painel]').forEach(function(btn){
    btn.addEventListener('click', function(){
      navegarParaPainel(btn.getAttribute('data-painel'));
    });
  });

  burger.addEventListener('click', function(){
    nav.classList.toggle('aberto');
  });
})();

