/* Estado dos valores dos campos dinâmicos — sobrevive à troca de tipo.
   Campos que não existem mais no tipo novo simplesmente não são lidos
   nem exibidos (efeito prático de "foram limpos"), mas se o usuário
   voltar para um tipo que tem o mesmo campo, o valor reaparece. */
let filtroImovelValores = {};

function imCampoRotuloUnidade(unidade){
  return unidade ? ` (${unidade})` : '';
}

function renderCampoChip(campo){
  const atual = filtroImovelValores[campo.id] || '';
  const botoes = campo.opcoes.map(o=>
    `<button type="button" class="leilao-chip${o.v===atual?' active':''}" data-campo="${campo.id}" data-valor="${o.v}">${o.l}</button>`
  ).join('');
  return `<div><label>${campo.label}</label><div class="leilao-chips" data-chips-de="${campo.id}">${botoes}</div></div>`;
}
function renderCampoSelect(campo){
  const atual = filtroImovelValores[campo.id] || '';
  const opts = campo.opcoes.map(o=> `<option value="${o.v}" ${o.v===atual?'selected':''}>${o.l}</option>`).join('');
  return `<div><label>${campo.label}</label><select id="${campo.id}" data-campo-dinamico="select">${opts}</select></div>`;
}
function renderCampoText(campo){
  const atual = filtroImovelValores[campo.id] || '';
  return `<div><label>${campo.label}</label><input type="text" id="${campo.id}" data-campo-dinamico="text" value="${atual}"></div>`;
}
function renderCampoCheckbox(campo){
  const atual = !!filtroImovelValores[campo.id];
  return `<div style="grid-column:1/-1; display:flex; align-items:center; gap:8px;">
    <input type="checkbox" id="${campo.id}" data-campo-dinamico="checkbox" ${atual?'checked':''} style="width:auto; margin:0;">
    <label style="margin:0; text-transform:none; font-size:13px; color:var(--text);" for="${campo.id}">${campo.label}</label>
  </div>`;
}
function renderCampoRangeArea(campo){
  const idDe = campo.id+'-de', idAte = campo.id+'-ate';
  const valDe = filtroImovelValores[idDe] || '', valAte = filtroImovelValores[idAte] || '';
  if(campo.semDe){
    return `<div><label>${campo.label}${imCampoRotuloUnidade(campo.unidade)}</label>
      <input type="number" min="0" id="${idAte}" data-campo-dinamico="numero" placeholder="Ex.: 10" value="${valAte}"></div>`;
  }
  return `<div><label>${campo.label}${imCampoRotuloUnidade(campo.unidade)}</label>
    <div style="display:flex; gap:6px;">
      <input type="number" min="0" id="${idDe}" data-campo-dinamico="numero" placeholder="De" value="${valDe}" style="flex:1;">
      <input type="number" min="0" id="${idAte}" data-campo-dinamico="numero" placeholder="Até" value="${valAte}" style="flex:1;">
    </div>
  </div>`;
}
function renderCampoRangeMoney(campo){
  const idDe = campo.id+'-de', idAte = campo.id+'-ate';
  const valDe = filtroImovelValores[idDe] || '', valAte = filtroImovelValores[idAte] || '';
  return `<div><label>${campo.label} (R$)</label>
    <div style="display:flex; gap:6px;">
      <input type="text" inputmode="decimal" id="${idDe}" data-campo-dinamico="moeda" placeholder="R$ 0,00" value="${valDe}" oninput="aplicarMascaraMoeda(this)" onblur="finalizarMascaraMoeda(this)" style="flex:1;">
      <input type="text" inputmode="decimal" id="${idAte}" data-campo-dinamico="moeda" placeholder="Sem limite" value="${valAte}" oninput="aplicarMascaraMoeda(this)" onblur="finalizarMascaraMoeda(this)" style="flex:1;">
    </div>
  </div>`;
}
function renderCampoDinamico(campo, tipoAtual){
  if(campo.soSeTipo && !campo.soSeTipo.includes(tipoAtual)) return '';
  if(campo.tipo==='chip') return renderCampoChip(campo);
  if(campo.tipo==='select') return renderCampoSelect(campo);
  if(campo.tipo==='text') return renderCampoText(campo);
  if(campo.tipo==='checkbox') return renderCampoCheckbox(campo);
  if(campo.tipo==='range-area') return renderCampoRangeArea(campo);
  if(campo.tipo==='range-money') return renderCampoRangeMoney(campo);
  return '';
}

function grupoCamposAtual(){
  const tipo = document.getElementById('im-filtro-tipo').value;
  if(!tipo) return {chave:'TODOS', tipo};
  const letra = TIPO_PARA_GRUPO_CAMPOS[tipo];
  return {chave: letra || 'TODOS', tipo};
}

function renderizarLinha2EMaisFiltros(){
  const {chave, tipo} = grupoCamposAtual();
  const config = CAMPOS_GRUPO[chave] || CAMPOS_GRUPO.TODOS;

  const linha2El = document.getElementById('im-linha2');
  linha2El.innerHTML = config.linha2.map(c=> renderCampoDinamico(c, tipo)).join('');

  const maisFiltrosEl = document.getElementById('im-mais-filtros-conteudo');
  maisFiltrosEl.innerHTML = config.maisFiltros.map(secao=>{
    const camposHtml = secao.campos.map(c=> renderCampoDinamico(c, tipo)).filter(h=>h).join('');
    if(!camposHtml) return '';
    return `<div class="im-mf-secao"><h3>${secao.secao}</h3><div class="im-mf-grid">${camposHtml}</div></div>`;
  }).join('');

  ligarEventosCamposDinamicos();
}

function ligarEventosCamposDinamicos(){
  document.querySelectorAll('#im-linha2 .leilao-chips, #im-mais-filtros-conteudo .leilao-chips').forEach(grupo=>{
    grupo.querySelectorAll('.leilao-chip').forEach(chip=>{
      chip.addEventListener('click', ()=>{
        grupo.querySelectorAll('.leilao-chip').forEach(c=>c.classList.remove('active'));
        chip.classList.add('active');
        filtroImovelValores[chip.getAttribute('data-campo')] = chip.getAttribute('data-valor');
        renderizarImoveis();
      });
    });
  });
  document.querySelectorAll('[data-campo-dinamico="select"]').forEach(sel=>{
    sel.addEventListener('change', ()=>{ filtroImovelValores[sel.id] = sel.value; renderizarImoveis(); });
  });
  document.querySelectorAll('[data-campo-dinamico="checkbox"]').forEach(chk=>{
    chk.addEventListener('change', ()=>{ filtroImovelValores[chk.id] = chk.checked; renderizarImoveis(); });
  });
  document.querySelectorAll('[data-campo-dinamico="text"]').forEach(inp=>{
    inp.addEventListener('input', ()=>{ filtroImovelValores[inp.id] = inp.value; });
    inp.addEventListener('blur', renderizarImoveis);
  });
  document.querySelectorAll('[data-campo-dinamico="numero"]').forEach(inp=>{
    inp.addEventListener('input', ()=>{ filtroImovelValores[inp.id] = inp.value; });
    inp.addEventListener('blur', renderizarImoveis);
  });
  document.querySelectorAll('[data-campo-dinamico="moeda"]').forEach(inp=>{
    inp.addEventListener('input', ()=>{ filtroImovelValores[inp.id] = inp.value; });
    inp.addEventListener('blur', renderizarImoveis);
  });
}

/* ---------- BAIRRO (multi-select, dependente da cidade) ---------- */
const BAIRROS_POR_CIDADE = {
  'Brasília': ['Asa Norte','Asa Sul','Águas Claras','Lago Norte','Lago Sul','Sudoeste','Noroeste','Taguatinga'],
  'Goiânia': ['Setor Bueno','Setor Oeste','Jardim Goiás','Setor Marista','Setor Central'],
  'Formosa': ['Centro','Buritis','Vila São José']
};
let filtroImovelBairrosSelecionados = [];

function atualizarResumoBairro(){
  const busca = document.getElementById('im-filtro-bairro-busca');
  const n = filtroImovelBairrosSelecionados.length;
  busca.value = n===0 ? '' : (n===1 ? filtroImovelBairrosSelecionados[0] : `${n} bairros selecionados`);
}

function mostrarListaBairro(){
  const cidade = document.getElementById('im-filtro-cidade').value;
  const lista = document.getElementById('im-filtro-bairro-lista');
  const bairros = (cidade && BAIRROS_POR_CIDADE[cidade]) || [];
  if(bairros.length===0){
    lista.innerHTML = '<div class="leilao-cidade-vazio">Nenhum bairro cadastrado para esta cidade.</div>';
  } else {
    lista.innerHTML = bairros.map(b=>{
      const marcado = filtroImovelBairrosSelecionados.includes(b);
      return `<label style="display:flex; align-items:center; gap:8px; padding:8px 11px; cursor:pointer; font-size:13px; color:var(--text);">
        <input type="checkbox" data-bairro="${b}" ${marcado?'checked':''} style="width:auto; margin:0;">${b}
      </label>`;
    }).join('');
  }
  lista.style.display = 'block';
  lista.querySelectorAll('input[type="checkbox"]').forEach(chk=>{
    chk.addEventListener('change', ()=>{
      const b = chk.getAttribute('data-bairro');
      if(chk.checked){ if(!filtroImovelBairrosSelecionados.includes(b)) filtroImovelBairrosSelecionados.push(b); }
      else { filtroImovelBairrosSelecionados = filtroImovelBairrosSelecionados.filter(x=>x!==b); }
      atualizarResumoBairro();
      renderizarImoveis();
    });
  });
}
function atualizarEstadoCampoBairro(){
  const cidade = document.getElementById('im-filtro-cidade').value;
  const busca = document.getElementById('im-filtro-bairro-busca');
  if(cidade && BAIRROS_POR_CIDADE[cidade]){
    busca.disabled = false;
    busca.placeholder = '-- Selecione o(s) bairro(s) --';
  } else {
    busca.disabled = true;
    busca.placeholder = '-- Escolha a cidade --';
    filtroImovelBairrosSelecionados = [];
    atualizarResumoBairro();
  }
}

/* ---------- FILTRO GERAL (usa a mesma config de campos do grupo atual) ---------- */
function chaveDadosDoId(id){
  // "im-quartos" -> "quartos" | "im-mf-piscina" -> "mf.piscina" | "im-area-util-de" -> "area-util-de"
  let s = id.replace(/^im-/, '');
  if(s.startsWith('mf-')) return 'mf.'+s.replace(/^mf-/, '');
  return s;
}
function lerValorImovel(im, chave){
  if(chave.startsWith('mf.')) return im.mf ? im.mf[chave.slice(3)] : undefined;
  return im[chave];
}

function imovelPassaNosCamposDinamicos(im, config, tipoAtual){
  const todosCampos = config.linha2.concat(config.maisFiltros.flatMap(s=>s.campos));
  for(const campo of todosCampos){
    if(campo.soSeTipo && !campo.soSeTipo.includes(tipoAtual)) continue;
    const valorFiltro = filtroImovelValores[campo.id];

    if(campo.tipo==='chip'){
      if(!valorFiltro) continue;
      const chave = chaveDadosDoId(campo.id);
      const v = lerValorImovel(im, chave);
      if(v===undefined || v===null || Number(v) < Number(valorFiltro)) return false;
    } else if(campo.tipo==='select'){
      if(!valorFiltro) continue;
      const chave = chaveDadosDoId(campo.id);
      const v = lerValorImovel(im, chave);
      if(String(v||'') !== String(valorFiltro)) return false;
    } else if(campo.tipo==='checkbox'){
      if(!valorFiltro) continue;
      const chave = chaveDadosDoId(campo.id);
      if(lerValorImovel(im, chave) !== true) return false;
    } else if(campo.tipo==='text'){
      if(!valorFiltro) continue;
      const chave = chaveDadosDoId(campo.id);
      const v = (lerValorImovel(im, chave)||'').toString().toLowerCase();
      if(!v.includes(valorFiltro.toLowerCase())) return false;
    } else if(campo.tipo==='range-area'){
      const chaveBase = chaveDadosDoId(campo.id);
      const de = parseFloat(filtroImovelValores[campo.id+'-de']);
      const ate = parseFloat(filtroImovelValores[campo.id+'-ate']);
      const v = parseFloat(lerValorImovel(im, chaveBase));
      if(!isNaN(de) || !isNaN(ate)){
        if(isNaN(v)) return false;
        if(!isNaN(de) && v < de) return false;
        if(!isNaN(ate) && v > ate) return false;
      }
    } else if(campo.tipo==='range-money'){
      const chaveBase = chaveDadosDoId(campo.id);
      const de = parseMoeda(filtroImovelValores[campo.id+'-de']);
      const ate = parseMoeda(filtroImovelValores[campo.id+'-ate']);
      const v = parseFloat(lerValorImovel(im, chaveBase));
      if(!isNaN(de) || !isNaN(ate)){
        if(isNaN(v)) return false;
        if(!isNaN(de) && v < de) return false;
        if(!isNaN(ate) && v > ate) return false;
      }
    }
  }
  return true;
}

function imoveisFiltrados(){
  const uf = document.getElementById('im-filtro-uf').value;
  const cidade = document.getElementById('im-filtro-cidade').value;
  const tipo = document.getElementById('im-filtro-tipo').value;
  const precoMin = parseMoeda(document.getElementById('im-filtro-preco-min').value);
  const precoMax = parseMoeda(document.getElementById('im-filtro-preco-max').value);

  const {chave} = grupoCamposAtual();
  const config = CAMPOS_GRUPO[chave] || CAMPOS_GRUPO.TODOS;

  return imoveisDados.filter(im=>{
    if(uf && im.uf !== uf) return false;
    if(cidade && im.cidade !== cidade) return false;
    if(filtroImovelBairrosSelecionados.length>0 && !filtroImovelBairrosSelecionados.includes(im.bairro)) return false;
    if(tipo && vitNormTipo(im.tipo) !== tipo) return false;   /* v41: tipos antigos */
    if(!isNaN(precoMin) && im.preco < precoMin) return false;
    if(!isNaN(precoMax) && im.preco > precoMax) return false;
    if(!imovelPassaNosCamposDinamicos(im, config, tipo)) return false;
    return true;
  });
}

