/* ==========================================================================
   VALIDAÇÃO DOS DADOS DE DEMONSTRAÇÃO (leilão, imóvel, empresa)
   Cada item passa pelo schema mínimo do seu tipo antes de entrar na
   lista renderizada. Item que não bate é descartado com console.warn
   — nunca quebra o card, nunca deixa vazar campo fora do contrato
   (ex.: cnpj/razao_social/inscricao em empresa). Preço/lance em texto
   ("R$ 100.000,00") é convertido para número; se não der número, o
   item fica de fora, sem crash. Nunca busca em domínio de terceiro
   para "consertar" o JSON — só aceita ou descarta.
   ========================================================================== */
const parseBRL = parseMoeda; // mesma função já usada na máscara de moeda do site

function validarUF(uf){
  const s = (uf||'').toString().trim().toUpperCase();
  return /^[A-Z]{2}$/.test(s) ? s : null;
}
function paraNumero(valor){
  if(typeof valor === 'number') return isNaN(valor) ? null : valor;
  if(typeof valor === 'string'){
    const n = parseBRL(valor);
    return isNaN(n) ? null : n;
  }
  return null;
}
function validarItemLeilao(item){
  if(!item || typeof item !== 'object') return null;
  const uf = validarUF(item.uf);
  const lanceMinimo = paraNumero(item.lance_minimo);
  if(!item.id || !uf || !item.modalidade || lanceMinimo===null || !item.status){
    console.warn('[validarLista] lote de leilão recusado (schema: id, uf, modalidade, lance_minimo, status):', item);
    return null;
  }
  return {...item, uf, lance_minimo: lanceMinimo};
}
function validarItemImovelSchema(item){
  if(!item || typeof item !== 'object') return null;
  const uf = validarUF(item.uf);
  const preco = paraNumero(item.preco);
  if(!item.id || !uf || !item.tipo || preco===null){
    console.warn('[validarLista] imóvel recusado (schema: id, uf, tipo, preco):', item);
    return null;
  }
  return {...item, uf, preco};
}
function validarItemEmpresaSchema(item){
  if(!item || typeof item !== 'object') return null;
  if('cnpj' in item || 'razao_social' in item || 'inscricao' in item){
    console.warn('[validarLista] operação recusada — campo proibido (cnpj/razao_social/inscricao):', item);
    return null;
  }
  const uf = validarUF(item.uf);
  if(!item.id || !item.titulo || !item.setor || !uf || !item.faixa_faturamento || !item.status){
    console.warn('[validarLista] operação recusada (schema: id, titulo, setor, uf, faixa_faturamento, status):', item);
    return null;
  }
  return {...item, uf};
}
/* tipo: 'leilao' | 'imovel' | 'empresa'. Lista inválida inteira (ou
   vazia) simplesmente vira []; quem chama decide a mensagem de vazio. */
function validarLista(tipo, array){
  if(!Array.isArray(array)) return [];
  const validador = tipo==='leilao' ? validarItemLeilao
    : tipo==='imovel' ? validarItemImovelSchema
    : tipo==='empresa' ? validarItemEmpresaSchema
    : null;
  if(!validador) return [];
  return array.map(validador).filter(x=>x!==null);
}

/* ---------- TESTE MANUAL DE validarLista (dev-only) ----------
   NÃO faz parte da navbar nem roda sozinho. Ferramenta pra quem for
   mexer no código: abra o console (F12) e chame
   rodarTestesValidacao() pra rodar os 6 casos do contrato de dados
   contra o código REAL de produção (não uma cópia). Sem framework
   (sem Jest/Cypress/Mocha) — só console.assert. Ver também
   testes/validacao.test.js (roda no Node, fora do navegador). */
window.rodarTestesValidacao = function(){
  let passou = 0;
  const total = 6;
  function caso(n, descricao, condicao){
    console.assert(condicao, `[validarLista] caso ${n} falhou: ${descricao}`);
    if(condicao) passou++;
    console.log(`${condicao ? '[OK]' : '[FALHOU]'} ${n}) ${descricao}`);
  }
  const r1 = validarLista('leilao', [{id:'lote_1', uf:'SP', modalidade:'judicial', lance_minimo:50000, status:'aberto'}]);
  caso(1, 'leilão válido entra na lista', r1.length===1 && r1[0].id==='lote_1');

  const r2 = validarLista('leilao', [{id:'lote_2', uf:'DF', modalidade:'extrajudicial', lance_minimo:'R$ 100.000,00', status:'aberto'}]);
  caso(2, 'lance em texto "R$ 100.000,00" vira number 100000', r2.length===1 && r2[0].lance_minimo===100000);

  const r3 = validarLista('empresa', [{id:'emp_x', titulo:'Teste', setor:'saude', uf:'DF', faixa_faturamento:'2M-5M', status:'disponivel', cnpj:'12.345.678/0001-99'}]);
  caso(3, 'empresa com campo cnpj é recusada', r3.length===0);

  const r4 = validarLista('imovel', [{id:'im_x', uf:'RJ', tipo:'casa', preco:'abc'}]);
  caso(4, 'imóvel com preco "abc" é recusado', r4.length===0);

  let r5, crashou = false;
  try{ r5 = validarLista('empresa', []); }catch(e){ crashou = true; }
  caso(5, 'array vazio retorna [] sem crash', !crashou && Array.isArray(r5) && r5.length===0);

  const r6 = validarLista('imovel', [{id:'im_y', uf:'df', tipo:'apartamento', preco:300000}]);
  caso(6, 'UF "df" minúscula normaliza para "DF" e é aceita', r6.length===1 && r6[0].uf==='DF');

  console.log(`\nResultado: ${passou}/${total}`);
  return passou === total;
};

