function carregarBaseLeiloesLocal(){   /* v40: modo local; online lê do servidor */
  try{
    const bruto = localStorage.getItem(LEILOES_BASE_KEY);
    if(bruto) return validarLista('leilao', JSON.parse(bruto));
  }catch(e){ /* localStorage indisponível — segue com base vazia */ }
  // Primeira vez nesse navegador: semeia com os 3 exemplos fictícios
  // como ponto de partida editável (não é mais a fonte fixa).
  salvarBaseLeiloesLocal(LEILOES_DEMO_EMBUTIDO);
  return validarLista('leilao', LEILOES_DEMO_EMBUTIDO);
}

function salvarBaseLeiloesLocal(lista){
  try{ localStorage.setItem(LEILOES_BASE_KEY, JSON.stringify(lista)); }
  catch(e){ /* falha ao salvar — segue sem persistir */ }
}

async function carregarLeiloes(){
  // A base única, hoje, é o localStorage administrado por esta própria
  // página. Quando o backend de /api/leiloes existir de verdade, o
  // visitante passa a ler de lá, sem nenhuma outra mudança no front.
  try{
    const resp = await fetch('/api/leiloes');
    if(!resp.ok) throw new Error('endpoint ainda não existe');
    leiloesDados = await resp.json();
  }catch(e){
    leiloesDados = carregarBaseLeiloes();
  }
  popularFiltroUF();
  renderizarLeiloes();
}

function popularFiltroUF(){
  const selUf = document.getElementById('filtro-uf');
  selUf.innerHTML = '<option value="">Todas</option>' +
    UF_LIST.map(u=>`<option value="${u.sigla}">${u.sigla} — ${u.nome}</option>`).join('');
}

function leiloesFiltradosV1(){
  const uf = document.getElementById('filtro-uf').value;
  const cidade = document.getElementById('filtro-cidade').value;
  const modalidade = document.getElementById('filtro-tipo').value;
  const imovel = document.getElementById('filtro-imovel').value;
  const quartosFiltro = filtroQuartosAtual;
  const precoMin = parseMoeda(document.getElementById('filtro-preco-min').value) || 0;
  const precoMaxRaw = parseMoeda(document.getElementById('filtro-preco-max').value);
  const precoMax = isNaN(precoMaxRaw) ? Infinity : precoMaxRaw;
  return leiloesDados.filter(l =>
    (!uf || l.uf===uf) &&
    (!cidade || l.cidade===cidade) &&
    (!modalidade || l.modalidade===modalidade) &&
    (!imovel || l.tipo_imovel===imovel) &&
    correspondeQuartos(l, quartosFiltro) &&
    l.lance_minimo >= precoMin && l.lance_minimo <= precoMax
  );
}

function correspondeQuartos(lote, selecionado){
  if(selecionado === '') return true; // "Todos" — não restringe, mesmo lotes sem o campo
  if(typeof lote.quartos !== 'number') return false; // sem quartos (terreno/comercial) some se um número específico foi escolhido
  if(selecionado === '4+') return lote.quartos >= 4;
  return lote.quartos === parseInt(selecionado, 10);
}

function renderizarLeiloesV1(){
  const grid = document.getElementById('leilao-grid');
  const vazio = document.getElementById('leilao-vazio');
  const semResultado = document.getElementById('leilao-sem-resultado');
  const contador = document.getElementById('leilao-contador');

  if(leiloesDados.length === 0){
    grid.innerHTML=''; grid.style.display='none';
    vazio.style.display='block'; semResultado.style.display='none';
    contador.textContent = '';
    return;
  }

  const lista = leiloesFiltrados();
  vazio.style.display='none';
  contador.textContent = lista.length===1 ? '1 lote encontrado' : `${lista.length} lotes encontrados`;

  if(lista.length===0){
    grid.innerHTML=''; grid.style.display='none';
    semResultado.style.display='block';
    return;
  }
  semResultado.style.display='none';
  grid.style.display='grid';

  grid.innerHTML = lista.map(l => {
    const capa = (l.fotos || []).find(f=>f.capa) || (l.fotos || [])[0];
    return `
    <button type="button" class="leilao-card" data-id="${l.id}">
      <div class="leilao-card-foto">${capa ? `<img src="${capa.src}" alt="${capa.alt||l.titulo}">` : 'Foto não disponível'}</div>
      <div class="leilao-card-body">
        <span class="leilao-card-tipo ${l.modalidade}">${l.modalidade}</span>
        <h3>${l.titulo}</h3>
        <div class="leilao-card-linha"><span>Local</span><b>${l.cidade}/${l.uf}</b></div>
        ${typeof l.quartos === 'number' ? `<div class="leilao-card-linha"><span>Quartos</span><b>${l.quartos===0 ? 'Kit/Studio' : l.quartos}</b></div>` : ''}
        <div class="leilao-card-linha"><span>Lance mínimo</span><b>${formatBRL(l.lance_minimo)}</b></div>
        <div class="leilao-card-linha"><span>1ª praça</span><b>${formatarDataBR(l.praca1)}</b></div>
        <div class="leilao-card-linha"><span>2ª praça</span><b>${formatarDataBR(l.praca2)}</b></div>
        <div class="leilao-card-linha"><span>Leiloeiro</span><b>${l.leiloeiro || "—"}</b></div>
        <div class="leilao-card-linha"><span>Edital nº</span><b>${l.edital || "—"}</b></div>
        <span class="leilao-card-status">${l.status}</span>
      </div>
    </button>
  `;}).join('');

  grid.querySelectorAll('.leilao-card').forEach(card=>{
    card.addEventListener('click', ()=> abrirFichaLeilao(card.getAttribute('data-id')));
  });
}

