popularUFFormularioLote();

function mostrarListaCidadeFormulario(termo){
  const uf = document.getElementById('lf-uf').value;
  const lista = document.getElementById('lf-cidade-lista');
  if(!uf){ lista.style.display='none'; return; }
  const cidades = (CIDADES_POR_UF && CIDADES_POR_UF[uf]) || CIDADES_POR_UF_EMBUTIDO[uf] || [];
  const termoNorm = normalizarTexto(termo);
  const filtradas = termoNorm ? cidades.filter(c => normalizarTexto(c).includes(termoNorm)) : cidades;

  lista.innerHTML = filtradas.length
    ? filtradas.slice(0, 80).map(c => `<button type="button" data-cidade="${c}">${c}</button>`).join('')
    : '<div class="leilao-cidade-vazio">Nenhuma cidade encontrada.</div>';
  lista.style.display = 'block';

  lista.querySelectorAll('button[data-cidade]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      document.getElementById('lf-cidade').value = btn.getAttribute('data-cidade');
      document.getElementById('lf-cidade-busca').value = btn.getAttribute('data-cidade');
      lista.style.display = 'none';
      atualizarPreviewFormulario();
    });
  });
}

document.getElementById('lf-uf').addEventListener('change', function(){
  const buscaCidade = document.getElementById('lf-cidade-busca');
  document.getElementById('lf-cidade').value = '';
  buscaCidade.value = '';
  if(this.value){
    buscaCidade.disabled = false;
    buscaCidade.placeholder = '-- Selecione a cidade --';
  } else {
    buscaCidade.disabled = true;
    buscaCidade.placeholder = '-- Escolha a UF --';
    document.getElementById('lf-cidade-lista').style.display = 'none';
  }
  atualizarPreviewFormulario();
});
document.getElementById('lf-cidade-busca').addEventListener('input', function(){
  document.getElementById('lf-cidade').value = '';
  mostrarListaCidadeFormulario(this.value);
});
document.getElementById('lf-cidade-busca').addEventListener('focus', function(){
  if(!this.disabled) mostrarListaCidadeFormulario(this.value);
});

/* ---------- MÍDIA DO LOTE (fotos + vídeos) ----------
   v1 sem servidor: guardado como Data URL dentro do próprio JSON do
   lote (mesma base local da pauta). Em produção, trocar por
   POST /api/lotes/:id/midia no NOSSO backend — o navegador nunca
   busca foto/vídeo em site de leiloeiro. */
let fotosFormulario = [];
let videosFormulario = [];
const LIMITE_FOTOS = 12;
const LIMITE_FOTO_MB = 5;
const LIMITE_VIDEOS = 2;
const LIMITE_VIDEO_MB = 40;

function lerArquivoComoDataURL(arquivo){
  return new Promise((resolve, reject)=>{
    const leitor = new FileReader();
    leitor.onload = ()=> resolve(leitor.result);
    leitor.onerror = reject;
    leitor.readAsDataURL(arquivo);
  });
}

function renderizarPreviewFotos(){
  const grid = document.getElementById('lf-fotos-grid');
  grid.innerHTML = fotosFormulario.map((f,i)=>`
    <div class="lf-foto-item ${f.capa?'capa':''}">
      ${f.capa ? '<span class="lf-foto-capa-selo">Capa</span>' : ''}
      <img src="${f.src}" alt="${f.alt||''}">
      <input type="text" class="lf-foto-alt" data-i="${i}" placeholder="Alt text (opcional)" value="${f.alt||''}">
      <div class="lf-foto-acoes">
        <button type="button" class="lf-btn-capa" data-i="${i}">Capa</button>
        <button type="button" class="lf-btn-subir" data-i="${i}" ${i===0?'disabled':''}>&uarr;</button>
        <button type="button" class="lf-btn-descer" data-i="${i}" ${i===fotosFormulario.length-1?'disabled':''}>&darr;</button>
        <button type="button" class="lf-btn-excluir" data-i="${i}">Excluir</button>
      </div>
    </div>
  `).join('');

  grid.querySelectorAll('.lf-btn-capa').forEach(b=> b.addEventListener('click', ()=>{
    const i = parseInt(b.getAttribute('data-i'),10);
    fotosFormulario.forEach((f,idx)=> f.capa = (idx===i));
    renderizarPreviewFotos();
  }));
  grid.querySelectorAll('.lf-btn-subir').forEach(b=> b.addEventListener('click', ()=>{
    const i = parseInt(b.getAttribute('data-i'),10);
    if(i>0){ [fotosFormulario[i-1], fotosFormulario[i]] = [fotosFormulario[i], fotosFormulario[i-1]]; renderizarPreviewFotos(); }
  }));
  grid.querySelectorAll('.lf-btn-descer').forEach(b=> b.addEventListener('click', ()=>{
    const i = parseInt(b.getAttribute('data-i'),10);
    if(i<fotosFormulario.length-1){ [fotosFormulario[i+1], fotosFormulario[i]] = [fotosFormulario[i], fotosFormulario[i+1]]; renderizarPreviewFotos(); }
  }));
  grid.querySelectorAll('.lf-btn-excluir').forEach(b=> b.addEventListener('click', ()=>{
    const i = parseInt(b.getAttribute('data-i'),10);
    const eraCapa = fotosFormulario[i].capa;
    fotosFormulario.splice(i,1);
    if(eraCapa && fotosFormulario.length) fotosFormulario[0].capa = true;
    renderizarPreviewFotos();
  }));
  grid.querySelectorAll('.lf-foto-alt').forEach(inp=> inp.addEventListener('input', ()=>{
    const i = parseInt(inp.getAttribute('data-i'),10);
    fotosFormulario[i].alt = inp.value;
  }));
  atualizarPreviewFormulario();
}

document.getElementById('lf-fotos-input').addEventListener('change', async function(){
  if(!ehAdmin()) return;
  const msg = document.getElementById('lf-fotos-msg');
  msg.style.display = 'none';
  const arquivos = Array.from(this.files || []);
  const avisos = [];

  for(const arquivo of arquivos){
    if(fotosFormulario.length >= LIMITE_FOTOS){ avisos.push(`Limite de ${LIMITE_FOTOS} fotos atingido.`); break; }
    if(arquivo.size > LIMITE_FOTO_MB*1024*1024){ avisos.push(`"${arquivo.name}" passa de ${LIMITE_FOTO_MB}MB — ignorada.`); continue; }
    if(!['image/jpeg','image/png','image/webp'].includes(arquivo.type)){ avisos.push(`"${arquivo.name}" não é JPEG/PNG/WEBP — ignorada.`); continue; }
    const src = await lerArquivoComoDataURL(arquivo);
    fotosFormulario.push({id:'foto-'+Date.now()+'-'+Math.random().toString(36).slice(2,7), src, capa: fotosFormulario.length===0, alt:''});
  }
  if(avisos.length){ msg.style.display='block'; msg.textContent = avisos.join(' '); }
  this.value = '';
  renderizarPreviewFotos();
});

function renderizarPreviewVideos(){
  const lista = document.getElementById('lf-videos-lista');
  lista.innerHTML = videosFormulario.map((v,i)=>`
    <div class="lf-video-item">
      <span>${v.tipo==='arquivo' ? '📎 ' : '🔗 '}${v.src.length>70 ? v.src.slice(0,70)+'…' : v.src}</span>
      <button type="button" class="lf-btn-video-excluir" data-i="${i}">Excluir</button>
    </div>
  `).join('');
  lista.querySelectorAll('.lf-btn-video-excluir').forEach(b=> b.addEventListener('click', ()=>{
    videosFormulario.splice(parseInt(b.getAttribute('data-i'),10), 1);
    renderizarPreviewVideos();
  }));
}

document.getElementById('lf-video-input').addEventListener('change', async function(){
  if(!ehAdmin()) return;
  const msg = document.getElementById('lf-videos-msg');
  msg.style.display = 'none';
  const arquivo = this.files && this.files[0];
  if(!arquivo) return;
  if(videosFormulario.length >= LIMITE_VIDEOS){
    msg.style.display='block'; msg.textContent = `Limite de ${LIMITE_VIDEOS} vídeos atingido.`;
    this.value = ''; return;
  }
  if(!['video/mp4','video/webm'].includes(arquivo.type)){
    msg.style.display='block'; msg.textContent = `"${arquivo.name}" não é MP4/WEBM.`;
    this.value = ''; return;
  }
  if(arquivo.size > LIMITE_VIDEO_MB*1024*1024){
    msg.style.display='block'; msg.textContent = `"${arquivo.name}" passa de ${LIMITE_VIDEO_MB}MB.`;
    this.value = ''; return;
  }
  const src = await lerArquivoComoDataURL(arquivo);
  videosFormulario.push({id:'video-'+Date.now(), src, tipo:'arquivo'});
  this.value = '';
  renderizarPreviewVideos();
});

document.getElementById('btn-add-video-url').addEventListener('click', function(){
  if(!ehAdmin()) return;
  const msg = document.getElementById('lf-videos-msg');
  msg.style.display = 'none';
  const campo = document.getElementById('lf-video-url');
  const url = campo.value.trim();
  if(!url){ return; }
  if(videosFormulario.length >= LIMITE_VIDEOS){
    msg.style.display='block'; msg.textContent = `Limite de ${LIMITE_VIDEOS} vídeos atingido.`;
    return;
  }
  if(!/^https?:\/\//i.test(url)){
    msg.style.display='block'; msg.textContent = 'Informe um link http(s) válido (YouTube ou Vimeo).';
    return;
  }
  videosFormulario.push({id:'video-'+Date.now(), src:url, tipo:'url'});
  campo.value = '';
  renderizarPreviewVideos();
});

