/* ==========================================================================
   v41 — LEILÕES TÃO COMPLETO QUANTO O MERCADO IMOBILIÁRIO
   (pedido do Thiago, 03/10). Reaproveita o MESMO motor de campos por
   tipo do Mercado imobiliário (CAMPOS_GRUPO / TIPO_PARA_GRUPO_CAMPOS /
   imovelPassaNosCamposDinamicos), com ids próprios "lei-":
   - filtros: UF, cidade, BAIRRO, tipo completo (residencial, rural,
     terreno, comercial), modalidade, situação, DESCONTO sobre a
     avaliação, OCUPAÇÃO, lance mín./máx., linha 2 por tipo e "Mais
     filtros" (comodidades, documentação, benfeitorias...);
   - cartão: bairro, área, avaliação e selo de desconto;
   - ficha: avaliação, desconto, bairro e CARACTERÍSTICAS do lote;
   - cadastro: tipo em lista, bairro, valor de avaliação e o bloco
     "Características" que muda conforme o tipo (o mesmo vale para o
     cadastro de imóveis, que também ganhou bairro e características).
   Tipos antigos continuam valendo: kit -> kitnet, terreno ->
   terreno_urbano, comercial -> sala_comercial.
   ========================================================================== */
var VIT_TIPOS_GRUPOS = [
  ['Residencial urbano', [['apartamento','Apartamento'],['casa','Casa'],['casa_condominio','Casa de condomínio'],['cobertura','Cobertura'],
                          ['kitnet','Kitnet / Studio'],['flat','Flat'],['loft','Loft'],['sobrado','Sobrado']]],
  ['Rural / agro',       [['fazenda','Fazenda'],['sitio','Sítio'],['chacara','Chácara'],['haras','Haras'],['area_rural','Área rural']]],
  ['Terreno / lote',     [['terreno_urbano','Terreno urbano'],['lote_condominio','Lote em condomínio'],['gleba','Gleba']]],
  ['Comercial',          [['sala_comercial','Sala comercial'],['loja','Loja'],['ponto_comercial','Ponto comercial'],['galpao','Galpão / Barracão'],
                          ['predio_comercial','Prédio comercial'],['hotel_pousada','Hotel / Pousada']]],
  ['Outros',             [['outros','Outros']]]
];
var VIT_TIPO_ANTIGO = {kit:'kitnet', terreno:'terreno_urbano', comercial:'sala_comercial'};
function vitNormTipo(t){ t = String(t || '').trim().toLowerCase(); return VIT_TIPO_ANTIGO[t] || t; }
function vitNomeTipo(t){
  const n = vitNormTipo(t);
  for(const g of VIT_TIPOS_GRUPOS) for(const o of g[1]) if(o[0] === n) return o[1];
  return t || 'Imóvel';
}
function vitTiposOptionsHtml(rotuloTodos){
  return (rotuloTodos ? '<option value="">' + rotuloTodos + '</option>' : '')
    + VIT_TIPOS_GRUPOS.map(g => '<optgroup label="' + g[0] + '">' + g[1].map(o => '<option value="' + o[0] + '">' + o[1] + '</option>').join('') + '</optgroup>').join('');
}
function vitGrupoDoTipo(t){ return TIPO_PARA_GRUPO_CAMPOS[vitNormTipo(t)] || 'TODOS'; }
function vitConfigDoTipo(t){ return CAMPOS_GRUPO[vitGrupoDoTipo(t)] || CAMPOS_GRUPO.TODOS; }

/* Área principal para o cartão (primeira que existir). */
var VIT_AREAS_CARTAO = [['area-util','m²'],['area-construida','m²'],['area-total','m²'],['area-terreno','m²'],['area-ha','ha'],
                        ['area-util-e','m²'],['area-terreno-d','m²'],['area-total-f','m²']];
function vitAreaPrincipal(item){
  for(const a of VIT_AREAS_CARTAO){ const v = parseFloat(item[a[0]]); if(!isNaN(v) && v > 0) return v.toLocaleString('pt-BR') + ' ' + a[1]; }
  return null;
}
function leiDesconto(l){
  const av = Number(l.valor_avaliacao), lance = Number(l.lance_minimo);
  if(!(av > 0) || !(lance >= 0)) return null;
  return Math.round(1000 * (1 - lance / av)) / 10;
}
function leiOcupacaoNorm(texto){
  const s = String(texto || '').toLowerCase();
  if(/desocup|livre|vago/.test(s)) return 'desocupado';
  if(/ocup/.test(s)) return 'ocupado';
  return '';
}

/* ---------- Características: exibição (ficha) ---------- */
function vitValorCaracteristica(campo, v){
  if(v === undefined || v === null || v === '' || v === false) return null;
  if(campo.tipo === 'checkbox') return v === true ? 'Sim' : null;
  if(campo.tipo === 'select'){
    const o = (campo.opcoes || []).find(x => String(x.v) === String(v));
    return o && o.v !== '' ? o.l : String(v);
  }
  if(campo.tipo === 'range-money'){ const n = Number(v); return isNaN(n) ? null : formatBRL(n); }
  if(campo.tipo === 'range-area'){ const n = parseFloat(v); return isNaN(n) ? null : n.toLocaleString('pt-BR') + (campo.unidade ? ' ' + campo.unidade : ''); }
  if(campo.tipo === 'chip'){ const n = parseInt(v, 10); return isNaN(n) ? null : String(n); }
  return String(v);
}
function vitCaracteristicasHtml(item, tipo){
  const cfg = vitConfigDoTipo(tipo), t = vitNormTipo(tipo);
  const secoes = [{secao:'Principais', campos: cfg.linha2}].concat(cfg.maisFiltros);
  const blocos = secoes.map(s => {
    const linhas = [], marcados = [];
    s.campos.forEach(c => {
      if(c.soSeTipo && !c.soSeTipo.includes(t)) return;
      const val = vitValorCaracteristica(c, lerValorImovel(item, chaveDadosDoId(c.id)));
      if(val === null) return;
      if(c.tipo === 'checkbox') marcados.push(c.label);
      else linhas.push('<div class="leilao-ficha-item"><span>' + escHtml(c.label) + '</span><b>' + escHtml(val) + '</b></div>');
    });
    if(!linhas.length && !marcados.length) return '';
    return '<h4 class="vit-car-secao">' + escHtml(s.secao) + '</h4>'
      + (linhas.length ? '<div class="leilao-ficha-grid">' + linhas.join('') + '</div>' : '')
      + (marcados.length ? '<div class="vit-car-marcados">' + marcados.map(m => '<span>&#10003; ' + escHtml(m) + '</span>').join('') + '</div>' : '');
  }).join('');
  return blocos ? '<div class="leilao-ficha-vazios vit-car"><h3>Características</h3>' + blocos + '</div>' : '';
}

/* ---------- Características: cadastro (formulários) ---------- */
function vitIdCampo(prefixo, chave){ return prefixo + '-' + chave.replace(/[^a-zA-Z0-9_-]/g, '_'); }
function vitFormCaracteristicas(caixaId, prefixo, tipo, item, pularChaves){
  const caixa = document.getElementById(caixaId);
  if(!caixa) return;
  const atuais = item || vitLerCaracteristicas(caixaId) || {};
  const cfg = vitConfigDoTipo(tipo), t = vitNormTipo(tipo);
  const secoes = [{secao:'Principais', campos: cfg.linha2}].concat(cfg.maisFiltros);
  const vistos = new Set(pularChaves || []);
  const html = secoes.map(s => {
    const campos = s.campos.map(c => {
      if(c.soSeTipo && !c.soSeTipo.includes(t)) return '';
      const chave = chaveDadosDoId(c.id);
      if(vistos.has(chave)) return '';
      vistos.add(chave);
      const v = lerValorImovel(atuais, chave);
      const id = vitIdCampo(prefixo, chave);
      const attrs = ' id="' + id + '" data-car-chave="' + escHtml(chave) + '" data-car-tipo="' + c.tipo + '"';
      if(c.tipo === 'checkbox'){
        return '<div class="vit-car-check"><input type="checkbox"' + attrs + (v === true ? ' checked' : '') + '><label for="' + id + '">' + escHtml(c.label) + '</label></div>';
      }
      let campo;
      if(c.tipo === 'select'){
        campo = '<select' + attrs + '>' + (c.opcoes || []).map(o => '<option value="' + escHtml(o.v) + '"' + (String(v || '') === String(o.v) ? ' selected' : '') + '>' + escHtml(o.v === '' ? 'Não informado' : o.l) + '</option>').join('') + '</select>';
      } else if(c.tipo === 'range-money'){
        campo = '<input type="text" inputmode="decimal" placeholder="R$ 0,00"' + attrs + ' value="' + (v !== undefined && v !== null && v !== '' ? escHtml(formatBRL(Number(v))) : '') + '" oninput="aplicarMascaraMoeda(this)" onblur="finalizarMascaraMoeda(this)">';
      } else if(c.tipo === 'chip' || c.tipo === 'range-area'){
        campo = '<input type="number" min="0" step="' + (c.tipo === 'chip' ? '1' : 'any') + '"' + attrs + ' value="' + (v !== undefined && v !== null ? escHtml(v) : '') + '">';
      } else {
        campo = '<input type="text"' + attrs + ' value="' + (v !== undefined && v !== null ? escHtml(v) : '') + '">';
      }
      return '<div><label for="' + id + '">' + escHtml(c.label) + (c.tipo === 'range-area' && c.unidade ? ' (' + escHtml(c.unidade) + ')' : '') + '</label>' + campo + '</div>';
    }).filter(Boolean);
    if(!campos.length) return '';
    return '<div class="vit-car-form-secao"><h4>' + escHtml(s.secao) + '</h4><div class="leilao-form-grid">' + campos.join('') + '</div></div>';
  }).join('');
  caixa.innerHTML = html || '<div class="leilao-ficha-sub">Escolha o tipo para ver as características.</div>';
}
function vitLerCaracteristicas(caixaId){
  const caixa = document.getElementById(caixaId);
  if(!caixa) return {};
  const out = {};
  caixa.querySelectorAll('[data-car-chave]').forEach(el => {
    const chave = el.getAttribute('data-car-chave'), tipo = el.getAttribute('data-car-tipo');
    let v;
    if(tipo === 'checkbox') v = el.checked ? true : null;
    else if(tipo === 'range-money'){ const n = parseMoeda(el.value); v = isNaN(n) ? null : n; }
    else if(tipo === 'chip'){ const n = parseInt(el.value, 10); v = isNaN(n) ? null : n; }
    else if(tipo === 'range-area'){ const n = parseFloat(el.value); v = isNaN(n) ? null : n; }
    else { v = el.value.trim() || null; }
    if(v === null) return;
    if(chave.startsWith('mf.')){ out.mf = out.mf || {}; out.mf[chave.slice(3)] = v; }
    else out[chave] = v;
  });
  return out;
}

/* ---------- Filtros da vitrine de leilões ---------- */
var filtroLeilaoValores = {};
var filtroLeilaoBairros = [];
function leiComValores(fn){
  const salvo = filtroImovelValores;
  filtroImovelValores = filtroLeilaoValores;
  try{ return fn(); } finally { filtroImovelValores = salvo; }
}
function leiPrefixar(html){
  return html.replace(/(id|for|data-campo|data-chips-de)="im-/g, '$1="lei-');
}
function leiChaveDoEl(id){ return String(id).replace(/^lei-/, 'im-'); }

function leiRenderLinha2(){
  const tipo = document.getElementById('filtro-imovel').value;
  const cfg = vitConfigDoTipo(tipo);
  leiComValores(() => {
    document.getElementById('lei-linha2').innerHTML = leiPrefixar(cfg.linha2.map(c => renderCampoDinamico(c, tipo)).join(''));
    document.getElementById('lei-mais-filtros-conteudo').innerHTML = leiPrefixar(cfg.maisFiltros.map(secao => {
      const h = secao.campos.map(c => renderCampoDinamico(c, tipo)).filter(x => x).join('');
      return h ? '<div class="im-mf-secao"><h3>' + secao.secao + '</h3><div class="im-mf-grid">' + h + '</div></div>' : '';
    }).join(''));
  });
  const raiz = ['#lei-linha2', '#lei-mais-filtros-conteudo'];
  raiz.forEach(sel => {
    const r = document.querySelector(sel);
    r.querySelectorAll('.leilao-chips').forEach(grupo => {
      grupo.querySelectorAll('.leilao-chip').forEach(chip => chip.addEventListener('click', () => {
        grupo.querySelectorAll('.leilao-chip').forEach(c => c.classList.remove('active'));
        chip.classList.add('active');
        filtroLeilaoValores[leiChaveDoEl(chip.getAttribute('data-campo'))] = chip.getAttribute('data-valor');
        renderizarLeiloes();
      }));
    });
    r.querySelectorAll('[data-campo-dinamico]').forEach(el => {
      const tipoCampo = el.getAttribute('data-campo-dinamico');
      if(tipoCampo === 'select') el.addEventListener('change', () => { filtroLeilaoValores[leiChaveDoEl(el.id)] = el.value; renderizarLeiloes(); });
      else if(tipoCampo === 'checkbox') el.addEventListener('change', () => { filtroLeilaoValores[leiChaveDoEl(el.id)] = el.checked; renderizarLeiloes(); });
      else { el.addEventListener('input', () => { filtroLeilaoValores[leiChaveDoEl(el.id)] = el.value; }); el.addEventListener('blur', () => renderizarLeiloes()); }
    });
  });
}

function leiBairrosDaCidade(cidade){
  const s = new Set(BAIRROS_POR_CIDADE[cidade] || []);
  (leiloesDados || []).concat(radarLista()).forEach(l => { if(l.bairro && normalizarTexto(l.cidade) === normalizarTexto(cidade)) s.add(l.bairro); });
  return Array.from(s).sort((a, b) => a.localeCompare(b, 'pt-BR'));
}
function leiAtualizarEstadoBairro(){
  const cidade = document.getElementById('filtro-cidade').value;
  const busca = document.getElementById('lei-filtro-bairro-busca');
  if(cidade && leiBairrosDaCidade(cidade).length){
    busca.disabled = false; busca.placeholder = '-- Selecione o(s) bairro(s) --';
  } else {
    busca.disabled = true; busca.placeholder = cidade ? 'Nenhum bairro cadastrado' : '-- Escolha a cidade --';
    if(filtroLeilaoBairros.length){ filtroLeilaoBairros = []; }
  }
  busca.value = filtroLeilaoBairros.length === 0 ? '' : (filtroLeilaoBairros.length === 1 ? filtroLeilaoBairros[0] : filtroLeilaoBairros.length + ' bairros selecionados');
}
function leiMostrarListaBairro(){
  const cidade = document.getElementById('filtro-cidade').value;
  const lista = document.getElementById('lei-filtro-bairro-lista');
  const bairros = leiBairrosDaCidade(cidade);
  lista.innerHTML = bairros.length ? bairros.map(b => '<label style="display:flex; align-items:center; gap:8px; padding:8px 11px; cursor:pointer; font-size:13px; color:var(--text);">'
      + '<input type="checkbox" data-bairro="' + escHtml(b) + '"' + (filtroLeilaoBairros.includes(b) ? ' checked' : '') + ' style="width:auto; margin:0;">' + escHtml(b) + '</label>').join('')
    : '<div class="leilao-cidade-vazio">Nenhum bairro cadastrado para esta cidade.</div>';
  lista.style.display = 'block';
  lista.querySelectorAll('input[type="checkbox"]').forEach(chk => chk.addEventListener('change', () => {
    const b = chk.getAttribute('data-bairro');
    if(chk.checked){ if(!filtroLeilaoBairros.includes(b)) filtroLeilaoBairros.push(b); }
    else filtroLeilaoBairros = filtroLeilaoBairros.filter(x => x !== b);
    leiAtualizarEstadoBairro();
    renderizarLeiloes();
  }));
}

function leiloesFiltrados(){
  const uf = document.getElementById('filtro-uf').value;
  const cidade = document.getElementById('filtro-cidade').value;
  const modalidade = document.getElementById('filtro-tipo').value;
  const tipo = document.getElementById('filtro-imovel').value;
  const situacao = document.getElementById('lei-filtro-status').value;
  const descontoMin = parseFloat(document.getElementById('lei-filtro-desconto').value);
  const ocupacao = document.getElementById('lei-filtro-ocupacao').value;
  const precoMin = parseMoeda(document.getElementById('filtro-preco-min').value) || 0;
  const precoMaxRaw = parseMoeda(document.getElementById('filtro-preco-max').value);
  const precoMax = isNaN(precoMaxRaw) ? Infinity : precoMaxRaw;
  const cfg = vitConfigDoTipo(tipo);
  const origem = (document.getElementById('lei-filtro-origem') || {}).value || '';
  const base = origem === 'radar' ? radarVisivel() : origem === 'analisado' ? leiloesDados : leiloesDados.concat(radarVisivel());
  return base.filter(l => {
    if(uf && l.uf !== uf) return false;
    if(cidade && normalizarTexto(l.cidade) !== normalizarTexto(cidade)) return false;
    if(filtroLeilaoBairros.length && !filtroLeilaoBairros.includes(l.bairro)) return false;
    if(modalidade && l.modalidade !== modalidade) return false;
    if(tipo && vitNormTipo(l.tipo_imovel) !== tipo) return false;
    if(situacao && l.status !== situacao) return false;
    if(!isNaN(descontoMin)){ const d = leiDesconto(l); if(d === null || d < descontoMin) return false; }
    if(ocupacao && leiOcupacaoNorm(l.ocupacao) !== ocupacao) return false;
    if(!(l.lance_minimo >= precoMin && l.lance_minimo <= precoMax)) return false;
    if(!leiComValores(() => imovelPassaNosCamposDinamicos(l, cfg, tipo))) return false;
    return true;
  });
}

function renderizarLeiloes(){
  leiAtualizarEstadoBairro();
  const grid = document.getElementById('leilao-grid');
  const vazio = document.getElementById('leilao-vazio');
  const semResultado = document.getElementById('leilao-sem-resultado');
  const contador = document.getElementById('leilao-contador');
  if(!_leiManterLimite) _leiLimite = LEI_PAGINA;
  _leiManterLimite = false;
  const maisWrap = document.getElementById('lei-mais-wrap');
  radarDesenharAviso();
  if(leiloesDados.length === 0 && radarLista().length === 0){
    grid.innerHTML = ''; grid.style.display = 'none';
    vazio.style.display = 'block'; semResultado.style.display = 'none';
    contador.textContent = '';
    if(maisWrap) maisWrap.style.display = 'none';
    return;
  }
  const lista = leiOrdenar(leiloesFiltrados());
  vazio.style.display = 'none';
  const nRadar = lista.filter(l => l.radar).length, nAnal = lista.length - nRadar;
  triBotaoVisivel();
  contador.textContent = (lista.length === 1 ? '1 lote encontrado' : lista.length.toLocaleString('pt-BR') + ' lotes encontrados')
    + (nRadar ? ' (' + nAnal.toLocaleString('pt-BR') + ' analisado(s) · ' + nRadar.toLocaleString('pt-BR') + ' do Radar)' : '')
    + ((typeof _radarCarregandoMais !== 'undefined' && _radarCarregandoMais) ? ' — carregando o Radar…' : '');   /* v133 */
  if(lista.length === 0){
    grid.innerHTML = ''; grid.style.display = 'none';
    semResultado.style.display = 'block';
    if(maisWrap) maisWrap.style.display = 'none';
    return;
  }
  semResultado.style.display = 'none';
  grid.style.display = 'grid';
  const visiveis = lista.slice(0, _leiLimite);
  if(maisWrap){
    const resta = lista.length - visiveis.length;
    maisWrap.style.display = resta > 0 ? 'block' : 'none';
    document.getElementById('lei-btn-mostrar-mais').textContent = 'Mostrar mais (' + resta.toLocaleString('pt-BR') + ' restante' + (resta === 1 ? '' : 's') + ')';
  }
  grid.innerHTML = visiveis.map(l => {
    if(l.radar) return radarCartao(l);
    const capa = (l.fotos || []).find(f => f.capa) || (l.fotos || [])[0];
    const desc = leiDesconto(l), area = vitAreaPrincipal(l);
    return `
    <button type="button" class="leilao-card" data-id="${escHtml(l.id)}">
      <div class="leilao-card-foto">${capa ? `<img src="${capa.src}" alt="${escHtml(capa.alt || l.titulo)}">` : 'Foto não disponível'}
        ${desc !== null && desc > 0 ? `<span class="lei-selo-desconto">-${String(desc).replace('.', ',')}%</span>` : ''}</div>
      <div class="leilao-card-body">
        <span class="leilao-card-tipo ${escHtml(l.modalidade)}">${escHtml(l.modalidade)}</span>
        <span class="lei-selo-origem lei-selo-analisado">Analisado${l.analise && l.analise.nota ? ' · Nota ' + escHtml(l.analise.nota) : ''}</span>
        <span class="lei-card-tipo-imovel">${escHtml(vitNomeTipo(l.tipo_imovel))}</span>
        <h3>${escHtml(l.titulo)}</h3>
        <div class="leilao-card-linha"><span>Local</span><b>${escHtml((l.bairro ? l.bairro + ' · ' : '') + l.cidade + '/' + l.uf)}</b></div>
        ${typeof l.quartos === 'number' ? `<div class="leilao-card-linha"><span>Quartos</span><b>${l.quartos === 0 ? 'Kit/Studio' : l.quartos}</b></div>` : ''}
        ${area ? `<div class="leilao-card-linha"><span>Área</span><b>${escHtml(area)}</b></div>` : ''}
        ${Number(l.valor_avaliacao) > 0 ? `<div class="leilao-card-linha"><span>Avaliação</span><b>${formatBRL(Number(l.valor_avaliacao))}</b></div>` : ''}
        <div class="leilao-card-linha"><span>Lance mínimo</span><b>${formatBRL(l.lance_minimo)}</b></div>
        <div class="leilao-card-linha"><span>1ª praça</span><b>${formatarDataBR(l.praca1)}</b></div>
        <div class="leilao-card-linha"><span>2ª praça</span><b>${formatarDataBR(l.praca2)}</b></div>
        <div class="leilao-card-linha"><span>Leiloeiro</span><b>${escHtml(l.leiloeiro || '—')}</b></div>
        <span class="leilao-card-status">${escHtml(l.status)}</span>
      </div>
    </button>`;
  }).join('');
  grid.querySelectorAll('.leilao-card').forEach(card => card.addEventListener('click', () => abrirFichaLeilao(card.getAttribute('data-id'))));
}

function limparFiltrosLeilao(){
  limparFiltrosLeilaoV1Campos();
  ['lei-filtro-status', 'lei-filtro-desconto', 'lei-filtro-ocupacao', 'lei-filtro-origem'].forEach(id => { document.getElementById(id).value = ''; });
  filtroLeilaoValores = {};
  filtroLeilaoBairros = [];
  leiRenderLinha2();
  renderizarLeiloes();
}

/* ---------- Ficha: complemento (avaliação, desconto, bairro, características) ---------- */
function abrirFichaLeilao(id, modoAdmin){
  if(String(id).startsWith('radar-')) return radarAbrirFicha(id);
  abrirFichaLeilaoV1(id, modoAdmin);
  const l = leiloesDados.find(x => x.id === id);
  const conteudo = document.getElementById('leilao-ficha-conteudo');
  if(!l || !conteudo) return;
  const sub = conteudo.querySelector('.leilao-ficha-sub');
  if(sub) sub.innerHTML = (l.modalidade === 'judicial' ? 'Leilão Judicial' : 'Leilão Extrajudicial') + ' · ' + escHtml(vitNomeTipo(l.tipo_imovel))
    + ' · ' + escHtml((l.bairro ? l.bairro + ', ' : '') + l.cidade + '/' + l.uf);
  const grid = conteudo.querySelector('.leilao-ficha-grid');
  const desc = leiDesconto(l), area = vitAreaPrincipal(l);
  if(grid){
    let extra = '';
    if(Number(l.valor_avaliacao) > 0) extra += '<div class="leilao-ficha-item"><span>Valor de avaliação</span><b>' + formatBRL(Number(l.valor_avaliacao)) + '</b></div>';
    if(desc !== null) extra += '<div class="leilao-ficha-item"><span>Desconto sobre a avaliação</span><b class="' + (desc > 0 ? 'desemp-ok' : '') + '">' + String(desc).replace('.', ',') + '%</b></div>';
    if(area) extra += '<div class="leilao-ficha-item"><span>Área</span><b>' + escHtml(area) + '</b></div>';
    grid.insertAdjacentHTML('beforeend', extra);
  }
  const vazios = conteudo.querySelector('.leilao-ficha-vazios');
  const car = vitCaracteristicasHtml(l, l.tipo_imovel);
  if(car){ if(vazios) vazios.insertAdjacentHTML('beforebegin', car); else conteudo.insertAdjacentHTML('beforeend', car); }
  if(l.analise && l.analise.nota){
    if(vazios) vazios.style.display = 'none';
    conteudo.insertAdjacentHTML('beforeend', triAnaliseHtml(l));
  }
}

function abrirFichaImovel(id){
  abrirFichaImovelV1(id);
  const im = (imoveisDados || []).find(x => x.id === id);
  const conteudo = document.getElementById('im-ficha-conteudo');
  if(!im || !conteudo) return;
  const sub = conteudo.querySelector('.leilao-ficha-sub');
  if(sub && im.bairro) sub.innerHTML = sub.innerHTML.replace(escHtml(im.cidade) + '/', escHtml(im.bairro) + ', ' + escHtml(im.cidade) + '/');
  const grid = conteudo.querySelector('.leilao-ficha-grid');
  const area = vitAreaPrincipal(im);
  if(grid && area) grid.insertAdjacentHTML('beforeend', '<div class="leilao-ficha-item"><span>Área</span><b>' + escHtml(area) + '</b></div>');
  const car = vitCaracteristicasHtml(im, im.tipo);
  const vazios = conteudo.querySelector('.leilao-ficha-vazios');
  if(car){ if(vazios) vazios.insertAdjacentHTML('beforebegin', car); else conteudo.insertAdjacentHTML('beforeend', car); }
}

