/* ---------- panorama: bairros de cada cidade ---------- */
function panBairros(chave){
  const lista = leiloesFiltrados().filter(l => l.cidade && (l.cidade + '/' + l.uf) === chave);
  const g = panAgrupar(lista, l => (l.bairro || '').trim() || '(bairro não informado)').slice(0, 30), max = g.length ? g[0].n : 0;
  return '<div class="pan-bairros" style="margin:6px 0 10px;"><b style="font-size:12.5px;">Bairros de ' + escHtml(chave) + '</b> <span style="font-size:11.5px; color:var(--ink-soft);">(' + lista.length.toLocaleString('pt-BR') + ' imóvel(is)' + (g.length === 30 ? '; os 30 bairros com mais imóveis' : '') + ')</span>'
    + panTabela(['Bairro', 'Imóveis', '', 'Desconto médio', 'Preço mediano', 'R$/m² mediano'],
        g.map(x => [escHtml(x.k), x.n.toLocaleString('pt-BR'), panBarra(x.n, max), panPct(x.desc), x.preco ? formatBRL(x.preco) : '—', x.m2 ? formatBRL(x.m2) : '—'])) + '</div>';
}
var _panAbrirV76L = panAbrir;
panAbrir = function(){
  _panAbrirV76L();
  const corpo = document.getElementById('panorama-corpo');
  if(!corpo) return;
  const h = [...corpo.querySelectorAll('h3')].find(x => /^Cidades com mais/.test(x.textContent));
  const tabela = h && h.nextElementSibling;
  if(!tabela) return;
  tabela.querySelectorAll('tbody tr').forEach(tr => {
    const td = tr.children[0], chave = td.textContent;
    td.innerHTML = '<button type="button" class="pan-cidade" data-pan-cidade="' + escHtml(chave) + '" style="background:none; border:0; padding:0; color:inherit; font:inherit; cursor:pointer; text-align:left;--v107-alin:left;">▸ ' + escHtml(chave) + '</button>';
  });
  tabela.addEventListener('click', e => {
    const b = e.target.closest('[data-pan-cidade]');
    if(!b) return;
    const tr = b.closest('tr'), prox = tr.nextElementSibling;
    if(prox && prox.classList.contains('pan-bairros-tr')){ prox.remove(); b.textContent = '▸ ' + b.getAttribute('data-pan-cidade'); return; }
    tr.insertAdjacentHTML('afterend', '<tr class="pan-bairros-tr"><td colspan="' + tr.children.length + '" style="padding:0 6px;">' + panBairros(b.getAttribute('data-pan-cidade')) + '</td></tr>');
    b.textContent = '▾ ' + b.getAttribute('data-pan-cidade');
  });
  const todas = panAgrupar(leiloesFiltrados(), l => l.cidade ? l.cidade + '/' + l.uf : '').sort((a, b) => a.k.localeCompare(b.k, 'pt-BR'));
  if(todas.length){
    tabela.insertAdjacentHTML('afterend', '<label style="display:block; font-size:12.5px; margin:8px 0;">Bairros de outra cidade: <select id="pan-outra-cidade" style="max-width:100%;"><option value="">— escolha a cidade —</option>'
      + todas.map(g => '<option value="' + escHtml(g.k) + '">' + escHtml(g.k) + ' (' + g.n + ')</option>').join('') + '</select></label><div id="pan-outra-bairros"></div>');
    document.getElementById('pan-outra-cidade').addEventListener('change', e => {
      document.getElementById('pan-outra-bairros').innerHTML = e.target.value ? panBairros(e.target.value) : '';
    });
  }
};

(function v76Iniciar(){
  const st = document.createElement('style');
  st.textContent = '.pre-selo{display:inline-block;font-size:11px;font-weight:700;color:var(--rust);margin-top:3px;}';
  document.head.appendChild(st);
  const b = document.getElementById('btn-uso');
  if(b) b.addEventListener('click', usoAbrir);
  const p = document.getElementById('btn-panorama');                 /* o botão chamava a versão antiga do Panorama */
  if(p){ const novo = p.cloneNode(true); p.replaceWith(novo); novo.addEventListener('click', () => panAbrir()); }
  try{ triBotaoVisivel(); }catch(e){}
})();

