function comAcentos(t){
  return String(t || '').replace(/[A-Za-zÀ-ÿ]+/g, w => {
    const a = ACENTOS_LEI[w.toLowerCase()];
    if(!a) return w;
    if(w === w.toUpperCase()) return a.toUpperCase();
    return w.charAt(0) === w.charAt(0).toUpperCase() ? a.charAt(0).toUpperCase() + a.slice(1) : a;
  });
}
var _radarCidadeCanonV76L = radarCidadeCanon;
