function leiVerificar(l){
  const d = leiDesconto(l);
  if(d === null) return '';
  const f = Number(l.desconto_fonte);
  if(d > 80) return 'Desconto acima de 80% (' + String(d).replace('.', ',') + '%): confira o preço e a avaliação na fonte antes de considerar.';
  if(isFinite(f) && f > 0 && Math.abs(f - d) > 2) return 'O desconto calculado (' + String(d).replace('.', ',') + '%) difere do informado pela fonte (' + String(f).replace('.', ',') + '%): confira.';
  return '';
}
