/* Mesmo "peso visual" para todas as logos: a área da logo fica constante (~7.000 px²), seja ela larga (TRF2, TJPA)
   ou quase quadrada (TJSE), dentro do limite de 220 × 62 px. Roda quando a logo termina de carregar. */
var SELO_AREA = 7000, SELO_W_MAX = 220, SELO_H_MAX = 62;
function seloAjustarTamanho(img){
  const w = img.naturalWidth, h = img.naturalHeight;
  if(!w || !h) return;
  const r = w / h;
  let hh = Math.sqrt(SELO_AREA / r), ww = hh * r;
  if(ww > SELO_W_MAX){ ww = SELO_W_MAX; hh = ww / r; }
  if(hh > SELO_H_MAX){ hh = SELO_H_MAX; ww = hh * r; }
  img.style.width = Math.round(ww) + 'px'; img.style.height = Math.round(hh) + 'px';
}
/* sigla comprida (DETRAN-GO, RENDIMENTO) não quebra em 2 linhas: a letra diminui */
var _seloHtmlV84 = seloHtml;
seloHtml = function(sel){
  const h = _seloHtmlV84(sel);
  if(sel.src) return h;
  const n = String(sel.sigla || '').length;
  const tam = n <= 7 ? 0 : n <= 9 ? 17 : n <= 12 ? 14 : 12;
  return tam ? h.replace('<span class="selo-sigla">', '<span class="selo-sigla" style="font-size:' + tam + 'px;">') : h;
};
var _seloLerCorV84 = seloLerCor;
seloLerCor = function(img){
  try{ seloAjustarTamanho(img); }catch(e){}
  return _seloLerCorV84(img);
};

