/* ---------- servidor ---------- */
async function veiRest(caminho, contar){
  const token = await contaTokenValido();
  if(!token) return {ok: false, status: 401, dados: null, total: null};
  try{
    const cab = {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Accept': 'application/json'};
    if(contar) cab['Prefer'] = 'count=exact';
    const r = await fetch(SUPABASE_URL + '/rest/v1/' + caminho, {headers: cab});
    const dados = await r.json().catch(() => null);
    const cr = r.headers.get('content-range') || '';
    const m = /\/(\d+)$/.exec(cr);
    return {ok: r.ok, status: r.status, dados, total: m ? Number(m[1]) : null};
  }catch(e){ return {ok: false, status: 0, dados: null, total: null}; }
}
async function veiRpc(nome){
  const token = await contaTokenValido();
  if(!token) return null;
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/rpc/' + nome, {method: 'POST', body: '{}',
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + token, 'Accept': 'application/json', 'Content-Type': 'application/json'}});
    return r.ok ? await r.json().catch(() => null) : null;
  }catch(e){ return null; }
}

/* ---------- opções dos filtros (todas de listas oficiais) ---------- */
function veiOpcoes(sel, pares, todos, manter){
  const atual = manter ? sel.value : '';
  sel.textContent = '';
  if(todos !== null){ const o = document.createElement('option'); o.value = ''; o.textContent = todos; sel.appendChild(o); }
  pares.forEach(p => {
    const o = document.createElement('option');
    o.value = String(p[0]); o.textContent = p[1];
    if(p[2]) o.disabled = true;
    sel.appendChild(o);
  });
  if(manter && [...sel.options].some(o => o.value === atual && !o.disabled)) sel.value = atual; else sel.value = todos !== null ? '' : (pares[0] ? String(pares[0][0]) : '');
}
function veiConta(n){ return n ? ' (' + n + ')' : ''; }
function veiResumo(chave, k){ return (_vei.resumo && _vei.resumo[chave] && Number(_vei.resumo[chave][k])) || 0; }
function veiMontarFixos(){
  veiOpcoes(veiEl('vei-f-tipo'), VEI_TIPOS.map(t => [t[0], t[1] + veiConta(veiResumo('por_tipo', t[0]))]), 'Todos os tipos', true);
  const anos = [];
  for(let a = veiAnoMax(); a >= VEI_ANO_MIN; a--) anos.push([a, String(a)]);
  veiOpcoes(veiEl('vei-f-ano-de'), anos, 'Qualquer', true);
  veiOpcoes(veiEl('vei-f-ano-ate'), anos, 'Qualquer', true);
  const ufs = Object.keys(VEI_UF_NOME).sort((a, b) => veiCompara(VEI_UF_NOME[a], VEI_UF_NOME[b]));
  veiOpcoes(veiEl('vei-f-uf'), ufs.map(u => [u, VEI_UF_NOME[u] + ' (' + u + ')' + veiConta(veiResumo('por_uf', u))]), 'Todos os estados', true);
  veiOpcoes(veiEl('vei-f-fonte'), VEI_FONTES.map(f => [f[0], f[1] + veiConta(veiResumo('por_fonte', f[0]))]), 'Todas as origens', true);
  veiOpcoes(veiEl('vei-f-condicao'), VEI_CONDICOES, 'Todas', true);
  veiOpcoes(veiEl('vei-f-combustivel'), VEI_COMBUSTIVEIS, 'Todos', true);
  veiOpcoes(veiEl('vei-f-desagio'), VEI_DESAGIO.map(d => [d, 'Pelo menos ' + d + '% abaixo']), 'Qualquer', true);
  veiOpcoes(veiEl('vei-f-km'), VEI_KM.map(k => [k, 'Até ' + k.toLocaleString('pt-BR') + ' km']), 'Qualquer', true);
  veiOpcoes(veiEl('vei-f-prazo'), VEI_PRAZO, 'Qualquer data', true);
  veiOpcoes(veiEl('vei-f-ordem'), VEI_ORDEM, null, true);
}
function veiMarcasDoTipo(tipo){
  const lista = (_vei.marcas || []).filter(m => !tipo || m.tipo === tipo);
  const por = new Map();
  lista.forEach(m => {
    const k = m.nome;
    if(!por.has(k)) por.set(k, {nome: m.nome, codigos: [], n: 0});
    const g = por.get(k);
    g.codigos.push([m.tipo, m.codigo]);
    g.n += veiResumo('por_marca', m.tipo + '|' + m.codigo);
  });
  return [...por.values()].sort((a, b) => veiCompara(a.nome, b.nome));
}
function veiMontarMarcas(){
  const sel = veiEl('vei-f-marca');
  if(!_vei.marcas || !_vei.marcas.length){
    veiOpcoes(sel, [], 'Lista FIPE ainda não carregada', false);
    sel.disabled = true;
    return;
  }
  sel.disabled = false;
  veiOpcoes(sel, veiMarcasDoTipo(veiEl('vei-f-tipo').value).map(g => [g.nome, g.nome + veiConta(g.n)]), 'Todas as marcas', true);
}
async function veiCarregarModelos(nome, tipo){
  const grupos = veiMarcasDoTipo(tipo).filter(g => g.nome === nome);
  const cods = grupos.length ? grupos[0].codigos : [];
  const out = new Map();
  for(const [t, c] of cods){
    const k = t + '|' + c;
    if(!_vei.modelos[k]){
      const r = await veiRest('veiculos_fipe_modelos?select=familia&tipo=eq.' + encodeURIComponent(t) + '&marca_codigo=eq.' + encodeURIComponent(c) + '&limit=5000');
      _vei.modelos[k] = r.ok && Array.isArray(r.dados) ? [...new Set(r.dados.map(x => x.familia).filter(Boolean))] : [];
    }
    _vei.modelos[k].forEach(f => {
      const kk = veiSa(f);
      const n = veiResumo('por_familia', t + '|' + c + '|' + f);
      if(!out.has(kk)) out.set(kk, {familia: f, n: 0});
      out.get(kk).n += n;
    });
  }
  return [...out.values()].sort((a, b) => veiCompara(a.familia, b.familia));
}
async function veiMontarModelos(){
  const sel = veiEl('vei-f-modelo'), marca = veiEl('vei-f-marca').value, tipo = veiEl('vei-f-tipo').value;
  if(!marca){ veiOpcoes(sel, [], 'Escolha a marca', false); sel.disabled = true; return; }
  const seq = (_vei.seqMod = (_vei.seqMod || 0) + 1);
  const fams = await veiCarregarModelos(marca, tipo);
  if(seq !== _vei.seqMod || veiEl('vei-f-marca').value !== marca) return;
  if(!fams.length){ veiOpcoes(sel, [], 'Sem lista oficial de modelos (use a busca)', false); sel.disabled = true; return; }
  sel.disabled = false;
  veiOpcoes(sel, fams.map(f => [f.familia, f.familia + veiConta(f.n)]), 'Todos os modelos', true);
}
function veiMontarCidades(){
  const sel = veiEl('vei-f-cidade'), uf = veiEl('vei-f-uf').value;
  if(!uf){ veiOpcoes(sel, [], 'Escolha a UF', false); sel.disabled = true; return; }
  const lista = (CIDADES_POR_UF_EMBUTIDO && CIDADES_POR_UF_EMBUTIDO[uf]) || [];
  sel.disabled = !lista.length;
  veiOpcoes(sel, lista.map(c => [c, c + veiConta(veiResumo('por_cidade', uf + '|' + c))]), 'Todas as cidades', true);
}

