    veiEl('vei-f-tipo').addEventListener('change', async () => { veiMontarMarcas(); await veiMontarModelos(); veiAgendar(); });
    veiEl('vei-f-marca').addEventListener('change', async () => { await veiMontarModelos(); veiAgendar(); });
    veiEl('vei-f-uf').addEventListener('change', () => { veiMontarCidades(); veiAgendar(); });
