/* ==========================================================================
   v78-LEI — MEU PERFIL DE IMÓVEL · OPORTUNIDADE · LUCRO ESTIMADO (SQL 111)
   Modelo (decisão do Thiago, 08/10/2026): saída = avaliação × 85% (5% custas/ITBI + 10% liquidez);
   lucro = saída − lance; retorno = lucro ÷ lance; OPORTUNIDADE = deságio >= 60% sobre a avaliação.
   ========================================================================== */
var LUCRO_CUSTAS = 0.05, LUCRO_LIQUIDEZ = 0.10, LUCRO_SAIDA = 1 - LUCRO_CUSTAS - LUCRO_LIQUIDEZ, OPORTUNIDADE_MIN = 60;
var PERFIL_RURAIS = ['fazenda', 'sitio', 'chacara', 'haras', 'area_rural', 'gleba'];
var PERFIL_NAO_MORADIA = ['terreno_urbano', 'lote_condominio', 'gleba', 'sala_comercial', 'loja', 'ponto_comercial', 'galpao', 'predio_comercial', 'hotel_pousada'];
var PERFIL_NOME = 'Meu perfil de imóvel';
var PERFIL_PRAZOS = [120, 180, 240, 300, 360, 420];
var PERFIL_RETORNOS = [0, 10, 20, 30, 40, 50, 75, 100];
var PERFIL_PADRAO = {modo: 'morar', renda: 12000, parcela: 3600, entrada: 60000, prazo: 360, juros: 11.5, capital: 400000, retmin: 30,
                     ufs: [], tipo: '', zona: '', quartos: 0, vmin: '', vmax: '', soopp: false, email: true, alvo: 'todos'};
var _perf = {form: null, alertaId: null, mostrar: 40, carregado: false};

function leiLucro(l){
  const av = Number(l.valor_avaliacao), la = Number(l.lance_minimo);
  if(!(av > 0) || !(la > 0)) return null;
  const saida = av * LUCRO_SAIDA, lucro = saida - la;
  return {av, lance: la, custas: av * LUCRO_CUSTAS, liquidez: av * LUCRO_LIQUIDEZ, saida, lucro, retorno: lucro / la * 100, desagio: (1 - la / av) * 100};
}
function leiOportunidade(l){ const d = leiDesconto(l); return d !== null && d >= OPORTUNIDADE_MIN; }
/* v118 — máscara de moeda R$ 0.000,00 (o usuário digita reais; vírgula opcional para centavos) */
function perfMoedaLerV118(t){
  t = String(t === null || t === undefined ? '' : t).trim();
  if(!t) return null;
  if(/^-?\d+(\.\d+)?$/.test(t)) return Number(t);              /* número cru (perfil salvo, preenchimento automático) */
  const i = t.lastIndexOf(','), int = (i >= 0 ? t.slice(0, i) : t).replace(/\D/g, ''), cent = i >= 0 ? t.slice(i + 1).replace(/\D/g, '').slice(0, 2) : '';
  if(!int && !cent) return null;
  return Number(int || 0) + (cent ? Number(cent.padEnd(2, '0')) / 100 : 0);
}
function perfMoedaFmtV118(v){
  return v === null || v === undefined || v === '' || !isFinite(Number(v)) ? ''
    : Number(v).toLocaleString('pt-BR', {style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2});
}
function perfMoedaDigitarV118(el){   /* durante a digitação: "R$ 600.000" (centavos só se o usuário digitar a vírgula); ao sair do campo: "R$ 600.000,00" */
  const t = el.value, car = el.selectionStart === null ? t.length : el.selectionStart;
  const dirDig = t.slice(car).replace(/\D/g, '').length;      /* dígitos à direita do cursor: o cursor fica no mesmo lugar */
  const i = t.indexOf(',');
  let int = (i >= 0 ? t.slice(0, i) : t).replace(/\D/g, '').replace(/^0+(?=\d)/, '');
  const cent = i >= 0 ? t.slice(i + 1).replace(/\D/g, '').slice(0, 2) : null;
  if(!int && !cent){ el.value = ''; return; }
  el.value = 'R$ ' + Number(int || 0).toLocaleString('pt-BR') + (cent !== null ? ',' + cent : '');
  let pos = el.value.length, n = 0;
  while(pos > 0 && n < dirDig){ pos--; if(/\d/.test(el.value[pos])) n++; }
  if(dirDig === 0) pos = el.value.length;
  try{ if(document.activeElement === el) el.setSelectionRange(pos, pos); }catch(e){}
}
function perfMoedaFormatarTodosV118(){
  document.querySelectorAll('#perf-form [data-perf-moeda]').forEach(el => {
    const v = perfMoedaLerV118(el.value);
    if(document.activeElement !== el) el.value = v === null ? '' : perfMoedaFmtV118(v);
  });
}
function perfMoedaLigarV118(){
  const form = document.getElementById('perf-form');
  if(!form || form.dataset.v118) return;
  form.dataset.v118 = '1';
  form.addEventListener('input', e => { if(e.target && e.target.hasAttribute && e.target.hasAttribute('data-perf-moeda')) perfMoedaDigitarV118(e.target); }, true);   /* captura: formata antes do cálculo */
  form.addEventListener('focusin', e => { const el = e.target;   /* ao entrar no campo, tira o ",00" para digitar */
    if(el && el.hasAttribute && el.hasAttribute('data-perf-moeda') && /,00$/.test(el.value)) el.value = el.value.replace(/,00$/, ''); });
  form.addEventListener('focusout', e => { const el = e.target;   /* ao sair, R$ 0.000,00 */
    if(el && el.hasAttribute && el.hasAttribute('data-perf-moeda')){ const v = perfMoedaLerV118(el.value); el.value = v === null ? '' : perfMoedaFmtV118(v); } });
  const r = document.getElementById('perf-renda');
  if(r) r.addEventListener('change', () => setTimeout(perfMoedaFormatarTodosV118, 0));   /* parcela sugerida (30%) também com máscara */
  perfMoedaFormatarTodosV118();
}
function perfPct(v){ return (Math.round(v * 10) / 10).toLocaleString('pt-BR') + '%'; }
function perfBRL(v){ return (v < 0 ? '− ' : '') + Number(Math.abs(v) || 0).toLocaleString('pt-BR', {style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2}); }   /* v118: com centavos */

/* ---------- cards e ficha do Leilão de imóveis ---------- */
function leiLotesPorId(){
  const m = new Map();
  (typeof leiloesDados !== 'undefined' ? leiloesDados : []).forEach(l => m.set(String(l.id), l));
  radarLista().forEach(l => m.set(String(l.id), l));
  return m;
}
var _renderizarLeiloesV78L = renderizarLeiloes;
renderizarLeiloes = function(){
  const r = _renderizarLeiloesV78L.apply(this, arguments);
  try{
    const mapa = leiLotesPorId();
    document.querySelectorAll('#leilao-grid .leilao-card[data-id]').forEach(card => {
      if(card.querySelector('.lei-lucro-linha')) return;
      const l = mapa.get(card.getAttribute('data-id'));
      if(!l) return;
      const corpo = card.querySelector('.leilao-card-body'), h3 = corpo && corpo.querySelector('h3');
      if(!corpo || !h3) return;
      if(leiOportunidade(l)){
        card.classList.add('lei-card-opp');
        h3.insertAdjacentHTML('beforebegin', '<span class="lei-selo-opp" title="Deságio de ' + OPORTUNIDADE_MIN + '% ou mais sobre a avaliação">★ OPORTUNIDADE</span>');
      }
      const k = leiLucro(l);
      if(k){
        const linhas = corpo.querySelectorAll('.leilao-card-linha');
        const ref = linhas.length ? linhas[linhas.length - 1] : h3;
        ref.insertAdjacentHTML('afterend', '<div class="leilao-card-linha lei-lucro-linha" title="Saída = avaliação × 85% (5% custas + 10% liquidez); lucro = saída − lance">'
          + '<span>Lucro estimado</span><b class="' + (k.lucro >= 0 ? 'desemp-ok' : 'desemp-ruim') + '">' + perfBRL(k.lucro) + ' (' + perfPct(k.retorno) + ')</b></div>');
      }
    });
    const b = document.getElementById('btn-oportunidades');
    if(b){ const on = document.getElementById('lei-filtro-desconto').value === String(OPORTUNIDADE_MIN); b.setAttribute('aria-pressed', on ? 'true' : 'false'); b.classList.toggle('lei-btn-ligado', on); }
  }catch(e){ console.warn('[v78 cards]', e); }
  return r;
};
function leiLucroQuadro(l){
  const k = leiLucro(l);
  if(!k) return '<div class="lei-lucro-quadro"><b>Simulação de lucro</b><p>Sem valor de avaliação: não dá para estimar o lucro.</p></div>';
  return '<div class="lei-lucro-quadro' + (leiOportunidade(l) ? ' lei-lucro-opp' : '') + '"><b>Simulação de lucro' + (leiOportunidade(l) ? ' · ★ OPORTUNIDADE' : '') + '</b>'
    + '<table><tr><td>Avaliação</td><td>' + perfBRL(k.av) + '</td></tr>'
    + '<tr><td>Custas de cartório e ITBI (5% da avaliação)</td><td>− ' + perfBRL(k.custas) + '</td></tr>'
    + '<tr><td>Deságio para vender rápido (10% da avaliação)</td><td>− ' + perfBRL(k.liquidez) + '</td></tr>'
    + '<tr><td>Valor de saída (85% da avaliação)</td><td>' + perfBRL(k.saida) + '</td></tr>'
    + '<tr><td>Lance mínimo</td><td>− ' + perfBRL(k.lance) + '</td></tr>'
    + '<tr class="tot"><td>Lucro estimado</td><td class="' + (k.lucro >= 0 ? 'desemp-ok' : 'desemp-ruim') + '">' + perfBRL(k.lucro) + '</td></tr>'
    + '<tr><td>Retorno sobre o lance</td><td class="' + (k.retorno >= 0 ? 'desemp-ok' : 'desemp-ruim') + '">' + perfPct(k.retorno) + '</td></tr>'
    + '<tr><td>Deságio do lance sobre a avaliação</td><td>' + perfPct(k.desagio) + '</td></tr></table>'
    + '<p>Estimativa com o lance mínimo. Lance maior reduz o lucro. Não inclui reforma, débitos de IPTU/condomínio nem comissão de leiloeiro: confira no edital.</p></div>';
}
var _abrirFichaLeilaoV78L = abrirFichaLeilao;
abrirFichaLeilao = function(id){
  const r = _abrirFichaLeilaoV78L.apply(this, arguments);
  const por = () => {
    const c = document.getElementById('leilao-ficha-conteudo');
    const l = leiLotesPorId().get(String(id));
    if(!c || !l || c.querySelector('.lei-lucro-quadro')) return;
    const g = c.querySelector('.leilao-ficha-grid');
    if(g) g.insertAdjacentHTML('afterend', leiLucroQuadro(l)); else c.insertAdjacentHTML('beforeend', leiLucroQuadro(l));
  };
  por(); setTimeout(por, 400);
  return r;
};

/* ---------- MEU PERFIL DE IMÓVEL ---------- */
function perfNum(id, min, max){
  const el = document.getElementById(id);
  if(el && el.hasAttribute('data-perf-moeda')){   /* v118: campo com máscara R$ */
    let v = perfMoedaLerV118(el.value);
    if(v === null) return null;
    if(min !== undefined && v < min){ v = min; el.value = perfMoedaFmtV118(v); }
    if(max !== undefined && v > max){ v = max; el.value = perfMoedaFmtV118(v); }
    return v;
  }
  let v = parseFloat(String(el.value).replace(',', '.'));
  if(!isFinite(v)) return null;
  if(min !== undefined && v < min){ v = min; el.value = min; }
  if(max !== undefined && v > max){ v = max; el.value = max; }
  return v;
}
function perfLerForm(){
  const v = id => document.getElementById(id).value;
  return {modo: _perf.form.modo, renda: perfNum('perf-renda', 0) || 0, parcela: perfNum('perf-parcela', 0) || 0, entrada: perfNum('perf-entrada', 0) || 0,
          prazo: Number(v('perf-prazo')) || 360, juros: perfNum('perf-juros', 0, 40) || 0, capital: perfNum('perf-capital', 0) || 0,
          retmin: Number(v('perf-retmin')) || 0, ufs: [..._perf.form.ufs], tipo: v('perf-tipo'), zona: v('perf-zona'),
          quartos: Number(v('perf-quartos')) || 0, vmin: perfNum('perf-vmin', 0), vmax: perfNum('perf-vmax', 0),
          soopp: document.getElementById('perf-soopp').checked, email: document.getElementById('perf-email').checked, alvo: v('perf-alvo')};
}
function perfJurosMes(f){ return Math.pow(1 + (f.juros || 0) / 100, 1 / 12) - 1; }
/* SAC: 1ª parcela = P/n + P·i  ->  P = parcela / (1/n + i) */
function perfMaxCompra(f){ const n = f.prazo || 360; return f.entrada + f.parcela / (1 / n + perfJurosMes(f)); }
function perfParcela(f, lance){ const P = Math.max(0, lance - f.entrada), n = f.prazo || 360; return P / n + P * perfJurosMes(f); }
function perfResultados(f){
  const base = (typeof leiloesDados !== 'undefined' ? leiloesDados : []).concat(typeof radarVisivel === 'function' ? radarVisivel() : radarLista());
  const mc = perfMaxCompra(f);
  const r = [];
  base.forEach(l => {
    const t = vitNormTipo(l.tipo_imovel), lance = Number(l.lance_minimo) || 0;
    if(f.ufs.length && !f.ufs.includes(l.uf)) return;
    if(f.tipo && t !== f.tipo) return;
    if(f.zona && (f.zona === 'rural') !== PERFIL_RURAIS.includes(t)) return;
    if(f.quartos > 0 && !(typeof l.quartos === 'number' && l.quartos >= f.quartos)) return;
    if(f.vmin && lance < f.vmin) return;
    if(f.vmax && lance > f.vmax) return;
    if(f.soopp && !leiOportunidade(l)) return;
    if(l.status && l.status !== 'aberto') return;
    const k = leiLucro(l);
    if(f.modo === 'morar'){
      if(!f.tipo && PERFIL_NAO_MORADIA.includes(t)) return;
      if(l.financiamento === false ? lance > f.entrada : lance > mc) return;
    } else {
      if(lance > f.capital) return;
      if(!k || k.retorno < f.retmin) return;
    }
    r.push({l, k});
  });
  return r.sort(f.modo === 'investir' ? (a, b) => (b.k ? b.k.lucro : -1e15) - (a.k ? a.k.lucro : -1e15)
                                      : (a, b) => (leiDesconto(b.l) || 0) - (leiDesconto(a.l) || 0));
}
function perfCartao(x, f){
  const l = x.l, k = x.k, opp = leiOportunidade(l), d = leiDesconto(l);
  const linha = (a, b, cls) => '<tr' + (cls ? ' class="' + cls + '"' : '') + '><td>' + a + '</td><td>' + b + '</td></tr>';
  const extra = f.modo === 'morar'
    ? linha('Parcela estimada (1ª do SAC)', l.financiamento === false ? 'Sem financiamento (à vista)' : perfBRL(perfParcela(f, Number(l.lance_minimo))) + (l.financiamento === true ? '' : ' <small>(confirme o financiamento)</small>'))
    : (k ? linha('Retorno sobre o lance', '<span class="' + (k.retorno >= 0 ? 'desemp-ok' : 'desemp-ruim') + '">' + perfPct(k.retorno) + '</span>') : '');
  return '<button type="button" class="perf-card' + (opp ? ' perf-opp' : '') + '" data-perf-id="' + escHtml(l.id) + '">'
    + '<div class="perf-ctop"><div><div class="perf-tit">' + escHtml(l.titulo || vitNomeTipo(l.tipo_imovel)) + '</div>'
    + '<div class="perf-loc">' + escHtml([l.cidade && (l.cidade + '/' + l.uf), l.radar ? (l.modalidade === 'judicial' ? 'Judicial' : (l.banco_nome || 'Caixa')) : 'Analisado SOLIDUNS'].filter(Boolean).join(' · ')) + '</div></div>'
    + '<span class="perf-pill' + (opp ? ' opp' : '') + '">' + (opp ? '★ Oportunidade' : (d !== null ? 'Deságio ' + perfPct(d) : 'Sem avaliação')) + '</span></div>'
    + (d !== null ? '<div class="perf-bar" title="Deságio sobre a avaliação"><i style="width:' + Math.max(0, Math.min(100, d)) + '%"></i></div>' : '')
    + '<table class="perf-k">'
    + (k ? linha('Avaliação', perfBRL(k.av)) : '')
    + linha('Lance mínimo', perfBRL(Number(l.lance_minimo) || 0))
    + (k ? linha('Custas e liquidez (15% da avaliação)', '− ' + perfBRL(k.custas + k.liquidez)) : '')
    + (k ? linha('Lucro estimado', '<span class="' + (k.lucro >= 0 ? 'desemp-ok' : 'desemp-ruim') + '">' + perfBRL(k.lucro) + '</span>', 'tot') : '')
    + extra + '</table>'
    + '<div class="perf-foot">' + escHtml(vitNomeTipo(l.tipo_imovel)) + (typeof l.quartos === 'number' && l.quartos > 0 ? ' · ' + l.quartos + ' quarto(s)' : '')
    + ' · ' + (PERFIL_RURAIS.includes(vitNormTipo(l.tipo_imovel)) ? 'rural' : 'urbano') + '</div></button>';
}
function perfDesenhar(){
  if(!document.getElementById('leilao-perfil-overlay')) return;
  const f = perfLerForm();
  _perf.form = f;
  const morar = f.modo === 'morar';
  document.getElementById('perf-m-morar').setAttribute('aria-pressed', morar ? 'true' : 'false');
  document.getElementById('perf-m-inv').setAttribute('aria-pressed', morar ? 'false' : 'true');
  document.getElementById('perf-box-morar').hidden = !morar;
  document.getElementById('perf-box-inv').hidden = morar;
  document.getElementById('perf-o-sug').textContent = perfBRL(f.renda * 0.3);
  document.getElementById('perf-o-max').textContent = perfBRL(perfMaxCompra(f));
  document.getElementById('perf-o-cap').textContent = perfBRL(f.capital);
  document.getElementById('perf-o-ret').textContent = f.retmin + '%';
  document.getElementById('perf-aviso-parcela').textContent = f.renda > 0 && f.parcela > f.renda * 0.3
    ? 'Atenção: a parcela passa de 30% da renda; os bancos costumam limitar a esse teto.' : '';
  const r = perfResultados(f);
  const nOpp = r.filter(x => leiOportunidade(x.l)).length;
  const lucroTot = r.reduce((s, x) => s + (x.k && x.k.lucro > 0 ? x.k.lucro : 0), 0);
  document.getElementById('perf-count').textContent = r.length.toLocaleString('pt-BR') + (r.length === 1 ? ' imóvel' : ' imóveis')
    + (nOpp ? ' · ' + nOpp + ' oportunidade(s)' : '');
  document.getElementById('perf-resumo').innerHTML = r.length && !morar
    ? 'Lucro estimado somado dos ' + r.length + ' imóveis: <b>' + perfBRL(lucroTot) + '</b> (cada um com o lance mínimo).' : '';
  const lista = document.getElementById('perf-lista');
  if(!radarLista().length && !(typeof leiloesDados !== 'undefined' && leiloesDados.length)){
    lista.innerHTML = '<div class="perf-vazio">Carregando os imóveis do Leilão…</div>';
  } else {
    lista.innerHTML = r.length ? r.slice(0, _perf.mostrar).map(x => perfCartao(x, f)).join('')
      : '<div class="perf-vazio">Nenhum imóvel com esse perfil hoje. Amplie os estados ou a faixa de valor. Com o e-mail ligado, você recebe um aviso quando entrar um imóvel compatível.</div>';
  }
  document.getElementById('perf-mais').style.display = r.length > _perf.mostrar ? '' : 'none';
}
function perfFiltrosAlerta(f){
  const a = {perfil: true, form: f};
  if(f.ufs.length) a.ufs = f.ufs.slice(0, 27);
  if(f.tipo) a.tipos = [f.tipo];
  else if(f.modo === 'morar') a.tipos = VIT_TIPOS_GRUPOS.flatMap(g => g[1].map(o => o[0])).filter(t => !PERFIL_NAO_MORADIA.includes(t));
  if(f.zona) a.zona = f.zona;
  if(f.quartos > 0) a.quartos_min = f.quartos;
  if(f.vmin) a.preco_min = f.vmin;
  if(f.modo === 'morar'){ a.compra_max = Math.round(perfMaxCompra(f)); a.entrada = f.entrada; if(f.vmax) a.preco_max = f.vmax; }
  else { a.preco_max = f.vmax ? Math.min(f.vmax, f.capital) : f.capital; a.retorno_min = f.retmin; }
  if(f.soopp || f.alvo === 'opp') a.oportunidade = true;
  return a;
}
function perfResumoTexto(f){
  const p = [f.modo === 'morar' ? 'para morar' : 'para investir'];
  p.push(f.ufs.length ? f.ufs.join(', ') : 'todos os estados');
  if(f.tipo) p.push(vitNomeTipo(f.tipo));
  if(f.zona) p.push(f.zona);
  if(f.quartos > 0) p.push(f.quartos + '+ quartos');
  if(f.modo === 'morar') p.push('compra até ' + perfBRL(perfMaxCompra(f)));
  else p.push('lance até ' + perfBRL(f.capital) + ', retorno ≥ ' + f.retmin + '%');
  if(f.soopp || f.alvo === 'opp') p.push('só oportunidades');
  return p.join(' · ');
}
var _alertaResumoV78L = alertaResumo;
alertaResumo = function(f){ return f && f.perfil && f.form ? 'Perfil: ' + perfResumoTexto(Object.assign({}, PERFIL_PADRAO, f.form)) : _alertaResumoV78L(f); };

async function perfSalvar(ev){
  if(ev) ev.preventDefault();
  const msg = document.getElementById('perf-toast');
  const f = perfLerForm();
  msg.className = 'perf-toast';
  msg.textContent = 'Salvando…';
  const corpo = {nome: PERFIL_NOME, filtros: perfFiltrosAlerta(f), ativo: !!f.email};
  let r;
  if(_perf.alertaId) r = await alertaRest('PATCH', 'leiloes_alertas?id=eq.' + encodeURIComponent(_perf.alertaId), corpo);
  else{
    r = await alertaRest('POST', 'leiloes_alertas', corpo);
    if(r.ok && Array.isArray(r.dados) && r.dados[0]) _perf.alertaId = r.dados[0].id;
  }
  try{ localStorage.setItem('soliduns_perfil_imovel', JSON.stringify(f)); }catch(e){}
  if(!r.ok){ msg.className = 'perf-toast erro'; msg.textContent = 'Perfil guardado só neste aparelho. ' + r.erro; return; }
  const em = (sessaoAtual && (sessaoAtual.email || (sessaoAtual.user && sessaoAtual.user.email))) || 'o e-mail da sua conta';
  msg.textContent = f.email ? 'Perfil salvo. Todo dia às 7h40, se entrar imóvel novo ' + (f.alvo === 'opp' || f.soopp ? '(só oportunidades) ' : '') + 'deste perfil, o aviso vai para ' + em + '.'
                            : 'Perfil salvo. E-mail desligado (ligue quando quiser).';
}
async function perfCarregar(){
  let form = null;
  try{ form = JSON.parse(localStorage.getItem('soliduns_perfil_imovel') || 'null'); }catch(e){ form = null; }
  _perf.alertaId = null;
  const r = await alertaRest('GET', 'leiloes_alertas?select=id,nome,filtros,ativo&nome=eq.' + encodeURIComponent(PERFIL_NOME) + '&order=criado_em.asc&limit=1');
  if(r.ok && Array.isArray(r.dados) && r.dados[0]){
    _perf.alertaId = r.dados[0].id;
    if(r.dados[0].filtros && r.dados[0].filtros.form) form = Object.assign({}, r.dados[0].filtros.form, {email: !!r.dados[0].ativo});
  }
  return Object.assign({}, PERFIL_PADRAO, form || {});
}
function perfPreencher(f){
  const set = (id, v) => { const el = document.getElementById(id); if(el) el.value = v === null || v === undefined ? '' : String(v); };
  _perf.form = Object.assign({}, PERFIL_PADRAO, f, {ufs: (f.ufs || []).filter(u => UF_LIST.some(x => x.sigla === u))});
  set('perf-renda', f.renda); set('perf-parcela', f.parcela); set('perf-entrada', f.entrada);
  set('perf-prazo', PERFIL_PRAZOS.includes(Number(f.prazo)) ? f.prazo : 360); set('perf-juros', f.juros);
  set('perf-capital', f.capital); set('perf-retmin', PERFIL_RETORNOS.includes(Number(f.retmin)) ? f.retmin : 30);
  set('perf-tipo', VIT_TIPOS_GRUPOS.some(g => g[1].some(o => o[0] === f.tipo)) ? f.tipo : '');
  set('perf-zona', ['urbana', 'rural'].includes(f.zona) ? f.zona : ''); set('perf-quartos', [0, 1, 2, 3, 4].includes(Number(f.quartos)) ? f.quartos : 0);
  set('perf-vmin', f.vmin || ''); set('perf-vmax', f.vmax || ''); set('perf-alvo', f.alvo === 'opp' ? 'opp' : 'todos');
  document.getElementById('perf-soopp').checked = !!f.soopp;
  document.getElementById('perf-email').checked = f.email !== false;
  document.querySelectorAll('#perf-ufs [data-uf]').forEach(b => b.setAttribute('aria-pressed', _perf.form.ufs.includes(b.getAttribute('data-uf')) ? 'true' : 'false'));
}
