  const ov = document.getElementById('leilao-perfil-overlay');
  const fechar = () => { ov.style.display = 'none'; };
  document.getElementById('perf-fechar').addEventListener('click', fechar);
  ov.addEventListener('click', e => { if(e.target === ov) fechar(); });
  document.addEventListener('keydown', e => { if(e.key === 'Escape' && ov.style.display !== 'none' && document.getElementById('leilao-ficha-overlay').style.display === 'none') fechar(); });
  document.getElementById('perf-m-morar').addEventListener('click', () => { _perf.form.modo = 'morar'; perfDesenhar(); });
