/* exportar planilha (.csv para Excel em português) */
function veiExportarV87(){
  const linhas = _vei.itens || [];
  if(!linhas.length){ alert('Nenhum lote na tela para exportar. Ajuste os filtros e busque de novo.'); return; }
  const cab = ['Título', 'Tipo', 'Modalidade', 'Marca', 'Modelo (família)', 'Ano fabricação', 'Ano modelo', 'Km', 'Combustível',
               'Condição', 'Cidade', 'UF', 'Lance inicial (R$)', 'Avaliação (R$)', 'FIPE (R$)', 'Deságio FIPE (%)',
               'Data do leilão', 'Anunciante', 'Favorito', 'Link'];
  const num = v => (v === null || v === undefined || v === '') ? '' : String(v).replace('.', ',');
  const cel = v => '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
  const corpo = linhas.map(l => [l.titulo, veiRotulo(VEI_TIPOS, l.tipo), veiRotulo(VEI_MODALIDADES, veiModalidadeV86(l)),
    l.marca, l.familia, l.ano_fabricacao, l.ano_modelo, l.km, l.combustivel, veiRotulo(VEI_CONDICOES, l.condicao),
    l.cidade, l.uf, num(l.lance_inicial), num(l.avaliacao), num(l.fipe_valor), num(l.desagio_fipe),
    veiData(l.data_leilao), l.origem_nome || l.anunciante_sigla, vfavListaV87().has(l.id) ? 'Sim' : '', l.url].map(cel).join(';'));
  const csv = '﻿' + cab.map(cel).join(';') + '\r\n' + corpo.join('\r\n');
  const a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([csv], {type: 'text/csv;charset=utf-8'}));
  a.download = 'veiculos_soliduns_' + veiHoje() + '.csv';
  document.body.appendChild(a); a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 2000);
}
