/* ===== v90 — ALERTAS DE VEÍCULOS POR E-MAIL (SQL 118) (patch90lei) ===== */
var VALERT_MAX = 5;
function valertFiltrosV90(){
  const v = veiFiltrosAtuais(), f = {};
  if(v.tipo) f.tipo = v.tipo;
  if(v.marca) f.marca = v.marca;
  if(v.familia) f.familia = v.familia;
  if(v.uf) f.uf = v.uf;
  if(v.cidade) f.cidade = v.cidade;
  if(v.fonte) f.fonte = v.fonte;
  if(v.modalidade) f.modalidade = v.modalidade;
  if(v.condicao) f.condicao = v.condicao;
  if(v.combustivel) f.combustivel = v.combustivel;
  if(v.lanceMin) f.lance_min = v.lanceMin;
  if(v.lanceMax) f.lance_max = v.lanceMax;
  if(v.desagio) f.desagio_min = Number(v.desagio);
  if(v.km) f.km_max = Number(v.km);
  if(v.anoDe) f.ano_de = Number(v.anoDe);
  if(v.anoAte) f.ano_ate = Number(v.anoAte);
  if(v.texto && v.texto.length) f.texto = v.texto.slice(0, 6).map(t => normalizarTexto(t));
  return f;
}
function valertResumoV90(f){
  const p = [];
  if(f.tipo) p.push(veiRotulo(VEI_TIPOS, f.tipo));
  if(f.marca) p.push(f.marca + (f.familia ? ' ' + f.familia : ''));
  if(f.cidade) p.push(f.cidade + (f.uf ? '/' + f.uf : '')); else if(f.uf) p.push(f.uf);
  if(f.modalidade) p.push(veiRotulo(VEI_MODALIDADES, f.modalidade).toLowerCase());
  if(f.fonte) p.push(veiRotulo(VEI_FONTES, f.fonte));
  if(f.condicao) p.push(veiRotulo(VEI_CONDICOES, f.condicao).toLowerCase());
  if(f.combustivel) p.push(f.combustivel.toLowerCase());
  if(f.ano_de) p.push('ano ≥ ' + f.ano_de);
  if(f.ano_ate) p.push('ano ≤ ' + f.ano_ate);
  if(f.lance_min) p.push('a partir de ' + formatBRL(f.lance_min));
  if(f.lance_max) p.push('até ' + formatBRL(f.lance_max));
  if(f.desagio_min) p.push('deságio ≥ ' + f.desagio_min + '%');
  if(f.km_max) p.push('até ' + Number(f.km_max).toLocaleString('pt-BR') + ' km');
  if(f.texto && f.texto.length) p.push('"' + f.texto.join(' ') + '"');
  return p.length ? p.join(' · ') : 'todos os veículos novos';
}
function valertBotoesV90(){
  const on = vitOnline() && sessaoAtual && sessaoAtual.user;
  ['vei-criar-alerta', 'vei-meus-alertas'].forEach(id => { const b = veiEl(id); if(b) b.style.display = on ? '' : 'none'; });
}
async function valertRestV90(metodo, caminho, corpo){
  const r = await alertaRest(metodo, caminho, corpo);
  if(!r.ok && /SQL 63/.test(r.erro || '')) r.erro = 'Os alertas de veículos ainda não foram ativados no banco (SQL 118).';
  return r;
}
async function valertCriarV90(){
  const f = valertFiltrosV90();
  const resumo = valertResumoV90(f);
  if(!Object.keys(f).length && !confirm('Nenhum filtro escolhido: o alerta vai avisar TODOS os veículos novos (pode ser muita coisa). Criar mesmo assim?')) return;
  const nome = (prompt('Nome do alerta de veículos:', resumo.slice(0, 80)) || '').trim();
  if(!nome) return;
  const r = await valertRestV90('POST', 'veiculos_alertas', {nome: nome.slice(0, 120), filtros: f});
  if(!r.ok){ alert(r.erro); return; }
  alert('Alerta criado: ' + resumo + '.\nTodo dia às 7h40, se houver veículo novo com esses filtros, você recebe um e-mail (o mesmo e-mail diário dos imóveis).');
}
