/* ===== v94 — MEU PERFIL DE VEÍCULO (usa veiculos_alertas do SQL 118) (patch94lei) ===== */
var VPERFIL_NOME = 'Meu perfil de veículo';
var _vperf = {alertaId: null, form: null};
function vperfFiltrosV94(fm){
  const f = {perfil: true, form: fm};
  if(fm.tipo) f.tipo = fm.tipo;
  if(fm.uf) f.uf = fm.uf;
  if(fm.orcamento > 0) f.lance_max = fm.orcamento;
  if(fm.ano_min > 0) f.ano_de = fm.ano_min;
  if(fm.km_max > 0) f.km_max = fm.km_max;
  if(fm.combustivel) f.combustivel = fm.combustivel;
  if(fm.objetivo === 'usar') f.condicao = 'circulacao';
  if(fm.objetivo === 'revender' && fm.desagio_min > 0) f.desagio_min = fm.desagio_min;
  return f;
}
function vperfResumoV94(fm){
  const p = [fm.objetivo === 'revender' ? 'para revender' : 'para usar'];
  if(fm.tipo) p.push(veiRotulo(VEI_TIPOS, fm.tipo).toLowerCase());
  if(fm.uf) p.push(fm.uf);
  if(fm.orcamento > 0) p.push('até ' + formatBRL(fm.orcamento));
  if(fm.ano_min > 0) p.push('ano ≥ ' + fm.ano_min);
  if(fm.km_max > 0) p.push('até ' + Number(fm.km_max).toLocaleString('pt-BR') + ' km');
  if(fm.combustivel) p.push(fm.combustivel.toLowerCase());
  if(fm.objetivo === 'revender' && fm.desagio_min > 0) p.push('deságio ≥ ' + fm.desagio_min + '%');
  return p.join(' · ');
}
