async function vperfSalvarV94(silencioso){
  const fm = vperfFormLerV94();
  const corpo = {nome: VPERFIL_NOME, filtros: vperfFiltrosV94(fm), ativo: true};
  let r;
  if(_vperf.alertaId) r = await valertRestV90('PATCH', 'veiculos_alertas?id=eq.' + encodeURIComponent(_vperf.alertaId), corpo);
  else r = await valertRestV90('POST', 'veiculos_alertas', corpo);
  if(!r.ok){ alert(r.erro); return false; }
  if(!_vperf.alertaId && Array.isArray(r.dados) && r.dados[0]) _vperf.alertaId = r.dados[0].id;
  _vperf.form = fm;
  veiEl('vperf-apagar').style.display = '';
  veiEl('vperf-aviso').textContent = 'Perfil salvo: ' + vperfResumoV94(fm) + '.';
  if(!silencioso) alert('Perfil salvo! Todo dia às 7h40, os veículos novos que combinam entram no seu e-mail diário.');
  return true;
}
async function vperfVerV94(){
  const fm = vperfFormLerV94();
  veiEl('vperf-overlay').style.display = 'none';
  const limpar = veiEl('vei-limpar');
  if(limpar) limpar.click();
  await new Promise(res => setTimeout(res, 50));
  if(fm.tipo) veiEl('vei-f-tipo').value = fm.tipo;
  if(fm.uf) veiEl('vei-f-uf').value = fm.uf;
  if(fm.orcamento > 0) veiEl('vei-f-lance-max').value = fm.orcamento;
  if(fm.ano_min > 0) veiEl('vei-f-ano-de').value = fm.ano_min;
  if(fm.km_max > 0) veiEl('vei-f-km').value = fm.km_max;
  if(fm.combustivel) veiEl('vei-f-combustivel').value = fm.combustivel;
  if(fm.objetivo === 'usar') veiEl('vei-f-condicao').value = 'circulacao';
  if(fm.objetivo === 'revender' && fm.desagio_min > 0){
    const sd = veiEl('vei-f-desagio');
    const op = [...sd.options].map(o => Number(o.value)).filter(v => v > 0 && v <= fm.desagio_min).sort((a, b) => b - a)[0];
    if(op) sd.value = String(op);
  }
  veiBuscar();
}
