/* ===== v95 — FICHA DO VEÍCULO EM PDF (patch95lei) ===== */
function vpdfFolhaV95(l){
  const linha = (rot, val) => (val === null || val === undefined || val === '' || val === '—') ? '' : '<tr><th>' + rot + '</th><td>' + val + '</td></tr>';
  const q = vhistQuedaV93(l);
  const foto = veiFotoV86(l);
  const hoje = new Date().toLocaleDateString('pt-BR');
  return '<div class="vpdf-topo"><b>SOLIDUNS</b><span style="font-size:11px;">Leilão de Automóveis · ficha emitida em ' + hoje + '</span></div>'
    + '<div class="vpdf-faixa"></div><div class="vpdf-corpo">'
    + '<h1>' + escHtml(l.titulo || 'Veículo') + '</h1>'
    + '<p class="vpdf-sub">' + escHtml(veiRotulo(VEI_TIPOS, l.tipo)) + ' · ' + escHtml(veiRotulo(VEI_MODALIDADES, veiModalidadeV86(l)))
    + (l.fonte === 'banco' ? ' · retomado de banco' : '') + ' · ' + escHtml(veiAnuncianteV86(l)) + (l.lote ? ' · lote ' + escHtml(l.lote) : '') + '</p>'
    + (foto ? '<img class="vpdf-foto" src="' + escHtml(foto) + '" referrerpolicy="no-referrer" alt="Foto do lote">' : '')
    + '<table>'
    + linha('Lance inicial', veiBRL(l.lance_inicial))
    + linha('Avaliação', veiBRL(l.avaliacao))
    + linha('Tabela FIPE', l.condicao === 'sucata' ? 'Não se aplica (sucata)' : (Number(l.fipe_valor) > 0 ? formatBRL(Number(l.fipe_valor)) + (l.fipe_referencia ? ' (' + escHtml(l.fipe_referencia) + ')' : '') : ''))
    + linha('Deságio sobre a FIPE', l.desagio_fipe !== null && l.desagio_fipe !== undefined ? String(l.desagio_fipe).replace('.', ',') + '%' : '')
    + (q ? linha('Histórico do lance', 'caiu de ' + formatBRL(q.de) + ' para ' + formatBRL(q.para) + ' (−' + panPct(q.pct).replace('%', '') + '%)') : '')
    + linha('Marca / modelo', escHtml([l.marca, l.familia].filter(Boolean).join(' ')))
    + linha('Como está no anúncio', escHtml(l.modelo_texto || ''))
    + linha('Ano (fabricação/modelo)', escHtml(veiAnoTxt(l)))
    + linha('Quilometragem', l.km !== null && l.km !== undefined ? Number(l.km).toLocaleString('pt-BR') + ' km' : '')
    + linha('Combustível', escHtml(l.combustivel || '')) + linha('Cor', escHtml(l.cor || ''))
    + linha('Final da placa', escHtml(l.placa_final || ''))
    + linha('Condição', escHtml(veiRotulo(VEI_CONDICOES, l.condicao)))
    + linha('Local', escHtml(l.cidade ? l.cidade + '/' + l.uf : (l.uf || '')) + (l.patio ? ' · pátio ' + escHtml(l.patio) : ''))
    + linha('Data do leilão', veiData(l.data_leilao) + (l.data_fim && l.data_fim !== l.data_leilao ? ' até ' + veiData(l.data_fim) : ''))
    + linha('Processo / edital', escHtml(l.processo || ''))
    + linha('Leiloeiro', escHtml(l.leiloeiro || ''))
    + linha('Página oficial', /^https:\/\//i.test(l.url || '') ? escHtml(l.url) : '')
    + linha('Ficha na SOLIDUNS', escHtml(vcompLinkV87(l)))
    + '</table>'
    + (l.descricao ? '<div style="font-size:11.5px;"><b>' + (l.fonte === 'leiloeiro' || l.fonte === 'banco' ? 'Descrição do anúncio' : 'Trecho do edital') + ' (dados pessoais omitidos):</b><br>' + escHtml(String(l.descricao).slice(0, 1200)) + '</div>' : '')
    + '<div class="vpdf-aviso">Leitura automática das fontes públicas, sem análise e sem custo. Não é recomendação de compra nem oferta. '
    + 'Antes de dar lance, confira o edital: vistoria, débitos (IPVA, multas), documentação, sinistro, taxas do leiloeiro e regras de retirada. '
    + 'SOLIDUNS · soliduns.com.br · contato@soliduns.com.br</div></div>';
}
function vpdfImprimirV95(l){
  let folha = veiEl('vpdf-folha');
  if(!folha){ document.body.insertAdjacentHTML('beforeend', '<div id="vpdf-folha"></div>'); folha = veiEl('vpdf-folha'); }
  folha.innerHTML = vpdfFolhaV95(l);
  document.body.classList.add('vpdf-imprimindo');
  const sair = () => { document.body.classList.remove('vpdf-imprimindo'); window.removeEventListener('afterprint', sair); };
  window.addEventListener('afterprint', sair);
  setTimeout(() => { try{ window.print(); }catch(e){} setTimeout(sair, 1500); }, 60);
}
var _veiFichaV95 = veiFicha;
