/* ===== v103 — PAINEL ADMIN DE QUALIDADE DOS VEÍCULOS (SQL 122) (patch103lei) ===== */
var VQUAL_CHECKS = [['sem_data', 'Sem data do leilão'], ['sem_lance', 'Sem lance'], ['lance_suspeito', 'Lance suspeito'],
  ['sem_foto', 'Sem foto'], ['sem_marca', 'Sem marca FIPE'], ['sem_fipe', 'Sem valor FIPE'], ['sem_cidade', 'Sem cidade'],
  ['duplicado', 'Duplicado provável']];
var _vqual = {lotes: [], ocultos: new Map(), ok: null, dupl: new Set()};
function vqualAdminV103(){ return typeof ehAdmin === 'function' && ehAdmin() && vitOnline(); }
function vqualProblemasV103(l){
  const p = [], lance = Number(l.lance_inicial), d = Number(l.desagio_fipe);
  if(!l.data_leilao) p.push('sem_data');
  if(!(lance > 0)) p.push('sem_lance');
  else if(lance < 500 || (isFinite(d) && l.desagio_fipe !== null && d > 90)) p.push('lance_suspeito');
  if(!l.foto_url && l.fonte !== 'djen') p.push('sem_foto');
  if(!l.marca) p.push('sem_marca');
  if(!(Number(l.fipe_valor) > 0) && l.tipo !== 'maquina' && l.condicao !== 'sucata') p.push('sem_fipe');
  if(!l.cidade) p.push('sem_cidade');
  if(_vqual.dupl.has(l.id)) p.push('duplicado');
  return p;
}
async function vqualCarregarV103(){
  const cols = 'id,titulo,fonte,origem_nome,anunciante_sigla,tipo,marca,familia,ano_modelo,ano_fabricacao,uf,cidade,lance_inicial,fipe_valor,desagio_fipe,data_leilao,foto_url,condicao,modalidade,url';
  const todos = [];
  for(let pag = 0; pag < 6; pag++){
    const r = await veiRest('veiculos_leiloes?select=' + cols + '&situacao=eq.ativo&order=id.asc&limit=1000&offset=' + pag * 1000);
    if(!r.ok || !Array.isArray(r.dados)) break;
    todos.push(...r.dados);
    if(r.dados.length < 1000) break;
  }
  _vqual.lotes = todos;
  const grupos = new Map();
  todos.forEach(l => {
    if(!l.marca || !(Number(l.lance_inicial) > 0)) return;
    const k = [l.marca, l.familia || '', l.ano_modelo || l.ano_fabricacao || '', Number(l.lance_inicial), l.uf || ''].join('|');
    if(!grupos.has(k)) grupos.set(k, []);
    grupos.get(k).push(l.id);
  });
  _vqual.dupl = new Set([...grupos.values()].filter(g => g.length > 1).flat());
  await vqualOcultosV103();
}
async function vqualOcultosV103(){
  const r = await alertaRest('GET', 'leiloes_ocultos?select=item_id,motivo,por,em&item_id=not.like.radar-*&order=em.desc&limit=2000');
  _vqual.ok = r.ok;
  _vqual.ocultos = new Map(r.ok ? (r.dados || []).map(o => [o.item_id, o]) : []);
}
function vqualAbrirV103(){
  if(!vqualAdminV103()) return;
  if(!veiEl('vqual-overlay')){
    document.body.insertAdjacentHTML('beforeend', '<div id="vqual-overlay" class="leilao-ficha-overlay" style="display:none;"><div class="leilao-ficha-box" style="max-width:1080px;">'
      + '<button type="button" class="voltar-link" id="vqual-fechar">&larr; Voltar aos veículos</button>'
      + '<h2 style="margin:4px 0 2px;">Qualidade dos dados — Veículos</h2>'
      + '<p style="font-size:12.5px; color:var(--ink-soft); margin:0 0 10px;">Verificações automáticas sobre todos os lotes ativos. "Ocultar" tira o lote do painel e dos e-mails '
      + 'de todos os assinantes, com o motivo registrado; os robôs não o trazem de volta. "Reexibir" desfaz. Duplicados não são escondidos sozinhos: você decide.</p>'
      + '<div style="display:flex; gap:10px; flex-wrap:wrap; margin-bottom:10px;"><label style="font-size:12px;">Problema <select id="vqual-filtro"></select></label>'
      + '<span id="vqual-cont" style="font-size:12px; color:var(--ink-soft); align-self:center;"></span></div>'
      + '<div id="vqual-lista"><p style="font-size:13px;">Carregando…</p></div><h3 style="margin:18px 0 6px;">Ocultados</h3><div id="vqual-ocultos"></div></div></div>');
    veiEl('vqual-fechar').addEventListener('click', () => { veiEl('vqual-overlay').style.display = 'none'; });
    veiEl('vqual-filtro').addEventListener('change', vqualDesenharV103);
    veiEl('vqual-overlay').addEventListener('click', async ev => {
      const fi = ev.target.closest('[data-vqual-ficha]');
      if(fi){
        const id = fi.getAttribute('data-vqual-ficha');
        const l = _vqual.lotes.find(x => x.id === id);
        if(l && !_vei.itens.find(x => x.id === id)){
          const r = await veiRest('veiculos_leiloes?select=*&id=eq.' + encodeURIComponent(id) + '&limit=1');
          _vei.itens.push(r.ok && r.dados && r.dados[0] ? r.dados[0] : l);
        }
        veiEl('vqual-overlay').style.display = 'none'; veiFicha(id); return;
      }
      const oc = ev.target.closest('[data-vqual-ocultar]');
      if(oc){
        const motivo = (prompt('Motivo para ocultar este veículo de todos os assinantes:', 'Dado suspeito') || '').trim();
        if(!motivo) return;
        const r = await alertaRest('POST', 'leiloes_ocultos', {item_id: oc.getAttribute('data-vqual-ocultar'), motivo: motivo.slice(0, 300)});
        if(!r.ok){ alert(r.erro); return; }
        await vqualOcultosV103(); vqualDesenharV103(); veiDesenhar(); return;
      }
      const re = ev.target.closest('[data-vqual-reexibir]');
      if(re){
        const r = await alertaRest('DELETE', 'leiloes_ocultos?item_id=eq.' + encodeURIComponent(re.getAttribute('data-vqual-reexibir')));
        if(!r.ok){ alert(r.erro); return; }
        await vqualOcultosV103(); vqualDesenharV103(); veiDesenhar();
      }
    });
  }
  veiEl('vqual-overlay').style.display = 'flex';
  veiEl('vqual-lista').innerHTML = '<p style="font-size:13px;">Carregando todos os lotes ativos…</p>';
  vqualCarregarV103().then(vqualDesenharV103);
}
function vqualDesenharV103(){
  if(_vqual.ok === false) veiEl('vqual-ocultos').innerHTML = '<p style="font-size:12.5px;">A tabela de ocultos não respondeu (confira os SQL 104 e 122).</p>';
  const itens = _vqual.lotes.filter(l => !_vqual.ocultos.has(l.id)).map(l => ({l, p: vqualProblemasV103(l)})).filter(x => x.p.length);
  const cont = {}; itens.forEach(x => x.p.forEach(c => { cont[c] = (cont[c] || 0) + 1; }));
  const sel = veiEl('vqual-filtro'), atual = sel.value;
  sel.innerHTML = '<option value="">Todos (' + itens.length + ')</option>' + VQUAL_CHECKS.map(([c, r]) => '<option value="' + c + '">' + r + ' (' + (cont[c] || 0) + ')</option>').join('');
  sel.value = atual;
  const vis = itens.filter(x => !sel.value || x.p.includes(sel.value));
  veiEl('vqual-cont').textContent = _vqual.lotes.length.toLocaleString('pt-BR') + ' lote(s) ativo(s) verificados · ' + vis.length + ' com problema' + (vis.length > 300 ? ' (mostrando 300)' : '');
  const rot = Object.fromEntries(VQUAL_CHECKS);
  const td = h => '<td style="padding:6px; border-bottom:1px solid var(--line); vertical-align:top;">' + h + '</td>';
  veiEl('vqual-lista').innerHTML = vis.length ? '<div style="overflow-x:auto;"><table style="width:100%; border-collapse:collapse; font-size:12.5px;"><tbody>'
    + vis.slice(0, 300).map(x => '<tr data-vqual="' + escHtml(x.l.id) + '">'
      + td('<b>' + escHtml(x.l.titulo || 'Veículo') + '</b><br><span style="color:var(--ink-soft);">' + escHtml(veiAnuncianteV86(x.l)) + ' · '
        + escHtml(x.l.cidade ? x.l.cidade + '/' + x.l.uf : (x.l.uf || 'sem UF')) + ' · ' + escHtml(x.l.id) + '</span>')
      + td(veiBRL(x.l.lance_inicial) + (Number(x.l.fipe_valor) > 0 ? '<br><span style="color:var(--ink-soft);">FIPE ' + formatBRL(Number(x.l.fipe_valor)) + '</span>' : ''))
      + td(x.p.map(c => '<span class="lei-selo-origem lei-selo-radar" style="margin:0 4px 4px 0;">' + escHtml(rot[c]) + '</span>').join(''))
      + td('<button type="button" class="leilao-limpar-filtros" data-vqual-ficha="' + escHtml(x.l.id) + '">Ficha</button> '
        + '<button type="button" class="leilao-limpar-filtros" data-vqual-ocultar="' + escHtml(x.l.id) + '">Ocultar</button>')
      + '</tr>').join('') + '</tbody></table></div>' : '<div class="placeholder-area">Nenhum problema encontrado.</div>';
  const oc = [..._vqual.ocultos.values()];
  veiEl('vqual-ocultos').innerHTML = oc.length ? oc.map(o => '<div class="leilao-ficha-item" data-vqual-oculto="' + escHtml(o.item_id) + '" style="margin-bottom:6px;"><div><b>' + escHtml(o.item_id) + '</b> — ' + escHtml(o.motivo)
      + '<div style="font-size:11px; color:var(--ink-soft);">por ' + escHtml(o.por || '?') + ' em ' + escHtml(formatarDataBR(String(o.em).slice(0, 10))) + '</div></div>'
      + '<button type="button" class="leilao-limpar-filtros" data-vqual-reexibir="' + escHtml(o.item_id) + '">Reexibir</button></div>').join('')
    : '<div style="font-size:12.5px; color:var(--ink-soft);">Nenhum veículo ocultado.</div>';
}
