function renderizarImoveis(){
  const grid = document.getElementById('im-grid');
  const vazio = document.getElementById('im-vazio');
  const semResultado = document.getElementById('im-sem-resultado');
  const contador = document.getElementById('im-contador');

  if(imoveisDados.length === 0){
    grid.innerHTML=''; grid.style.display='none';
    vazio.style.display='block'; semResultado.style.display='none';
    contador.textContent = '';
    return;
  }
  const lista = imoveisFiltrados();
  vazio.style.display='none';
  contador.textContent = lista.length===1 ? '1 imóvel encontrado' : `${lista.length} imóveis encontrados`;

  if(lista.length===0){
    grid.innerHTML=''; grid.style.display='none';
    semResultado.style.display='block';
    return;
  }
  semResultado.style.display='none';
  grid.style.display='grid';

  grid.innerHTML = lista.map(im => {
    const capa = (im.fotos || []).find(f=>f.capa) || (im.fotos || [])[0];
    return `
    <button type="button" class="leilao-card" data-id="${im.id}">
      <div class="leilao-card-foto">${capa ? `<img src="${capa.src}" alt="${capa.alt||im.titulo}">` : 'Foto não disponível'}</div>
      <div class="leilao-card-body">
        <span class="leilao-card-tipo judicial">${vitNomeTipo(im.tipo)}</span>
        <h3>${im.titulo}</h3>
        <div class="leilao-card-linha"><span>Local</span><b>${im.cidade}/${im.uf}</b></div>
        ${typeof im.quartos === 'number' ? `<div class="leilao-card-linha"><span>Quartos</span><b>${im.quartos===0 ? 'Kit/Studio' : im.quartos}</b></div>` : ''}
        <div class="leilao-card-linha"><span>Preço</span><b>${formatBRL(im.preco)}</b></div>
      </div>
    </button>
  `;}).join('');
  grid.querySelectorAll('.leilao-card').forEach(card=>{
    card.addEventListener('click', ()=> abrirFichaImovel(card.getAttribute('data-id')));
  });
}

