/* ---------- GALERIA DE FOTOS / VÍDEOS DA FICHA DO IMÓVEL ----------
   Mesmo padrão da ficha do Leilão (galeriaFotosAtual/desenharGaleria),
   com estado e ids próprios: as duas fichas existem juntas no DOM (uma
   delas com display:none), então reaproveitar os ids/estado do Leilão
   aqui quebraria getElementById se as duas já tivessem sido abertas
   na mesma sessão. */
let galeriaFotosAtualImovel = [];
let galeriaIndiceAtualImovel = 0;

function renderizarGaleriaFichaImovel(fotos){
  const wrap = document.getElementById('im-galeria-wrap');
  if(!fotos.length){ wrap.innerHTML = ''; return; }
  galeriaFotosAtualImovel = fotos;
  galeriaIndiceAtualImovel = fotos.findIndex(f=>f.capa);
  if(galeriaIndiceAtualImovel < 0) galeriaIndiceAtualImovel = 0;
  desenharGaleriaImovel();
}
function desenharGaleriaImovel(){
  const wrap = document.getElementById('im-galeria-wrap');
  const foto = galeriaFotosAtualImovel[galeriaIndiceAtualImovel];
  wrap.innerHTML = `
    <div class="leilao-galeria">
      <img src="${foto.src}" alt="${foto.alt||''}">
      ${galeriaFotosAtualImovel.length>1 ? `
        <button type="button" class="leilao-galeria-seta leilao-galeria-esq" id="im-galeria-seta-esq">&#10094;</button>
        <button type="button" class="leilao-galeria-seta leilao-galeria-dir" id="im-galeria-seta-dir">&#10095;</button>
        <span class="leilao-galeria-contador">${galeriaIndiceAtualImovel+1} / ${galeriaFotosAtualImovel.length}</span>
      ` : ''}
    </div>
  `;
  if(galeriaFotosAtualImovel.length>1){
    document.getElementById('im-galeria-seta-esq').addEventListener('click', ()=>{
      galeriaIndiceAtualImovel = (galeriaIndiceAtualImovel - 1 + galeriaFotosAtualImovel.length) % galeriaFotosAtualImovel.length;
      desenharGaleriaImovel();
    });
    document.getElementById('im-galeria-seta-dir').addEventListener('click', ()=>{
      galeriaIndiceAtualImovel = (galeriaIndiceAtualImovel + 1) % galeriaFotosAtualImovel.length;
      desenharGaleriaImovel();
    });
  }
}

function renderizarVideosFichaImovel(videos){
  const wrap = document.getElementById('im-video-wrap');
  if(!videos.length){ wrap.innerHTML = ''; return; }
  wrap.innerHTML = `
    <div class="leilao-video-bloco">
      <h3>Vídeos</h3>
      ${videos.map((v,i)=>{
        if(v.tipo === 'arquivo'){
          return `<div class="leilao-video-item"><video controls preload="metadata" src="${v.src}"></video></div>`;
        }
        return `<div class="leilao-video-item" id="im-video-url-slot-${i}">
          <div class="leilao-video-thumb" data-i="${i}">
            <div class="leilao-video-thumb-wrap"><span class="lf-play-icone">&#9658;</span><span>Assistir vídeo</span></div>
          </div>
        </div>`;
      }).join('')}
    </div>
  `;
  videos.forEach((v,i)=>{
    if(v.tipo !== 'arquivo'){
      const thumb = wrap.querySelector(`.leilao-video-thumb[data-i="${i}"]`);
      if(thumb) thumb.addEventListener('click', ()=>{
        const embed = urlParaEmbed(v.src);
        const slot = document.getElementById('im-video-url-slot-'+i);
        slot.innerHTML = embed
          ? `<iframe src="${embed}" allow="autoplay; fullscreen" allowfullscreen></iframe>`
          : `<a href="${v.src}" target="_blank" rel="noopener" class="btn-leilao-secundario">Abrir vídeo em nova aba</a>`;
      });
    }
  });
}

