function renderizarListaAdminImoveis(){
  const base = carregarBaseImoveis();
  const tbody = document.getElementById('im-admin-tbody');
  const vazio = document.getElementById('im-admin-vazio');
  tbody.innerHTML = '';
  vazio.style.display = base.length ? 'none' : 'block';
  base.forEach(im=>{
    const tr = document.createElement('tr');
    tr.innerHTML = `
      <td>${im.titulo}</td>
      <td>${vitNomeTipo(im.tipo)}</td>
      <td>${im.cidade}/${im.uf}</td>
      <td>${formatBRL(im.preco)}</td>
      <td class="acoes">
        <button type="button" class="ac-editar">Editar</button>
        <button type="button" class="ac-excluir">Excluir</button>
      </td>
    `;
    tr.querySelector('.ac-editar').addEventListener('click', ()=> abrirFormularioImovel(im.id));
    tr.querySelector('.ac-excluir').addEventListener('click', ()=> excluirImovel(im.id));
    tbody.appendChild(tr);
  });
}

function excluirImovel(id){
  if(!ehAdmin()) return;
  if(!confirm('Excluir este imóvel definitivamente?')) return;
  let base = carregarBaseImoveis();
  base = base.filter(im=>im.id!==id);
  salvarBaseImoveis(base);
  imoveisDados = base;
  renderizarListaAdminImoveis();
  renderizarImoveis();
}

