function mostrarListaCidadeFormularioImovel(termo){
  const uf = document.getElementById('im-uf').value;
  const lista = document.getElementById('im-cidade-lista');
  if(!uf){ lista.style.display='none'; return; }
  const cidades = (CIDADES_POR_UF && CIDADES_POR_UF[uf]) || CIDADES_POR_UF_EMBUTIDO[uf] || [];
  const termoNorm = normalizarTexto(termo);
  const filtradas = termoNorm ? cidades.filter(c=>normalizarTexto(c).includes(termoNorm)) : cidades;
  lista.innerHTML = filtradas.length
    ? filtradas.slice(0,80).map(c=>`<button type="button" data-cidade="${c}">${c}</button>`).join('')
    : '<div class="leilao-cidade-vazio">Nenhuma cidade encontrada.</div>';
  lista.style.display = 'block';
  lista.querySelectorAll('button[data-cidade]').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      document.getElementById('im-cidade').value = btn.getAttribute('data-cidade');
      document.getElementById('im-cidade-busca').value = btn.getAttribute('data-cidade');
      lista.style.display = 'none';
    });
  });
}
document.getElementById('im-uf').addEventListener('change', function(){
  const busca = document.getElementById('im-cidade-busca');
  document.getElementById('im-cidade').value = '';
  busca.value = '';
  if(this.value){
    busca.disabled = false;
    busca.placeholder = '-- Selecione a cidade --';
  } else {
    busca.disabled = true;
    busca.placeholder = '-- Escolha a UF --';
    document.getElementById('im-cidade-lista').style.display = 'none';
  }
});
document.getElementById('im-cidade-busca').addEventListener('input', function(){
  document.getElementById('im-cidade').value = '';
  mostrarListaCidadeFormularioImovel(this.value);
});
document.getElementById('im-cidade-busca').addEventListener('focus', function(){
  if(!this.disabled) mostrarListaCidadeFormularioImovel(this.value);
});

