function abrirFormularioImovel(id){
  if(!ehAdmin()) return;
  limparFormularioImovel();
  const titulo = document.getElementById('im-form-titulo-modal');
  if(id){
    const base = carregarBaseImoveis();
    const im = base.find(x=>x.id===id);
    if(im){
      titulo.textContent = 'Editar imóvel';
      document.getElementById('im-id').value = im.id;
      document.getElementById('im-titulo').value = im.titulo || '';
      document.getElementById('im-tipo').value = im.tipo || 'casa';
      document.getElementById('im-quartos').value = (typeof im.quartos==='number') ? im.quartos : '';
      document.getElementById('im-uf').value = im.uf || '';
      if(im.uf){
        document.getElementById('im-cidade-busca').disabled = false;
        document.getElementById('im-cidade-busca').placeholder = '-- Selecione a cidade --';
        document.getElementById('im-cidade').value = im.cidade || '';
        document.getElementById('im-cidade-busca').value = im.cidade || '';
      }
      document.getElementById('im-preco').value = im.preco ? formatBRL(im.preco) : '';
      document.getElementById('im-descricao').value = im.descricao || '';
      fotosFormularioImovel = JSON.parse(JSON.stringify(im.fotos || []));
      videosFormularioImovel = JSON.parse(JSON.stringify(im.videos || []));
      renderizarPreviewFotosImovel();
      renderizarPreviewVideosImovel();
    }
  } else {
    titulo.textContent = 'Cadastrar imóvel';
  }
  imFormExtras(id);   /* v41 */
  document.getElementById('im-admin-overlay').style.display = 'none';
  document.getElementById('im-form-overlay').style.display = 'flex';
}
document.getElementById('im-btn-novo').addEventListener('click', ()=> { if(ehAdmin()) abrirFormularioImovel(null); });
document.getElementById('im-form-cancelar').addEventListener('click', ()=>{
  document.getElementById('im-form-overlay').style.display = 'none';
});

document.getElementById('im-btn-salvar').addEventListener('click', function(){
  if(!ehAdmin()) return;
  const msg = document.getElementById('im-form-msg');
  const tituloInput = document.getElementById('im-titulo');
  const ufInput = document.getElementById('im-uf');
  const cidadeBuscaInput = document.getElementById('im-cidade-busca');
  const precoInput = document.getElementById('im-preco');

  const titulo = tituloInput.value.trim();
  const uf = ufInput.value;
  const cidade = document.getElementById('im-cidade').value;
  const preco = parseMoeda(precoInput.value);

  const valido = validarCampos([
    {input: tituloInput, obrigatorio:true, mensagemVazio:'Informe o título do imóvel.'},
    {input: ufInput, obrigatorio:true, mensagemVazio:'Selecione a UF.'},
    {input: cidadeBuscaInput, obrigatorio: !!uf, mensagemVazio:'Selecione a cidade.'},
    {input: precoInput, obrigatorio:true, tipo:'numero', moeda:true, minimo:0, mensagemVazio:'Informe o preço.', mensagemInvalido:'Informe um preço válido (R$ 0,00 ou mais).'}
  ]);
  if(!valido || !cidade){
    if(uf && !cidade) mostrarErroCampo(cidadeBuscaInput, 'Selecione a cidade.');
    msg.textContent = 'Corrija os campos destacados antes de salvar.';
    msg.className = 'auth-msg erro';
    return;
  }
  msg.textContent = '';

  const idExistente = document.getElementById('im-id').value;
  const quartosValor = document.getElementById('im-quartos').value.trim();
  const quartos = quartosValor === '' ? null : parseInt(quartosValor, 10);

  const imovel = {
    id: idExistente || ('imovel-' + Date.now()),
    titulo,
    tipo: document.getElementById('im-tipo').value,
    uf, cidade, preco,
    quartos: (typeof quartos==='number' && !isNaN(quartos)) ? quartos : null,
    descricao: document.getElementById('im-descricao').value.trim() || null,
    origem: 'manual',
    fotos: fotosFormularioImovel,
    videos: videosFormularioImovel,
    ...imFormDadosExtras()   /* v41: bairro, características */
  };

  const base = carregarBaseImoveis();
  const idx = base.findIndex(x=>x.id===imovel.id);
  if(idx>=0) base[idx]=imovel; else base.push(imovel);
  salvarBaseImoveis(base);
  imoveisDados = base;

  document.getElementById('im-form-overlay').style.display = 'none';
  renderizarListaAdminImoveis();
  renderizarImoveis();
  document.getElementById('im-admin-overlay').style.display = 'flex';
});

carregarImoveis();

/* ==========================================================================
   INVESTIMENTOS — COMPRA E VENDA DE EMPRESAS
   Dados fictícios de demonstração. Sem CNPJ real, sem razão social de
   terceiro, sem classificado de CNPJ — só sociedade/operação genérica.
   ========================================================================== */
const NOMES_SETOR_EMPRESA = {
  servicos: 'Serviços', saude: 'Saúde', agronegocio: 'Agronegócio', educacao: 'Educação',
  comercio: 'Comércio', industria: 'Indústria', tecnologia: 'Tecnologia', outros: 'Outros'
};
const NOMES_STATUS_EMPRESA = {
  disponivel: 'Disponível', em_analise: 'Em análise', negociacao: 'Negociação em curso', concluida: 'Concluída'
};
const NOMES_FAIXA_FATURAMENTO = {
  'ate-500k': 'Até R$ 500 mil/ano', '500k-2M': 'R$ 500 mil a R$ 2 milhões/ano',
  '2M-5M': 'R$ 2 milhões a R$ 5 milhões/ano', '5M-10M': 'R$ 5 milhões a R$ 10 milhões/ano',
  '10M-20M': 'R$ 10 milhões a R$ 20 milhões/ano', 'acima-20M': 'Acima de R$ 20 milhões/ano'
};

/* Dados de exemplo — sem CNPJ real, sem razão social de terceiro. Em
   produção, troca por GET /api/empresas no NOSSO servidor; aqui é só
   GET local do JSON de demonstração (com fallback embutido abaixo,
   já que o app roda como arquivo único). */
const EMPRESAS_DEMO_EMBUTIDO = [
  {
    id: "emp_001",
    titulo: "Rede de clínicas odontológicas — Exemplo Fictício A",
    setor: "saude",
    uf: "DF",
    cidade: "Brasília",
    faixa_faturamento: "2M-5M",
    status: "em_analise",
    origem: "manual",
    updated_at: "2026-08-30T00:00:00-03:00"
  },
  {
    id: "emp_002",
    titulo: "Distribuidora de insumos agrícolas — Exemplo Fictício B",
    setor: "agronegocio",
    uf: "GO",
    cidade: "Goiânia",
    faixa_faturamento: "10M-20M",
    status: "disponivel",
    origem: "manual",
    updated_at: "2026-08-30T00:00:00-03:00"
  },
  {
    id: "emp_003",
    titulo: "Escola de idiomas com 3 unidades — Exemplo Fictício C",
    setor: "educacao",
    uf: "SP",
    cidade: "São Paulo",
    faixa_faturamento: "500k-2M",
    status: "negociacao",
    origem: "manual",
    updated_at: "2026-08-30T00:00:00-03:00"
  }
];
const EMPRESAS_BASE_KEY = 'soliduns-empresas-base';
const EMPRESAS_JSON_URL = 'empresas-demo.json';

async function carregarEmpresasDemoJSON(){
  try{
    const resp = await fetch(EMPRESAS_JSON_URL);
    if(!resp.ok) throw new Error('arquivo não encontrado');
    const dados = await resp.json();
    if(!Array.isArray(dados)) throw new Error('formato inesperado');
    return validarLista('empresa', dados);
  }catch(e){
    return validarLista('empresa', EMPRESAS_DEMO_EMBUTIDO);
  }
}

function carregarBaseEmpresasLocal(){   /* v40: modo local; online lê do servidor */
  try{
    const bruto = localStorage.getItem(EMPRESAS_BASE_KEY);
    if(bruto) return validarLista('empresa', JSON.parse(bruto));
  }catch(e){}
  return validarLista('empresa', EMPRESAS_DEMO_EMBUTIDO); // salvaguarda síncrona — carregarEmpresas() já semeia antes
}
function salvarBaseEmpresasLocal(lista){
  try{ localStorage.setItem(EMPRESAS_BASE_KEY, JSON.stringify(lista)); }catch(e){}
}
let empresasDados = [];

function renderizarEmpresas(){
  const grid = document.getElementById('empresas-grid');
  const vazio = document.getElementById('empresas-vazio');
  if(empresasDados.length === 0){
    grid.innerHTML=''; grid.style.display='none';
    vazio.style.display='block';
    return;
  }
  vazio.style.display='none';
  grid.style.display='grid';
  grid.innerHTML = empresasDados.map(e => `
    <button type="button" class="card-vazio card-clicavel" data-id="${e.id}" style="text-align:left;--v107-alin:left; cursor:pointer;">
      <span class="tag-categoria">${NOMES_SETOR_EMPRESA[e.setor] || e.setor}</span>
      <h3>${e.titulo}</h3>
      <p>${e.cidade ? e.cidade+'/' : ''}${e.uf} · ${NOMES_FAIXA_FATURAMENTO[e.faixa_faturamento] || e.faixa_faturamento} · <b style="color:var(--gold);">${NOMES_STATUS_EMPRESA[e.status] || e.status}</b></p>
    </button>
  `).join('');
  grid.querySelectorAll('.card-clicavel').forEach(card=>{
    card.addEventListener('click', ()=> abrirFichaEmpresa(card.getAttribute('data-id')));
  });
}

function abrirFichaEmpresa(id){
  const e = empresasDados.find(x=>x.id===id);
  if(!e) return;
  document.getElementById('empresas-ficha-conteudo').innerHTML = `
    <h2>${e.titulo}</h2>
    <div class="leilao-ficha-sub">${NOMES_SETOR_EMPRESA[e.setor] || e.setor} · ${e.cidade ? e.cidade+'/' : ''}${e.uf} · <span class="leilao-tag-origem">Manual</span></div>
    <div class="leilao-ficha-grid">
      <div class="leilao-ficha-item"><span>Faixa de faturamento</span><b>${NOMES_FAIXA_FATURAMENTO[e.faixa_faturamento] || e.faixa_faturamento}</b></div>
      <div class="leilao-ficha-item"><span>Status</span><b>${NOMES_STATUS_EMPRESA[e.status] || e.status}</b></div>
    </div>
    <div class="leilao-ficha-vazios">
      <h3>Descrição</h3>
      <div class="leilao-ficha-item"><b>${e.descricao || 'Não informado'}</b></div>
    </div>
    ${ehAdmin() ? `<button type="button" class="btn-leilao-admin" id="empresas-btn-editar-da-ficha" style="margin-top:14px;">Editar esta operação</button>` : ''}
  `;
  document.getElementById('empresas-ficha-overlay').style.display='flex';
  if(ehAdmin()){
    document.getElementById('empresas-btn-editar-da-ficha').addEventListener('click', ()=>{
      document.getElementById('empresas-ficha-overlay').style.display='none';
      abrirFormularioEmpresa(e.id);
    });
  }
}
document.getElementById('empresas-ficha-fechar').addEventListener('click', ()=>{
  document.getElementById('empresas-ficha-overlay').style.display='none';
});

/* ---------- ADMIN DE OPERAÇÕES ---------- */
function abrirAdminEmpresas(){
  if(!ehAdmin()) return;
  renderizarListaAdminEmpresas();
  document.getElementById('empresas-admin-overlay').style.display = 'flex';
}
document.getElementById('btn-abrir-admin-empresas').addEventListener('click', abrirAdminEmpresas);
document.getElementById('empresas-admin-fechar').addEventListener('click', ()=>{
  document.getElementById('empresas-admin-overlay').style.display = 'none';
});

function renderizarListaAdminEmpresas(){
  const base = carregarBaseEmpresas();
  const tbody = document.getElementById('empresas-admin-tbody');
  const vazio = document.getElementById('empresas-admin-vazio');
  if(base.length === 0){
    tbody.innerHTML=''; vazio.style.display='block';
    return;
  }
  vazio.style.display='none';
  tbody.innerHTML = base.map(e => `
    <tr>
      <td>${e.titulo}</td>
      <td>${NOMES_SETOR_EMPRESA[e.setor] || e.setor}</td>
      <td>${e.uf}</td>
      <td>${NOMES_STATUS_EMPRESA[e.status] || e.status}</td>
      <td class="acoes">
        <button type="button" class="ac-editar" data-id="${e.id}">Editar</button>
        <button type="button" class="ac-excluir" data-id="${e.id}">Excluir</button>
      </td>
    </tr>
  `).join('');
  tbody.querySelectorAll('.ac-editar').forEach(b=> b.addEventListener('click', ()=> abrirFormularioEmpresa(b.getAttribute('data-id'))));
  tbody.querySelectorAll('.ac-excluir').forEach(b=> b.addEventListener('click', ()=>{
    const id = b.getAttribute('data-id');
    const base2 = carregarBaseEmpresas().filter(x=>x.id!==id);
    salvarBaseEmpresas(base2);
    empresasDados = base2;
    renderizarListaAdminEmpresas();
    renderizarEmpresas();
  }));
}
document.getElementById('empresas-btn-novo').addEventListener('click', ()=> { if(ehAdmin()) abrirFormularioEmpresa(null); });
document.getElementById('empresas-form-cancelar').addEventListener('click', ()=>{
  document.getElementById('empresas-form-overlay').style.display = 'none';
});

function popularUFEmpresas(){
  const sel = document.getElementById('empresas-uf');
  if(sel.options.length) return;
  sel.innerHTML = UF_LIST.map(u=>`<option value="${u.sigla}">${u.sigla} — ${u.nome}</option>`).join('');
}

function abrirFormularioEmpresa(id){
  if(!ehAdmin()) return;
  popularUFEmpresas();
  document.getElementById('empresas-titulo').value = '';
  document.getElementById('empresas-setor').value = 'servicos';
  document.getElementById('empresas-uf').value = 'DF';
  document.getElementById('empresas-cidade').value = '';
  document.getElementById('empresas-faturamento').value = '500k-2M';
  document.getElementById('empresas-status').value = 'disponivel';
  document.getElementById('empresas-descricao').value = '';
  document.getElementById('empresas-form-msg').textContent = '';

  const titulo = document.getElementById('empresas-form-titulo-modal');
  let idExistente = '';
  if(id){
    const base = carregarBaseEmpresas();
    const e = base.find(x=>x.id===id);
    if(e){
      titulo.textContent = 'Editar operação';
      idExistente = e.id;
      document.getElementById('empresas-titulo').value = e.titulo || '';
      document.getElementById('empresas-setor').value = e.setor || 'servicos';
      document.getElementById('empresas-uf').value = e.uf || 'DF';
      document.getElementById('empresas-cidade').value = e.cidade || '';
      document.getElementById('empresas-faturamento').value = e.faixa_faturamento || '500k-2M';
      document.getElementById('empresas-status').value = e.status || 'disponivel';
      document.getElementById('empresas-descricao').value = e.descricao || '';
    }
  } else {
    titulo.textContent = 'Cadastrar operação';
  }
  document.getElementById('empresas-form-overlay').setAttribute('data-id-existente', idExistente);
  document.getElementById('empresas-admin-overlay').style.display = 'none';
  document.getElementById('empresas-form-overlay').style.display = 'flex';
}

document.getElementById('empresas-btn-salvar').addEventListener('click', function(){
  if(!ehAdmin()) return;
  const msg = document.getElementById('empresas-form-msg');
  const tituloInput = document.getElementById('empresas-titulo');
  const setorInput = document.getElementById('empresas-setor');
  const ufInput = document.getElementById('empresas-uf');
  const titulo = tituloInput.value.trim();
  const setor = setorInput.value;

  const valido = validarCampos([
    {input: tituloInput, obrigatorio:true, mensagemVazio:'Informe o título da operação.'},
    {input: setorInput, obrigatorio:true, mensagemVazio:'Selecione o setor.'},
    {input: ufInput, obrigatorio:true, mensagemVazio:'Selecione a UF.'}
  ]);
  if(!valido){
    msg.textContent = 'Corrija os campos destacados antes de salvar.';
    msg.className = 'auth-msg erro';
    return;
  }
  msg.textContent = '';

  const idExistente = document.getElementById('empresas-form-overlay').getAttribute('data-id-existente') || '';
  const operacao = {
    id: idExistente || ('emp_' + Date.now()),
    titulo,
    setor,
    uf: document.getElementById('empresas-uf').value,
    cidade: document.getElementById('empresas-cidade').value.trim() || null,
    faixa_faturamento: document.getElementById('empresas-faturamento').value,
    status: document.getElementById('empresas-status').value,
    descricao: document.getElementById('empresas-descricao').value.trim() || null,
    origem: 'manual',
    updated_at: new Date().toISOString()
  };

  const base = carregarBaseEmpresas();
  const idx = base.findIndex(x=>x.id===operacao.id);
  if(idx>=0) base[idx]=operacao; else base.push(operacao);
  salvarBaseEmpresas(base);
  empresasDados = base;

  document.getElementById('empresas-form-overlay').style.display = 'none';
  renderizarListaAdminEmpresas();
  renderizarEmpresas();
  document.getElementById('empresas-admin-overlay').style.display = 'flex';
});

async function carregarEmpresas(){
  // Se já existe base salva localmente (admin já cadastrou/editou algo),
  // respeita ela e não sobrescreve com o JSON de demonstração de novo.
  let jaExiste = false;
  try{ jaExiste = !!localStorage.getItem(EMPRESAS_BASE_KEY); }catch(e){}
  if(!jaExiste){
    const dados = await carregarEmpresasDemoJSON();
    salvarBaseEmpresasLocal(dados);   /* v40: exemplos só no navegador */
  }
  empresasDados = carregarBaseEmpresas();
  renderizarEmpresas();
}
carregarEmpresas();


