/* ---------- 123º/132º: busca e filtro do catálogo de certificações ---------- */
function normalizarTextoCert(s){
  return (s||'').toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
}
const NOMES_FUNCAO_CERT = {
  distribuicao:'Distribuição', gestao:'Gestão', assessoria:'Assessoria', analise:'Análise',
  operacoes:'Operações', credito:'Crédito', seguros:'Seguros', risco:'Risco', compliance:'Compliance'
};

let certFiltroRegiao = 'todas';
let certFiltroQ = '';
let certDebounceTimer = null;

function renderizarCatalogoCertificacoes(){
  const q = normalizarTextoCert(certFiltroQ);
  const filtradas = CERTIFICACOES_CATALOGO.filter(c=>{
    const okRegiao = certFiltroRegiao==='todas' || c.regiao===certFiltroRegiao;
    if(!okRegiao) return false;
    if(!q) return true;
    const blob = normalizarTextoCert([c.sigla,c.nome,c.entidade,c.aplicacao,c.funcao].join(' '));
    return blob.includes(q);
  });

  const grupos = {};
  filtradas.forEach(c=>{ (grupos[c.grupo] = grupos[c.grupo]||[]).push(c); });

  const lista = document.getElementById('cert-catalogo-lista');
  const vazio = document.getElementById('cert-vazio');
  const contador = document.getElementById('cert-contador');
  if(!lista) return;

  contador.textContent = filtradas.length + (filtradas.length===1 ? ' certificação' : ' certificações');

  if(filtradas.length === 0){
    lista.innerHTML = '';
    vazio.style.display = 'block';
    return;
  }
  vazio.style.display = 'none';

  lista.innerHTML = Object.keys(grupos).map(nomeGrupo=>{
    const itens = grupos[nomeGrupo];
    return `<article class="cert-grupo">
      <h3>${nomeGrupo}</h3>
      <div class="cert-tabela-wrap">
        <table>
          <thead><tr><th>Certificação</th><th>Nome por extenso</th><th>Aplicação típica</th></tr></thead>
          <tbody>
            ${itens.map(c=>`
              <tr class="cert-linha-clicavel" tabindex="0" data-slug="${c.slug}"
                  data-sigla="${c.sigla}" data-nome="${c.nome}" data-entidade="${c.entidade}"
                  data-aplicacao="${c.aplicacao}" data-regiao="${c.regiao}" data-funcao="${c.funcao}">
                <th scope="row">${c.sigla}${c.transicao ? '<span class="cert-tag-transicao">Em transição</span>' : ''}</th>
                <td>${c.nome}</td>
                <td>${c.aplicacao}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    </article>`;
  }).join('');

  lista.querySelectorAll('.cert-linha-clicavel').forEach(linha=>{
    linha.addEventListener('click', ()=> abrirFichaCertificacao(linha.getAttribute('data-slug')));
    linha.addEventListener('keydown', e=>{
      if(e.key==='Enter' || e.key===' '){ e.preventDefault(); abrirFichaCertificacao(linha.getAttribute('data-slug')); }
    });
  });
}

function aplicarFiltroCertificacoes(){
  renderizarCatalogoCertificacoes();
  const params = new URLSearchParams();
  if(certFiltroQ) params.set('q', certFiltroQ);
  if(certFiltroRegiao !== 'todas') params.set('regiao', certFiltroRegiao);
  const novaQuery = params.toString();
  history.replaceState(null, '', window.location.pathname + (novaQuery ? '?'+novaQuery : '') + window.location.hash);
}

function inicializarBuscaCertificacoes(){
  const params = new URLSearchParams(window.location.search);
  certFiltroQ = params.get('q') || '';
  certFiltroRegiao = params.get('regiao') || 'todas';
  const input = document.getElementById('cert-busca');
  if(input) input.value = certFiltroQ;
  document.querySelectorAll('.cert-chips button').forEach(btn=>{
    const ativo = btn.getAttribute('data-regiao') === certFiltroRegiao;
    btn.setAttribute('aria-pressed', ativo ? 'true' : 'false');
  });
  renderizarCatalogoCertificacoes();
}

document.getElementById('cert-busca').addEventListener('input', function(){
  certFiltroQ = this.value;
  clearTimeout(certDebounceTimer);
  certDebounceTimer = setTimeout(aplicarFiltroCertificacoes, 180);
});
document.getElementById('cert-busca').addEventListener('keydown', function(e){
  if(e.key === 'Escape'){
    this.value = '';
    certFiltroQ = '';
    certFiltroRegiao = 'todas';
    document.querySelectorAll('.cert-chips button').forEach(b=> b.setAttribute('aria-pressed', b.getAttribute('data-regiao')==='todas' ? 'true':'false'));
    aplicarFiltroCertificacoes();
  }
});
document.querySelectorAll('.cert-chips button').forEach(btn=>{
  btn.addEventListener('click', ()=>{
    document.querySelectorAll('.cert-chips button').forEach(b=>b.setAttribute('aria-pressed','false'));
    btn.setAttribute('aria-pressed','true');
    certFiltroRegiao = btn.getAttribute('data-regiao');
    aplicarFiltroCertificacoes();
  });
});

function abrirFichaCertificacao(slug){
  const c = CERTIFICACOES_CATALOGO.find(x=>x.slug===slug);
  if(!c) return;
  document.getElementById('cert-ficha-conteudo').innerHTML = `
    <h2>${c.sigla}</h2>
    <p class="leilao-ficha-sub">${c.nome}</p>
    <div class="leilao-ficha-grid">
      <div class="leilao-ficha-item"><span>Entidade</span><b>${c.entidade}</b></div>
      <div class="leilao-ficha-item"><span>Trilha relacionada</span><b>${NOMES_FUNCAO_CERT[c.funcao]||c.funcao}</b></div>
      <div class="leilao-ficha-item"><span>Região</span><b>${c.regiao==='brasil'?'Brasil':'Internacional'}</b></div>
    </div>
    <div class="leilao-ficha-vazios">
      <h3>Aplicação típica</h3>
      <div class="leilao-ficha-item"><b>${c.aplicacao}</b></div>
    </div>
    <p class="note" style="margin-top:14px;">Confirme regras vigentes (exame, validade, equivalências) diretamente com ${c.entidade}. Este catálogo é referência — não substitui a fonte oficial.</p>
  `;
  document.getElementById('cert-ficha-overlay').style.display = 'flex';
}
document.getElementById('cert-ficha-fechar').addEventListener('click', ()=>{
  document.getElementById('cert-ficha-overlay').style.display = 'none';
});

/* TOC da página de certificações: scroll manual via JS, nunca por
   href="#id" nativo — o app inteiro roteia por hash (#/rota), e um
   href="#cert-catalogo" mudaria o hash e cairia direto na 404. */
document.querySelectorAll('.edu-prep-toc [data-scroll-to]').forEach(link=>{
  link.addEventListener('click', (e)=>{
    e.preventDefault();
    const alvo = document.getElementById(link.getAttribute('data-scroll-to'));
    if(alvo) alvo.scrollIntoView({behavior:'smooth', block:'start'});
  });
});


let educacaoCategoriaAtiva = null;

const NOMES_CATEGORIA_EDU = {preparatorios:'Cursos Preparatórios', livres:'Cursos Livres', artigos:'Artigos Técnicos'};
const RESUMOS_CATEGORIA_EDU = {
  preparatorios: 'Trilhas para concursos e certificações.',
  livres: 'Formação livre, sem pré-requisito.',
  artigos: 'Leitura curta, aplicação prática.'
};

/* Cada subseção mantém seu próprio botão Administrar. As três categorias
   já são geridas pelo mesmo cadastro de artigos (título, resumo, PDF/HTML,
   publicado/rascunho) — abrirAdminArtigos() já lista e filtra por
   categoria, então não duplicamos um segundo CRUD aqui. */
const CONFIG_ADMIN_EDUCACAO = {
  preparatorios: { texto: 'Administrar cursos preparatórios', handler: abrirAdminArtigos },
  livres: { texto: 'Administrar cursos livres', handler: abrirAdminArtigos },
  artigos: { texto: 'Administrar artigos técnicos', handler: abrirAdminArtigos },
};

/* Troca de subseção — sempre via hash (ver roteador). Mantém a mesma
   view/painel; só o miolo muda. */
function selecionarCategoriaEducacao(categoria){
  educacaoCategoriaAtiva = categoria;
  const viewer = document.getElementById('artigo-viewer-overlay');
  if(viewer.style.display !== 'none'){ viewer.style.display = 'none'; viewer.innerHTML = ''; }
  renderizarEducacao();
}

function renderizarEducacao(){
  const nav = document.getElementById('edu-categorias');
  const btnVoltar = document.getElementById('edu-voltar-categorias');
  const grid = document.getElementById('educacao-grid');
  const btnAdmin = document.getElementById('btn-admin-categoria-educacao');
  const breadcrumb = document.getElementById('edu-breadcrumb');
  const titulo = document.getElementById('edu-titulo');
  const subtitulo = document.getElementById('edu-subtitulo');

  nav.querySelectorAll('.escolha-card').forEach(btn=>{
    btn.classList.toggle('ativo', btn.getAttribute('data-categoria') === educacaoCategoriaAtiva);
  });

  // Botão de admin: só existe DEPOIS que uma categoria foi selecionada,
  // e só para quem é admin — nunca aparece na grade de categorias (página 1).
  if(educacaoCategoriaAtiva && ehAdmin()){
    const cfg = CONFIG_ADMIN_EDUCACAO[educacaoCategoriaAtiva];
    btnAdmin.textContent = cfg.texto;
    btnAdmin.onclick = cfg.handler;
    btnAdmin.style.display = 'inline-block';
  } else {
    btnAdmin.style.display = 'none';
    btnAdmin.onclick = null;
  }

  if(!educacaoCategoriaAtiva){
    nav.style.display = 'grid';
    grid.style.display = 'none';
    document.getElementById('prep-certificacoes-grupos').style.display = 'none';
    btnVoltar.style.display = 'none';
    breadcrumb.style.display = 'none';
    titulo.textContent = 'Educação Continuada';
    subtitulo.textContent = 'Cursos e aulas para você e sua equipe';
    setTituloPagina('Educação continuada');
    return;
  }

  nav.style.display = 'none';
  btnVoltar.style.display = 'inline-block';
  grid.style.display = 'grid';
  breadcrumb.style.display = 'block';
  breadcrumb.textContent = 'Educação continuada / ' + NOMES_CATEGORIA_EDU[educacaoCategoriaAtiva];
  titulo.textContent = NOMES_CATEGORIA_EDU[educacaoCategoriaAtiva];
  subtitulo.textContent = RESUMOS_CATEGORIA_EDU[educacaoCategoriaAtiva];
  setTituloPagina(NOMES_CATEGORIA_EDU[educacaoCategoriaAtiva]);

  /* v37: fichas do servidor (edu.publicacoes). */
  const catAtual = educacaoCategoriaAtiva;
  let artigos = [], avisoPub = '';
  if(_pubLista){
    artigos = _pubLista.filter(a => a.categoria === catAtual);
  } else if(_pubErro){
    avisoPub = PUB_MENSAGENS[_pubErro] || PUB_MENSAGENS.servidor;
  } else {
    avisoPub = 'Carregando…';
    pubListar().then(() => { if(educacaoCategoriaAtiva === catAtual) renderizarEducacao(); },
                     () => { if(educacaoCategoriaAtiva === catAtual) renderizarEducacao(); });
  }
  const itemFixo = educacaoCategoriaAtiva === 'preparatorios' ? [{
    id: '__certificacoes-mercado-financeiro', fixo: true,
    titulo: 'Introdução',
    resumo: 'Certificações do Mercado Financeiro — credenciais, remuneração, progressão e plano integrado de estudos, Brasil + Mundo.'
  }] : [];

  if(artigos.length === 0 && itemFixo.length === 0){
    grid.innerHTML = `<div class="card-vazio"><p style="color:var(--ink-soft); margin:0;">${escHtml(avisoPub || 'Em implantação — nenhum conteúdo publicado ainda.')}</p></div>`;
    return;
  }

  grid.innerHTML = itemFixo.concat(artigos).map(a=>{
    if(a.fixo){
      return `<div class="card-vazio card-clicavel" data-fixo="${a.id}">
        <h3>${a.titulo}</h3>
        <p>${a.resumo}</p>
      </div>`;
    }
    const temConteudo = a.status === 'publicado';
    const clicavel = temConteudo ? 'card-clicavel' : '';
    const selo = !temConteudo ? '<span class="tag-em-breve">Rascunho</span>'
      : (pubBloqueada(a) ? '<span class="tag-em-breve pub-selo-pago">Planos pagos</span>'
      : (a.gratuito && _areas && !_areas.tudo ? '<span class="tag-em-breve pub-selo-gratis">Gratuito</span>' : ''));
    return `
      <div class="card-vazio ${clicavel}" data-id="${escHtml(a.id)}">
        <h3>${escHtml(a.titulo)}</h3>
        ${a.resumo ? `<p>${escHtml(a.resumo)}</p>` : ''}
        ${selo}
      </div>
    `;
  }).join('') + (avisoPub && artigos.length === 0 ? `<div class="card-vazio"><p style="color:var(--ink-soft); margin:0;">${escHtml(avisoPub)}</p></div>` : '');

  grid.querySelectorAll('.card-clicavel[data-id]').forEach(card=>{
    card.addEventListener('click', ()=> navegarHash('#/educacao/' + educacaoCategoriaAtiva + '/' + card.getAttribute('data-id')));
  });
  grid.querySelectorAll('.card-clicavel[data-fixo]').forEach(card=>{
    card.addEventListener('click', ()=> navegarHash('#/educacao/preparatorios/certificacoes'));
  });

  renderizarGruposCertificacoesPrep();
}

/* Cursos Preparatórios: abaixo do card "Introdução", um card por
   certificação do catálogo, agrupado pela mesma categoria usada no
   catálogo completo (grupo). Cada card leva à página de curso daquela
   certificação — nunca ao catálogo genérico. */
function renderizarGruposCertificacoesPrep(){
  const container = document.getElementById('prep-certificacoes-grupos');
  if(educacaoCategoriaAtiva !== 'preparatorios'){
    container.style.display = 'none';
    container.innerHTML = '';
    return;
  }
  const grupos = [];
  const porGrupo = {};
  CERTIFICACOES_CATALOGO.forEach(c=>{
    if(!porGrupo[c.grupo]){ porGrupo[c.grupo] = []; grupos.push(c.grupo); }
    porGrupo[c.grupo].push(c);
  });

  container.innerHTML = grupos.map(g=>`
    <div class="prep-cert-grupo">
      <h3 class="prep-cert-grupo-titulo">${g}</h3>
      <div class="prep-cert-tiles">
        ${porGrupo[g].map(c=>`
          <div class="prep-cert-tile" data-slug="${c.slug}">
            <span class="sigla">${c.sigla}</span>
            <span class="nome">${c.nome}</span>
            <span class="entidade">${c.entidade}</span>
          </div>
        `).join('')}
      </div>
    </div>
  `).join('');
  container.style.display = 'block';

  container.querySelectorAll('.prep-cert-tile').forEach(tile=>{
    tile.addEventListener('click', ()=> navegarHash('#/educacao/preparatorios/curso/' + tile.getAttribute('data-slug')));
  });
  eduMarcarTilesPlano();   /* v34: selo "Fora do seu plano" */
  return;
}

/* Página de curso de UMA certificação — aberta a partir do card dela
   em Cursos Preparatórios. O conteúdo do curso em si (módulos, aulas,
   avaliação) ainda não existe; a página já mostra o cabeçalho real da
   certificação (catálogo oficial) e deixa isso explícito, em vez de
   inventar um currículo. */
function abrirCursoCertificacao(slug, partes){
  const cert = CERTIFICACOES_CATALOGO.find(c=> c.slug === slug);
  if(!cert){ mostrar404(); return; }

  mostrarPainelDash('curso-certificacao');

  /* C-Pro R tem apostila e banco de questões completos — abre o curso de
     verdade. As demais certificações seguem com o aviso honesto de que o
     currículo ainda não existe, em vez de inventar um. */
  /* Cursos com apostila e banco de questões completos abrem o curso de
     verdade. As demais certificações seguem com o aviso honesto de que o
     currículo ainda não existe, em vez de inventar um. */
  if(CURSOS[slug]){
    /* v34: curso fora do plano (SQL 31). O banco já recusa; aqui só avisa. */
    if(eduForaDoPlano(_eduMeus, slug)){ eduMostrarForaDoPlano(cert); return; }
    if(!_eduMeus && sessaoAtual && !sessaoAtual.modoLocal){
      const hashAntes = window.location.hash;
      document.getElementById('curso-certificacao-conteudo').innerHTML = '<div class="curso-cert-em-preparo"><strong>Carregando o curso…</strong></div>';
      const limite = new Promise(res => setTimeout(() => res(null), 6000));
      Promise.race([eduMeusCursos(), limite]).then(meus => {
        if(window.location.hash !== hashAntes) return;
        if(eduForaDoPlano(meus, slug)){ eduMostrarForaDoPlano(cert); return; }
        if(!_eduMeus) _eduMeus = {exige_plano:false, liberados:new Set(), em:Date.now() - EDU_MEUS_VALIDADE + 60000}; /* sem resposta: não bloqueia; tenta de novo em 1 min */
        abrirCursoCertificacao(slug, partes);
      });
      return;
    }
    if(_eduMeus && Date.now() - _eduMeus.em >= EDU_MEUS_VALIDADE) eduMeusCursos(); /* renova em segundo plano */
    if(cursoAtual !== CURSOS[slug]){
      /* Troca de curso: o progresso em memória é do curso anterior e as
         chaves de bloco ('m2-b0') coincidem entre cursos. Sem zerar aqui,
         um bloco concluído em um curso destrava o outro. */
      cursoAtual = CURSOS[slug];
      cproEstado = {respostas:{}, concluidos:{}};
      cproSyncPendente = false;
    }
    cproPrepararProgresso();
    cproAbrir(cert, partes || []);
    return;
  }

  document.getElementById('curso-certificacao-conteudo').innerHTML = `
    <div class="curso-cert-hero">
      <span class="tag-categoria">${cert.grupo}</span>
      <h1>${cert.nome}</h1>
      <p class="subsigla">${cert.sigla} · ${cert.entidade}</p>
      <p>${cert.aplicacao}</p>
    </div>
    <div class="curso-cert-em-preparo">
      <strong>Curso em preparação</strong>
      Os módulos, aulas e simulados de ${cert.sigla} ainda estão sendo estruturados.
      Enquanto isso, veja o panorama completo dessa credencial na Introdução de Cursos Preparatórios.
    </div>
  `;
  setTituloPagina(cert.sigla + ' — ' + cert.nome, cert.aplicacao);
}

