  ({pedidos: raPedidos, revisao: raRevisao, publicados: raPublicados, config: raConfig, custos: raCustos})[aba]()
    .catch(e => { c.innerHTML = '<div class="cpro-aviso"><span>&#9432;</span><span>' + escHtml(e.message) + '</span></div>'; });
