/* A-02, A-03, A-04 — fila de revisão, revisão de uma versão e publicação */
var RA_CHECK = [['fontes', 'Fontes conferidas (Apêndice A)'], ['premissas', 'Premissas revisadas'], ['rubrica', 'Rubrica do bloco C confirmada (botão acima)'],
                ['r_ia', 'Verificador R-IA aprovado'], ['avisos_legais', 'Avisos legais conferidos']];
function raValor(v, moeda){ if(v === null || v === undefined) return '—'; return (moeda === 'USD' ? 'US$ ' : 'R$ ') + Number(v).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }
/* v84-AG (Q32, SQL 63): COMPRA com Score PERENE abaixo de 40 só é aprovada com justificativa escrita (mínimo de 30 caracteres) */
function raExigeJust(v){
  return v.revisao_obrigatoria === true
    || (String(v.recomendacao || '').toUpperCase() === 'COMPRA' && v.score_perene != null && Number(v.score_perene) < 40);
}
function raJustBloco(v){
  const ob = raExigeJust(v);
  return '<label class="ra-just' + (ob ? ' obrigatoria' : '') + '">'
    + (ob ? '<span><span class="ra-just-selo">OBRIGATÓRIA</span> — COMPRA com Score PERENE abaixo de 40. Explique por que a recomendação se mantém (mínimo de 30 caracteres).</span>'
          : '<span>Justificativa do administrador (opcional)</span>')
    + '<textarea rows="3" maxlength="2000" data-ra-just="' + v.id + '"' + (ob ? ' data-ra-just-ob="1"' : '') + '></textarea>'
    + (ob ? '<span class="ra-just-conta" data-ra-just-conta="' + v.id + '">0 de 30 caracteres</span>' : '') + '</label>';
}
