  try{ d = _relMercado === 'us' ? (window.__relUSReal ? await relRpc('relatorio_empresa_us', {p_ticker: ticker}) : relDadosUS(ticker))
                                 : await relEmpresaComHistV115(ticker); }   /* v115: + histórico da B3 */   /* v46; v48 */
  catch(e){ caixa.innerHTML = '<div class="cpro-aviso"><span>&#9432;</span><span>' + escHtml(REL_MSG[e.tipo] || REL_MSG.servidor) + '</span></div>'; return; }
