function formatarPrecoCotacao(mercado, valor){
  return mercado === 'br' ? formatBRL(valor) : ('US$ ' + valor.toFixed(2).replace('.', ','));
}

/* ===== v108 — link do ticker para o relatório (patch108lei) ===== */
function tkLimparV108(t){
  return String(t == null ? '' : t).replace(/&amp;/g, '&').replace(/<[^>]*>/g, '').trim().toUpperCase().replace(/[^A-Z0-9.\-]/g, '').slice(0, 12);
}
function tkEnderecoV108(t, mercado){
  return '#/investimentos/mercado-financeiro/relatorios?ticker=' + encodeURIComponent(t) + '&mercado=' + (mercado === 'us' ? 'EUA' : 'BR');
}
function tkLinkV108(ticker, mercado, rotulo){
  const t = tkLimparV108(ticker);
  if(!t) return rotulo == null ? '' : rotulo;
  const m = mercado === 'us' ? 'us' : 'br';
  return '<a class="tk-rel" href="' + tkEnderecoV108(t, m) + '" data-tk="' + t + '" data-mercado="' + m + '" title="Abrir o relatório de ' + t + '">' + rotulo + '</a>';
}
function templateCotacaoAltaBaixa(c){
  const positivo = c.variacao_pct >= 0;
  const cor = positivo ? 'var(--teal)' : 'var(--rust)';
  const sinal = positivo ? '+' : '';
  return `<div class="cotacoes-item">
    <div class="cotacoes-item-topo"><b>${tkLinkV108(c.ticker, c.mercado, c.ticker)}</b><span style="color:${cor};">${sinal}${c.variacao_pct.toFixed(2)}%</span></div>
    <div class="cotacoes-item-baixo"><span>${c.nome}</span><span>${formatarPrecoCotacao(c.mercado, c.preco)}</span></div>
  </div>`;
}
function templateCotacaoDividendo(c){
  return `<div class="cotacoes-item">
    <div class="cotacoes-item-topo"><b>${tkLinkV108(c.ticker, c.mercado, c.ticker)}</b><span class="cotacoes-badge-dividendo">Dividendos</span></div>
    <div class="cotacoes-item-baixo"><span>${formatarPrecoCotacao(c.mercado, c.valor_provento)}</span><span>${formatarDataBR(c.data_provento)}</span></div>
  </div>`;
}

/* ---------- COTAÇÕES DE FIM DE PREGÃO (EOD) — v17 ----------
   Mercado brasileiro: o Supabase coleta a lista da B3 (via brapi.dev)
   todo dia útil às 19h e grava o resumo em public.cotacoes_eod (SQL 05).
   Aqui só se lê esse resumo. Dados de fim de dia da B3 podem ser
   redistribuídos sem custo e sem autorização prévia; por isso a coleta
   é sempre depois do fechamento. Sem resumo disponível (tabela vazia,
   usuário sem sessão, falha de rede), a seção volta ao demonstrativo,
   identificado como tal. */
window.__cotacoesEOD = null;
let __cotacoesEODEstado = 'ocioso';
const __cotacoesBRRotulos = {};
function cotacoesBRGuardarRotulos(){
  if(__cotacoesBRRotulos.ok) return;
  const t = document.getElementById('cotacoes-br-titulo');
  const c = document.getElementById('cotacoes-br-col3-titulo');
  const r = document.getElementById('cotacoes-br-rodape');
  if(!t || !c || !r) return;
  __cotacoesBRRotulos.titulo = t.textContent;
  __cotacoesBRRotulos.col3 = c.textContent;
  __cotacoesBRRotulos.rodape = r.textContent;
  __cotacoesBRRotulos.ok = true;
}
async function carregarCotacoesEOD(){
  if(__cotacoesEODEstado === 'carregando' || __cotacoesEODEstado === 'ok') return;
  if(!sessaoAtual || !sessaoAtual.access_token) return;
  __cotacoesEODEstado = 'carregando';
  try{
    const r = await fetch(SUPABASE_URL + '/rest/v1/cotacoes_eod?mercado=eq.br'
      + '&select=capturado_em,altas,baixas,mais_negociadas,ativos_liquidos,fonte,todas'
      + '&order=capturado_em.desc&limit=1', {
      headers: {'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + sessaoAtual.access_token, 'Accept': 'application/json'}
    });
    if(!r.ok) throw new Error('HTTP ' + r.status);
    const linhas = await r.json();
    if(Array.isArray(linhas) && linhas.length && linhas[0] && !isNaN(Date.parse(linhas[0].capturado_em))){
      window.__cotacoesEOD = linhas[0];
      __cotacoesEODEstado = 'ok';
    } else {
      __cotacoesEODEstado = 'ocioso'; // ainda sem coleta: tenta de novo na próxima abertura
    }
  }catch(e){
    console.warn('[cotacoes-eod] não foi possível ler o resumo:', e && e.message);
    __cotacoesEODEstado = 'ocioso';
  }
  renderizarCotacoes('br');
}
/* v46: valores do mercado americano em dólar */
function formatarUSD(v){ return 'US$ ' + Number(v).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }
function formatarVolumeUSD(v){
  const n = Number(v) || 0;
  if(n >= 1e9) return 'US$ ' + (n/1e9).toFixed(2).replace('.', ',') + ' bi';
  if(n >= 1e6) return 'US$ ' + (n/1e6).toFixed(1).replace('.', ',') + ' mi';
  return formatarUSD(n);
}
function formatarVolumeFinanceiro(v){
  const n = Number(v) || 0;
  if(n >= 1e9) return 'R$ ' + (n/1e9).toFixed(2).replace('.', ',') + ' bi';
  if(n >= 1e6) return 'R$ ' + (n/1e6).toFixed(1).replace('.', ',') + ' mi';
  return formatBRL(n);
}
function templateCotacaoVolume(c){
  const positivo = c.variacao_pct >= 0;
  const cor = positivo ? 'var(--teal)' : 'var(--rust)';
  const sinal = positivo ? '+' : '';
  return `<div class="cotacoes-item">
    <div class="cotacoes-item-topo"><b>${tkLinkV108(c.ticker, c.mercado, escaparHtml(c.ticker))}</b><span>${formatarVolumeFinanceiro(c.volume_fin)}</span></div>
    <div class="cotacoes-item-baixo"><span>${escaparHtml(c.nome)}</span><span style="color:${cor};">${sinal}${Number(c.variacao_pct).toFixed(2)}%</span></div>
  </div>`;
}
/* v20: setor em português na tabela de cotações. Ordem: setor da CVM do
   próprio código (base da Busca Avançada); setor da CVM de outro código da
   mesma empresa (ex.: ALUP11 usa o de ALUP3/ALUP4); tradução do setor que a
   brapi envia em inglês (BDRs, ETFs e papéis fora da CVM). */
const SETORES_BRAPI_PT = {
  'finance':'Financeiro','utilities':'Utilidade pública','energy minerals':'Petróleo, gás e carvão',
  'non-energy minerals':'Mineração e siderurgia','process industries':'Indústria de transformação',
  'consumer non-durables':'Bens de consumo não duráveis','consumer durables':'Bens de consumo duráveis',
  'retail trade':'Varejo','transportation':'Transporte','health services':'Serviços de saúde',
  'health technology':'Tecnologia em saúde','technology services':'Serviços de tecnologia',
  'electronic technology':'Tecnologia eletrônica','commercial services':'Serviços comerciais',
  'producer manufacturing':'Bens industriais','industrial services':'Serviços industriais',
  'communications':'Comunicações','distribution services':'Distribuição','consumer services':'Serviços ao consumidor',
  'miscellaneous':'Diversos','government':'Governo'
};
let __setorCVMMapa = null, __setorCVMMapaFonte = null;
/* v21: o mesmo mapa guarda também o nome da empresa na CVM (nomeTk/nomeRaiz),
   usado quando a brapi manda o próprio código como nome (ex.: AXIA3/AXIA7). */
function __montarMapaCVM(){
  const base = window.__baseRealBR;
  if(!Array.isArray(base) || !base.length) return false;
  if(__setorCVMMapaFonte !== base){
    __setorCVMMapa = {tk:{}, raiz:{}, nomeTk:{}, nomeRaiz:{}};
    base.forEach(a=>{
      if(!a || !a.ticker) return;
      const r = a.ticker.slice(0,4);
      const nome = String(a.nome||'').trim();
      if(nome && nome.toUpperCase() !== a.ticker.toUpperCase()){
        __setorCVMMapa.nomeTk[a.ticker] = nome;
        if(!__setorCVMMapa.nomeRaiz[r]) __setorCVMMapa.nomeRaiz[r] = nome;
      }
      if(!a.setor || a.setor === 'Sem setor informado') return;
      __setorCVMMapa.tk[a.ticker] = a.setor;
      if(!__setorCVMMapa.raiz[r]) __setorCVMMapa.raiz[r] = a.setor;
    });
    __setorCVMMapaFonte = base;
  }
  return true;
}
function nomeCotacao(ticker, nomeBrapi){
  const t = String(ticker||'').toUpperCase();
  const n = String(nomeBrapi||'').trim();
  if(n && n.toUpperCase() !== t) return n;
  if(__montarMapaCVM()){
    if(__setorCVMMapa.nomeTk[t]) return __setorCVMMapa.nomeTk[t];
    if(__setorCVMMapa.nomeRaiz[t.slice(0,4)]) return __setorCVMMapa.nomeRaiz[t.slice(0,4)];
  }
  return n || t;
}
function setorCotacaoPT(ticker, setorBrapi){
  const base = window.__baseRealBR;
  if(__montarMapaCVM()){
    const t = String(ticker||'').toUpperCase();
    if(__setorCVMMapa.tk[t]) return __setorCVMMapa.tk[t];
    if(__setorCVMMapa.raiz[t.slice(0,4)]) return __setorCVMMapa.raiz[t.slice(0,4)];
  }
  const en = String(setorBrapi||'').trim();
  if(!en) return '';
  return SETORES_BRAPI_PT[en.toLowerCase()] || en;
}
function renderizarCotacoesEOD(){
  cotacoesBRGuardarRotulos();
  const d = window.__cotacoesEOD;
  const data = new Date(d.capturado_em);
  /* Data do pregão, não da coleta: coleta feita antes das 18h ou em fim de
     semana (ex.: disparo manual) mostra o último dia útil anterior.
     Feriados da B3 não são tratados aqui. */
  const partes = new Intl.DateTimeFormat('en-CA', {timeZone:'America/Sao_Paulo', year:'numeric', month:'2-digit', day:'2-digit', hour:'2-digit', hourCycle:'h23'})
    .formatToParts(data).reduce((o,p)=>{ o[p.type]=p.value; return o; }, {});
  const pregao = new Date(Date.UTC(+partes.year, +partes.month - 1, +partes.day));
  if(+partes.hour < 18) pregao.setUTCDate(pregao.getUTCDate() - 1);
  while(pregao.getUTCDay() === 0 || pregao.getUTCDay() === 6) pregao.setUTCDate(pregao.getUTCDate() - 1);
  const dataBR = pregao.toLocaleDateString('pt-BR', {timeZone:'UTC'});
  const titulo = document.getElementById('cotacoes-br-titulo');
  const filtro = document.getElementById('cotacoes-br-filtro');
  const col3 = document.getElementById('cotacoes-br-col3-titulo');
  const rodape = document.getElementById('cotacoes-br-rodape');
  if(titulo) titulo.textContent = 'Cotações de fechamento — pregão de ' + dataBR;
  if(filtro) filtro.style.display = 'none';
  if(col3) col3.textContent = 'Mais negociadas';
  if(rodape){
    const dias = (Date.now() - data.getTime()) / 86400000;
    rodape.textContent = 'Dados de fim de dia (EOD) do pregão de ' + dataBR + '. Fonte: ' + (d.fonte || 'B3')
      + '. Liquidez = volume financeiro de pelo menos R$ 5 milhões no dia (' + (d.ativos_liquidos || 0) + ' ações nesse pregão).'
      + (dias > 4 ? ' Atenção: este é o último fechamento disponível; a coleta mais recente não ocorreu.' : '')
      + ' Informação educativa, não é recomendação de investimento.';
  }
  const normalizar = arr => (Array.isArray(arr) ? arr : []).map(x => ({
    mercado:'br', ticker:String(x.ticker||''), nome:nomeCotacao(String(x.ticker||''), String(x.nome||'')), setor:setorCotacaoPT(String(x.ticker||''), String(x.setor||'')),
    preco:Number(x.preco)||0, variacao_pct:Number(x.variacao_pct)||0, volume_fin:Number(x.volume_fin)||0
  }));
  /* v18: com a lista completa (SQL 06), os cards passam a ranquear TODAS as
     ações do pregão. O filtro de liquidez vem ligado por padrão (sem ele o
     topo das altas é ocupado por papéis com meia dúzia de negócios) e pode
     ser desligado para ver a B3 inteira. */
  const todas = normalizar(d.todas);
  let grupos;
  if(todas.length){
    const universo = window.__eodSoLiquidas === false ? todas : todas.filter(c => c.volume_fin >= 5000000);
    grupos = {
      alta: universo.filter(c => c.variacao_pct > 0).sort((a,b)=> b.variacao_pct - a.variacao_pct),
      baixa: universo.filter(c => c.variacao_pct < 0).sort((a,b)=> a.variacao_pct - b.variacao_pct),
      dividendo: universo.slice().sort((a,b)=> b.volume_fin - a.volume_fin)
    };
    cotacoesEODMontarControles(todas.length, todas.filter(c => c.volume_fin >= 5000000).length);
    cotacoesEODRenderTabela(todas, dataBR);
  } else {
    grupos = {alta: normalizar(d.altas), baixa: normalizar(d.baixas), dividendo: normalizar(d.mais_negociadas)};
  }
  ['alta','baixa','dividendo'].forEach(tipo=>{
    const container = document.querySelector(`.cotacoes-lista[data-mercado="br"][data-tipo="${tipo}"]`);
    const btn = document.querySelector(`.cotacoes-vertodos[data-mercado="br"][data-tipo="${tipo}"]`);
    if(!container || !btn) return;
    const lista = grupos[tipo];
    const expandido = container.getAttribute('data-expandido') === '1';
    const visiveis = expandido ? lista : lista.slice(0, 3);
    container.classList.toggle('cotacoes-lista-rolagem', expandido);
    container.innerHTML = visiveis.length
      ? visiveis.map(c => tipo === 'dividendo' ? templateCotacaoVolume(c) : templateCotacaoAltaBaixa(Object.assign({}, c, {ticker:escaparHtml(c.ticker), nome:escaparHtml(c.nome)}))).join('')
      : '<p class="cotacoes-vazio">' + (tipo === 'alta' ? 'Nenhuma ação líquida fechou em alta.' : tipo === 'baixa' ? 'Nenhuma ação líquida fechou em baixa.' : 'Sem dados.') + '</p>';
    btn.style.display = lista.length > 3 ? 'block' : 'none';
    btn.textContent = expandido ? 'Ver menos' : ('Ver todos (' + lista.length + ')');
  });
}
function cotacoesEODMontarControles(total, liquidas){
  const box = document.querySelector('#mercado-br-conteudo .cotacoes-box');
  if(!box) return;
  let ctl = document.getElementById('cotacoes-br-controles');
  if(!ctl){
    ctl = document.createElement('div');
    ctl.id = 'cotacoes-br-controles';
    ctl.className = 'cotacoes-eod-controles';
    ctl.innerHTML = '<label class="cotacoes-eod-toggle"><input type="checkbox" id="cotacoes-br-so-liquidas" checked> '
      + 'Somente ações com liquidez (volume financeiro de pelo menos R$ 5 milhões no dia)</label>'
      + '<span class="cotacoes-eod-contagem" id="cotacoes-br-contagem"></span>';
    const colunas = box.querySelector('.cotacoes-colunas');
    box.insertBefore(ctl, colunas);
    ctl.querySelector('input').addEventListener('change', function(){
      window.__eodSoLiquidas = this.checked;
      document.querySelectorAll('.cotacoes-lista[data-mercado="br"]').forEach(c => c.setAttribute('data-expandido','0'));
      renderizarCotacoes('br');
    });
  }
  ctl.style.display = '';
  ctl.querySelector('input').checked = window.__eodSoLiquidas !== false;
  const cont = document.getElementById('cotacoes-br-contagem');
  if(cont) cont.textContent = total + ' ações negociadas no pregão · ' + liquidas + ' com liquidez';
}
window.__eodOrdem = {campo:'ticker', dir:1};
function cotacoesEODRenderTabela(todas, dataBR){
  const box = document.querySelector('#mercado-br-conteudo .cotacoes-box');
  if(!box) return;
  let sec = document.getElementById('cotacoes-br-tabela');
  if(!sec){
    sec = document.createElement('div');
    sec.id = 'cotacoes-br-tabela';
    sec.className = 'cotacoes-eod-tabela';
    sec.innerHTML = '<div class="cotacoes-eod-tabela-topo"><h3 id="cotacoes-br-tabela-titulo"></h3>'
      + '<input type="search" id="cotacoes-br-busca" placeholder="Buscar por código, empresa ou setor" aria-label="Buscar ação"></div>'
      + '<div class="cotacoes-eod-tabela-wrap"><table><thead><tr>'
      + '<th data-campo="ticker">Ação</th><th data-campo="nome">Empresa</th><th data-campo="setor">Setor</th>'
      + '<th data-campo="preco" class="num">Fechamento</th><th data-campo="variacao_pct" class="num">Variação</th>'
      + '<th data-campo="volume_fin" class="num">Volume financeiro</th></tr></thead><tbody></tbody></table></div>'
      + '<p class="cotacoes-eod-tabela-rodape" id="cotacoes-br-tabela-rodape"></p>';
    const rodape = document.getElementById('cotacoes-br-rodape');
    box.insertBefore(sec, rodape);
    sec.querySelector('#cotacoes-br-busca').addEventListener('input', ()=> cotacoesEODRenderTabela(window.__eodTodasCache || [], window.__eodDataCache || ''));
    sec.querySelectorAll('th[data-campo]').forEach(th=>{
      th.tabIndex = 0;
      const ordenar = ()=>{
        const campo = th.getAttribute('data-campo');
        const o = window.__eodOrdem;
        window.__eodOrdem = {campo, dir: o.campo === campo ? -o.dir : (['preco','variacao_pct','volume_fin'].includes(campo) ? -1 : 1)};
        cotacoesEODRenderTabela(window.__eodTodasCache || [], window.__eodDataCache || '');
      };
      th.addEventListener('click', ordenar);
      th.addEventListener('keydown', e=>{ if(e.key==='Enter' || e.key===' '){ e.preventDefault(); ordenar(); } });
    });
  }
  sec.style.display = '';
  window.__eodTodasCache = todas; window.__eodDataCache = dataBR;
  const soLiq = window.__eodSoLiquidas !== false;
  const termo = (document.getElementById('cotacoes-br-busca').value || '').trim().toLowerCase();
  let linhas = soLiq ? todas.filter(c => c.volume_fin >= 5000000) : todas.slice();
  if(termo) linhas = linhas.filter(c => c.ticker.toLowerCase().includes(termo) || c.nome.toLowerCase().includes(termo) || String(c.setor||'').toLowerCase().includes(termo));
  const {campo, dir} = window.__eodOrdem;
  linhas.sort((a,b)=>{
    const x = a[campo], y = b[campo];
    return (typeof x === 'number' ? x - y : String(x).localeCompare(String(y), 'pt-BR')) * dir;
  });
  document.getElementById('cotacoes-br-tabela-titulo').textContent =
    (soLiq ? 'Ações com liquidez' : 'Todas as ações da B3') + ' — fechamento de ' + dataBR;
  sec.querySelectorAll('th[data-campo]').forEach(th=>{
    const ativo = th.getAttribute('data-campo') === campo;
    th.setAttribute('aria-sort', ativo ? (dir > 0 ? 'ascending' : 'descending') : 'none');
    th.classList.toggle('ordenado', ativo);
  });
  sec.querySelector('tbody').innerHTML = linhas.length ? linhas.map(c=>{
    const cor = c.variacao_pct > 0 ? 'var(--teal)' : (c.variacao_pct < 0 ? 'var(--rust)' : 'var(--ink-soft)');
    const sinal = c.variacao_pct > 0 ? '+' : '';
    return `<tr><td class="tk">${tkLinkV108(c.ticker, 'br', escaparHtml(c.ticker))}</td><td>${escaparHtml(c.nome)}</td><td>${escaparHtml(c.setor || '—')}</td>`
      + `<td class="num">${formatBRL(c.preco)}</td><td class="num" style="color:${cor};">${sinal}${c.variacao_pct.toFixed(2).replace('.', ',')}%</td>`
      + `<td class="num">${formatarVolumeFinanceiro(c.volume_fin)}</td></tr>`;
  }).join('') : '<tr><td colspan="6" class="vazio">Nenhuma ação encontrada.</td></tr>';
  document.getElementById('cotacoes-br-tabela-rodape').textContent = linhas.length + ' ações exibidas. Clique no título de uma coluna para ordenar.';
}
function restaurarRotulosCotacoesBR(){
  if(!__cotacoesBRRotulos.ok) return;
  const t = document.getElementById('cotacoes-br-titulo');
  const f = document.getElementById('cotacoes-br-filtro');
  const c = document.getElementById('cotacoes-br-col3-titulo');
  const r = document.getElementById('cotacoes-br-rodape');
  if(t) t.textContent = __cotacoesBRRotulos.titulo;
  if(f) f.style.display = '';
  if(c) c.textContent = __cotacoesBRRotulos.col3;
  if(r) r.textContent = __cotacoesBRRotulos.rodape;
  ['cotacoes-br-controles','cotacoes-br-tabela'].forEach(id=>{ const el = document.getElementById(id); if(el) el.style.display = 'none'; });
  document.querySelectorAll('.cotacoes-lista[data-mercado="br"]').forEach(c => c.classList.remove('cotacoes-lista-rolagem'));
}

function renderizarCotacoes(mercado){
  if(mercado === 'us' && window.__cotacoesUS){ renderizarCotacoesUSReais(); return; }   /* v48 */
  if(mercado === 'br'){
    cotacoesBRGuardarRotulos();
    if(window.__cotacoesEOD){ renderizarCotacoesEOD(); return; }
    restaurarRotulosCotacoesBR();
  }
  const selFiltro = document.querySelector(`.cotacoes-indice[data-mercado="${mercado}"]`);
  const indice = selFiltro ? selFiltro.value : '';
  const linhasMercado = COTACOES_DEMO.filter(c => c.mercado === mercado && (!indice || c.indice === indice));

  ['alta','baixa','dividendo'].forEach(tipo=>{
    const container = document.querySelector(`.cotacoes-lista[data-mercado="${mercado}"][data-tipo="${tipo}"]`);
    const btn = document.querySelector(`.cotacoes-vertodos[data-mercado="${mercado}"][data-tipo="${tipo}"]`);
    if(!container || !btn) return;

    const doTipo = linhasMercado.filter(c => c.tipo === tipo);
    const expandido = container.getAttribute('data-expandido') === '1';
    const visiveis = expandido ? doTipo : doTipo.slice(0, 3);

    container.innerHTML = visiveis.length
      ? visiveis.map(c => tipo === 'dividendo' ? templateCotacaoDividendo(c) : templateCotacaoAltaBaixa(c)).join('')
      : '<p class="cotacoes-vazio">Nenhum ativo nesse filtro.</p>';

    btn.style.display = doTipo.length > 3 ? 'block' : 'none';
    btn.textContent = expandido ? 'Ver menos' : 'Ver todos';
  });
}

document.querySelectorAll('.cotacoes-indice').forEach(sel=>{
  sel.addEventListener('change', function(){ renderizarCotacoes(this.getAttribute('data-mercado')); });
});
document.querySelectorAll('.cotacoes-vertodos').forEach(btn=>{
  btn.addEventListener('click', function(){
    const mercado = this.getAttribute('data-mercado');
    const tipo = this.getAttribute('data-tipo');
    const container = document.querySelector(`.cotacoes-lista[data-mercado="${mercado}"][data-tipo="${tipo}"]`);
    const expandido = container.getAttribute('data-expandido') === '1';
    container.setAttribute('data-expandido', expandido ? '0' : '1');
    renderizarCotacoes(mercado);
  });
});

renderizarCotacoes('br');
renderizarCotacoes('us');

popularFiltroSetor();
renderizarCardsScreener();


atualizarDescricaoAnexo();
atualizarFatorRTexto();
iniciarApp();
atualizarDescricaoPresumido();

/* ==========================================================================
   ATALHO ESC — volta para a tela anterior sem precisar do mouse.
   Ordem (a primeira condição que valer, ganha; nunca faz logout nem
   envia formulário):
   1) Overlay/modal/dropdown/menu aberto -> ESC fecha só isso.
   2) (coberto pelo item 1: os formulários "Cadastrar/Administrar" são
      os próprios overlays — fechar = mesmo efeito do link "Cancelar",
      sem gravar nada.)
   3) Sem overlay aberto -> ESC = volta ao hash anterior (history.back()).
   4) Sem histórico interno -> landing pública (deslogado) ou home
      logada (logado). Nunca fecha a aba. */
const __historicoInicialLength = window.history.length;

function fecharTudoAberto(){
  let fechouAlgo = false;

  // 0) Formulário de calculadora aberto (âncora abaixo dos ícones) ->
  //    ESC volta ao grid de ícones, antes de qualquer outro fallback.
  const calcArea = document.getElementById('calc-form-area');
  if(calcArea && calcArea.innerHTML.trim() !== ''){
    calcArea.innerHTML = '';
    fechouAlgo = true;
  }

  // 0b) Modal "Configurar regras" (75º prompt) tem checagem de alteração
  //     não salva — se houver mudança, confirma antes de fechar; se
  //     confirmar que não, este ESC não fecha mais nada (evita fechar
  //     outra coisa junto com uma confirmação pendente).
  const regrasOverlay = document.getElementById('cc-regras-overlay');
  if(regrasOverlay && getComputedStyle(regrasOverlay).display !== 'none'){
    return tentarFecharModalRegras();
  }

  // 1) Todos os modais/overlays do app (ficha, admin, formulários,
  //    Equipe, Convidar, B3, viewer de PDF, simulação — todos usam
  //    a mesma classe).
  document.querySelectorAll('.leilao-ficha-overlay').forEach(overlay=>{
    if(getComputedStyle(overlay).display !== 'none'){
      overlay.style.display = 'none';
      fechouAlgo = true;
    }
  });

  // 2) Listas de busca de cidade (UF→cidade) abertas.
  document.querySelectorAll('.leilao-cidade-lista').forEach(lista=>{
    if(getComputedStyle(lista).display !== 'none'){
      lista.style.display = 'none';
      fechouAlgo = true;
    }
  });

  // 3) Dropdown "Serviços" da landing.
  const ddServicos = document.getElementById('landing-dropdown-servicos');
  if(ddServicos && ddServicos.classList.contains('aberto')){
    ddServicos.classList.remove('aberto');
    fechouAlgo = true;
  }

  // 4) Menu hambúrguer mobile da landing.
  const navMobile = document.getElementById('landing-nav-mobile');
  if(navMobile && navMobile.classList.contains('aberto')){
    navMobile.classList.remove('aberto');
    fechouAlgo = true;
  }

  // 5) Dropdowns da barra "Mercado Financeiro" (Internacional/Ações/FIIs...).
  document.querySelectorAll('.mf-dropdown.aberto').forEach(dd=>{
    dd.classList.remove('aberto');
    fechouAlgo = true;
  });

  // 6) Submenu "Investimentos" da navbar (dashboard e módulo fiscal).
  ['wrap-investimentos-dash','wrap-investimentos'].forEach(id=>{
    const wrap = document.getElementById(id);
    if(wrap && wrap.classList.contains('aberto')){
      wrap.classList.remove('aberto');
      fechouAlgo = true;
    }
  });

  return fechouAlgo;
}

document.addEventListener('keydown', function(e){
  if(e.key !== 'Escape') return;

  // 1) Fecha só o que estiver aberto — nunca troca de rota junto.
  if(fecharTudoAberto()){
    e.preventDefault();
    return;
  }

  // 3) Sem overlay aberto -> volta um passo na navegação interna do app
  //    (painel do dashboard, ou view do módulo fiscal), antes de tentar
  //    o histórico do navegador.
  const teladashboardAtiva = document.getElementById('tela-dashboard').style.display !== 'none';
  const telaFiscalAtiva = document.getElementById('main-app').style.display !== 'none';
  const telaServicoAtiva = document.getElementById('tela-servico').style.display !== 'none';
  const telaExecutivoAtiva = document.getElementById('tela-executivo').style.display !== 'none';
  const telaEquipeAtiva = document.getElementById('tela-equipe').style.display !== 'none';
  if(telaServicoAtiva || telaExecutivoAtiva || telaEquipeAtiva){
    // Página de serviço ou executiva (públicas): ESC tem o mesmo efeito
    // do botão Voltar — direto para a home pública, mesmo se o usuário
    // estiver logado (nunca cai no dashboard por engano).
    e.preventDefault();
    irParaLandingPublica();
    return;
  }
  if(teladashboardAtiva && typeof window.voltarPainelAnteriorDash === 'function' && window.voltarPainelAnteriorDash()){
    e.preventDefault();
    return;
  }
  if(telaFiscalAtiva && typeof voltarViewAnteriorFiscal === 'function' && voltarViewAnteriorFiscal()){
    e.preventDefault();
    return;
  }

  if(window.history.length > __historicoInicialLength){
    e.preventDefault();
    window.history.back();
    return;
  }

  // 4) Sem histórico interno -> landing pública (deslogado) ou home logada.
  e.preventDefault();
  if(sessaoAtual){
    if(!window.location.hash || window.location.hash==='#' || window.location.hash==='#/'){
      return; // já está na home logada, nada a fazer
    }
    navegarHash('#/educacao');
  } else {
    if(typeof irParaLandingPublica === 'function') irParaLandingPublica();
  }
});

/* ==========================================================================
   CALCULADORAS — sistema financeiro, trabalhista e tributos.
   Tudo calculado no navegador, sem crawler e sem buscar BCB/Receita/UOL.
   Tabelas de INSS/IRRF são CONSTANTES abaixo (fáceis de editar quando a
   lei/tabela oficial mudar) — nunca buscadas ao vivo.
   ========================================================================== */

const CALC_DISCLAIMER = 'Simulação Soliduns. Não substitui Banco Central, banco, Receita, INSS, eSocial ou advogado. Não tem valor normativo.';

/* ---------- Conversão de taxa: % a.m. ou % a.a. -> i mensal decimal ---------- */
function taxaMensalEquivalente(taxaPercentual, periodicidade){
  const i = taxaPercentual / 100;
  if(periodicidade === 'aa') return Math.pow(1 + i, 1/12) - 1;
  return i;
}

/* ---------- INSS progressivo por faixas acumuladas (exemplo/editável) ----------
   Faixas de exemplo — confira o teto e as alíquotas vigentes ao editar. */
const INSS_FAIXAS = [
  {ate: 1412.00, aliquota: 0.075},
  {ate: 2666.68, aliquota: 0.09},
  {ate: 4000.03, aliquota: 0.12},
  {ate: 7786.02, aliquota: 0.14}
];
const INSS_TETO_SALARIO = 7786.02;

function inss(bruto){
  const base = Math.min(Math.max(0, bruto||0), INSS_TETO_SALARIO);
  let imposto = 0, faixaAnterior = 0;
  for(const faixa of INSS_FAIXAS){
    if(base > faixaAnterior){
      imposto += (Math.min(base, faixa.ate) - faixaAnterior) * faixa.aliquota;
    }
    faixaAnterior = faixa.ate;
  }
  return imposto;
}

/* ---------- IRRF progressivo + redutor (exemplo/editável) ----------
   Tabela de exemplo + redutor da Lei 15.270/2025 simplificado (renda até
   o teto informado com IR efetivo zero). Atualize quando a lei mudar. */
const IRRF_FAIXAS = [
  {ate: 2259.20, aliquota: 0, deducao: 0},
  {ate: 2826.65, aliquota: 0.075, deducao: 169.44},
  {ate: 3751.05, aliquota: 0.15, deducao: 381.44},
  {ate: 4664.68, aliquota: 0.225, deducao: 662.77},
  {ate: Infinity, aliquota: 0.275, deducao: 896.00}
];
const IRRF_DEDUCAO_DEPENDENTE = 189.59;
const IRRF_REDUTOR_TETO = 5000.00;

function irrfBruto(base){
  base = Math.max(0, base||0);
  const faixa = IRRF_FAIXAS.find(f => base <= f.ate);
  return Math.max(0, base*faixa.aliquota - faixa.deducao);
}
function irrf(base){
  base = Math.max(0, base||0);
  if(base <= IRRF_REDUTOR_TETO) return 0;
  return irrfBruto(base);
}

/* ---------- A1. Aplicação com depósitos regulares ---------- */
function calcA1(pv, p, n, i){
  if(i === 0) return pv + p*n;
  return pv*Math.pow(1+i, n) + p*(Math.pow(1+i, n) - 1)/i;
}

/* ---------- A2. Financiamento Price ---------- */
function calcA2(pv, n, i){
  const pmt = pv * (i*Math.pow(1+i,n)) / (Math.pow(1+i,n) - 1);
  return {pmt, total: pmt*n, juros: pmt*n - pv};
}

/* ---------- A3. Valor futuro de um capital ---------- */
function calcA3(pv, n, i){
  const fv = pv*Math.pow(1+i, n);
  return {fv, juros: fv - pv};
}

/* ---------- A4. Correção de valores ---------- */
function calcA4(v0, n, i){
  return v0*Math.pow(1+i, n);
}

/* ---------- A5. SAC × Price ---------- */
function calcA5Sac(pv, n, i){
  const amort = pv/n;
  let saldo = pv, totalPago = 0;
  const linhas = [];
  for(let k=1; k<=n; k++){
    const juros = saldo*i;
    const prestacao = amort + juros;
    linhas.push({k, amort, juros, prestacao});
    totalPago += prestacao;
    saldo -= amort;
  }
  return {linhas, primeira: linhas[0].prestacao, ultima: linhas[n-1].prestacao, total: totalPago, juros: totalPago - pv};
}

/* ---------- A6. Consórcios (sorteio / lance livre / lance embutido) ----------
   Consórcio não é Price — não há juros, só taxa de administração,
   fundo de reserva e (opcional) correção da carta. O mês N da
   contemplação é sempre HIPOTÉTICO, informado pelo usuário — a
   ferramenta nunca sorteia nem prevê assembleia. */
/* Modo de correção (70º): 'nenhuma' | 'aa' (INCC % a.a., convertido pra
   mensal) | 'am' (INCC já informado direto ao mês, sem converter).
   Índice do contrato manda — aqui a taxa é a que o usuário digitou. */
function calcA6Fator(modo, taxa){
  if(modo==='aa') return Math.pow(1 + (taxa||0)/100, 1/12);
  if(modo==='am') return 1 + (taxa||0)/100;
  return 1; // 'nenhuma'
}
function calcA6Coluna(params, livrePct, embutidoPct){
  const {cartaInicial, prazo, mesN, adminPct, reservaPct, adesao, seguroMensal, fatorM, teto, reduzirParcela} = params;

  // Parcela cheia no mês 1 (sem correção) + seguro
  const P = cartaInicial * (1 + adminPct/100 + reservaPct/100) / prazo + seguroMensal;

  // Carta corrigida no mês N
  const cartaN = cartaInicial * Math.pow(fatorM, mesN-1);

  if(embutidoPct > teto){
    return {erro: `Lance embutido (${embutidoPct}%) acima do teto (${teto}%).`};
  }

  const embutidoRS = cartaN * (embutidoPct/100);
  const livreRS = cartaN * (livrePct/100);
  const creditoLiquido = cartaN - embutidoRS;

  if(creditoLiquido <= 0){
    return {erro: 'embutido comeu a carta'};
  }

  // Soma de P_1..P_N — cada parcela corrigida pelo mesmo fator da carta
  let somaParcelasAteN = 0;
  const parcelasCorrigidas = [];
  for(let k=1; k<=mesN; k++){
    const Pk = P * Math.pow(fatorM, k-1);
    somaParcelasAteN += Pk;
    parcelasCorrigidas.push(Pk);
  }

  const desembolsoAteN = somaParcelasAteN + adesao + livreRS;
  const devidoTotal = cartaN * (1 + adminPct/100 + reservaPct/100);
  const pagoAteN = somaParcelasAteN;
  const lanceQueAbate = livreRS + embutidoRS;
  const saldo = Math.max(devidoTotal - pagoAteN - lanceQueAbate, 0);
  const mesesRestantes = prazo - mesN;

  let pDepois, mesesDepois;
  if(reduzirParcela && mesesRestantes > 0){
    pDepois = saldo / mesesRestantes + seguroMensal;
    mesesDepois = mesesRestantes;
  } else {
    pDepois = P;
    mesesDepois = Math.ceil(saldo / Math.max(P, 0.01));
  }

  const totalEstimadoAteFim = desembolsoAteN + pDepois * mesesDepois;
  const indicador = (desembolsoAteN / creditoLiquido) / mesN;

  return {P, cartaN, embutidoRS, livreRS, creditoLiquido, desembolsoAteN, saldo, mesesRestantes, pDepois, mesesDepois, totalEstimadoAteFim, indicador, parcelasCorrigidas};
}

/* ---------- 69º: financiamento (Price e SAC) no mesmo mês N, pra
   comparar com o consórcio. Reaproveita calcA2/calcA5Sac (46º). ---------- */
function calcA6Financiamento(bem, entrada, prazoFin, taxaAA, mesN){
  const financiado = Math.max(bem - entrada, 0);
  const n = Math.max(1, prazoFin);
  const i = Math.pow(1 + taxaAA/100, 1/12) - 1;
  const price = calcA2(financiado, n, i);
  const sac = calcA5Sac(financiado, n, i);
  const nEfetivo = Math.min(mesN, n);

  return {
    financiado,
    price: {
      desembolsoAteN: entrada + price.pmt * nEfetivo,
      parcelaAposN: mesN < n ? price.pmt : 0,
      totalFim: entrada + price.total
    },
    sac: {
      desembolsoAteN: entrada + sac.linhas.slice(0, nEfetivo).reduce((s,l)=>s+l.prestacao,0),
      parcelaAposN: mesN < n ? sac.linhas[mesN].prestacao : 0,
      totalFim: entrada + sac.total
    }
  };
}

/* ---------- 71º: renda fixa — custo de oportunidade do mesmo fluxo
   de caixa do consórcio (parcelas do cenário "só sorteio", + o lance
   livre do cenário 2 no mês N, se marcado), aplicado a uma taxa que
   o usuário informa. Não é o consórcio virando CDB — é só "o que
   esse dinheiro renderia se não tivesse entrado no grupo". ---------- */
function calcA6RendaFixa(parcelasCorrigidas, livreRS, taxaAA, bemComparar, incluirLivre){
  if(taxaAA===null || taxaAA===undefined || isNaN(taxaAA)) return {semTaxa:true};
  const i = Math.pow(1 + taxaAA/100, 1/12) - 1;
  const N = parcelasCorrigidas.length;
  let fv = 0;
  for(let k=1; k<=N; k++){
    fv += parcelasCorrigidas[k-1] * Math.pow(1+i, N-k);
  }
  if(incluirLivre) fv += livreRS;
  return {fv, diferenca: fv - bemComparar, daria: fv >= bemComparar, indicador: fv / N};
}

/* ---------- B1. Salário líquido ---------- */
function calcB1(bruto, dependentes, vtPercent, outros){
  const inssVal = inss(bruto);
  const baseIR = Math.max(0, bruto - inssVal - dependentes*IRRF_DEDUCAO_DEPENDENTE);
  const irrfVal = irrf(baseIR);
  const vtVal = bruto * (vtPercent/100);
  const liquido = bruto - inssVal - irrfVal - vtVal - outros;
  return {inss: inssVal, irrf: irrfVal, vt: vtVal, outros, liquido, baseIR};
}

/* ---------- B2. Rescisão ---------- */
function contarAvos(dataInicio, dataFim){
  let avos = 0, cursor = new Date(dataInicio);
  while(true){
    const proximoMes = new Date(cursor.getFullYear(), cursor.getMonth()+1, cursor.getDate());
    if(proximoMes > dataFim){
      const diasNoMes = Math.round((dataFim - cursor)/(1000*60*60*24));
      if(diasNoMes >= 15) avos++;
      break;
    }
    avos++;
    cursor = proximoMes;
  }
  return Math.min(12, avos);
}
function ultimoAniversario(admissao, demissao){
  let aniversario = new Date(admissao);
  while(true){
    const proximo = new Date(aniversario.getFullYear()+1, aniversario.getMonth(), aniversario.getDate());
    if(proximo > demissao) break;
    aniversario = proximo;
  }
  return aniversario;
}
function calcB2({salario, admissao, demissao, motivo, fgtsSaldo, feriasVencidas, aviso}){
  const inicioAnoDemissao = new Date(demissao.getFullYear(), 0, 1);
  const marcoInicio13 = admissao > inicioAnoDemissao ? admissao : inicioAnoDemissao;
  const avos13 = contarAvos(marcoInicio13, demissao);
  const marcoFerias = ultimoAniversario(admissao, demissao);
  const avosFerias = contarAvos(marcoFerias, demissao);

  const saldoDias = demissao.getDate();
  const saldoSalario = (salario/30)*saldoDias;

  const decimoProp = salario*(avos13/12);
  const feriasProp = salario*(avosFerias/12);
  const feriasPropTerco = feriasProp/3;
  const feriasVenc = feriasVencidas ? salario : 0;
  const feriasVencTerco = feriasVenc/3;

  let avisoIndenizado = 0;
  if(aviso === 'indenizado') avisoIndenizado = salario;

  let multaFgts = 0;
  if(motivo === 'sem_justa_causa') multaFgts = fgtsSaldo*0.40;
  else if(motivo === 'acordo') multaFgts = fgtsSaldo*0.20;

  const inssSaldo = inss(saldoSalario);
  const irrfSaldo = irrf(Math.max(0, saldoSalario - inssSaldo));
  const inss13 = inss(decimoProp);
  const irrf13 = irrf(Math.max(0, decimoProp - inss13));

  const bruto = saldoSalario + avisoIndenizado + feriasVenc + feriasVencTerco + feriasProp + feriasPropTerco + decimoProp + multaFgts;
  const descontos = inssSaldo + irrfSaldo + inss13 + irrf13;
  return {avos13, avosFerias, saldoDias, saldoSalario, decimoProp, feriasProp, feriasPropTerco,
          feriasVenc, feriasVencTerco, avisoIndenizado, multaFgts, inssSaldo, irrfSaldo, inss13, irrf13,
          bruto, descontos, liquido: bruto - descontos};
}

/* ---------- B3. Horas extras ---------- */
function calcB3(salario, horasBase, qtd50, qtd100, incluirDSR, diasUteis, repousos){
  const valorHora = salario/horasBase;
  const he50 = qtd50 * valorHora * 1.5;
  const he100 = qtd100 * valorHora * 2;
  let dsr = 0;
  if(incluirDSR && diasUteis>0) dsr = (he50+he100) * (repousos/diasUteis);
  return {valorHora, he50, he100, dsr, total: he50+he100+dsr};
}

/* ---------- B4. 13º e férias avulsos ---------- */
function calcB4(salario, avos, tipo){
  const resultado = {};
  if(tipo === 'decimo' || tipo === 'ambos'){
    const decimoTerceiro = salario * (avos/12);
    const decimoInss = inss(decimoTerceiro);
    resultado.decimoTerceiro = decimoTerceiro;
    resultado.decimoInss = decimoInss;
    resultado.decimoIrrf = irrf(Math.max(0, decimoTerceiro - decimoInss));
  }
  if(tipo === 'ferias' || tipo === 'ambos'){
    const feriasBase = salario * (avos/12);
    resultado.feriasBase = feriasBase;
    resultado.feriasTerco = feriasBase/3;
    resultado.feriasTotal = feriasBase + feriasBase/3;
  }
  return resultado;
}

/* ---------- B5. Custo CLT para a empresa ---------- */
function calcB5(salario, regime, percentualPatronal, beneficios){
  const fgts = salario*0.08, decimo = salario*0.0833, ferias = salario*0.0833, tercoFerias = salario*0.0278;
  const provisoes = fgts+decimo+ferias+tercoFerias;
  const encargosPatronais = regime === 'lucro' ? salario*(percentualPatronal/100) : 0;
  const custoMensal = salario + encargosPatronais + provisoes + beneficios;
  return {fgts, decimo, ferias, tercoFerias, provisoes, encargosPatronais, custoMensal, multiplicador: custoMensal/salario};
}

/* ---------- C2. Carnê-leão ---------- */
function calcC2(rendimento, despesa){
  const base = Math.max(0, rendimento - despesa);
  return {base, imposto: irrf(base)};
}

/* ---------- UI: abrir/fechar calculadora, montar formulário, calcular ---------- */
function calcCampoDinheiro(id, label, placeholder){
  return `<div><label>${label}</label><input type="text" inputmode="decimal" id="${id}" placeholder="${placeholder||'R$ 0,00'}" oninput="aplicarMascaraMoeda(this)" onblur="finalizarMascaraMoeda(this)"></div>`;
}
function calcCampoTaxa(idValor, idPeriodo, label){
  return `<div><label>${label}</label>
    <div style="display:flex; gap:8px;">
      <input type="text" inputmode="decimal" id="${idValor}" placeholder="Ex.: 1,00" style="flex:2;">
      <select id="${idPeriodo}" style="flex:1;"><option value="am">% a.m.</option><option value="aa">% a.a.</option></select>
    </div>
  </div>`;
}
function calcCampoNumero(id, label, placeholder, valorDefault){
  return `<div><label>${label}</label><input type="number" id="${id}" placeholder="${placeholder||''}" ${valorDefault!==undefined?`value="${valorDefault}"`:''}></div>`;
}
function calcCampoPercentual(id, label, placeholder, valorDefault){
  const val = valorDefault!==undefined ? String(valorDefault).replace('.',',') : '';
  return `<div><label>${label}</label><input type="text" inputmode="decimal" id="${id}" placeholder="${placeholder||'Ex.: 1,00'}" value="${val}"></div>`;
}
function calcLerTaxaMensal(idValor, idPeriodo){
  const valor = parseFloat((document.getElementById(idValor).value||'0').replace(',','.'));
  const periodo = document.getElementById(idPeriodo).value;
  return taxaMensalEquivalente(valor, periodo);
}
function calcLinhaResultado(k, v, destaque){
  return `<div class="result-line${destaque?' total':''}"><span class="k">${k}</span><span class="v">${v}</span></div>`;
}
function calcDisclaimerHtml(){
  return `<p class="calc-disclaimer">${CALC_DISCLAIMER}</p>`;
}

const CALC_TITULOS = {
  a1:'Aplicação com depósitos regulares', a2:'Financiamento — prestações fixas (Price)',
  a3:'Valor futuro de um capital', a4:'Correção de valores', a5:'SAC × Price (imóvel)',
  a6:'Consórcios',
  b1:'Salário líquido (holerite)', b2:'Rescisão (estimativa)', b3:'Horas extras',
  b4:'13º e férias avulsos', b5:'Custo CLT para a empresa',
  c1:'IRRF mensal', c2:'Carnê-leão (estimativa)', c3:'Teto / contribuição INSS'
};

function abrirCalculadora(codigo){
  if(codigo === 'c4'){ document.getElementById('painel-calculadoras').classList.remove('ativo'); navegarHash('#/gestao-fiscal'); return; }
  if(codigo === 'c5'){ document.getElementById('painel-calculadoras').classList.remove('ativo'); navegarHash('#/gestao-fiscal?sim=futuro'); return; }

  const area = document.getElementById('calc-form-area');
  let camposHtml = '';

  if(codigo==='a1'){
    camposHtml = calcCampoDinheiro('calc-a1-pv','Valor inicial (opcional)') +
      calcCampoDinheiro('calc-a1-p','Depósito mensal') +
      calcCampoTaxa('calc-a1-taxa','calc-a1-periodo','Taxa') +
      calcCampoNumero('calc-a1-n','Prazo (meses)','Ex.: 24');
  } else if(codigo==='a2'){
    camposHtml = calcCampoDinheiro('calc-a2-pv','Valor financiado') +
      calcCampoTaxa('calc-a2-taxa','calc-a2-periodo','Taxa') +
      calcCampoNumero('calc-a2-n','Prazo (meses)','Ex.: 12');
  } else if(codigo==='a3'){
    camposHtml = calcCampoDinheiro('calc-a3-pv','Valor hoje') +
      calcCampoTaxa('calc-a3-taxa','calc-a3-periodo','Taxa') +
      calcCampoNumero('calc-a3-n','Prazo (meses)','Ex.: 12');
  } else if(codigo==='a4'){
    camposHtml = calcCampoDinheiro('calc-a4-v0','Valor original') +
      calcCampoPercentual('calc-a4-taxa','Fator mensal % (informado por você)','Ex.: 0,50') +
      calcCampoNumero('calc-a4-n','Prazo (meses)','Ex.: 12') +
      `<p class="note">Cole a taxa mensal equivalente. Para série oficial use a Calculadora do Cidadão no site do BCB: <a href="https://www.bcb.gov.br/meubc/calculadoradocidadao" target="_blank" rel="noopener" style="color:var(--gold);">bcb.gov.br/meubc/calculadoradocidadao</a></p>`;
  } else if(codigo==='a5'){
    camposHtml = calcCampoDinheiro('calc-a5-imovel','Valor do imóvel') +
      calcCampoDinheiro('calc-a5-entrada','Entrada') +
      calcCampoPercentual('calc-a5-taxa','Taxa % a.a.','Ex.: 10') +
      calcCampoNumero('calc-a5-prazo','Prazo (anos, máx. 35)','Ex.: 30');
  } else if(codigo==='a6'){
    camposHtml = calcCampoDinheiro('calc-a6-carta','Carta de crédito atual') +
      calcCampoNumero('calc-a6-prazo','Prazo do grupo (meses, 12–360)','Ex.: 120') +
      calcCampoNumero('calc-a6-mesn','Mês N da contemplação hipotética','Ex.: 24') +
      calcCampoPercentual('calc-a6-admin','Taxa de administração total (%)','Ex.: 15') +
      calcCampoPercentual('calc-a6-reserva','Fundo de reserva total (%)','Ex.: 2') +
      calcCampoDinheiro('calc-a6-adesao','Seguro / adesão (R$ à vista)') +
      calcCampoDinheiro('calc-a6-seguro-mensal','Seguro mensal (R$)') +
      calcCampoPercentual('calc-a6-livre','Lance livre — % da carta no mês N','Ex.: 0') +
      calcCampoPercentual('calc-a6-embutido','Lance embutido — % da carta no mês N','Ex.: 0') +
      calcCampoPercentual('calc-a6-teto','Teto do lance embutido (%)','Ex.: 30',30) +
      `<div style="grid-column:1/-1;">
        <label>Após a contemplação</label>
        <div style="display:flex; gap:18px; align-items:center; margin-bottom:14px;">
          <label style="display:flex; align-items:center; gap:6px; margin:0; text-transform:none; font-size:13px; color:var(--text);">
            <input type="radio" name="calc-a6-pos" id="calc-a6-pos-parcela" value="parcela" checked style="width:auto; margin:0;"> Reduzir parcela
          </label>
          <label style="display:flex; align-items:center; gap:6px; margin:0; text-transform:none; font-size:13px; color:var(--text);">
            <input type="radio" name="calc-a6-pos" id="calc-a6-pos-prazo" value="prazo" style="width:auto; margin:0;"> Reduzir prazo
          </label>
        </div>
      </div>` +
      `<div style="grid-column:1/-1; border-top:1px dashed var(--line); padding-top:14px; margin-top:2px;">
        <label>Correção da carta e da parcela</label>
        <div style="display:flex; gap:18px; align-items:center; margin-bottom:14px; flex-wrap:wrap;">
          <label style="display:flex; align-items:center; gap:6px; margin:0; text-transform:none; font-size:13px; color:var(--text);">
            <input type="radio" name="calc-a6-corr-modo" id="calc-a6-corr-nenhuma" value="nenhuma" checked style="width:auto; margin:0;"> Sem correção
          </label>
          <label style="display:flex; align-items:center; gap:6px; margin:0; text-transform:none; font-size:13px; color:var(--text);">
            <input type="radio" name="calc-a6-corr-modo" id="calc-a6-corr-aa" value="aa" style="width:auto; margin:0;"> INCC constante % a.a.
          </label>
          <label style="display:flex; align-items:center; gap:6px; margin:0; text-transform:none; font-size:13px; color:var(--text);">
            <input type="radio" name="calc-a6-corr-modo" id="calc-a6-corr-am" value="am" style="width:auto; margin:0;"> INCC constante % a.m.
          </label>
        </div>
      </div>` +
      calcCampoPercentual('calc-a6-corr-taxa','Taxa do índice (%, conforme opção acima)','Ex.: 6') +
      `<div style="grid-column:1/-1; border-top:1px dashed var(--line); padding-top:14px; margin-top:2px;">
        <label style="color:var(--gold);">Financiamento para comparar</label>
      </div>` +
      calcCampoDinheiro('calc-a6-fin-bem','Valor do bem (padrão: carta de crédito)') +
      calcCampoDinheiro('calc-a6-fin-entrada','Entrada') +
      calcCampoNumero('calc-a6-fin-prazo','Prazo do financiamento (meses, padrão: prazo do grupo)') +
      calcCampoPercentual('calc-a6-fin-taxa','Taxa de juros % a.a. (aprox. de CET, sem MIP/DFI)','Ex.: 12') +
      `<div style="grid-column:1/-1; border-top:1px dashed var(--line); padding-top:14px; margin-top:2px;">
        <label style="color:var(--gold);">Renda fixa para comparar</label>
      </div>` +
      calcCampoPercentual('calc-a6-rf-taxa','Taxa % a.a. líquida de IR (obrigatória para esta coluna)') +
      `<div style="grid-column:1/-1; display:flex; align-items:center; gap:8px; margin-bottom:14px;">
        <input type="checkbox" id="calc-a6-rf-livre" checked style="width:auto; margin:0;">
        <label style="margin:0; text-transform:none; font-size:13px; color:var(--text);" for="calc-a6-rf-livre">Simular o lance livre aplicado na renda fixa</label>
      </div>` +
      `<p class="note">A ferramenta NÃO sorteia — você informa o mês N hipotético. Taxa, fundo, lance e correção seguem o CONTRATO do grupo. Índice do contrato manda; aqui a taxa é a que você digitou. Referência: <a href="https://www.bcb.gov.br" target="_blank" rel="noopener" style="color:var(--gold);">bcb.gov.br</a> e Lei 11.795/2008.</p>`;
  } else if(codigo==='b1'){
    camposHtml = calcCampoDinheiro('calc-b1-bruto','Salário bruto') +
      calcCampoNumero('calc-b1-dependentes','Dependentes IR',null,0) +
      `<div><label>Desconto VT</label><select id="calc-b1-vt"><option value="0">Sem VT (0%)</option><option value="6">Com VT (6%)</option></select></div>` +
      calcCampoDinheiro('calc-b1-outros','Outros descontos (saúde etc.)');
  } else if(codigo==='b2'){
    camposHtml = calcCampoDinheiro('calc-b2-salario','Salário') +
      `<div><label>Admissão</label><input type="date" id="calc-b2-admissao"></div>` +
      `<div><label>Demissão</label><input type="date" id="calc-b2-demissao"></div>` +
      `<div><label>Motivo</label><select id="calc-b2-motivo">
        <option value="sem_justa_causa">Sem justa causa</option>
        <option value="pedido">Pedido de demissão</option>
        <option value="justa_causa">Justa causa</option>
        <option value="acordo">Acordo (art. 484-A)</option>
      </select></div>` +
      calcCampoDinheiro('calc-b2-fgts','Saldo de FGTS informado') +
      `<div><label>Férias vencidas</label><select id="calc-b2-feriasvenc"><option value="nao">Não</option><option value="sim">Sim</option></select></div>` +
      `<div><label>Aviso prévio</label><select id="calc-b2-aviso">
        <option value="indenizado">Indenizado</option>
        <option value="trabalhado">Trabalhado</option>
        <option value="nao">Não cabe</option>
      </select></div>`;
  } else if(codigo==='b3'){
    camposHtml = calcCampoDinheiro('calc-b3-salario','Salário') +
      calcCampoNumero('calc-b3-horas','Horas mensais base',null,220) +
      calcCampoNumero('calc-b3-qtd50','Qtd. horas extras 50%',null,0) +
      calcCampoNumero('calc-b3-qtd100','Qtd. horas extras 100%',null,0) +
      `<div style="grid-column:1/-1;"><label><input type="checkbox" id="calc-b3-dsr" style="width:auto; display:inline-block; margin-right:6px;">Incluir reflexo de DSR</label></div>` +
      `<div id="calc-b3-dsr-campos" style="display:none; grid-column:1/-1;" class="grid2">
        ${calcCampoNumero('calc-b3-diasuteis','Dias úteis no mês',null,22)}
        ${calcCampoNumero('calc-b3-repousos','Dias de repouso no mês',null,4)}
      </div>` +
      `<p class="note">Acordo/CCT pode mudar a base de 220h e os percentuais.</p>`;
  } else if(codigo==='b4'){
    camposHtml = calcCampoDinheiro('calc-b4-salario','Salário') +
      calcCampoNumero('calc-b4-avos','Meses (avos, 1–12)',null,12) +
      `<div><label>Tipo</label><select id="calc-b4-tipo">
        <option value="ambos">13º e férias</option>
        <option value="decimo">Só 13º</option>
        <option value="ferias">Só férias</option>
      </select></div>`;
  } else if(codigo==='b5'){
    camposHtml = calcCampoDinheiro('calc-b5-salario','Salário') +
      `<div><label>Regime</label><select id="calc-b5-regime">
        <option value="simples">Simples (Anexo III/V) — sem INSS patronal clássico</option>
        <option value="lucro">Lucro Presumido/Real — com INSS patronal</option>
      </select></div>` +
      calcCampoPercentual('calc-b5-percentual','Percentual patronal editável (%)',null,26.8) +
      calcCampoDinheiro('calc-b5-beneficios','Benefícios (opcional, R$/mês)');
  } else if(codigo==='c1'){
    camposHtml = calcCampoDinheiro('calc-c1-base','Base mensal') +
      calcCampoNumero('calc-c1-dependentes','Dependentes',null,0) +
      `<p class="note">A tabela oficial é da Receita Federal — as faixas usadas aqui são exemplo/editável no código.</p>`;
  } else if(codigo==='c2'){
    camposHtml = calcCampoDinheiro('calc-c2-rendimento','Rendimento mensal (aluguel etc.)') +
      calcCampoDinheiro('calc-c2-despesa','Despesa dedutível') +
      `<p class="note">Confira no programa Carnê-Leão da Receita.</p>`;
  } else if(codigo==='c3'){
    camposHtml = calcCampoDinheiro('calc-c3-salario','Salário de contribuição') +
      `<p class="note">Tabela e teto são exemplo/editável. Confira em <a href="https://www.gov.br/inss" target="_blank" rel="noopener" style="color:var(--gold);">gov.br/inss</a>.</p>`;
  }

  area.innerHTML = `
    <div class="leilao-ficha-box calc-form-fechar" style="max-width:720px; margin:24px auto 0;">
      <button type="button" class="voltar-link" id="calc-btn-fechar">&larr; Voltar às calculadoras</button>
      <h2 style="margin-top:4px;">${CALC_TITULOS[codigo]}</h2>
      <div class="grid2">${camposHtml}</div>
      <button type="button" class="btn-leilao-admin" id="calc-btn-calcular">Calcular</button>
      <div id="calc-calculadoras-resultado" style="margin-top:18px;"></div>
    </div>
  `;
  area.scrollIntoView({behavior:'smooth', block:'start'});

  document.getElementById('calc-btn-fechar').addEventListener('click', fecharFormularioCalc);
  const dsrCheck = document.getElementById('calc-b3-dsr');
  if(dsrCheck){
    dsrCheck.addEventListener('change', function(){
      document.getElementById('calc-b3-dsr-campos').style.display = this.checked ? 'grid' : 'none';
    });
  }
  document.getElementById('calc-btn-calcular').addEventListener('click', ()=> calcularCalculadora(codigo));
}

function fecharFormularioCalc(){
  const area = document.getElementById('calc-form-area');
  if(area) area.innerHTML = '';
}

function calcularCalculadora(codigo){
  const res = document.getElementById('calc-calculadoras-resultado');
  let html = '';

  if(codigo==='a1'){
    const pv = parseMoeda(document.getElementById('calc-a1-pv').value)||0;
    const p = parseMoeda(document.getElementById('calc-a1-p').value)||0;
    const n = parseInt(document.getElementById('calc-a1-n').value,10)||0;
    const i = calcLerTaxaMensal('calc-a1-taxa','calc-a1-periodo');
    const fv = calcA1(pv,p,n,i);
    html = calcLinhaResultado('Valor futuro (FV)', formatBRL(fv), true);
  } else if(codigo==='a2'){
    const pv = parseMoeda(document.getElementById('calc-a2-pv').value)||0;
    const n = parseInt(document.getElementById('calc-a2-n').value,10)||0;
    const i = calcLerTaxaMensal('calc-a2-taxa','calc-a2-periodo');
    const r = calcA2(pv,n,i);
    html = calcLinhaResultado('Prestação (PMT)', formatBRL(r.pmt), true) +
      calcLinhaResultado('Total pago', formatBRL(r.total)) +
      calcLinhaResultado('Juros totais', formatBRL(r.juros)) +
      `<p class="note warn">Não inclui IOF, seguro nem CET — a prestação bancária real costuma ser maior.</p>`;
  } else if(codigo==='a3'){
    const pv = parseMoeda(document.getElementById('calc-a3-pv').value)||0;
    const n = parseInt(document.getElementById('calc-a3-n').value,10)||0;
    const i = calcLerTaxaMensal('calc-a3-taxa','calc-a3-periodo');
    const r = calcA3(pv,n,i);
    html = calcLinhaResultado('Valor futuro (FV)', formatBRL(r.fv), true) + calcLinhaResultado('Juros', formatBRL(r.juros));
  } else if(codigo==='a4'){
    const v0 = parseMoeda(document.getElementById('calc-a4-v0').value)||0;
    const n = parseInt(document.getElementById('calc-a4-n').value,10)||0;
    const taxaPct = parseFloat((document.getElementById('calc-a4-taxa').value||'0').replace(',','.'))||0;
    const vf = calcA4(v0,n,taxaPct/100);
    html = calcLinhaResultado('Valor corrigido', formatBRL(vf), true);
  } else if(codigo==='a5'){
    const imovel = parseMoeda(document.getElementById('calc-a5-imovel').value)||0;
    const entrada = parseMoeda(document.getElementById('calc-a5-entrada').value)||0;
    const taxaAno = parseFloat((document.getElementById('calc-a5-taxa').value||'0').replace(',','.'))||0;
    let prazoAnos = parseInt(document.getElementById('calc-a5-prazo').value,10)||0;
    prazoAnos = Math.min(35, prazoAnos);
    const financiado = imovel - entrada;
    const n = prazoAnos*12;
    const i = taxaMensalEquivalente(taxaAno,'aa');
    const price = calcA2(financiado, n, i);
    const sac = calcA5Sac(financiado, n, i);
    html = `<h3 style="color:var(--gold); font-size:15px; margin:0 0 8px;">Price</h3>` +
      calcLinhaResultado('Prestação (fixa)', formatBRL(price.pmt)) +
      calcLinhaResultado('Total pago', formatBRL(price.total)) +
      calcLinhaResultado('Juros totais', formatBRL(price.juros), true) +
      `<h3 style="color:var(--gold); font-size:15px; margin:18px 0 8px;">SAC</h3>` +
      calcLinhaResultado('1ª parcela', formatBRL(sac.primeira)) +
      calcLinhaResultado('Última parcela', formatBRL(sac.ultima)) +
      calcLinhaResultado('Total pago', formatBRL(sac.total)) +
      calcLinhaResultado('Juros totais', formatBRL(sac.juros), true) +
      `<p class="note">Sem TR, MIP, DFI ou taxa de avaliação.</p>` +
      `<details style="margin-top:12px;"><summary style="cursor:pointer; color:var(--gold); font-size:13px;">Ver as 12 primeiras parcelas (SAC)</summary>
        <div style="max-height:260px; overflow:auto; margin-top:10px;">
          <table class="leilao-admin-table"><thead><tr><th>Parcela</th><th>Amortização</th><th>Juros</th><th>Prestação</th></tr></thead>
          <tbody>${sac.linhas.slice(0,12).map(l=>`<tr><td>${l.k}</td><td>${formatBRL(l.amort)}</td><td>${formatBRL(l.juros)}</td><td>${formatBRL(l.prestacao)}</td></tr>`).join('')}</tbody></table>
        </div>
      </details>`;
  } else if(codigo==='a6'){
    const cartaInput = document.getElementById('calc-a6-carta');
    const prazoInput = document.getElementById('calc-a6-prazo');
    const corrTaxaInput = document.getElementById('calc-a6-corr-taxa');
    const corrModoPre = document.querySelector('input[name="calc-a6-corr-modo"]:checked').value;

    const regrasA6 = [
      {input: cartaInput, obrigatorio:true, tipo:'numero', moeda:true, minimo:0, mensagemVazio:'Informe a carta de crédito.', mensagemInvalido:'Informe um valor válido (R$ 0,00 ou mais).'},
      {input: prazoInput, obrigatorio:true, tipo:'numero', minimo:1, mensagemVazio:'Informe o prazo do grupo (meses).', mensagemInvalido:'O prazo deve ser maior que zero.'}
    ];
    if(corrModoPre !== 'nenhuma'){
      regrasA6.push({input: corrTaxaInput, obrigatorio:true, tipo:'numero', minimo:0, mensagemVazio:'Informe a taxa do índice.', mensagemInvalido:'Informe uma taxa numérica válida.'});
    } else {
      limparErroCampo(corrTaxaInput);
    }
    if(!validarCampos(regrasA6)){
      html = '<p class="empty">Corrija os campos destacados acima antes de calcular.</p>';
      document.getElementById('calc-calculadoras-resultado').innerHTML = html + calcDisclaimerHtml();
      return;
    }

    const cartaInicial = parseMoeda(document.getElementById('calc-a6-carta').value)||0;
    let prazo = parseInt(document.getElementById('calc-a6-prazo').value,10)||0;
    prazo = Math.max(12, Math.min(360, prazo));
    let mesN = parseInt(document.getElementById('calc-a6-mesn').value,10)||1;
    mesN = Math.max(1, Math.min(prazo, mesN));
    const adminPct = parseFloat((document.getElementById('calc-a6-admin').value||'0').replace(',','.'))||0;
    const reservaPct = parseFloat((document.getElementById('calc-a6-reserva').value||'0').replace(',','.'))||0;
    const adesao = parseMoeda(document.getElementById('calc-a6-adesao').value)||0;
    const seguroMensal = parseMoeda(document.getElementById('calc-a6-seguro-mensal').value)||0;
    const livrePct = parseFloat((document.getElementById('calc-a6-livre').value||'0').replace(',','.'))||0;
    const embutidoPct = parseFloat((document.getElementById('calc-a6-embutido').value||'0').replace(',','.'))||0;
    const teto = parseFloat((document.getElementById('calc-a6-teto').value||'30').replace(',','.'))||30;
    const reduzirParcela = document.getElementById('calc-a6-pos-parcela').checked;

    const corrModo = document.querySelector('input[name="calc-a6-corr-modo"]:checked').value;
    const corrTaxa = parseFloat((document.getElementById('calc-a6-corr-taxa').value||'0').replace(',','.'))||0;
    const fatorM = calcA6Fator(corrModo, corrTaxa);

    const paramsBase = {cartaInicial, prazo, mesN, adminPct, reservaPct, adesao, seguroMensal, fatorM, teto, reduzirParcela};

    const colunas = [
      {titulo:'Só sorteio', r: calcA6Coluna(paramsBase, 0, 0)},
      {titulo:'Lance livre', r: calcA6Coluna(paramsBase, livrePct, 0)},
      {titulo:'Embutido ± livre', r: calcA6Coluna(paramsBase, livrePct, embutidoPct)}
    ];

    const colunaHtml = colunas.map(c=>{
      if(c.r.erro){
        return `<div><h4 style="color:var(--gold); font-size:14px; margin:0 0 8px;">${c.titulo}</h4><p class="note warn">${c.r.erro === 'embutido comeu a carta' ? 'Embutido comeu a carta — crédito líquido ficaria zero ou negativo.' : c.r.erro}</p></div>`;
      }
      const r = c.r;
      return `<div>
        <h4 style="color:var(--gold); font-size:14px; margin:0 0 8px;">${c.titulo}</h4>
        ${calcLinhaResultado('Crédito líquido', formatBRL(r.creditoLiquido))}
        ${calcLinhaResultado('Desembolso até o mês '+mesN, formatBRL(r.desembolsoAteN))}
        ${calcLinhaResultado('Parcela após o mês '+mesN, formatBRL(r.pDepois))}
        ${calcLinhaResultado('Total estimado até o fim', formatBRL(r.totalEstimadoAteFim), true)}
        ${calcLinhaResultado('Indicador (R$ caixa / R$ carta / mês)', r.indicador.toFixed(4))}
      </div>`;
    }).join('');

    // Linha de impacto do índice (70º) — só faz sentido mostrar se houver correção
    const colSemLance = colunas[0].r;
    let linhaImpacto = '';
    if(corrModo !== 'nenhuma' && !colSemLance.erro){
      linhaImpacto = `<p class="note" style="margin-bottom:16px;">No mês ${mesN} a carta foi de ${formatBRL(cartaInicial)} para ${formatBRL(colSemLance.cartaN)}. Parcela de ${formatBRL(colSemLance.P)} para ${formatBRL(colSemLance.parcelasCorrigidas[mesN-1])}. Índice do contrato manda — aqui a taxa é a que você digitou.</p>`;
    }

    // 69º — Financiamento (Price e SAC) no mesmo mês N
    const finBemInput = parseMoeda(document.getElementById('calc-a6-fin-bem').value);
    const finBem = isNaN(finBemInput) || finBemInput<=0 ? cartaInicial : finBemInput;
    const finEntrada = parseMoeda(document.getElementById('calc-a6-fin-entrada').value)||0;
    const finPrazoInput = parseInt(document.getElementById('calc-a6-fin-prazo').value,10);
    const finPrazo = isNaN(finPrazoInput) || finPrazoInput<=0 ? prazo : finPrazoInput;
    const finTaxaAA = parseFloat((document.getElementById('calc-a6-fin-taxa').value||'0').replace(',','.'))||0;
    const fin = calcA6Financiamento(finBem, finEntrada, finPrazo, finTaxaAA, mesN);

    const financiamentoHtml = `<div>
        <h4 style="color:var(--gold); font-size:14px; margin:0 0 8px;">Financiamento — Price</h4>
        ${calcLinhaResultado('Desembolso até o mês '+mesN, formatBRL(fin.price.desembolsoAteN))}
        ${calcLinhaResultado('Parcela após o mês '+mesN, fin.price.parcelaAposN>0 ? formatBRL(fin.price.parcelaAposN) : 'Quitado')}
        ${calcLinhaResultado('Total estimado até o fim', formatBRL(fin.price.totalFim), true)}
      </div>
      <div>
        <h4 style="color:var(--gold); font-size:14px; margin:0 0 8px;">Financiamento — SAC</h4>
        ${calcLinhaResultado('Desembolso até o mês '+mesN, formatBRL(fin.sac.desembolsoAteN))}
        ${calcLinhaResultado('Parcela após o mês '+mesN, fin.sac.parcelaAposN>0 ? formatBRL(fin.sac.parcelaAposN) : 'Quitado')}
        ${calcLinhaResultado('Total estimado até o fim', formatBRL(fin.sac.totalFim), true)}
      </div>`;

    // 71º — Renda fixa (custo de oportunidade)
    const rfTaxaRaw = document.getElementById('calc-a6-rf-taxa').value.trim();
    const rfTaxaAA = rfTaxaRaw === '' ? null : parseFloat(rfTaxaRaw.replace(',','.'));
    const rfIncluirLivre = document.getElementById('calc-a6-rf-livre').checked;
    const bemComparar = finBem;
    let rendaFixaHtml = '';
    if(!colSemLance.erro){
      const rf = calcA6RendaFixa(colSemLance.parcelasCorrigidas, colunas[1].r.erro ? 0 : colunas[1].r.livreRS, rfTaxaAA, bemComparar, rfIncluirLivre);
      if(rf.semTaxa){
        rendaFixaHtml = `<div><h4 style="color:var(--gold); font-size:14px; margin:0 0 8px;">Renda fixa (mesmo fluxo)</h4><p class="note">Informe a taxa % a.a. líquida de IR para calcular esta coluna.</p></div>`;
      } else {
        rendaFixaHtml = `<div>
          <h4 style="color:var(--gold); font-size:14px; margin:0 0 8px;">Renda fixa (mesmo fluxo)</h4>
          ${calcLinhaResultado('Acumulado no mês '+mesN, formatBRL(rf.fv))}
          ${calcLinhaResultado(rf.daria ? 'Sobra frente ao bem' : 'Falta frente ao bem', formatBRL(Math.abs(rf.diferenca)), true)}
          <p class="note" style="margin:6px 0 0;">${rf.daria ? 'Daria para comprar à vista no mês '+mesN+'.' : 'Faltariam '+formatBRL(Math.abs(rf.diferenca))+' para comprar à vista no mês '+mesN+'.'}</p>
          ${calcLinhaResultado('Indicador (caixa médio rendendo, R$/mês)', formatBRL(rf.indicador))}
        </div>`;
      }
    }

    html = linhaImpacto +
      `<div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:18px;">${colunaHtml}</div>` +
      `<h3 style="color:var(--gold); font-size:15px; margin:20px 0 8px;">Comparando com financiamento</h3>` +
      `<div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:18px;">${financiamentoHtml}</div>` +
      `<h3 style="color:var(--gold); font-size:15px; margin:20px 0 8px;">Comparando com renda fixa</h3>` +
      `<div style="display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:18px;">${rendaFixaHtml}</div>` +
      `<p class="note warn" style="margin-top:16px;">Simulação Soliduns. Você informa o mês N; não prevemos assembleia. Não é CET Bacen. Taxa, fundo, lance e correção seguem o CONTRATO do grupo. Lance perdedor em geral volta — aqui o lance só entra se contemplar no mês N. Taxa líquida da renda fixa é a que você digitou; consórcio não é CDB — a coluna de renda fixa só mostra o que o mesmo desembolso renderia se não estivesse no grupo.</p>`;
  } else if(codigo==='b1'){
    const bruto = parseMoeda(document.getElementById('calc-b1-bruto').value)||0;
    const dependentes = parseInt(document.getElementById('calc-b1-dependentes').value,10)||0;
    const vt = parseFloat(document.getElementById('calc-b1-vt').value)||0;
    const outros = parseMoeda(document.getElementById('calc-b1-outros').value)||0;
    const r = calcB1(bruto, dependentes, vt, outros);
    html = calcLinhaResultado('Salário bruto', formatBRL(bruto)) +
      calcLinhaResultado('INSS', '- '+formatBRL(r.inss)) +
      calcLinhaResultado('Base IR', formatBRL(r.baseIR)) +
      calcLinhaResultado('IRRF', '- '+formatBRL(r.irrf)) +
      calcLinhaResultado('Vale-transporte', '- '+formatBRL(r.vt)) +
      calcLinhaResultado('Outros descontos', '- '+formatBRL(r.outros)) +
      calcLinhaResultado('Salário líquido', formatBRL(r.liquido), true);
  } else if(codigo==='b2'){
    const salario = parseMoeda(document.getElementById('calc-b2-salario').value)||0;
    const admissaoStr = document.getElementById('calc-b2-admissao').value;
    const demissaoStr = document.getElementById('calc-b2-demissao').value;
    if(!admissaoStr || !demissaoStr){
      res.innerHTML = '<p class="note warn">Informe as datas de admissão e demissão.</p>';
      return;
    }
    const admissao = new Date(admissaoStr+'T00:00:00');
    const demissao = new Date(demissaoStr+'T00:00:00');
    const motivo = document.getElementById('calc-b2-motivo').value;
    const fgtsSaldo = parseMoeda(document.getElementById('calc-b2-fgts').value)||0;
    const feriasVencidas = document.getElementById('calc-b2-feriasvenc').value === 'sim';
    const aviso = document.getElementById('calc-b2-aviso').value;
    const r = calcB2({salario, admissao, demissao, motivo, fgtsSaldo, feriasVencidas, aviso});
    html = calcLinhaResultado('Saldo de dias ('+r.saldoDias+' dias)', formatBRL(r.saldoSalario)) +
      (r.avisoIndenizado ? calcLinhaResultado('Aviso prévio indenizado (isento)', formatBRL(r.avisoIndenizado)) : '') +
      (r.feriasVenc ? calcLinhaResultado('Férias vencidas + 1/3 (isento)', formatBRL(r.feriasVenc+r.feriasVencTerco)) : '') +
      calcLinhaResultado('Férias proporcionais + 1/3 (isento) — '+r.avosFerias+'/12', formatBRL(r.feriasProp+r.feriasPropTerco)) +
      calcLinhaResultado('13º proporcional — '+r.avos13+'/12', formatBRL(r.decimoProp)) +
      (r.multaFgts ? calcLinhaResultado('Multa FGTS (isenta)', formatBRL(r.multaFgts)) : '') +
      calcLinhaResultado('Total bruto', formatBRL(r.bruto)) +
      calcLinhaResultado('INSS (saldo + 13º)', '- '+formatBRL(r.inssSaldo+r.inss13)) +
      calcLinhaResultado('IRRF (saldo + 13º)', '- '+formatBRL(r.irrfSaldo+r.irrf13)) +
      calcLinhaResultado('Total líquido estimado', formatBRL(r.liquido), true) +
      `<p class="note warn">Estimativa — não gera TRCT. INSS/IRRF incidem só sobre saldo de dias e 13º; as demais verbas listadas como isentas seguem a regra geral, mas confirme o caso concreto.</p>`;
  } else if(codigo==='b3'){
    const salario = parseMoeda(document.getElementById('calc-b3-salario').value)||0;
    const horas = parseFloat(document.getElementById('calc-b3-horas').value)||220;
    const qtd50 = parseFloat(document.getElementById('calc-b3-qtd50').value)||0;
    const qtd100 = parseFloat(document.getElementById('calc-b3-qtd100').value)||0;
    const incluirDSR = document.getElementById('calc-b3-dsr').checked;
    const diasUteis = parseFloat(document.getElementById('calc-b3-diasuteis').value)||22;
    const repousos = parseFloat(document.getElementById('calc-b3-repousos').value)||4;
    const r = calcB3(salario, horas, qtd50, qtd100, incluirDSR, diasUteis, repousos);
    html = calcLinhaResultado('Valor da hora', formatBRL(r.valorHora)) +
      calcLinhaResultado('Horas extras 50%', formatBRL(r.he50)) +
      calcLinhaResultado('Horas extras 100%', formatBRL(r.he100)) +
      (incluirDSR ? calcLinhaResultado('Reflexo de DSR', formatBRL(r.dsr)) : '') +
      calcLinhaResultado('Total', formatBRL(r.total), true);
  } else if(codigo==='b4'){
    const salario = parseMoeda(document.getElementById('calc-b4-salario').value)||0;
    const avos = Math.min(12, parseInt(document.getElementById('calc-b4-avos').value,10)||0);
    const tipo = document.getElementById('calc-b4-tipo').value;
    const r = calcB4(salario, avos, tipo);
    html = '';
    if(r.decimoTerceiro !== undefined){
      html += calcLinhaResultado('13º proporcional', formatBRL(r.decimoTerceiro)) +
        calcLinhaResultado('INSS sobre 13º (aprox.)', '- '+formatBRL(r.decimoInss)) +
        calcLinhaResultado('IRRF sobre 13º (aprox.)', '- '+formatBRL(r.decimoIrrf));
    }
    if(r.feriasBase !== undefined){
      html += calcLinhaResultado('Férias', formatBRL(r.feriasBase)) +
        calcLinhaResultado('1/3 constitucional (isento de IR)', formatBRL(r.feriasTerco)) +
        calcLinhaResultado('Total férias + 1/3', formatBRL(r.feriasTotal), true);
    }
  } else if(codigo==='b5'){
    const salario = parseMoeda(document.getElementById('calc-b5-salario').value)||0;
    const regime = document.getElementById('calc-b5-regime').value;
    const percentual = parseFloat((document.getElementById('calc-b5-percentual').value||'0').replace(',','.'))||0;
    const beneficios = parseMoeda(document.getElementById('calc-b5-beneficios').value)||0;
    const r = calcB5(salario, regime, percentual, beneficios);
    html = calcLinhaResultado('FGTS (8%)', formatBRL(r.fgts)) +
      calcLinhaResultado('13º (8,33%)', formatBRL(r.decimo)) +
      calcLinhaResultado('Férias (8,33%)', formatBRL(r.ferias)) +
      calcLinhaResultado('1/3 férias (2,78%)', formatBRL(r.tercoFerias)) +
      (r.encargosPatronais ? calcLinhaResultado('Encargos patronais ('+String(percentual).replace('.',',')+'%)', formatBRL(r.encargosPatronais)) : '') +
      (beneficios ? calcLinhaResultado('Benefícios', formatBRL(beneficios)) : '') +
      calcLinhaResultado('Custo mensal aproximado', formatBRL(r.custoMensal), true) +
      calcLinhaResultado('Multiplicador sobre o salário', r.multiplicador.toFixed(2)+'×') +
      `<p class="note">Percentual patronal editável — não é o FAP/RAT oficial da empresa.</p>`;
  } else if(codigo==='c1'){
    const base = parseMoeda(document.getElementById('calc-c1-base').value)||0;
    const dependentes = parseInt(document.getElementById('calc-c1-dependentes').value,10)||0;
    const baseComDeducao = Math.max(0, base - dependentes*IRRF_DEDUCAO_DEPENDENTE);
    const imposto = irrf(baseComDeducao);
    html = calcLinhaResultado('Base mensal', formatBRL(base)) +
      calcLinhaResultado('Dedução por dependentes', '- '+formatBRL(dependentes*IRRF_DEDUCAO_DEPENDENTE)) +
      calcLinhaResultado('Base após dedução', formatBRL(baseComDeducao)) +
      calcLinhaResultado('IRRF', formatBRL(imposto), true);
  } else if(codigo==='c2'){
    const rendimento = parseMoeda(document.getElementById('calc-c2-rendimento').value)||0;
    const despesa = parseMoeda(document.getElementById('calc-c2-despesa').value)||0;
    const r = calcC2(rendimento, despesa);
    html = calcLinhaResultado('Base', formatBRL(r.base)) + calcLinhaResultado('IR estimado', formatBRL(r.imposto), true);
  } else if(codigo==='c3'){
    const salario = parseMoeda(document.getElementById('calc-c3-salario').value)||0;
    const contribuicao = inss(salario);
    const noTeto = salario >= INSS_TETO_SALARIO;
    html = calcLinhaResultado('Salário de contribuição considerado', formatBRL(Math.min(salario,INSS_TETO_SALARIO))) +
      calcLinhaResultado('Teto do INSS (exemplo)', formatBRL(INSS_TETO_SALARIO)) +
      calcLinhaResultado('Contribuição do segurado', formatBRL(contribuicao), true) +
      (noTeto ? '<p class="note warn">Valor informado está no teto ou acima dele.</p>' : '');
  }

  html += calcDisclaimerHtml();
  res.innerHTML = html;
}

document.addEventListener('click', function(e){
  const card = e.target.closest('.calc-card');
  if(card) abrirCalculadora(card.getAttribute('data-calc'));
});

